  fit?: 'contain' | 'cover';
  mode?: HalftoneRevealMode;
  shape?: HalftoneRevealShape;
  cellSize?: number;
  angle?: number;
  dotScale?: number;
  inkColor?: string;
  accentColor?: string;
  paperColor?: string;
  contrast?: number;
