                    zoomClass
                  )}
                  src={item.src}
                  srcSet={item.srcSet}
                  sizes={item.sizes}
                  width={item.width}
                  height={item.height}
                  alt={item.alt ?? ''}
                  title={item.title}
                  loading="lazy"
                  decoding="async"
                  draggable={false}
                />
              );
              const text = (labels === 'inline' || labels === 'below') && item.title ? item.title : null;
              const inner = (
                <>
                  {visual}
                  {text && (
                    <span className={labelClass} aria-hidden={!isNode && !!item.alt}>
                      {text}
                    </span>
                  )}
                </>
              );
              const name = isNode ? (item.ariaLabel ?? item.title) : (item.alt ?? item.title);
              return (
                <li
                  className={itemClass}
                  key={key}
                  role="listitem"
