                  style={
                    item.hoverColor ? ({ '--logoloop-item-color': item.hoverColor } as React.CSSProperties) : undefined
                  }
                >
                  {item.href ? (
                    <a
                      className={contentClass(item)}
                      href={item.href}
                      aria-label={name || 'logo link'}
                      target="_blank"
                      rel="noreferrer noopener"
