'use client';

import { useEffect, useRef, type HTMLAttributes, type ReactNode } from 'react';

export type MagnetAxis = 'both' | 'x' | 'y';

export interface MagnetSpring {
  stiffness?: number;
  damping?: number;
  mass?: number;
}

export interface MagnetProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  padding?: number;
  disabled?: boolean;
  magnetStrength?: number;
  maxOffset?: number;
  exclusive?: boolean;
  axis?: MagnetAxis;
  tilt?: number;
  scale?: number;
  spring?: MagnetSpring;
  onActiveChange?: (active: boolean) => void;
  wrapperClassName?: string;
  innerClassName?: string;
}

type Motion = { x: number; y: number; tiltX: number; tiltY: number; scale: number };

type Point = { x: number; y: number };

type Settings = {
  padding: number;
  disabled: boolean;
  strength: number;
  maxOffset?: number;
  exclusive: boolean;
  axis: MagnetAxis;
  tilt: number;
  scale: number;
  stiffness: number;
  damping: number;
  mass: number;
  onActiveChange?: (active: boolean) => void;
};

type Entry = {
  wrapper: HTMLDivElement;
  settings: { current: Settings };
  reduce: boolean;
  wake: () => void;
  active: boolean;
};

const DEFAULT_SPRING = { stiffness: 170, damping: 16, mass: 1 };

const smoothstep = (edge0: number, edge1: number, value: number) => {
  const t = Math.min(1, Math.max(0, (value - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
};

const registry = new Set<Entry>();
const field: { pointer: Point | null; owner: Entry | null } = { pointer: null, owner: null };
let detach: (() => void) | null = null;

const reach = (rect: DOMRect, pointer: Point) => {
  const dx = pointer.x - (rect.left + rect.width / 2);
  const dy = pointer.y - (rect.top + rect.height / 2);
  const outside = Math.hypot(Math.max(0, Math.abs(dx) - rect.width / 2), Math.max(0, Math.abs(dy) - rect.height / 2));
  return { dx, dy, outside };
};

const arbitrate = () => {
  let winner: Entry | null = null;
  let nearest = Infinity;
  let closest = Infinity;
  for (const entry of registry) {
    const s = entry.settings.current;
    let near: { dx: number; dy: number; outside: number } | null = null;
    if (field.pointer && !s.disabled && !entry.reduce) {
      near = reach(entry.wrapper.getBoundingClientRect(), field.pointer);
      if (near.outside > s.padding) near = null;
    }
    if (!s.exclusive) {
      if (near || entry.active) entry.wake();
      continue;
    }
    if (!near) continue;
    const center = Math.hypot(near.dx, near.dy);
    if (near.outside < nearest || (near.outside === nearest && center < closest)) {
      winner = entry;
      nearest = near.outside;
      closest = center;
    }
  }
  const previous = field.owner;
  field.owner = winner;
  if (previous && previous !== winner) previous.wake();
  if (winner) winner.wake();
};

const attach = () => {
  const onPointerMove = (event: PointerEvent) => {
    if (event.pointerType === 'touch') return;
    field.pointer = { x: event.clientX, y: event.clientY };
    arbitrate();
  };
  const onLeave = () => {
    field.pointer = null;
    arbitrate();
  };
  window.addEventListener('pointermove', onPointerMove, { passive: true });
  window.addEventListener('scroll', arbitrate, { passive: true, capture: true });
  document.documentElement.addEventListener('pointerleave', onLeave);
  window.addEventListener('blur', onLeave);
  return () => {
    window.removeEventListener('pointermove', onPointerMove);
    window.removeEventListener('scroll', arbitrate, { capture: true });
    document.documentElement.removeEventListener('pointerleave', onLeave);
    window.removeEventListener('blur', onLeave);
  };
};

const Magnet = ({
  children,
  padding = 100,
  disabled = false,
  magnetStrength = 2,
  maxOffset,
  exclusive = true,
  axis = 'both',
  tilt = 0,
  scale = 1,
  spring,
  onActiveChange,
  wrapperClassName = '',
  innerClassName = '',
  style,
  ...props
}: MagnetProps) => {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const innerRef = useRef<HTMLDivElement>(null);
  const wakeRef = useRef<(() => void) | null>(null);
  const settings: Settings = {
    padding: Math.max(0, padding),
    disabled,
    strength: Math.max(0.1, magnetStrength),
    maxOffset,
    exclusive,
    axis,
    tilt,
    scale,
    stiffness: Math.max(1, spring?.stiffness ?? DEFAULT_SPRING.stiffness),
    damping: Math.max(0, spring?.damping ?? DEFAULT_SPRING.damping),
    mass: Math.max(0.01, spring?.mass ?? DEFAULT_SPRING.mass),
    onActiveChange
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    const wrapper = wrapperRef.current;
    const inner = innerRef.current;
    if (!wrapper || !inner) return undefined;

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const current: Motion = { x: 0, y: 0, tiltX: 0, tiltY: 0, scale: 1 };
    const velocity: Motion = { x: 0, y: 0, tiltX: 0, tiltY: 0, scale: 0 };
    let active = false;
    let raf = 0;
    let last = 0;

    const solve = (target: Motion, dt: number) => {
      const s = settingsRef.current;
      let resting = true;
      (Object.keys(current) as (keyof Motion)[]).forEach(key => {
        const force = s.stiffness * (target[key] - current[key]) - s.damping * velocity[key];
        velocity[key] += (force / s.mass) * dt;
        current[key] += velocity[key] * dt;
        const epsilon = key === 'scale' ? 0.001 : 0.05;
        if (Math.abs(target[key] - current[key]) > epsilon || Math.abs(velocity[key]) > epsilon) resting = false;
      });
      return resting;
    };

    const measure = () => {
      const s = settingsRef.current;
      const target: Motion = { x: 0, y: 0, tiltX: 0, tiltY: 0, scale: 1 };
      if (s.disabled || reduce || !field.pointer) return { target, engaged: false };
      if (s.exclusive && field.owner !== entry) return { target, engaged: false };
      const rect = wrapper.getBoundingClientRect();
      const { dx, dy, outside } = reach(rect, field.pointer);
      if (outside > s.padding) return { target, engaged: false };
      const pull = s.padding > 0 ? 1 - smoothstep(s.padding * 0.5, s.padding, outside) : 1;
      let x = s.axis === 'y' ? 0 : (dx / s.strength) * pull;
      let y = s.axis === 'x' ? 0 : (dy / s.strength) * pull;
      if (s.maxOffset !== undefined && s.maxOffset !== null) {
        const length = Math.hypot(x, y);
        if (length > s.maxOffset) {
          x *= s.maxOffset / length;
          y *= s.maxOffset / length;
        }
      }
      const nx = Math.max(-1, Math.min(1, dx / Math.max(rect.width / 2, 1)));
      const ny = Math.max(-1, Math.min(1, dy / Math.max(rect.height / 2, 1)));
      target.x = x;
      target.y = y;
      target.tiltX = -ny * s.tilt * pull;
      target.tiltY = nx * s.tilt * pull;
      target.scale = 1 + (s.scale - 1) * pull;
      return { target, engaged: true };
    };

    const apply = () => {
      const { x, y, tiltX, tiltY, scale } = current;
      const turned = Math.abs(tiltX) > 0.01 || Math.abs(tiltY) > 0.01;
      inner.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0)${
        turned ? ` perspective(800px) rotateX(${tiltX.toFixed(2)}deg) rotateY(${tiltY.toFixed(2)}deg)` : ''
      }${Math.abs(scale - 1) > 0.0005 ? ` scale(${scale.toFixed(4)})` : ''}`;
    };

    const frame = (now: number) => {
      raf = 0;
      const dt = last ? Math.min((now - last) / 1000, 1 / 30) : 1 / 60;
      last = now;
      const { target, engaged } = measure();
      if (engaged !== active) {
        active = engaged;
        entry.active = engaged;
        if (engaged) wrapper.setAttribute('data-magnet-active', '');
        else wrapper.removeAttribute('data-magnet-active');
        settingsRef.current.onActiveChange?.(engaged);
      }
      const steps = Math.ceil(dt / (1 / 120));
      let resting = true;
      for (let i = 0; i < steps; i++) resting = solve(target, dt / steps);
      if (resting) {
        (Object.keys(current) as (keyof Motion)[]).forEach(key => {
          current[key] = target[key];
          velocity[key] = 0;
        });
      }
      apply();
      if (!resting) raf = requestAnimationFrame(frame);
      else last = 0;
    };

    function wake() {
      if (!raf) raf = requestAnimationFrame(frame);
    }

    const entry: Entry = { wrapper, settings: settingsRef, reduce, wake, active: false };
    registry.add(entry);
    if (!detach) detach = attach();
    wakeRef.current = () => {
      arbitrate();
      wake();
    };

    return () => {
      cancelAnimationFrame(raf);
      wakeRef.current = null;
      registry.delete(entry);
      if (field.owner === entry) field.owner = null;
      if (!registry.size && detach) {
        detach();
        detach = null;
      }
    };
  }, []);

  useEffect(() => {
    wakeRef.current?.();
  });

  return (
    <div
      ref={wrapperRef}
      className={wrapperClassName}
      style={{ position: 'relative', display: 'inline-block', ...style }}
      {...props}
    >
      <div ref={innerRef} className={innerClassName} style={{ willChange: 'transform' }}>
        {children}
      </div>
    </div>
  );
};

export default Magnet;

'use client';

import { useEffect, useRef, type CSSProperties } from 'react';

type Variant = 'solid' | 'outline' | 'contour';
type Motion = 'orbit' | 'drift' | 'lava';

interface MetaBallsProps {
  className?: string;
  color?: string;
  cursorBallColor?: string;
  speed?: number;
  enableMouseInteraction?: boolean;
  hoverSmoothness?: number;
  animationSize?: number;
  ballCount?: number;
  clumpFactor?: number;
  cursorBallSize?: number;
  enableTransparency?: boolean;
  variant?: Variant;
  motion?: Motion;
  gooeyness?: number;
  stickiness?: number;
  stretch?: number;
  wobble?: number;
  lineWidth?: number;
  rings?: number;
  clickBurst?: boolean;
  intro?: boolean;
  paused?: boolean;
  dpr?: number;
  style?: CSSProperties;
}

interface Body {
  vx: number;
  vy: number;
  a: number;
  b: number;
  va: number;
  vb: number;
}

interface Look {
  size: number;
  time: number;
}

const MAX_BALLS = 50;
const SLOTS = MAX_BALLS + 1;
const VARIANTS: Record<string, number> = { solid: 0, outline: 1, contour: 2 };
const VISIBLE = 0.877;

const fract = (x: number) => x - Math.floor(x);

const hash31 = (p: number) => {
  const r = [p * 0.1031, p * 0.103, p * 0.0973].map(fract);
  const dot = r[0] * (r[1] + 33.33) + r[1] * (r[2] + 33.33) + r[2] * (r[0] + 33.33);
  return r.map(value => fract(value + dot));
};

const hash33 = (v: number[]) => {
  const p = [v[0] * 0.1031, v[1] * 0.103, v[2] * 0.0973].map(fract);
  const dot = p[0] * (p[1] + 33.33) + p[1] * (p[0] + 33.33) + p[2] * (p[2] + 33.33);
  const q = p.map(value => fract(value + dot));
  return [fract((q[0] + q[1]) * q[2]), fract((q[0] + q[0]) * q[1]), fract((q[1] + q[0]) * q[0])];
};

const toRgb = (color: string): [number, number, number] => {
  let hex = String(color || '')
    .trim()
    .replace('#', '');
  if (hex.length === 3) hex = hex.replace(/./g, c => c + c);
  if (!/^[0-9a-f]{6}/i.test(hex)) return [1, 1, 1];
  return [0, 2, 4].map(index => parseInt(hex.slice(index, index + 2), 16) / 255) as [number, number, number];
};

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const smoothstep = (a: number, b: number, x: number) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
const easeOut = (t: number) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
const easeInOut = (t: number) => {
  const x = clamp(t, 0, 1);
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
};

const VERTEX = `#version 300 es
in vec2 position;
void main() {
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

const FRAGMENT = `#version 300 es
precision highp float;

uniform vec2 uResolution;
uniform float uScale;
uniform vec4 uBalls[${SLOTS}];
uniform vec4 uShapes[${SLOTS}];
uniform int uCount;
uniform float uGamma;
uniform float uThreshold;
uniform vec3 uColor;
uniform vec3 uCursorColor;
uniform int uVariant;
uniform float uLine;
uniform float uSpacing;
uniform float uRings;
uniform float uOpaque;

out vec4 outColor;

void main() {
  vec2 p = (gl_FragCoord.xy - 0.5 * uResolution) * uScale;
  float field = 0.0;
  float tint = 0.0;
  float mass = 0.0;
  vec2 grad = vec2(0.0);
  bool classic = abs(uGamma - 1.0) < 0.001;
  for (int i = 0; i < ${SLOTS}; i++) {
    if (i >= uCount) break;
    vec4 ball = uBalls[i];
    vec4 shape = uShapes[i];
    vec2 d = p - ball.xy;
    vec2 q = vec2(shape.x * d.x + shape.y * d.y, shape.y * d.x + shape.z * d.y);
    float qq = max(dot(q, q), ball.z * 1e-4 + 1e-12);
    float v = ball.z / qq;
    float w = classic ? v : pow(v, uGamma);
    field += w;
    float weight = w / (1.0 + w / uThreshold);
    mass += weight;
    tint += weight * ball.w;
    grad -= 2.0 * uGamma * w / qq * vec2(shape.x * q.x + shape.y * q.y, shape.y * q.x + shape.z * q.y);
  }
  float slope = max(length(grad) * uScale, 1e-8);
  vec3 color = mix(uColor, uCursorColor, mass > 0.0 ? clamp(tint / mass, 0.0, 1.0) : 0.0);
  float alpha;
  if (uVariant == 0) {
    alpha = field > 3.0 * uThreshold ? 1.0 : clamp((field - uThreshold) / slope + 0.5, 0.0, 1.0);
  } else if (uVariant == 1) {
    alpha = field > 3.0 * uThreshold ? 0.0 : clamp(0.5 * uLine + 0.5 - abs((field - uThreshold) / slope), 0.0, 1.0);
  } else {
    float rho = pow(max(field / uThreshold, 1e-6), -0.5 / uGamma);
    float rate = rho * slope / (2.0 * uGamma * max(field, 1e-8));
    float u = (rho - 1.0) / uSpacing;
    float ring = floor(u + 0.5);
    float gap = (u - ring) * uSpacing / max(rate, 1e-8);
    alpha = clamp(0.5 * uLine + 0.5 - abs(gap), 0.0, 1.0);
    alpha *= ring < -0.5 || ring > uRings + 0.5 ? 0.0 : 1.0 - ring / (uRings + 1.0);
    if (ring > 0.5) alpha *= smoothstep(uLine * 6.0, uLine * 12.0, uSpacing / max(rate, 1e-8));
  }
  outColor = vec4(color * alpha, uOpaque > 0.5 ? 1.0 : alpha);
}
`;

const compile = (gl: WebGL2RenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type) as WebGLShader;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  return shader;
};

const createBall = (index: number) => {
  const h1 = hash31(index + 1);
  const h2 = hash33(h1);
  return {
    start: h1[0] * Math.PI * 2,
    rate: 0.1 * Math.PI + h1[1] * 0.3 * Math.PI,
    reach: 5 + h1[1] * 5,
    toggle: Math.floor(h2[0] * 2),
    radius: 0.5 + h2[2] * 1.5,
    lane: h2[1] * 2 - 1,
    rise: 0.55 + h1[2] * 0.7,
    sway: h2[0] * Math.PI * 2,
    delay: 0.1 + fract(h1[2] * 7.31 + h2[1] * 3.17) * 0.55,
    x: 0,
    y: 0,
    vx: 0,
    vy: 0,
    fx: 0,
    fy: 0,
    ax: 0,
    ay: 0,
    avx: 0,
    avy: 0,
    a: 0,
    b: 0,
    va: 0,
    vb: 0
  };
};

type Ball = ReturnType<typeof createBall>;

const MetaBalls = ({
  className = '',
  color = '#ffffff',
  cursorBallColor = '#ffffff',
  speed = 0.3,
  enableMouseInteraction = true,
  hoverSmoothness = 0.1,
  animationSize = 30,
  ballCount = 15,
  clumpFactor = 1,
  cursorBallSize = 3,
  enableTransparency = false,
  variant = 'solid',
  motion = 'orbit',
  gooeyness = 0.5,
  stickiness = 0.5,
  stretch = 0.5,
  wobble = 0.5,
  lineWidth = 1.5,
  rings = 4,
  clickBurst = true,
  intro = true,
  paused = false,
  dpr,
  style
}: MetaBallsProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const settings = {
    color,
    cursorBallColor,
    speed,
    enableMouseInteraction,
    hoverSmoothness,
    animationSize,
    ballCount,
    clumpFactor,
    cursorBallSize,
    enableTransparency,
    variant,
    motion,
    gooeyness,
    stickiness,
    stretch,
    wobble,
    lineWidth,
    rings,
    clickBurst,
    paused,
    dpr
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;
  const introRef = useRef(intro);
  const engineRef = useRef<{ refresh: () => void } | null>(null);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;
    const gl = canvas.getContext('webgl2', { alpha: true, antialias: false, premultipliedAlpha: true });
    if (!gl) return;

    const program = gl.createProgram() as WebGLProgram;
    gl.attachShader(program, compile(gl, gl.VERTEX_SHADER, VERTEX));
    gl.attachShader(program, compile(gl, gl.FRAGMENT_SHADER, FRAGMENT));
    gl.bindAttribLocation(program, 0, 'position');
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return;
    gl.useProgram(program);

    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

    const uniform = (name: string) => gl.getUniformLocation(program, name);
    const loc = {
      resolution: uniform('uResolution'),
      scale: uniform('uScale'),
      balls: uniform('uBalls'),
      shapes: uniform('uShapes'),
      count: uniform('uCount'),
      gamma: uniform('uGamma'),
      threshold: uniform('uThreshold'),
      color: uniform('uColor'),
      cursorColor: uniform('uCursorColor'),
      variant: uniform('uVariant'),
      line: uniform('uLine'),
      spacing: uniform('uSpacing'),
      rings: uniform('uRings'),
      opaque: uniform('uOpaque')
    };

    const ballData = new Float32Array(SLOTS * 4);
    const shapeData = new Float32Array(SLOTS * 4);
    const balls = Array.from({ length: MAX_BALLS }, (_, index) => createBall(index));
    const idle = createBall(MAX_BALLS + 7);
    const cursor = { x: 0, y: 0, vx: 0, vy: 0, a: 0, b: 0, va: 0, vb: 0, pulse: 0, pulseVelocity: 0, ready: false };
    const pointer = { x: 0, y: 0, inside: false };
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const view = { width: 1, height: 1, ratio: 1 };
    const colors = new Map<string, [number, number, number]>();
    const rgb = (value: string) => {
      if (!colors.has(value)) colors.set(value, toRgb(value));
      return colors.get(value) as [number, number, number];
    };
    let phase = 0;
    let clock = 0;
    let introAt = introRef.current && !reduced ? 0 : -1;
    let visible = true;
    let raf = 0;
    let last = 0;
    let dirty = true;

    const resize = () => {
      const rect = container.getBoundingClientRect();
      const s = settingsRef.current;
      const ratio = Math.max(0.5, Math.min(s.dpr ?? window.devicePixelRatio ?? 1, 2));
      view.width = Math.max(1, rect.width);
      view.height = Math.max(1, rect.height);
      view.ratio = ratio;
      canvas.width = Math.max(1, Math.round(view.width * ratio));
      canvas.height = Math.max(1, Math.round(view.height * ratio));
      gl.viewport(0, 0, canvas.width, canvas.height);
      dirty = true;
    };

    const toWorld = (clientX: number, clientY: number) => {
      const rect = container.getBoundingClientRect();
      const scale = settingsRef.current.animationSize / Math.max(1, rect.height);
      return {
        x: (clientX - rect.left - rect.width / 2) * scale,
        y: (rect.top + rect.height / 2 - clientY) * scale,
        inside: clientX >= rect.left && clientX <= rect.right && clientY >= rect.top && clientY <= rect.bottom
      };
    };

    const presence = (): Look => {
      if (introAt < 0) return { size: 1, time: Infinity };
      const t = clock - introAt;
      return { size: easeOut(t / 0.5), time: t };
    };

    const release = (ball: Ball, look: Look) =>
      look.time === Infinity ? 1 : easeInOut((look.time - ball.delay) / 1.15);

    const anchor = (ball: Ball, s: typeof settings, spread: number): [number, number] => {
      const halfWidth = (s.animationSize * view.width) / view.height / 2;
      const halfHeight = s.animationSize / 2;
      const clump = Math.min(1.25, s.clumpFactor);
      if (s.motion === 'lava') {
        const cycle = Math.sin(phase * ball.rise * 1.6 + ball.start);
        const x =
          ball.lane * halfWidth * 0.8 * clump + Math.sin(phase * 0.5 * ball.rise + ball.sway) * halfWidth * 0.06;
        const y = Math.sign(cycle) * Math.pow(Math.abs(cycle), 0.55) * halfHeight * 0.9;
        return [x * spread, y * spread];
      }
      if (s.motion === 'drift') {
        const x = Math.sin(phase * ball.rise * 0.9 + ball.start) * halfWidth * 0.84 * clump;
        const y = Math.sin(phase * ball.rate * 1.3 + ball.sway) * halfHeight * 0.78 * clump;
        return [x * spread, y * spread];
      }
      const t = phase * ball.rate;
      const angle = ball.start + t;
      return [
        Math.cos(angle) * ball.reach * s.clumpFactor * spread,
        Math.sin(angle + t * ball.toggle) * ball.reach * s.clumpFactor * spread
      ];
    };

    const deform = (body: Body, h: number, s: typeof settings) => {
      const speed = Math.hypot(body.vx, body.vy);
      const amount = 0.6 * s.stretch * Math.tanh(speed / 14);
      let ta = 0;
      let tb = 0;
      if (speed > 1e-4) {
        ta = (amount * (body.vx * body.vx - body.vy * body.vy)) / (speed * speed);
        tb = (amount * 2 * body.vx * body.vy) / (speed * speed);
      }
      const omega = 13;
      const zeta = 0.85 - 0.68 * clamp(s.wobble, 0, 1);
      body.va += (omega * omega * (ta - body.a) - 2 * zeta * omega * body.va) * h;
      body.vb += (omega * omega * (tb - body.b) - 2 * zeta * omega * body.vb) * h;
      body.a += body.va * h;
      body.b += body.vb * h;
    };

    const bridge = (s: typeof settings) => {
      const goo = clamp(s.gooeyness, 0, 1);
      const gamma = goo < 0.5 ? 1 + (0.5 - goo) * 1.2 : 1 - (goo - 0.5) * 0.5;
      return { gamma, threshold: Math.pow(1.3, gamma), reach: Math.pow(2, 0.5 / gamma) };
    };

    const step = (h: number, s: typeof settings, count: number, look: Look) => {
      const { reach } = bridge(s);
      const pull = 36 * clamp(s.stickiness, 0, 1);
      const cursorRadius = s.cursorBallSize * VISIBLE * look.size * (1 + cursor.pulse);
      phase += h * s.speed;

      for (let i = 0; i < count; i++) {
        const ball = balls[i];
        const [x, y] = anchor(ball, s, release(ball, look));
        ball.avx = clamp((x - ball.ax) / h, -40, 40);
        ball.avy = clamp((y - ball.ay) / h, -40, 40);
        ball.ax = x;
        ball.ay = y;
        ball.fx = 20 * (x - ball.x) - 5.4 * (ball.vx - ball.avx);
        ball.fy = 20 * (y - ball.y) - 5.4 * (ball.vy - ball.avy);
      }

      for (let i = 0; i < count; i++) {
        const p = balls[i];
        const rp = p.radius * VISIBLE * look.size;
        for (let j = i + 1; j < count; j++) {
          const q = balls[j];
          const rq = q.radius * VISIBLE * look.size;
          const dx = q.x - p.x;
          const dy = q.y - p.y;
          const distance = Math.hypot(dx, dy) || 1e-4;
          const far = (rp + rq) * reach;
          if (distance >= far) continue;
          const core = (rp + rq) * 0.62;
          let force;
          if (distance < core) force = -60 * (core - distance);
          else {
            const t = (distance - core) / (far - core);
            force = pull * Math.min(rp, rq) * smoothstep(0, 0.6, t) * (1 - smoothstep(0.82, 1, t));
          }
          const nx = dx / distance;
          const ny = dy / distance;
          const mp = rp * rp + 0.05;
          const mq = rq * rq + 0.05;
          p.fx += (nx * force) / mp;
          p.fy += (ny * force) / mp;
          q.fx -= (nx * force) / mq;
          q.fy -= (ny * force) / mq;
        }
        const dx = cursor.x - p.x;
        const dy = cursor.y - p.y;
        const distance = Math.hypot(dx, dy) || 1e-4;
        const far = (rp + cursorRadius) * reach;
        if (distance < far) {
          const core = (rp + cursorRadius) * 0.62;
          let force;
          if (distance < core) force = -140 * (core - distance);
          else {
            const t = (distance - core) / (far - core);
            force = pull * 0.6 * rp * smoothstep(0, 0.6, t) * (1 - smoothstep(0.82, 1, t));
          }
          p.fx += ((dx / distance) * force) / (rp * rp + 0.05);
          p.fy += ((dy / distance) * force) / (rp * rp + 0.05);
        }
      }

      for (let i = 0; i < count; i++) {
        const ball = balls[i];
        ball.vx += ball.fx * h;
        ball.vy += ball.fy * h;
        ball.x += ball.vx * h;
        ball.y += ball.vy * h;
        deform(ball, h, s);
        if (!Number.isFinite(ball.x + ball.y + ball.vx + ball.vy + ball.a + ball.b + ball.va + ball.vb)) {
          Object.assign(ball, { x: ball.ax, y: ball.ay, vx: 0, vy: 0, a: 0, b: 0, va: 0, vb: 0 });
        }
      }
    };

    const moveCursor = (dt: number, s: typeof settings, look: Look) => {
      let tx: number;
      let ty: number;
      if (pointer.inside && s.enableMouseInteraction) {
        tx = pointer.x;
        ty = pointer.y;
      } else {
        const out = look.time === Infinity ? 1 : easeInOut((look.time - 0.75) / 1.3);
        if (s.motion === 'lava' || s.motion === 'drift') {
          [tx, ty] = anchor(idle, s, out);
        } else {
          const halfWidth = (s.animationSize * view.width) / view.height / 2;
          const halfHeight = s.animationSize / 2;
          tx = Math.cos(clock * s.speed) * halfWidth * 0.3 * out;
          ty = Math.sin(clock * s.speed) * halfHeight * 0.3 * out;
        }
      }
      if (!cursor.ready) {
        cursor.x = tx;
        cursor.y = ty;
        cursor.ready = true;
      }
      const follow = 1 - Math.pow(1 - clamp(s.hoverSmoothness, 0.001, 1), dt * 60);
      const nx = cursor.x + (tx - cursor.x) * follow;
      const ny = cursor.y + (ty - cursor.y) * follow;
      const blend = 1 - Math.exp(-dt / 0.05);
      cursor.vx += ((nx - cursor.x) / Math.max(dt, 1e-4) - cursor.vx) * blend;
      cursor.vy += ((ny - cursor.y) / Math.max(dt, 1e-4) - cursor.vy) * blend;
      cursor.x = nx;
      cursor.y = ny;
    };

    const burst = (x: number, y: number) => {
      const s = settingsRef.current;
      const count = clamp(Math.round(s.ballCount), 0, MAX_BALLS);
      const radius = s.animationSize * 0.45;
      for (let i = 0; i < count; i++) {
        const ball = balls[i];
        const dx = ball.x - x;
        const dy = ball.y - y;
        const distance = Math.hypot(dx, dy) || 1e-4;
        if (distance > radius) continue;
        const falloff = Math.pow(1 - distance / radius, 1.2);
        const kick = 72 * falloff;
        ball.vx += (dx / distance) * kick - (dy / distance) * kick * 0.3;
        ball.vy += (dy / distance) * kick + (dx / distance) * kick * 0.3;
      }
      cursor.pulseVelocity += 9;
    };

    const shapeOf = (body: Body, out: Float32Array, offset: number) => {
      const m = Math.hypot(body.a, body.b);
      const c = Math.cosh(m);
      const k = m > 1e-6 ? Math.sinh(m) / m : 1;
      out[offset] = c - k * body.a;
      out[offset + 1] = -k * body.b;
      out[offset + 2] = c + k * body.a;
      out[offset + 3] = 0;
    };

    const draw = () => {
      const s = settingsRef.current;
      const count = clamp(Math.round(s.ballCount), 0, MAX_BALLS);
      const look = presence();
      const { gamma, threshold } = bridge(s);
      for (let i = 0; i < count; i++) {
        const ball = balls[i];
        const radius = ball.radius * look.size;
        ballData[i * 4] = ball.x;
        ballData[i * 4 + 1] = ball.y;
        ballData[i * 4 + 2] = radius * radius;
        ballData[i * 4 + 3] = 0;
        shapeOf(ball, shapeData, i * 4);
      }
      const cursorRadius = s.cursorBallSize * look.size * (1 + cursor.pulse);
      ballData[count * 4] = cursor.x;
      ballData[count * 4 + 1] = cursor.y;
      ballData[count * 4 + 2] = cursorRadius * cursorRadius;
      ballData[count * 4 + 3] = 1;
      shapeOf(cursor, shapeData, count * 4);

      gl.uniform2f(loc.resolution, canvas.width, canvas.height);
      gl.uniform1f(loc.scale, s.animationSize / canvas.height);
      gl.uniform4fv(loc.balls, ballData);
      gl.uniform4fv(loc.shapes, shapeData);
      gl.uniform1i(loc.count, count + 1);
      gl.uniform1f(loc.gamma, gamma);
      gl.uniform1f(loc.threshold, threshold);
      gl.uniform3fv(loc.color, rgb(s.color));
      gl.uniform3fv(loc.cursorColor, rgb(s.cursorBallColor));
      gl.uniform1i(loc.variant, VARIANTS[s.variant] ?? 0);
      gl.uniform1f(loc.line, Math.max(0.25, s.lineWidth) * view.ratio);
      gl.uniform1f(loc.spacing, 0.28);
      gl.uniform1f(loc.rings, clamp(Math.round(s.rings), 0, 12));
      gl.uniform1f(loc.opaque, s.enableTransparency ? 0 : 1);
      gl.clearColor(0, 0, 0, s.enableTransparency ? 0 : 1);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      dirty = false;
    };

    const frame = (now: number) => {
      raf = 0;
      if (!visible) return;
      const dt = Math.min(0.05, last ? (now - last) / 1000 : 1 / 60);
      last = now;
      const s = settingsRef.current;
      if (!s.paused && dt > 1e-4) {
        clock += dt;
        const count = clamp(Math.round(s.ballCount), 0, MAX_BALLS);
        const look = presence();
        moveCursor(dt, s, look);
        const steps = Math.max(1, Math.ceil(dt / (1 / 240)));
        for (let i = 0; i < steps; i++) step(dt / steps, s, count, look);
        deform(cursor, dt, s);
        cursor.pulseVelocity += (-170 * cursor.pulse - 2 * 0.42 * 13 * cursor.pulseVelocity) * dt;
        cursor.pulse = Math.max(-0.4, cursor.pulse + cursor.pulseVelocity * dt);
        dirty = true;
      }
      if (dirty) draw();
      raf = requestAnimationFrame(frame);
    };

    const start = () => {
      if (raf || !visible) return;
      last = 0;
      raf = requestAnimationFrame(frame);
    };

    const onMove = (event: PointerEvent) => {
      const point = toWorld(event.clientX, event.clientY);
      pointer.x = point.x;
      pointer.y = point.y;
      pointer.inside = point.inside;
    };
    const onLeave = (event: PointerEvent) => {
      if (!event.relatedTarget) pointer.inside = false;
    };
    const onLift = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse') pointer.inside = false;
    };
    const onDown = (event: PointerEvent) => {
      const s = settingsRef.current;
      if (!s.clickBurst || !s.enableMouseInteraction || s.paused || event.button !== 0) return;
      const point = toWorld(event.clientX, event.clientY);
      if (point.inside) burst(point.x, point.y);
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(container);
    const intersection = new IntersectionObserver(entries => {
      visible = entries.some(entry => entry.isIntersecting);
      if (visible) start();
    });
    intersection.observe(container);
    window.addEventListener('pointermove', onMove, { passive: true });
    window.addEventListener('pointerdown', onDown, { passive: true });
    window.addEventListener('pointerout', onLeave);
    window.addEventListener('pointerup', onLift);
    window.addEventListener('pointercancel', onLift);

    resize();
    start();
    engineRef.current = {
      refresh: () => {
        dirty = true;
      }
    };

    return () => {
      cancelAnimationFrame(raf);
      resizeObserver.disconnect();
      intersection.disconnect();
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerdown', onDown);
      window.removeEventListener('pointerout', onLeave);
      window.removeEventListener('pointerup', onLift);
      window.removeEventListener('pointercancel', onLift);
      gl.deleteBuffer(buffer);
      gl.deleteProgram(program);
      engineRef.current = null;
    };
  }, []);

  useEffect(() => {
    engineRef.current?.refresh();
  });

  return (
    <div ref={containerRef} className={`relative h-full w-full ${className}`.trim()} style={style}>
      <canvas ref={canvasRef} className="block h-full w-full" />
    </div>
  );
};

export default MetaBalls;

'use client';

import { useEffect, useRef, type CSSProperties } from 'react';

export interface MetallicPaintProps {
  imageSrc?: string;
  text?: string;
  fontFamily?: string;
  fontWeight?: number | string;
  color?: string;
  backgroundColor?: string;
  density?: number;
  softness?: number;
  dispersion?: number;
  distortion?: number;
  edgeBend?: number;
  angle?: number;
  speed?: number;
  scale?: number;
  rotation?: number;
  mouseTilt?: number;
  lightMode?: boolean;
  intro?: boolean;
  paused?: boolean;
  dpr?: number;
  className?: string;
  style?: CSSProperties;
}

type Rgba = number[];

interface Settings {
  tint: Rgba;
  back: Rgba;
  density: number;
  softness: number;
  dispersion: number;
  distortion: number;
  edgeBend: number;
  angle: number;
  speed: number;
  scale: number;
  rotation: number;
  mouseTilt: number;
  lightMode: boolean;
  intro: boolean;
  paused: boolean;
  dpr?: number;
}

interface Engine {
  setPending: (value: boolean) => void;
  setImage: (data: ImageData | null) => void;
  wake: () => void;
  redraw: () => void;
}

const WORKING_SIZE = 512;
const MAX_SIDE = 2048;
const MAX_PIXELS = 2560 * 1600 * 2;

const VERTEX = `#version 300 es
layout(location = 0) in vec2 a_position;
uniform vec2 u_resolution;
uniform float u_imageAspect;
uniform float u_scale;
uniform float u_rotation;
out vec2 v_imageUV;

void main() {
  gl_Position = vec4(a_position, 0.0, 1.0);
  vec2 uv = a_position * 0.5;
  float r = u_rotation * 3.14159265358979323846 / 180.0;
  mat2 turn = mat2(cos(r), sin(r), -sin(r), cos(r));
  vec2 imageBox;
  imageBox.x = min(u_resolution.x / u_imageAspect, u_resolution.y) * u_imageAspect;
  imageBox.y = imageBox.x / u_imageAspect;
  v_imageUV = uv * (u_resolution / imageBox) / u_scale;
  v_imageUV.x *= u_imageAspect;
  v_imageUV = turn * v_imageUV;
  v_imageUV.x /= u_imageAspect;
  v_imageUV += 0.5;
  v_imageUV.y = 1.0 - v_imageUV.y;
}`;

const FRAGMENT = `#version 300 es
precision highp float;

uniform sampler2D u_image;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec4 u_colorBack;
uniform vec4 u_colorTint;
uniform float u_softness;
uniform float u_repetition;
uniform float u_shiftRed;
uniform float u_shiftBlue;
uniform float u_distortion;
uniform float u_contour;
uniform float u_angle;
uniform vec2 u_tilt;
uniform float u_reveal;
uniform float u_light;

in vec2 v_imageUV;

out vec4 fragColor;

#define PI 3.14159265358979323846

vec2 rotate(vec2 uv, float th) {
  return mat2(cos(th), sin(th), -sin(th), cos(th)) * uv;
}

vec3 permute(vec3 x) { return mod(((x * 34.0) + 1.0) * x, 289.0); }

float snoise(vec2 v) {
  const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
  vec2 i = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);
  vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod(i, 289.0);
  vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
  vec3 g;
  g.x = a0.x * x0.x + h.x * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

float getColorChanges(float c1, float c2, float stripe, vec3 w, float blur, float bump, float tint) {
  float ch = mix(c2, c1, smoothstep(0.0, 2.0 * blur, stripe));
  float border = w[0];
  ch = mix(ch, c2, smoothstep(border, border + 2.0 * blur, stripe));
  bump = smoothstep(0.2, 0.8, bump);
  border = w[0] + 0.4 * (1.0 - bump) * w[1];
  ch = mix(ch, c1, smoothstep(border, border + 2.0 * blur, stripe));
  border = w[0] + 0.5 * (1.0 - bump) * w[1];
  ch = mix(ch, c2, smoothstep(border, border + 2.0 * blur, stripe));
  border = w[0] + w[1];
  ch = mix(ch, c1, smoothstep(border, border + 2.0 * blur, stripe));
  float gradientT = (stripe - w[0] - w[1]) / w[2];
  float gradient = mix(c1, c2, smoothstep(0.0, 1.0, gradientT));
  ch = mix(ch, gradient, smoothstep(border, border + 0.5 * blur, stripe));
  ch = mix(ch, 1.0 - min(1.0, (1.0 - ch) / max(tint, 0.0001)), u_colorTint.a);
  return ch;
}

float getImgFrame(vec2 uv, float th) {
  float frame = 1.0;
  frame *= smoothstep(0.0, th, uv.y);
  frame *= 1.0 - smoothstep(1.0 - th, 1.0, uv.y);
  frame *= smoothstep(0.0, th, uv.x);
  frame *= 1.0 - smoothstep(1.0 - th, 1.0, uv.x);
  return frame;
}

float blurEdge3x3(sampler2D tex, vec2 uv, vec2 dudx, vec2 dudy, float radius, float centerSample) {
  vec2 texel = 1.0 / vec2(textureSize(tex, 0));
  vec2 r = radius * texel;
  float sum = 4.0 * centerSample;
  sum += 2.0 * textureGrad(tex, uv + vec2(0.0, -r.y), dudx, dudy).r;
  sum += 2.0 * textureGrad(tex, uv + vec2(0.0, r.y), dudx, dudy).r;
  sum += 2.0 * textureGrad(tex, uv + vec2(-r.x, 0.0), dudx, dudy).r;
  sum += 2.0 * textureGrad(tex, uv + vec2(r.x, 0.0), dudx, dudy).r;
  sum += textureGrad(tex, uv + vec2(-r.x, -r.y), dudx, dudy).r;
  sum += textureGrad(tex, uv + vec2(r.x, -r.y), dudx, dudy).r;
  sum += textureGrad(tex, uv + vec2(-r.x, r.y), dudx, dudy).r;
  sum += textureGrad(tex, uv + vec2(r.x, r.y), dudx, dudy).r;
  return sum / 16.0;
}

void main() {
  const float firstFrameOffset = 2.8;
  float t = 0.3 * (u_time + firstFrameOffset);

  vec2 uv = v_imageUV;
  vec2 dudx = dFdx(v_imageUV);
  vec2 dudy = dFdy(v_imageUV);
  vec4 img = textureGrad(u_image, uv, dudx, dudy);

  float cycleWidth = u_repetition;

  vec2 rotatedUV = uv - vec2(0.5);
  float angle = (-u_angle + 70.0) * PI / 180.0;
  float cosA = cos(angle);
  float sinA = sin(angle);
  rotatedUV = vec2(rotatedUV.x * cosA - rotatedUV.y * sinA, rotatedUV.x * sinA + rotatedUV.y * cosA) + vec2(0.5);

  float edge = blurEdge3x3(u_image, uv, dudx, dudy, 6.0, img.r);
  edge = pow(edge, 1.6);
  edge *= smoothstep(0.0, 0.4, u_contour);

  float opacity = img.g * getImgFrame(v_imageUV, 0.0);
  float depth = img.r;

  float diagBLtoTR = rotatedUV.x - rotatedUV.y;
  float diagTLtoBR = rotatedUV.x + rotatedUV.y;

  vec3 color1 = mix(vec3(0.98, 0.98, 1.0), vec3(0.9, 0.9, 0.93), u_light);
  vec3 color2 = vec3(0.1, 0.1, 0.1 + 0.1 * smoothstep(0.7, 1.3, diagTLtoBR));

  vec2 gradUV = uv - 0.5 - u_tilt * vec2(0.18, -0.12);
  float dist = length(gradUV + vec2(0.0, 0.2 * diagBLtoTR));
  gradUV = rotate(gradUV, (0.25 - 0.2 * diagBLtoTR) * PI);
  float direction = gradUV.x;

  float bump = pow(1.8 * dist, 1.2);
  bump = 1.0 - bump;
  bump *= pow(uv.y, 0.3);

  float thinStrip1 = 0.12 / cycleWidth * (1.0 - 0.4 * bump);
  float thinStrip2 = 0.07 / cycleWidth * (1.0 + 0.4 * bump);
  float wideStrip = 1.0 - thinStrip1 - thinStrip2;

  float noise = snoise(uv - t);
  edge += (1.0 - edge) * u_distortion * noise;

  direction += diagBLtoTR;
  direction -= 2.0 * noise * diagBLtoTR * (smoothstep(0.0, 1.0, edge) * (1.0 - smoothstep(0.0, 1.0, edge)));
  direction *= mix(1.0, 1.0 - edge, smoothstep(0.5, 1.0, u_contour));
  direction -= 1.7 * edge * smoothstep(0.5, 1.0, u_contour);
  direction += 0.2 * pow(u_contour, 4.0) * (1.0 - smoothstep(0.0, 1.0, edge));

  bump *= clamp(pow(uv.y, 0.1), 0.3, 1.0);
  direction *= 0.1 + (1.1 - edge) * bump;
  direction *= 0.4 + 0.6 * (1.0 - smoothstep(0.5, 1.0, edge));
  direction += 0.18 * (smoothstep(0.1, 0.2, uv.y) * (1.0 - smoothstep(0.2, 0.4, uv.y)));
  direction += 0.03 * (smoothstep(0.1, 0.2, 1.0 - uv.y) * (1.0 - smoothstep(0.2, 0.4, 1.0 - uv.y)));
  direction *= 0.5 + 0.5 * pow(uv.y, 2.0);
  direction *= cycleWidth;
  direction -= t + dot(u_tilt, vec2(0.35, 0.2));

  float colorDispersion = clamp(1.0 - bump, 0.0, 1.0);
  float dispersionRed = colorDispersion;
  dispersionRed += 0.03 * bump * noise;
  dispersionRed += 5.0 * (smoothstep(-0.1, 0.2, uv.y) * (1.0 - smoothstep(0.1, 0.5, uv.y))) * (smoothstep(0.4, 0.6, bump) * (1.0 - smoothstep(0.4, 1.0, bump)));
  dispersionRed -= diagBLtoTR;

  float dispersionBlue = colorDispersion * 1.3;
  dispersionBlue += (smoothstep(0.0, 0.4, uv.y) * (1.0 - smoothstep(0.1, 0.8, uv.y))) * (smoothstep(0.4, 0.6, bump) * (1.0 - smoothstep(0.4, 0.8, bump)));
  dispersionBlue -= 0.2 * edge;

  dispersionRed *= u_shiftRed / 20.0;
  dispersionBlue *= u_shiftBlue / 20.0;

  float softness = 0.05 * u_softness;
  float blur = softness + 0.5 * smoothstep(1.0, 10.0, u_repetition) * smoothstep(0.0, 1.0, edge);
  float smallCanvas = 1.0 - smoothstep(100.0, 500.0, min(u_resolution.x, u_resolution.y));
  blur += smallCanvas * smoothstep(0.0, 1.0, edge);
  float rExtraBlur = softness * (0.05 + 0.1 * (u_shiftRed / 20.0) * bump);
  float gExtraBlur = softness * 0.05 / max(0.001, abs(1.0 - diagBLtoTR));

  vec3 w = vec3(thinStrip1 * cycleWidth, thinStrip2 * cycleWidth, wideStrip);
  w[1] -= 0.02 * smoothstep(0.0, 1.0, edge + bump);
  float stripeR = fract(direction + dispersionRed);
  float r = getColorChanges(color1.r, color2.r, stripeR, w, blur + fwidth(stripeR) + rExtraBlur, bump, u_colorTint.r);
  float stripeG = fract(direction);
  float g = getColorChanges(color1.g, color2.g, stripeG, w, blur + fwidth(stripeG) + gExtraBlur, bump, u_colorTint.g);
  float stripeB = fract(direction - dispersionBlue);
  float b = getColorChanges(color1.b, color2.b, stripeB, w, blur + fwidth(stripeB), bump, u_colorTint.b);

  vec3 sheen = mix(vec3(1.0), u_colorTint.rgb, 0.45 * u_colorTint.a);
  r *= sheen.r;
  g *= sheen.g;
  b *= sheen.b;

  float rim = smoothstep(0.78, 1.0, depth) * u_light;
  r *= 1.0 - rim * 0.62;
  g *= 1.0 - rim * 0.62;
  b *= 1.0 - rim * 0.58;

  float pour = u_reveal * 1.25 - 0.1;
  opacity *= smoothstep(1.0 - pour, 1.15 - pour, depth) * smoothstep(0.0, 0.25, u_reveal);

  vec3 color = vec3(r, g, b) * opacity;
  vec3 back = u_colorBack.rgb * u_colorBack.a;
  color += back * (1.0 - opacity);
  opacity += u_colorBack.a * (1.0 - opacity);
  color += 1.0 / 256.0 * (fract(sin(dot(0.014 * gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453123) - 0.5);
  fragColor = vec4(color, opacity);
}`;

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const parseColor = (() => {
  let context: CanvasRenderingContext2D | null = null;
  return (value: string, fallback: Rgba): Rgba => {
    if (typeof document === 'undefined') return fallback;
    context ??= document.createElement('canvas').getContext('2d', { willReadFrequently: true });
    if (!context) return fallback;
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = 'rgba(0, 0, 0, 0)';
    context.fillStyle = String(value);
    context.fillRect(0, 0, 1, 1);
    const [r, g, b, a] = context.getImageData(0, 0, 1, 1).data;
    return [r / 255, g / 255, b / 255, a / 255];
  };
})();

const loadImage = (src: string) =>
  new Promise<HTMLImageElement>((resolve, reject) => {
    const image = new Image();
    image.crossOrigin = 'anonymous';
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error('MetallicPaint: failed to load the image'));
    image.src = src;
  });

const isVector = async (src: string): Promise<boolean> => {
  if (/\.svg($|[?#])/i.test(src) || src.startsWith('data:image/svg+xml')) return true;
  if (!src.startsWith('blob:')) return false;
  try {
    const blob = await (await fetch(src)).blob();
    return blob.type === 'image/svg+xml';
  } catch {
    return false;
  }
};

const drawImageSource = async (src: string): Promise<HTMLCanvasElement> => {
  const [image, vector] = await Promise.all([loadImage(src), isVector(src)]);
  let width = image.naturalWidth || image.width || MAX_SIDE;
  let height = image.naturalHeight || image.height || MAX_SIDE;
  const longest = Math.max(width, height);
  const fit = vector ? MAX_SIDE / longest : clamp(1024 / longest, 1, MAX_SIDE / longest);
  width = Math.max(1, Math.round(width * fit));
  height = Math.max(1, Math.round(height * fit));
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d', { willReadFrequently: true }) as CanvasRenderingContext2D;
  ctx.drawImage(image, 0, 0, width, height);
  const data = ctx.getImageData(0, 0, width, height);
  let opaque = true;
  for (let i = 3; i < data.data.length; i += 4) {
    if (data.data[i] < 250) {
      opaque = false;
      break;
    }
  }
  if (opaque) {
    for (let i = 0; i < data.data.length; i += 4) {
      const light = Math.min(data.data[i], data.data[i + 1], data.data[i + 2]);
      data.data[i + 3] = Math.round(clamp((250 - light) / 30, 0, 1) * 255);
    }
    ctx.putImageData(data, 0, 0);
  }
  return canvas;
};

const drawTextSource = async (
  text: string,
  fontFamily: string,
  fontWeight: number | string
): Promise<HTMLCanvasElement | null> => {
  const size = 320;
  const font = `${fontWeight} ${size}px ${fontFamily}`;
  try {
    await document.fonts?.load(font, text);
  } catch {
    return null;
  }
  const probe = document.createElement('canvas').getContext('2d') as CanvasRenderingContext2D;
  probe.font = font;
  const metrics = probe.measureText(text);
  const ascent = metrics.actualBoundingBoxAscent || size * 0.8;
  const descent = metrics.actualBoundingBoxDescent || size * 0.2;
  const left = metrics.actualBoundingBoxLeft || 0;
  const right = metrics.actualBoundingBoxRight || metrics.width;
  const pad = size * 0.12;
  const canvas = document.createElement('canvas');
  canvas.width = Math.ceil(left + right + pad * 2);
  canvas.height = Math.ceil(ascent + descent + pad * 2);
  const ctx = canvas.getContext('2d') as CanvasRenderingContext2D;
  ctx.font = font;
  ctx.fillStyle = '#000';
  ctx.textBaseline = 'alphabetic';
  ctx.fillText(text, pad + left, pad + ascent);
  return canvas;
};

const solvePoisson = (mask: Uint8Array, width: number, height: number) => {
  const interior: number[] = [];
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = y * width + x;
      if (!mask[i]) continue;
      const boundary =
        x === 0 ||
        y === 0 ||
        x === width - 1 ||
        y === height - 1 ||
        !mask[i - 1] ||
        !mask[i + 1] ||
        !mask[i - width] ||
        !mask[i + width] ||
        !mask[i - width - 1] ||
        !mask[i - width + 1] ||
        !mask[i + width - 1] ||
        !mask[i + width + 1];
      if (!boundary) interior.push(i);
    }
  }
  const field = new Float32Array(width * height);
  const red: number[] = [];
  const black: number[] = [];
  interior.forEach(i => (((i % width) + Math.floor(i / width)) % 2 === 0 ? red.push(i) : black.push(i)));
  const relax = (list: number[]) => {
    for (let k = 0; k < list.length; k++) {
      const i = list[k];
      const sum = field[i + 1] + field[i - 1] + field[i - width] + field[i + width];
      field[i] = 1.9 * ((0.01 + sum) / 4) - 0.9 * field[i];
    }
  };
  for (let iteration = 0; iteration < 40; iteration++) {
    relax(red);
    relax(black);
  }
  let peak = 0;
  interior.forEach(i => {
    if (field[i] > peak) peak = field[i];
  });
  return { field, peak: peak || 1 };
};

const processShape = (source: HTMLCanvasElement): ImageData => {
  const width = source.width;
  const height = source.height;
  const fit = WORKING_SIZE / Math.min(width, height);
  const workW = Math.max(2, Math.round(width * fit));
  const workH = Math.max(2, Math.round(height * fit));

  const small = document.createElement('canvas');
  small.width = workW;
  small.height = workH;
  const smallCtx = small.getContext('2d', { willReadFrequently: true }) as CanvasRenderingContext2D;
  smallCtx.drawImage(source, 0, 0, workW, workH);
  const smallData = smallCtx.getImageData(0, 0, workW, workH).data;
  const mask = new Uint8Array(workW * workH);
  for (let i = 0; i < mask.length; i++) mask[i] = smallData[i * 4 + 3] > 0 ? 1 : 0;

  const { field, peak } = solvePoisson(mask, workW, workH);
  const gradient = smallCtx.createImageData(workW, workH);
  for (let i = 0; i < mask.length; i++) {
    const p = i * 4;
    const value = mask[i] ? 255 * (1 - field[i] / peak) : 255;
    gradient.data[p] = value;
    gradient.data[p + 1] = value;
    gradient.data[p + 2] = value;
    gradient.data[p + 3] = mask[i] ? 255 : 0;
  }
  smallCtx.putImageData(gradient, 0, 0);

  const out = document.createElement('canvas');
  out.width = width;
  out.height = height;
  const outCtx = out.getContext('2d', { willReadFrequently: true }) as CanvasRenderingContext2D;
  outCtx.imageSmoothingEnabled = true;
  outCtx.imageSmoothingQuality = 'high';
  outCtx.drawImage(small, 0, 0, workW, workH, 0, 0, width, height);
  const result = outCtx.getImageData(0, 0, width, height);
  const original = (source.getContext('2d', { willReadFrequently: true }) as CanvasRenderingContext2D).getImageData(
    0,
    0,
    width,
    height
  ).data;
  for (let i = 0; i < result.data.length; i += 4) {
    const alpha = original[i + 3];
    if (alpha === 0) {
      result.data[i] = 255;
      result.data[i + 1] = 0;
    } else {
      result.data[i] = result.data[i + 3] === 0 ? 0 : result.data[i];
      result.data[i + 1] = alpha;
    }
    result.data[i + 2] = 255;
    result.data[i + 3] = 255;
  }
  return result;
};

const compile = (gl: WebGL2RenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
};

export default function MetallicPaint({
  imageSrc,
  text,
  fontFamily = 'system-ui, sans-serif',
  fontWeight = 800,
  color = '#ffffff',
  backgroundColor = 'transparent',
  density = 2,
  softness = 0.1,
  dispersion = 0.3,
  distortion = 0.07,
  edgeBend = 0.6,
  angle = 70,
  speed = 1,
  scale = 0.6,
  rotation = 0,
  mouseTilt = 0.5,
  lightMode = false,
  intro = true,
  paused = false,
  dpr,
  className = '',
  style
}: MetallicPaintProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const engineRef = useRef<Engine | null>(null);
  const settingsRef = useRef<Settings>(null as unknown as Settings);

  settingsRef.current = {
    tint: parseColor(color, [1, 1, 1, 1]),
    back: parseColor(backgroundColor, [0, 0, 0, 0]),
    density: clamp(density, 0.5, 12),
    softness: clamp(softness, 0, 1),
    dispersion: clamp(dispersion, -1, 1),
    distortion: clamp(distortion, 0, 1),
    edgeBend: clamp(edgeBend, 0, 1),
    angle,
    speed,
    scale: Math.max(0.05, scale),
    rotation,
    mouseTilt: clamp(mouseTilt, 0, 1.5),
    lightMode,
    intro,
    paused,
    dpr
  };

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return undefined;
    const gl = canvas.getContext('webgl2', { alpha: true, premultipliedAlpha: true, antialias: false });
    if (!gl) return undefined;
    const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
    const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
    const program = gl.createProgram();
    if (!vertex || !fragment || !program) return undefined;
    gl.attachShader(program, vertex);
    gl.attachShader(program, fragment);
    gl.linkProgram(program);
    gl.deleteShader(vertex);
    gl.deleteShader(fragment);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return undefined;
    gl.useProgram(program);

    const uniforms: Record<string, WebGLUniformLocation | null> = {};
    const count = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
    for (let i = 0; i < count; i++) {
      const info = gl.getActiveUniform(program, i);
      if (info) uniforms[info.name] = gl.getUniformLocation(program, info.name);
    }

    const vao = gl.createVertexArray();
    const buffer = gl.createBuffer();
    gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

    const texture = gl.createTexture();
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array([255, 0, 255, 255]));
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.uniform1i(uniforms.u_image, 0);

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const state = {
      raf: 0,
      last: 0,
      time: 0,
      visible: true,
      pending: false,
      hasImage: false,
      imageAspect: 1,
      width: 0,
      height: 0,
      revealStart: -1,
      reveal: settingsRef.current.intro && !reduce ? 0 : 1,
      tiltX: 0,
      tiltY: 0,
      velocityX: 0,
      velocityY: 0,
      targetX: 0,
      targetY: 0,
      alive: true
    };

    const resize = () => {
      const s = settingsRef.current;
      const rect = container.getBoundingClientRect();
      const base = s.dpr ?? Math.min(window.devicePixelRatio || 1, 2);
      let ratio = Math.max(base, 2);
      const pixels = rect.width * rect.height * ratio * ratio;
      if (pixels > MAX_PIXELS) ratio *= Math.sqrt(MAX_PIXELS / pixels);
      const width = Math.max(1, Math.round(rect.width * ratio));
      const height = Math.max(1, Math.round(rect.height * ratio));
      if (width === state.width && height === state.height) return;
      state.width = width;
      state.height = height;
      canvas.width = width;
      canvas.height = height;
      gl.viewport(0, 0, width, height);
    };

    const draw = () => {
      const s = settingsRef.current;
      if (state.pending || !state.hasImage) {
        gl.clearColor(0, 0, 0, 0);
        gl.clear(gl.COLOR_BUFFER_BIT);
        return;
      }
      gl.useProgram(program);
      gl.uniform2f(uniforms.u_resolution, state.width, state.height);
      gl.uniform1f(uniforms.u_time, state.time);
      gl.uniform1f(uniforms.u_imageAspect, state.imageAspect);
      gl.uniform1f(uniforms.u_scale, s.scale);
      gl.uniform1f(uniforms.u_rotation, s.rotation);
      gl.uniform4f(uniforms.u_colorBack, s.back[0], s.back[1], s.back[2], s.back[3]);
      gl.uniform4f(uniforms.u_colorTint, s.tint[0], s.tint[1], s.tint[2], s.tint[3]);
      gl.uniform1f(uniforms.u_softness, s.softness);
      gl.uniform1f(uniforms.u_repetition, s.density);
      gl.uniform1f(uniforms.u_shiftRed, s.dispersion);
      gl.uniform1f(uniforms.u_shiftBlue, s.dispersion);
      gl.uniform1f(uniforms.u_distortion, s.distortion);
      gl.uniform1f(uniforms.u_contour, s.edgeBend);
      gl.uniform1f(uniforms.u_angle, s.angle);
      gl.uniform2f(uniforms.u_tilt, state.tiltX, state.tiltY);
      gl.uniform1f(uniforms.u_reveal, state.reveal);
      gl.uniform1f(uniforms.u_light, s.lightMode ? 1 : 0);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.bindVertexArray(vao);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    };

    const frame = (now: number) => {
      state.raf = 0;
      if (!state.alive) return;
      const s = settingsRef.current;
      const dt = state.last ? Math.min(0.05, (now - state.last) / 1000) : 1 / 60;
      state.last = now;
      const moving = !s.paused && !reduce && s.speed !== 0;
      if (moving) state.time += dt * s.speed;

      let busy = moving;
      if (state.reveal < 1 && !state.pending) {
        if (state.revealStart < 0) state.revealStart = now;
        const progress = clamp((now - state.revealStart) / 1600, 0, 1);
        state.reveal = 1 - (1 - progress) ** 3;
        if (moving) state.time += dt * 2.4 * (1 - progress) ** 2;
        busy = true;
      }

      const stiffness = 60;
      const damping = 14;
      const steps = Math.max(1, Math.ceil(dt / (1 / 240)));
      const h = dt / steps;
      for (let i = 0; i < steps; i++) {
        state.velocityX += (stiffness * (state.targetX * s.mouseTilt - state.tiltX) - damping * state.velocityX) * h;
        state.velocityY += (stiffness * (state.targetY * s.mouseTilt - state.tiltY) - damping * state.velocityY) * h;
        state.tiltX += state.velocityX * h;
        state.tiltY += state.velocityY * h;
      }
      if (
        Math.abs(state.targetX * s.mouseTilt - state.tiltX) > 0.0005 ||
        Math.abs(state.targetY * s.mouseTilt - state.tiltY) > 0.0005 ||
        Math.abs(state.velocityX) + Math.abs(state.velocityY) > 0.0005
      ) {
        busy = true;
      }

      draw();
      if (busy && state.visible) state.raf = requestAnimationFrame(frame);
      else state.last = 0;
    };

    const wake = () => {
      if (!state.raf && state.alive && state.visible) state.raf = requestAnimationFrame(frame);
    };

    const onMove = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      state.targetX = clamp(((event.clientX - rect.left) / rect.width) * 2 - 1, -1.2, 1.2);
      state.targetY = clamp(((event.clientY - rect.top) / rect.height) * 2 - 1, -1.2, 1.2);
      wake();
    };

    const onLeave = () => {
      state.targetX = 0;
      state.targetY = 0;
      wake();
    };

    const resizeObserver = new ResizeObserver(() => {
      resize();
      draw();
    });
    resizeObserver.observe(container);

    const visibility = new IntersectionObserver(entries => {
      state.visible = entries.some(entry => entry.isIntersecting);
      if (state.visible) wake();
    });
    visibility.observe(container);

    const onLost = (event: Event) => {
      event.preventDefault();
      state.alive = false;
      cancelAnimationFrame(state.raf);
    };

    canvas.addEventListener('webglcontextlost', onLost);
    container.addEventListener('pointermove', onMove);
    container.addEventListener('pointerleave', onLeave);

    engineRef.current = {
      setPending: (value: boolean) => {
        state.pending = value;
        draw();
      },
      setImage: (data: ImageData | null) => {
        state.pending = false;
        gl.bindTexture(gl.TEXTURE_2D, texture);
        if (data) {
          gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, data);
          gl.generateMipmap(gl.TEXTURE_2D);
          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
          state.imageAspect = data.width / data.height;
          state.hasImage = true;
        } else {
          gl.texImage2D(
            gl.TEXTURE_2D,
            0,
            gl.RGBA,
            1,
            1,
            0,
            gl.RGBA,
            gl.UNSIGNED_BYTE,
            new Uint8Array([255, 0, 255, 255])
          );
          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
          state.imageAspect = 1;
          state.hasImage = false;
        }
        draw();
        wake();
      },
      wake,
      redraw: () => {
        resize();
        draw();
        wake();
      }
    };

    resize();
    draw();
    wake();

    return () => {
      state.alive = false;
      cancelAnimationFrame(state.raf);
      resizeObserver.disconnect();
      visibility.disconnect();
      canvas.removeEventListener('webglcontextlost', onLost);
      container.removeEventListener('pointermove', onMove);
      container.removeEventListener('pointerleave', onLeave);
      engineRef.current = null;
      gl.deleteTexture(texture);
      gl.deleteBuffer(buffer);
      gl.deleteVertexArray(vao);
      gl.deleteProgram(program);
    };
  }, []);

  useEffect(() => {
    let active = true;
    const source = text ? drawTextSource(text, fontFamily, fontWeight) : imageSrc ? drawImageSource(imageSrc) : null;
    if (!source) {
      engineRef.current?.setImage(null);
      return undefined;
    }
    engineRef.current?.setPending(true);
    source
      .then(canvas => {
        if (!active || !canvas) return;
        const data = processShape(canvas);
        if (active) engineRef.current?.setImage(data);
      })
      .catch(() => {
        if (active) engineRef.current?.setImage(null);
      });
    return () => {
      active = false;
    };
  }, [imageSrc, text, fontFamily, fontWeight]);

  useEffect(() => {
    engineRef.current?.redraw();
  });

  return (
    <div ref={containerRef} className={`relative h-full w-full ${className}`.trim()} style={style}>
      <canvas ref={canvasRef} className="block h-full w-full" />
    </div>
  );
}

'use client';

import React, { useEffect, useRef } from 'react';

export type NoiseBlendMode = 'normal' | 'overlay' | 'soft-light' | 'multiply' | 'screen' | 'difference';

export type NoiseProps = {
  opacity?: number;
  size?: number;
  fps?: number;
  blendMode?: NoiseBlendMode;
  contrast?: number;
  colored?: boolean;
  dust?: number;
  scratches?: number;
  scanlines?: number;
  flicker?: number;
  fixed?: boolean;
  zIndex?: number;
  className?: string;
  style?: React.CSSProperties;
};

const ROOT = 'pointer-events-none absolute inset-0 overflow-hidden';
const FIXED = 'pointer-events-none fixed inset-0 overflow-hidden';
const GRAIN = 'absolute inset-0 bg-repeat [image-rendering:pixelated]';
const DUST = 'absolute inset-0 h-full w-full';
const LINES =
  'absolute inset-0 bg-[repeating-linear-gradient(to_bottom,rgba(0,0,0,0.55)_0,rgba(0,0,0,0.55)_1px,transparent_1px,transparent_3px)]';

const TILE = 256;
const TAU = Math.PI * 2;
const BLENDS: NoiseBlendMode[] = ['normal', 'overlay', 'soft-light', 'multiply', 'screen', 'difference'];

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const generator = (seed: number) => {
  let state = seed >>> 0 || 1;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};

const paintTile = (contrast: number, colored: boolean) => {
  const canvas = document.createElement('canvas');
  canvas.width = TILE;
  canvas.height = TILE;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  const image = ctx.createImageData(TILE, TILE);
  const data = image.data;
  const random = generator(1013904223);
  const range = 0.5 + contrast * 1.1;
  const sample = () => clamp(0.5 + (random() + random() - 1) * range, 0, 1) * 255;
  for (let i = 0; i < data.length; i += 4) {
    const value = sample();
    data[i] = value;
    data[i + 1] = colored ? sample() : value;
    data[i + 2] = colored ? sample() : value;
    data[i + 3] = 255;
  }
  ctx.putImageData(image, 0, 0);
  return canvas;
};

const drawSpeck = (
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
  tone: string,
  alpha: number
) => {
  const lobes = 1 + Math.floor(Math.random() * 3);
  for (let k = 0; k < lobes; k++) {
    const ox = x + (Math.random() - 0.5) * radius * 1.4;
    const oy = y + (Math.random() - 0.5) * radius * 1.4;
    const size = radius * (0.55 + Math.random() * 0.5);
    const fill = ctx.createRadialGradient(ox, oy, 0, ox, oy, size);
    fill.addColorStop(0, `rgba(${tone}, ${alpha})`);
    fill.addColorStop(0.55, `rgba(${tone}, ${alpha * 0.85})`);
    fill.addColorStop(1, `rgba(${tone}, 0)`);
    ctx.fillStyle = fill;
    ctx.beginPath();
    ctx.arc(ox, oy, size, 0, TAU);
    ctx.fill();
  }
};

const drawHair = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
  const x = Math.random() * width;
  const y = Math.random() * height;
  const length = 14 + Math.random() * 46;
  const angle = Math.random() * TAU;
  const bend = (Math.random() - 0.5) * length * 0.9;
  const ex = x + Math.cos(angle) * length;
  const ey = y + Math.sin(angle) * length;
  const cx = (x + ex) / 2 - Math.sin(angle) * bend;
  const cy = (y + ey) / 2 + Math.cos(angle) * bend;
  ctx.strokeStyle = `rgba(16, 12, 9, ${0.4 + Math.random() * 0.35})`;
  ctx.lineWidth = 0.6 + Math.random() * 0.7;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.quadraticCurveTo(cx, cy, ex, ey);
  ctx.stroke();
};

const Noise = ({
  opacity = 0.2,
  size = 1,
  fps = 24,
  blendMode = 'overlay',
  contrast = 0.6,
  colored = false,
  dust = 0,
  scratches = 0,
  scanlines = 0,
  flicker = 0,
  fixed = false,
  zIndex,
  className = '',
  style
}: NoiseProps) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const grainRef = useRef<HTMLDivElement>(null);
  const dustRef = useRef<HTMLCanvasElement>(null);
  const linesRef = useRef<HTMLDivElement>(null);
  const urlRef = useRef('');
  const wakeRef = useRef<(() => void) | null>(null);
  const settings = {
    opacity: clamp(opacity, 0, 1),
    size: Math.max(0.5, size),
    fps: clamp(fps, 0, 60),
    flicker: clamp(flicker, 0, 1),
    dust: clamp(dust, 0, 1),
    scratches: clamp(scratches, 0, 1)
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;
  const blend = BLENDS.includes(blendMode) ? blendMode : 'normal';

  useEffect(() => {
    const grain = grainRef.current;
    if (!grain) return undefined;
    let alive = true;
    const canvas = paintTile(clamp(contrast, 0, 1), colored);
    canvas?.toBlob(blob => {
      if (!alive || !blob) return;
      const previous = urlRef.current;
      urlRef.current = URL.createObjectURL(blob);
      grain.style.backgroundImage = `url("${urlRef.current}")`;
      if (previous) URL.revokeObjectURL(previous);
    });
    return () => {
      alive = false;
    };
  }, [contrast, colored]);

  useEffect(() => {
    const root = rootRef.current;
    const grain = grainRef.current;
    const canvas = dustRef.current;
    const ctx = canvas?.getContext('2d');
    if (!root || !grain || !canvas || !ctx) return undefined;
    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const scratchList: { x: number; age: number; life: number; weight: number; light: boolean; phase: number }[] = [];
    let raf = 0;
    let last = 0;
    let roll = 0;
    let visible = true;
    let alive = true;
    let width = 1;
    let height = 1;

    const paintDust = (s: typeof settings, step: number) => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      if (s.dust <= 0 && s.scratches <= 0 && scratchList.length === 0) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const area = (width * height) / 400000;

      if (s.dust > 0) {
        const specks = Math.round(s.dust * 42 * area * (0.6 + Math.random() * 0.8));
        for (let i = 0; i < specks; i++) {
          const light = Math.random() < 0.3;
          drawSpeck(
            ctx,
            Math.random() * width,
            Math.random() * height,
            0.6 + Math.random() ** 2.5 * 3.4,
            light ? '255, 250, 240' : '18, 14, 10',
            0.6 + Math.random() * 0.35
          );
        }
        const hairs = Math.random() < s.dust * 0.7 ? 1 + Math.floor(Math.random() * s.dust * 2.4) : 0;
        for (let i = 0; i < hairs; i++) drawHair(ctx, width, height);
      }

      if (step) {
        if (scratchList.length < 3 && Math.random() < s.scratches * 0.06) {
          scratchList.push({
            x: Math.random() * width,
            age: 0,
            life: 0.6 + Math.random() * 2.6,
            weight: 0.6 + Math.random() * 0.8,
            light: Math.random() < 0.7,
            phase: Math.random() * TAU
          });
        }
        for (let i = scratchList.length - 1; i >= 0; i--) {
          const scratch = scratchList[i];
          scratch.age += step;
          scratch.x += (Math.random() - 0.5) * 1.2;
          if (scratch.age >= scratch.life) scratchList.splice(i, 1);
        }
      }
      scratchList.forEach(scratch => {
        const fade = Math.min(1, scratch.age / 0.15, (scratch.life - scratch.age) / 0.3);
        const alpha = (0.25 + Math.random() * 0.35) * fade;
        ctx.strokeStyle = scratch.light ? `rgba(255, 252, 245, ${alpha})` : `rgba(14, 11, 8, ${alpha})`;
        ctx.lineWidth = scratch.weight;
        ctx.beginPath();
        for (let y = 0; y <= height; y += 24) {
          const x = scratch.x + Math.sin(y * 0.012 + scratch.phase) * 1.4;
          if (y === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      });
    };

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      width = Math.max(1, root.clientWidth);
      height = Math.max(1, root.clientHeight);
      canvas.width = Math.round(width * dpr);
      canvas.height = Math.round(height * dpr);
      paintDust(settingsRef.current, 0);
    };

    const tick = (now: number) => {
      raf = 0;
      if (!alive) return;
      const s = settingsRef.current;
      const rate = reduce ? 0 : s.fps;
      if (rate > 0 && now - last >= 1000 / rate) {
        const step = last ? Math.min(0.2, (now - last) / 1000) : 1 / rate;
        last = now;
        const span = TILE * s.size;
        grain.style.backgroundPosition = `${(Math.random() * span).toFixed(1)}px ${(Math.random() * span).toFixed(1)}px`;
        grain.style.opacity = String(s.opacity * (1 - s.flicker * Math.random() * 0.7));
        roll = (roll + 1) % 3;
        linesRef.current?.style.setProperty('background-position', `0 ${roll}px`);
        paintDust(s, step);
      }
      if (visible && rate > 0) raf = requestAnimationFrame(tick);
    };

    const wake = () => {
      paintDust(settingsRef.current, 0);
      if (raf || !alive || !visible) return;
      raf = requestAnimationFrame(tick);
    };
    wakeRef.current = wake;

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(root);
    const visibility = new IntersectionObserver(entries => {
      visible = entries.some(entry => entry.isIntersecting);
      if (visible) wake();
    });
    visibility.observe(root);
    resize();
    wake();

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      wakeRef.current = null;
      resizeObserver.disconnect();
      visibility.disconnect();
      if (urlRef.current) URL.revokeObjectURL(urlRef.current);
      urlRef.current = '';
    };
  }, []);

  useEffect(() => {
    wakeRef.current?.();
  });

  return (
    <div
      ref={rootRef}
      className={`${fixed ? FIXED : ROOT}${className ? ` ${className}` : ''}`}
      style={{ zIndex, ...style }}
      aria-hidden="true"
    >
      <div
        ref={grainRef}
        className={GRAIN}
        style={{
          opacity: settings.opacity,
          mixBlendMode: blend,
          backgroundSize: `${TILE * settings.size}px ${TILE * settings.size}px`
        }}
      />
      <canvas ref={dustRef} className={DUST} />
      {scanlines > 0 && (
        <div ref={linesRef} className={LINES} style={{ opacity: clamp(scanlines, 0, 1), mixBlendMode: blend }} />
      )}
    </div>
  );
};

export default Noise;

