'use client';

import React, { useEffect, useRef } from 'react';

const ROOT = 'relative h-full w-full';
const CANVAS = 'pointer-events-none absolute inset-0 block h-full w-full';
const CONTENT = 'relative z-[1] flex h-full w-full items-center justify-center';

const VERTEX = `#version 300 es
in vec2 aPosition;
void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

const SHAPE = `#version 300 es
precision highp float;
uniform vec2 uResolution;
uniform float uDpr;
uniform int uShape;
uniform float uSides;
uniform vec2 uHalf;
uniform float uRadius;
uniform float uRound;
uniform sampler2D uFieldTexture;
uniform vec2 uField;
uniform float uThickness;
uniform float uFill;
uniform float uEchoes;
uniform float uSpacing;
uniform float uAngle;
out vec4 outColor;

const float PI = 3.14159265;

float sdRoundBox(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

float sdPolygon(vec2 p, float r, float n) {
  float an = PI / n;
  vec2 acs = vec2(cos(an), sin(an));
  float bn = mod(atan(p.x, p.y), 2.0 * an) - an;
  p = length(p) * vec2(cos(bn), abs(sin(bn)));
  p -= r * acs;
  p.y += clamp(-p.y, 0.0, r * acs.y);
  return length(p) * sign(p.x);
}

float sdStar(vec2 p, float r, float n, float m) {
  float an = PI / n;
  float en = PI / m;
  vec2 acs = vec2(cos(an), sin(an));
  vec2 ecs = vec2(cos(en), sin(en));
  float bn = mod(atan(p.x, p.y), 2.0 * an) - an;
  p = length(p) * vec2(cos(bn), abs(sin(bn)));
  p -= r * acs;
  p += ecs * clamp(-dot(p, ecs), 0.0, r * acs.y / ecs.y);
  return length(p) * sign(p.x);
}

float shapeDistance(vec2 p) {
  if (uShape < 0) return 1e5;
  float c = cos(uAngle);
  float s = sin(uAngle);
  p = mat2(c, -s, s, c) * p;
  if (uShape == 0) return sdRoundBox(p, uHalf, uRound);
  if (uShape == 1) return length(p) - uRadius;
  if (uShape == 2) return sdPolygon(p, uRadius - uRound, uSides) - uRound;
  if (uShape == 3) return sdStar(p, uRadius - uRound, uSides, mix(2.0, uSides, 0.42)) - uRound;
  vec2 uv = p / (2.0 * uField.x) + 0.5;
  vec2 inside = clamp(uv, 0.0, 1.0);
  float d = texture(uFieldTexture, vec2(inside.x, 1.0 - inside.y)).r * uField.y;
  return d + length((uv - inside) * 2.0 * uField.x);
}

void main() {
  vec2 p = gl_FragCoord.xy / uDpr - 0.5 * uResolution;
  float d = shapeDistance(p);
  float aa = 1.0 / uDpr;
  float hw = 0.5 * uThickness;
  float cover = uFill > 0.5 ? clamp(0.5 - d / aa, 0.0, 1.0) : 0.0;
  for (int i = 0; i < 24; i++) {
    if (float(i) >= uEchoes) break;
    if (uFill > 0.5 && i == 0) continue;
    float x = uFill > 0.5 ? d - float(i) * uSpacing : d + float(i) * uSpacing;
    cover = max(cover, clamp((hw - abs(x)) / aa + 0.5, 0.0, 1.0));
  }
  outColor = vec4(cover, 0.0, 0.0, 1.0);
}`;

const BLUR = `#version 300 es
precision highp float;
uniform sampler2D uSource;
uniform float uLod;
uniform vec2 uStep;
uniform vec2 uScale;
out vec4 outColor;

void main() {
  vec2 size = vec2(textureSize(uSource, int(uLod)));
  vec2 center = gl_FragCoord.xy * uScale;
  float sum = textureLod(uSource, center / size, uLod).r * 6.0;
  sum += textureLod(uSource, (center - uStep) / size, uLod).r * 4.0;
  sum += textureLod(uSource, (center + uStep) / size, uLod).r * 4.0;
  sum += textureLod(uSource, (center - 2.0 * uStep) / size, uLod).r;
  sum += textureLod(uSource, (center + 2.0 * uStep) / size, uLod).r;
  outColor = vec4(sum / 16.0, 0.0, 0.0, 1.0);
}`;

const COMPOSITE = `#version 300 es
precision highp float;
uniform sampler2D uPyramid;
uniform float uMaxLod;
uniform vec2 uResolution;
uniform float uDpr;
uniform float uThickness;
uniform float uFill;
uniform float uEchoes;
uniform float uSpacing;
uniform vec3 uColor;
uniform float uBackdrop;
uniform float uBlur;
uniform vec3 uLens;
uniform vec2 uLensShape;
uniform float uFocus;
uniform float uChroma;
out vec4 outColor;

float bspline(vec2 uv, float lod) {
  vec2 size = vec2(textureSize(uPyramid, int(lod)));
  vec2 st = uv * size - 0.5;
  vec2 i = floor(st);
  vec2 f = st - i;
  vec2 f2 = f * f;
  vec2 f3 = f2 * f;
  vec2 w0 = (1.0 - 3.0 * f + 3.0 * f2 - f3) / 6.0;
  vec2 w1 = (4.0 - 6.0 * f2 + 3.0 * f3) / 6.0;
  vec2 w2 = (1.0 + 3.0 * f + 3.0 * f2 - 3.0 * f3) / 6.0;
  vec2 w3 = f3 / 6.0;
  vec2 g0 = w0 + w1;
  vec2 g1 = w2 + w3;
  vec2 p0 = (i - 0.5 + w1 / g0) / size;
  vec2 p1 = (i + 1.5 + w3 / g1) / size;
  float a = textureLod(uPyramid, p0, lod).r;
  float b = textureLod(uPyramid, vec2(p1.x, p0.y), lod).r;
  float c = textureLod(uPyramid, vec2(p0.x, p1.y), lod).r;
  float d = textureLod(uPyramid, p1, lod).r;
  return g0.y * (g0.x * a + g1.x * b) + g1.y * (g0.x * c + g1.x * d);
}

float blurred(vec2 uv, float sigma) {
  if (sigma <= 0.6) return textureLod(uPyramid, uv, 0.0).r;
  float lod = sigma < 1.7 ? (sigma - 0.6) / 1.1 : log2(sigma / 0.866);
  lod = clamp(lod, 0.0, uMaxLod);
  float base = floor(lod);
  float t = lod - base;
  float a = base < 0.5 ? textureLod(uPyramid, uv, 0.0).r : bspline(uv, base);
  if (t < 0.001) return a;
  return mix(a, bspline(uv, min(base + 1.0, uMaxLod)), t);
}

void main() {
  vec2 texel = 1.0 / vec2(textureSize(uPyramid, 0));
  vec2 uv = gl_FragCoord.xy * texel;
  vec2 p = gl_FragCoord.xy / uDpr - 0.5 * uResolution;
  vec2 toLens = p - uLens.xy;
  float lensDistance = length(toLens);
  float lens = uLens.z * (1.0 - smoothstep(uLensShape.x * (1.0 - uLensShape.y), uLensShape.x, lensDistance));
  float amount = mix(lens, 1.0 - lens, uFocus);
  float sigma = uBlur * amount * uDpr;
  vec2 dir = lensDistance > 0.001 ? toLens / lensDistance : vec2(0.0);
  vec2 split = dir * uChroma * 0.3 * sigma * texel;
  vec3 cover = vec3(
    blurred(uv - split, sigma * (1.0 + uChroma * 0.25)),
    blurred(uv, sigma),
    blurred(uv + split, sigma * (1.0 - uChroma * 0.2))
  );
  if (uFill < 0.5) {
    float spread = sigma / uDpr;
    float reach = uEchoes > 1.5 ? min(spread, uSpacing) : spread;
    cover *= 1.0 + 0.6 * max(reach - 0.5, 0.0) / max(uThickness, 0.5);
  }
  cover = mix(cover, 0.85 + 0.15 * (1.0 - exp((0.85 - cover) / 0.15)), step(0.85, cover));
  float grain = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453) - 0.5;
  cover = clamp(cover + grain / 255.0, 0.0, 1.0);
  float alpha = max(max(cover.r, cover.g), cover.b);
  outColor = vec4(uColor * cover + (alpha - cover) * uBackdrop, alpha);
}`;

export type ShapeBlurShape = 'rect' | 'circle' | 'polygon' | 'star';

export interface ShapeBlurProps {
  shape?: ShapeBlurShape;
  src?: string;
  sides?: number;
  size?: number;
  roundness?: number;
  thickness?: number;
  fill?: boolean;
  echoes?: number;
  spacing?: number;
  color?: string;
  blur?: number;
  lensSize?: number;
  lensSoftness?: number;
  focus?: boolean;
  chroma?: number;
  rotation?: number;
  spin?: number;
  idle?: boolean;
  children?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

type Control = { load: (value: string) => void; wake: () => void };

const SHAPES: ShapeBlurShape[] = ['rect', 'circle', 'polygon', 'star'];
const FIELD = 512;
const PAD = 0.35;
const FAR = 1e20;

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const compile = (gl: WebGL2RenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
};

const link = (gl: WebGL2RenderingContext, vertex: WebGLShader, source: string) => {
  const fragment = compile(gl, gl.FRAGMENT_SHADER, source);
  const program = gl.createProgram();
  if (!fragment || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.bindAttribLocation(program, 0, 'aPosition');
  gl.linkProgram(program);
  gl.deleteShader(fragment);
  if (gl.getProgramParameter(program, gl.LINK_STATUS)) return program;
  gl.deleteProgram(program);
  return null;
};

const locate = (gl: WebGL2RenderingContext, program: WebGLProgram, names: string[]) => {
  const map: Record<string, WebGLUniformLocation | null> = {};
  for (const name of names) map[name] = gl.getUniformLocation(program, name);
  return map;
};

const sweep = (
  grid: Float64Array,
  offset: number,
  stride: number,
  length: number,
  f: Float64Array,
  v: Int32Array,
  z: Float64Array
) => {
  for (let q = 0; q < length; q++) f[q] = grid[offset + q * stride];
  let k = 0;
  v[0] = 0;
  z[0] = -FAR;
  z[1] = FAR;
  for (let q = 1; q < length; q++) {
    let s = (f[q] + q * q - (f[v[k]] + v[k] * v[k])) / (2 * (q - v[k]));
    while (s <= z[k]) {
      k--;
      s = (f[q] + q * q - (f[v[k]] + v[k] * v[k])) / (2 * (q - v[k]));
    }
    k++;
    v[k] = q;
    z[k] = s;
    z[k + 1] = FAR;
  }
  k = 0;
  for (let q = 0; q < length; q++) {
    while (z[k + 1] < q) k++;
    const gap = q - v[k];
    grid[offset + q * stride] = gap * gap + f[v[k]];
  }
};

const distanceTransform = (grid: Float64Array, size: number) => {
  const f = new Float64Array(size);
  const v = new Int32Array(size);
  const z = new Float64Array(size + 1);
  for (let x = 0; x < size; x++) sweep(grid, x, size, size, f, v, z);
  for (let y = 0; y < size; y++) sweep(grid, y * size, 1, size, f, v, z);
};

const buildField = (image: HTMLImageElement) => {
  const raster = document.createElement('canvas');
  raster.width = FIELD;
  raster.height = FIELD;
  const ctx = raster.getContext('2d', { willReadFrequently: true });
  if (!ctx) return null;
  const width = image.naturalWidth || FIELD;
  const height = image.naturalHeight || FIELD;
  const scale = FIELD / (1 + PAD) / Math.max(width, height);
  ctx.drawImage(image, (FIELD - width * scale) / 2, (FIELD - height * scale) / 2, width * scale, height * scale);
  const pixels = ctx.getImageData(0, 0, FIELD, FIELD).data;
  const outside = new Float64Array(FIELD * FIELD);
  const inside = new Float64Array(FIELD * FIELD);
  for (let i = 0; i < FIELD * FIELD; i++) {
    const alpha = pixels[i * 4 + 3] / 255;
    const edge = 0.5 - alpha;
    outside[i] = alpha >= 0.999 ? 0 : alpha <= 0.001 ? FAR : edge > 0 ? edge * edge : 0;
    inside[i] = alpha >= 0.999 ? FAR : alpha <= 0.001 ? 0 : edge < 0 ? edge * edge : 0;
  }
  distanceTransform(outside, FIELD);
  distanceTransform(inside, FIELD);
  const field = new Float32Array(FIELD * FIELD);
  for (let i = 0; i < FIELD * FIELD; i++) field[i] = Math.sqrt(outside[i]) - Math.sqrt(inside[i]);
  return field;
};

const ShapeBlur = ({
  shape = 'rect',
  src,
  sides = 6,
  size = 0.8,
  roundness = 0.2,
  thickness = 2,
  fill = false,
  echoes = 1,
  spacing = 12,
  color = '#ffffff',
  blur = 16,
  lensSize = 0.3,
  lensSoftness = 0.7,
  focus = false,
  chroma = 0.3,
  rotation = 0,
  spin = 0,
  idle = true,
  children,
  className = '',
  style
}: ShapeBlurProps) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const controlRef = useRef<Control | null>(null);
  const settings = {
    shape: Math.max(0, SHAPES.indexOf(shape)),
    src: src || '',
    sides: clamp(Math.round(sides), 3, 12),
    size: clamp(size, 0.05, 1),
    roundness: clamp(roundness, 0, 1),
    thickness: clamp(thickness, 0.5, 40),
    fill,
    echoes: clamp(Math.round(echoes), 1, 24),
    spacing: Math.max(1, spacing),
    color,
    blur: Math.max(0, blur),
    lensSize: clamp(lensSize, 0.02, 2),
    lensSoftness: clamp(lensSoftness, 0, 1),
    focus,
    chroma: clamp(chroma, 0, 1),
    rotation,
    spin,
    idle
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const gl = canvas?.getContext('webgl2', { alpha: true, premultipliedAlpha: true, antialias: false });
    if (!root || !canvas || !gl) return undefined;

    const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
    if (!vertex) return undefined;
    const shapeProgram = link(gl, vertex, SHAPE);
    const blurProgram = link(gl, vertex, BLUR);
    const compositeProgram = link(gl, vertex, COMPOSITE);
    if (!shapeProgram || !blurProgram || !compositeProgram) return undefined;

    const shapeUniforms = locate(gl, shapeProgram, [
      'uResolution',
      'uDpr',
      'uShape',
      'uSides',
      'uHalf',
      'uRadius',
      'uRound',
      'uFieldTexture',
      'uField',
      'uThickness',
      'uFill',
      'uEchoes',
      'uSpacing',
      'uAngle'
    ]);
    const blurUniforms = locate(gl, blurProgram, ['uSource', 'uLod', 'uStep', 'uScale']);
    const compositeUniforms = locate(gl, compositeProgram, [
      'uPyramid',
      'uMaxLod',
      'uResolution',
      'uDpr',
      'uThickness',
      'uFill',
      'uEchoes',
      'uSpacing',
      'uColor',
      'uBackdrop',
      'uBlur',
      'uLens',
      'uLensShape',
      'uFocus',
      'uChroma'
    ]);

    const vao = gl.createVertexArray();
    gl.bindVertexArray(vao);
    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

    const precise = Boolean(gl.getExtension('EXT_color_buffer_float'));
    const format = precise ? gl.R16F : gl.R8;
    const framebuffer = gl.createFramebuffer();

    const fieldTexture = gl.createTexture();
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, fieldTexture);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.R16F, 1, 1, 0, gl.RED, gl.FLOAT, new Float32Array([1e4]));

    const probe = document.createElement('canvas');
    probe.width = 1;
    probe.height = 1;
    const probeCtx = probe.getContext('2d', { willReadFrequently: true });
    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const pointer = { x: 0, y: 0, active: false };
    const lens = { x: 0, y: 0, power: 0, placed: false };
    const pyramid = {
      texture: null as WebGLTexture | null,
      temps: [] as (WebGLTexture | null)[],
      sizes: [] as number[][],
      levels: 0,
      key: ''
    };
    const state = {
      width: 1,
      height: 1,
      dpr: 1,
      time: 0,
      angle: 0,
      color: [1, 1, 1] as number[],
      backdrop: 0,
      colorKey: '',
      image: 'none' as 'none' | 'loading' | 'ready' | 'failed',
      request: 0
    };
    let raf = 0;
    let last = 0;
    let visible = true;
    let alive = true;

    const allocate = () => {
      if (pyramid.texture) gl.deleteTexture(pyramid.texture);
      pyramid.temps.forEach(texture => gl.deleteTexture(texture));
      const width = canvas.width;
      const height = canvas.height;
      pyramid.levels = Math.min(10, Math.floor(Math.log2(Math.max(width, height))) + 1);
      pyramid.sizes = [];
      for (let k = 0; k < pyramid.levels; k++) {
        pyramid.sizes.push([Math.max(1, width >> k), Math.max(1, height >> k)]);
      }
      const configure = () => {
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      };
      pyramid.texture = gl.createTexture();
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, pyramid.texture);
      gl.texStorage2D(gl.TEXTURE_2D, pyramid.levels, format, width, height);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_NEAREST);
      configure();
      pyramid.temps = [null];
      for (let k = 1; k < pyramid.levels; k++) {
        const texture = gl.createTexture();
        gl.bindTexture(gl.TEXTURE_2D, texture);
        gl.texStorage2D(gl.TEXTURE_2D, 1, format, pyramid.sizes[k][0], pyramid.sizes[k - 1][1]);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        configure();
        pyramid.temps.push(texture);
      }
      pyramid.key = '';
    };

    const resolveColor = (value: string) => {
      if (value === state.colorKey) return;
      state.colorKey = value;
      canvas.style.color = value;
      const computed = getComputedStyle(canvas).color;
      canvas.style.color = '';
      if (!probeCtx) return;
      probeCtx.clearRect(0, 0, 1, 1);
      probeCtx.fillStyle = computed;
      probeCtx.fillRect(0, 0, 1, 1);
      const [r, g, b] = probeCtx.getImageData(0, 0, 1, 1).data;
      state.color = [r / 255, g / 255, b / 255];
      state.backdrop = 0.2126 * state.color[0] + 0.7152 * state.color[1] + 0.0722 * state.color[2] < 0.5 ? 1 : 0;
    };

    const wander = (t: number) => {
      const s = settingsRef.current;
      const minHalf = Math.min(state.width, state.height) / 2;
      const inset = (1 - s.size) * minHalf;
      const reachX = s.shape === 0 && !s.src ? state.width / 2 - inset : s.size * minHalf;
      const reachY = s.shape === 0 && !s.src ? state.height / 2 - inset : s.size * minHalf;
      return [
        reachX * (0.75 * Math.sin(t * 0.37) + 0.2 * Math.sin(t * 1.13 + 1.7)),
        reachY * (0.7 * Math.sin(t * 0.53 + 0.9) + 0.2 * Math.cos(t * 0.91 + 0.4))
      ];
    };

    const drawShape = (s: typeof settings) => {
      const { width, height } = state;
      const minHalf = Math.min(width, height) / 2;
      const inset = (1 - s.size) * minHalf;
      const halfX = Math.max(1, width / 2 - inset);
      const halfY = Math.max(1, height / 2 - inset);
      const radius = s.size * minHalf;
      const fieldHalf = radius * (1 + PAD);
      let shapeIndex = s.shape;
      if (s.src) shapeIndex = state.image === 'ready' ? 4 : state.image === 'failed' ? s.shape : -1;
      const round =
        shapeIndex === 0
          ? s.roundness * Math.min(halfX, halfY)
          : s.roundness * radius * (shapeIndex === 3 ? 0.12 : 0.3);
      const angle = ((s.rotation + state.angle) * Math.PI) / 180;
      const key = [
        canvas.width,
        canvas.height,
        shapeIndex,
        s.sides,
        halfX,
        halfY,
        radius,
        round,
        s.thickness,
        s.fill,
        s.echoes,
        s.spacing,
        angle.toFixed(5)
      ].join('|');
      if (key === pyramid.key) return;
      pyramid.key = key;

      gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, pyramid.texture, 0);
      gl.viewport(0, 0, pyramid.sizes[0][0], pyramid.sizes[0][1]);
      gl.useProgram(shapeProgram);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, fieldTexture);
      gl.uniform1i(shapeUniforms.uFieldTexture, 0);
      gl.uniform2f(shapeUniforms.uResolution, width, height);
      gl.uniform1f(shapeUniforms.uDpr, state.dpr);
      gl.uniform1i(shapeUniforms.uShape, shapeIndex);
      gl.uniform1f(shapeUniforms.uSides, s.sides);
      gl.uniform2f(shapeUniforms.uHalf, halfX, halfY);
      gl.uniform1f(shapeUniforms.uRadius, radius);
      gl.uniform1f(shapeUniforms.uRound, round);
      gl.uniform2f(shapeUniforms.uField, fieldHalf, (2 * fieldHalf) / FIELD);
      gl.uniform1f(shapeUniforms.uThickness, s.thickness);
      gl.uniform1f(shapeUniforms.uFill, s.fill ? 1 : 0);
      gl.uniform1f(shapeUniforms.uEchoes, s.echoes);
      gl.uniform1f(shapeUniforms.uSpacing, s.spacing);
      gl.uniform1f(shapeUniforms.uAngle, angle);
      gl.drawArrays(gl.TRIANGLES, 0, 3);

      gl.useProgram(blurProgram);
      gl.uniform1i(blurUniforms.uSource, 0);
      for (let k = 1; k < pyramid.levels; k++) {
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, pyramid.temps[k], 0);
        gl.viewport(0, 0, pyramid.sizes[k][0], pyramid.sizes[k - 1][1]);
        gl.bindTexture(gl.TEXTURE_2D, pyramid.texture);
        gl.uniform1f(blurUniforms.uLod, k - 1);
        gl.uniform2f(blurUniforms.uStep, 1, 0);
        gl.uniform2f(blurUniforms.uScale, 2, 1);
        gl.drawArrays(gl.TRIANGLES, 0, 3);

        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, pyramid.texture, k);
        gl.viewport(0, 0, pyramid.sizes[k][0], pyramid.sizes[k][1]);
        gl.bindTexture(gl.TEXTURE_2D, pyramid.temps[k]);
        gl.uniform1f(blurUniforms.uLod, 0);
        gl.uniform2f(blurUniforms.uStep, 0, 1);
        gl.uniform2f(blurUniforms.uScale, 1, 2);
        gl.drawArrays(gl.TRIANGLES, 0, 3);
      }
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    };

    const render = () => {
      const s = settingsRef.current;
      if (!pyramid.texture) return;
      resolveColor(s.color);
      gl.bindVertexArray(vao);
      gl.disable(gl.BLEND);
      drawShape(s);

      const { width, height } = state;
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.useProgram(compositeProgram);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, pyramid.texture);
      gl.uniform1i(compositeUniforms.uPyramid, 0);
      gl.uniform1f(compositeUniforms.uMaxLod, pyramid.levels - 1);
      gl.uniform2f(compositeUniforms.uResolution, width, height);
      gl.uniform1f(compositeUniforms.uDpr, state.dpr);
      gl.uniform1f(compositeUniforms.uThickness, s.thickness);
      gl.uniform1f(compositeUniforms.uFill, s.fill ? 1 : 0);
      gl.uniform1f(compositeUniforms.uEchoes, s.echoes);
      gl.uniform1f(compositeUniforms.uSpacing, s.spacing);
      gl.uniform3f(compositeUniforms.uColor, state.color[0], state.color[1], state.color[2]);
      gl.uniform1f(compositeUniforms.uBackdrop, state.backdrop);
      gl.uniform1f(compositeUniforms.uBlur, s.blur);
      gl.uniform3f(compositeUniforms.uLens, lens.x, lens.y, lens.power);
      gl.uniform2f(compositeUniforms.uLensShape, s.lensSize * Math.min(width, height), s.lensSoftness);
      gl.uniform1f(compositeUniforms.uFocus, s.focus ? 1 : 0);
      gl.uniform1f(compositeUniforms.uChroma, s.chroma);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    };

    const frame = (now: number) => {
      raf = 0;
      if (!alive || !visible) return;
      const s = settingsRef.current;
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;
      state.time += dt;
      if (!reduce) state.angle = (state.angle + s.spin * dt) % 360;

      const drifting = !pointer.active && s.idle && !reduce;
      let targetX = lens.x;
      let targetY = lens.y;
      let targetPower = 0;
      if (pointer.active) {
        targetX = pointer.x;
        targetY = pointer.y;
        targetPower = 1;
      } else if (drifting) {
        [targetX, targetY] = wander(state.time);
        targetPower = 0.85;
      }
      if (!lens.placed) {
        lens.x = targetX;
        lens.y = targetY;
        lens.placed = true;
      }
      const follow = 1 - Math.exp(-dt * (pointer.active ? 10 : 3));
      lens.x += (targetX - lens.x) * follow;
      lens.y += (targetY - lens.y) * follow;
      lens.power += (targetPower - lens.power) * (1 - Math.exp(-dt * 4));

      render();

      const settled =
        Math.abs(targetX - lens.x) < 0.1 &&
        Math.abs(targetY - lens.y) < 0.1 &&
        Math.abs(targetPower - lens.power) < 0.002;
      if (!settled || drifting || (s.spin && !reduce)) raf = requestAnimationFrame(frame);
      else last = 0;
    };

    const wake = () => {
      if (raf || !alive || !visible) return;
      raf = requestAnimationFrame(frame);
    };

    const load = (value: string) => {
      const request = ++state.request;
      state.image = value ? 'loading' : 'none';
      wake();
      if (!value) return;
      const image = new Image();
      image.crossOrigin = 'anonymous';
      image.onload = () => {
        if (!alive || request !== state.request) return;
        let field: Float32Array | null = null;
        try {
          field = buildField(image);
        } catch {
          field = null;
        }
        if (!field) {
          state.image = 'failed';
          wake();
          return;
        }
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, fieldTexture);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.R16F, FIELD, FIELD, 0, gl.RED, gl.FLOAT, field);
        state.image = 'ready';
        wake();
      };
      image.onerror = () => {
        if (!alive || request !== state.request) return;
        state.image = 'failed';
        wake();
      };
      image.src = value;
    };

    const onPointerMove = (event: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      const margin = settingsRef.current.lensSize * Math.min(rect.width, rect.height);
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;
      pointer.active = x > -margin && y > -margin && x < rect.width + margin && y < rect.height + margin;
      pointer.x = x - rect.width / 2;
      pointer.y = rect.height / 2 - y;
      wake();
    };

    const onPointerLeave = () => {
      pointer.active = false;
      wake();
    };

    const resize = () => {
      state.dpr = Math.min(window.devicePixelRatio || 1, 2);
      state.width = Math.max(1, root.clientWidth);
      state.height = Math.max(1, root.clientHeight);
      canvas.width = Math.round(state.width * state.dpr);
      canvas.height = Math.round(state.height * state.dpr);
      allocate();
      render();
      wake();
    };

    controlRef.current = { load, wake };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(root);
    const visibility = new IntersectionObserver(entries => {
      visible = entries.some(entry => entry.isIntersecting);
      if (visible) {
        last = 0;
        wake();
      }
    });
    visibility.observe(root);
    window.addEventListener('pointermove', onPointerMove, { passive: true });
    document.documentElement.addEventListener('pointerleave', onPointerLeave);
    resize();

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      controlRef.current = null;
      resizeObserver.disconnect();
      visibility.disconnect();
      window.removeEventListener('pointermove', onPointerMove);
      document.documentElement.removeEventListener('pointerleave', onPointerLeave);
      if (pyramid.texture) gl.deleteTexture(pyramid.texture);
      pyramid.temps.forEach(texture => gl.deleteTexture(texture));
      gl.deleteTexture(fieldTexture);
      gl.deleteFramebuffer(framebuffer);
      gl.deleteBuffer(buffer);
      gl.deleteVertexArray(vao);
      gl.deleteProgram(shapeProgram);
      gl.deleteProgram(blurProgram);
      gl.deleteProgram(compositeProgram);
      gl.deleteShader(vertex);
    };
  }, []);

  useEffect(() => {
    controlRef.current?.load(src || '');
  }, [src]);

  useEffect(() => {
    controlRef.current?.wake();
  });

  return (
    <div ref={rootRef} className={`${ROOT}${className ? ` ${className}` : ''}`} style={style}>
      <canvas ref={canvasRef} className={CANVAS} aria-hidden="true" />
      {children && <div className={CONTENT}>{children}</div>}
    </div>
  );
};

export default ShapeBlur;

'use client';

import { useEffect, useRef, useState, type CSSProperties } from 'react';

export interface SplashCursorProps {
  colors?: string[];
  rainbow?: boolean;
  colorSpeed?: number;
  intensity?: number;
  size?: number;
  force?: number;
  swirl?: number;
  trail?: number;
  momentum?: number;
  shading?: number;
  glow?: number;
  quality?: 'low' | 'medium' | 'high';
  clickSplash?: boolean;
  intro?: boolean;
  contained?: boolean;
  theme?: 'dark' | 'light';
  zIndex?: number;
  className?: string;
  style?: CSSProperties;
}

type RGB = [number, number, number];

type Uniforms = Record<string, WebGLUniformLocation | null>;

interface Format {
  internal: number;
  format: number;
}

interface Target {
  texture: WebGLTexture;
  fbo: WebGLFramebuffer;
  width: number;
  height: number;
  texelX: number;
  texelY: number;
  attach: (unit: number) => number;
}

interface DoubleTarget {
  read: Target;
  write: Target;
  width: number;
  height: number;
  texelX: number;
  texelY: number;
  swap: () => void;
}

interface Pointer {
  x: number;
  y: number;
  px: number;
  py: number;
  ready: boolean;
  moved: boolean;
  offset: number;
}

const QUALITY: Record<string, { sim: number; dye: number; iterations: number }> = {
  low: { sim: 64, dye: 512, iterations: 10 },
  medium: { sim: 96, dye: 1024, iterations: 16 },
  high: { sim: 128, dye: 1440, iterations: 20 }
};
const BLOOM_RESOLUTION = 256;
const BLOOM_ITERATIONS = 4;
const BLOOM_THRESHOLD = 0.3;
const BLOOM_KNEE = 0.7;

const ROOT = 'pointer-events-none fixed inset-0 data-[contained]:absolute';
const CANVAS = 'block h-full w-full';

const VERTEX = `#version 300 es
precision highp float;
in vec2 aPosition;
uniform vec2 texelSize;
out vec2 vUv;
out vec2 vL;
out vec2 vR;
out vec2 vT;
out vec2 vB;
void main() {
  vUv = aPosition * 0.5 + 0.5;
  vL = vUv - vec2(texelSize.x, 0.0);
  vR = vUv + vec2(texelSize.x, 0.0);
  vT = vUv + vec2(0.0, texelSize.y);
  vB = vUv - vec2(0.0, texelSize.y);
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

const HEADER = `#version 300 es
precision highp float;
precision highp sampler2D;
in vec2 vUv;
in vec2 vL;
in vec2 vR;
in vec2 vT;
in vec2 vB;
out vec4 outColor;
`;

const SHADERS: Record<string, string> = {
  copy: `uniform sampler2D uTexture;
void main() {
  outColor = texture(uTexture, vUv);
}`,
  clear: `uniform sampler2D uTexture;
uniform float value;
void main() {
  outColor = value * texture(uTexture, vUv);
}`,
  splat: `uniform sampler2D uTarget;
uniform float aspectRatio;
uniform vec3 color;
uniform vec2 pointA;
uniform vec2 pointB;
uniform float radius;
void main() {
  vec2 scale = vec2(aspectRatio, 1.0);
  vec2 pa = (vUv - pointA) * scale;
  vec2 ba = (pointB - pointA) * scale;
  float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-9), 0.0, 1.0);
  vec2 d = pa - ba * h;
  vec3 base = texture(uTarget, vUv).xyz;
  outColor = vec4(base + exp(-dot(d, d) / radius) * color, 1.0);
}`,
  burst: `uniform sampler2D uTarget;
uniform float aspectRatio;
uniform vec2 point;
uniform float radius;
uniform float strength;
uniform float seed;
void main() {
  vec2 d = (vUv - point) * vec2(aspectRatio, 1.0);
  float distance = length(d);
  vec2 direction = d / max(distance, 0.00001);
  float angle = atan(d.y, d.x);
  float petals = 0.78 + 0.22 * sin(angle * 5.0 + seed) * sin(angle * 3.0 - seed * 1.7);
  vec2 twist = vec2(-direction.y, direction.x) * 0.3 * sin(angle * 4.0 + seed * 2.3);
  float falloff = exp(-dot(d, d) / radius) * distance / sqrt(radius);
  outColor = vec4(texture(uTarget, vUv).xy + (direction * petals + twist) * falloff * strength, 0.0, 1.0);
}`,
  crown: `uniform sampler2D uTarget;
uniform float aspectRatio;
uniform vec2 point;
uniform float radius;
uniform vec3 colorA;
uniform vec3 colorB;
uniform float seed;
void main() {
  vec2 d = (vUv - point) * vec2(aspectRatio, 1.0);
  vec3 ink = exp(-dot(d, d) / (radius * 0.45)) * colorA;
  for (int i = 0; i < 7; i++) {
    float index = float(i);
    float angle = seed + index * 0.8975979 + sin(seed * 3.0 + index * 1.9) * 0.35;
    float reach = sqrt(radius) * (0.75 + 0.45 * fract(sin(seed * 7.1 + index * 3.7) * 43.7));
    float drop = radius * (0.08 + 0.12 * fract(sin(seed * 2.9 + index * 5.3) * 31.9));
    vec2 q = d - vec2(cos(angle), sin(angle)) * reach;
    ink += exp(-dot(q, q) / drop) * mix(colorA, colorB, fract(index * 0.37 + 0.2));
  }
  outColor = vec4(texture(uTarget, vUv).xyz + ink, 1.0);
}`,
  advection: `uniform sampler2D uVelocity;
uniform sampler2D uSource;
uniform vec2 texelSize;
uniform float dt;
uniform float dissipation;
void main() {
  vec2 coord = vUv - dt * texture(uVelocity, vUv).xy * texelSize;
  outColor = texture(uSource, coord) / (1.0 + dissipation * dt);
}`,
  divergence: `uniform sampler2D uVelocity;
void main() {
  float L = texture(uVelocity, vL).x;
  float R = texture(uVelocity, vR).x;
  float T = texture(uVelocity, vT).y;
  float B = texture(uVelocity, vB).y;
  vec2 C = texture(uVelocity, vUv).xy;
  if (vL.x < 0.0) L = -C.x;
  if (vR.x > 1.0) R = -C.x;
  if (vT.y > 1.0) T = -C.y;
  if (vB.y < 0.0) B = -C.y;
  outColor = vec4(0.5 * (R - L + T - B), 0.0, 0.0, 1.0);
}`,
  curl: `uniform sampler2D uVelocity;
void main() {
  float L = texture(uVelocity, vL).y;
  float R = texture(uVelocity, vR).y;
  float T = texture(uVelocity, vT).x;
  float B = texture(uVelocity, vB).x;
  outColor = vec4(0.5 * (R - L - T + B), 0.0, 0.0, 1.0);
}`,
  vorticity: `uniform sampler2D uVelocity;
uniform sampler2D uCurl;
uniform float curl;
uniform float dt;
void main() {
  float L = texture(uCurl, vL).x;
  float R = texture(uCurl, vR).x;
  float T = texture(uCurl, vT).x;
  float B = texture(uCurl, vB).x;
  float C = texture(uCurl, vUv).x;
  vec2 force = 0.5 * vec2(abs(T) - abs(B), abs(R) - abs(L));
  force /= length(force) + 0.0001;
  force *= curl * C;
  force.y *= -1.0;
  vec2 velocity = texture(uVelocity, vUv).xy + force * dt;
  outColor = vec4(clamp(velocity, -1000.0, 1000.0), 0.0, 1.0);
}`,
  pressure: `uniform sampler2D uPressure;
uniform sampler2D uDivergence;
void main() {
  float L = texture(uPressure, vL).x;
  float R = texture(uPressure, vR).x;
  float T = texture(uPressure, vT).x;
  float B = texture(uPressure, vB).x;
  float divergence = texture(uDivergence, vUv).x;
  outColor = vec4((L + R + B + T - divergence) * 0.25, 0.0, 0.0, 1.0);
}`,
  gradient: `uniform sampler2D uPressure;
uniform sampler2D uVelocity;
void main() {
  float L = texture(uPressure, vL).x;
  float R = texture(uPressure, vR).x;
  float T = texture(uPressure, vT).x;
  float B = texture(uPressure, vB).x;
  vec2 velocity = texture(uVelocity, vUv).xy - vec2(R - L, T - B);
  outColor = vec4(velocity, 0.0, 1.0);
}`,
  prefilter: `uniform sampler2D uTexture;
uniform vec3 curve;
uniform float threshold;
void main() {
  vec3 c = texture(uTexture, vUv).rgb;
  float br = max(c.r, max(c.g, c.b));
  float rq = clamp(br - curve.x, 0.0, curve.y);
  rq = curve.z * rq * rq;
  c *= max(rq, br - threshold) / max(br, 0.0001);
  outColor = vec4(c, 0.0);
}`,
  blur: `uniform sampler2D uTexture;
uniform float intensity;
void main() {
  vec4 sum = texture(uTexture, vL) + texture(uTexture, vR) + texture(uTexture, vT) + texture(uTexture, vB);
  outColor = sum * 0.25 * intensity;
}`,
  display: `uniform sampler2D uTexture;
uniform sampler2D uBloom;
uniform vec2 texelSize;
uniform float shading;
uniform float bloom;
uniform float light;
float hash(vec2 p) {
  vec3 q = fract(vec3(p.xyx) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}
void main() {
  vec3 c = texture(uTexture, vUv).rgb;
  if (shading > 0.0) {
    float dx = length(texture(uTexture, vR).rgb) - length(texture(uTexture, vL).rgb);
    float dy = length(texture(uTexture, vT).rgb) - length(texture(uTexture, vB).rgb);
    vec3 n = normalize(vec3(dx, dy, length(texelSize)));
    c *= mix(1.0, clamp(n.z + 0.7, 0.7, 1.0), shading);
  }
  if (bloom > 0.0) {
    c += max(texture(uBloom, vUv).rgb, 0.0) * bloom;
  }
  c = max(c, 0.0);
  float peak = max(c.r, max(c.g, c.b));
  float grain = (hash(gl_FragCoord.xy) - 0.5) / 255.0 * smoothstep(0.0, 0.03, peak);
  if (light > 0.5) {
    vec3 transmit = exp(-2.4 * c);
    float low = min(transmit.r, min(transmit.g, transmit.b));
    float alpha = clamp(1.0 - low + grain, 0.0, 1.0);
    outColor = vec4(min(transmit - low, vec3(alpha)), alpha);
  } else {
    c = max(c + grain, 0.0);
    float alpha = clamp(max(c.r, max(c.g, c.b)), 0.0, 1.0);
    outColor = vec4(min(c, vec3(alpha)), alpha);
  }
}`
};

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const parseColor = (value: string): RGB => {
  let hex = String(value).replace('#', '').trim();
  if (hex.length === 3) hex = [...hex].map(char => char + char).join('');
  const number = parseInt(hex.slice(0, 6), 16);
  if (Number.isNaN(number)) return [1, 1, 1];
  return [((number >> 16) & 255) / 255, ((number >> 8) & 255) / 255, (number & 255) / 255];
};

const hsv = (h: number, s: number, v: number): RGB => {
  const i = Math.floor(h * 6);
  const f = h * 6 - i;
  const p = v * (1 - s);
  const q = v * (1 - f * s);
  const t = v * (1 - (1 - f) * s);
  const sector = ((i % 6) + 6) % 6;
  if (sector === 0) return [v, t, p];
  if (sector === 1) return [q, v, p];
  if (sector === 2) return [p, v, t];
  if (sector === 3) return [p, q, v];
  if (sector === 4) return [t, p, v];
  return [v, p, q];
};

function SplashCursor({
  colors = ['#4f8cff', '#2dd4bf', '#ffd166'],
  rainbow = true,
  colorSpeed = 1,
  intensity = 1,
  size = 1,
  force = 1,
  swirl = 3,
  trail = 1,
  momentum = 1,
  shading = 1,
  glow = 0,
  quality = 'high',
  clickSplash = true,
  intro = true,
  contained = false,
  theme = 'dark',
  zIndex = 50,
  className = '',
  style
}: SplashCursorProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [generation, setGeneration] = useState(0);

  const settings = {
    palette: (Array.isArray(colors) && colors.length ? colors : ['#ffffff']).map(parseColor),
    rainbow,
    colorSpeed: Math.max(0, colorSpeed),
    intensity: Math.max(0, intensity),
    size: Math.max(0.05, size),
    force: Math.max(0, force),
    swirl: Math.max(0, swirl),
    trail: Math.max(0.05, trail),
    momentum: Math.max(0.05, momentum),
    shading: clamp(shading, 0, 1),
    glow: clamp(glow, 0, 1),
    quality: QUALITY[quality] ? quality : 'high',
    clickSplash,
    contained,
    light: theme === 'light'
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;
  const introRef = useRef(intro);

  useEffect(() => {
    const parent = rootRef.current?.parentElement;
    if (!contained || !parent || getComputedStyle(parent).position !== 'static') return undefined;
    const previous = parent.style.position;
    parent.style.position = 'relative';
    return () => {
      parent.style.position = previous;
    };
  }, [contained]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;
    const gl = canvas.getContext('webgl2', {
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      preserveDrawingBuffer: false
    });
    if (!gl) return undefined;
    gl.getExtension('EXT_color_buffer_float');
    gl.getExtension('EXT_color_buffer_half_float');

    const renderable = (internal: number, format: number) => {
      const texture = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.texImage2D(gl.TEXTURE_2D, 0, internal, 4, 4, 0, format, gl.HALF_FLOAT, null);
      const fbo = gl.createFramebuffer();
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0);
      const complete = gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE;
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      gl.deleteFramebuffer(fbo);
      gl.deleteTexture(texture);
      return complete;
    };
    const rgba: Format = { internal: gl.RGBA16F, format: gl.RGBA };
    if (!renderable(rgba.internal, rgba.format)) return undefined;
    const rg: Format = renderable(gl.RG16F, gl.RG) ? { internal: gl.RG16F, format: gl.RG } : rgba;
    const r: Format = renderable(gl.R16F, gl.RED) ? { internal: gl.R16F, format: gl.RED } : rg;

    const compile = (type: number, source: string) => {
      const shader = gl.createShader(type) as WebGLShader;
      gl.shaderSource(shader, source);
      gl.compileShader(shader);
      return shader;
    };
    const vertex = compile(gl.VERTEX_SHADER, VERTEX);
    const programs: Record<string, { program: WebGLProgram; uniforms: Uniforms }> = {};
    let broken = false;
    Object.entries(SHADERS).forEach(([name, body]) => {
      const fragment = compile(gl.FRAGMENT_SHADER, HEADER + body);
      const program = gl.createProgram() as WebGLProgram;
      gl.attachShader(program, vertex);
      gl.attachShader(program, fragment);
      gl.bindAttribLocation(program, 0, 'aPosition');
      gl.linkProgram(program);
      gl.deleteShader(fragment);
      if (!gl.getProgramParameter(program, gl.LINK_STATUS)) broken = true;
      const uniforms: Uniforms = {};
      const count = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
      for (let i = 0; i < count; i++) {
        const info = gl.getActiveUniform(program, i);
        if (info) uniforms[info.name] = gl.getUniformLocation(program, info.name);
      }
      programs[name] = { program, uniforms };
    });
    gl.deleteShader(vertex);

    const buffer = gl.createBuffer();
    const vao = gl.createVertexArray();
    gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

    const targets = new Set<Target>();
    let disposed = false;
    let lost = false;

    const release = () => {
      if (gl.isContextLost()) return;
      targets.forEach(target => {
        gl.deleteFramebuffer(target.fbo);
        gl.deleteTexture(target.texture);
      });
      targets.clear();
      Object.values(programs).forEach(item => gl.deleteProgram(item.program));
      gl.deleteBuffer(buffer);
      gl.deleteVertexArray(vao);
    };

    if (broken) {
      release();
      return undefined;
    }

    const use = (name: string) => {
      const item = programs[name];
      gl.useProgram(item.program);
      return item.uniforms;
    };

    const blit = (target: Target | null) => {
      if (target) {
        gl.viewport(0, 0, target.width, target.height);
        gl.bindFramebuffer(gl.FRAMEBUFFER, target.fbo);
      } else {
        gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      }
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    };

    const createTarget = (width: number, height: number, format: Format, filter: number): Target => {
      gl.activeTexture(gl.TEXTURE0);
      const texture = gl.createTexture() as WebGLTexture;
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texImage2D(gl.TEXTURE_2D, 0, format.internal, width, height, 0, format.format, gl.HALF_FLOAT, null);
      const fbo = gl.createFramebuffer() as WebGLFramebuffer;
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0);
      gl.viewport(0, 0, width, height);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      const target = {
        texture,
        fbo,
        width,
        height,
        texelX: 1 / width,
        texelY: 1 / height,
        attach: (unit: number) => {
          gl.activeTexture(gl.TEXTURE0 + unit);
          gl.bindTexture(gl.TEXTURE_2D, texture);
          return unit;
        }
      };
      targets.add(target);
      return target;
    };

    const destroyTarget = (target: Target | null) => {
      if (!target) return;
      gl.deleteFramebuffer(target.fbo);
      gl.deleteTexture(target.texture);
      targets.delete(target);
    };

    const reshape = (target: Target, width: number, height: number, format: Format) => {
      gl.bindTexture(gl.TEXTURE_2D, target.texture);
      gl.texImage2D(gl.TEXTURE_2D, 0, format.internal, width, height, 0, format.format, gl.HALF_FLOAT, null);
      target.width = width;
      target.height = height;
      target.texelX = 1 / width;
      target.texelY = 1 / height;
    };

    const createDouble = (width: number, height: number, format: Format, filter: number) => {
      const pair: DoubleTarget = {
        read: createTarget(width, height, format, filter),
        write: createTarget(width, height, format, filter),
        width,
        height,
        texelX: 1 / width,
        texelY: 1 / height,
        swap: () => {
          const current = pair.read;
          pair.read = pair.write;
          pair.write = current;
        }
      };
      return pair;
    };

    const resizeDouble = (
      pair: DoubleTarget,
      width: number,
      height: number,
      format: Format,
      filter: number,
      keep: boolean
    ) => {
      if (keep) {
        const next = createTarget(width, height, format, filter);
        const u = use('copy');
        gl.uniform1i(u.uTexture, pair.read.attach(0));
        blit(next);
        destroyTarget(pair.read);
        pair.read = next;
      } else {
        reshape(pair.read, width, height, format);
      }
      reshape(pair.write, width, height, format);
      pair.width = width;
      pair.height = height;
      pair.texelX = 1 / width;
      pair.texelY = 1 / height;
    };

    const resolution = (base: number) => {
      const width = gl.drawingBufferWidth;
      const height = gl.drawingBufferHeight;
      const aspect = Math.max(width, height) / Math.max(1, Math.min(width, height));
      const short = Math.round(base);
      const long = Math.round(base * aspect);
      return width > height ? { width: long, height: short } : { width: short, height: long };
    };

    const fit = () => {
      const ratio = Math.min(window.devicePixelRatio || 1, 2);
      const width = Math.max(1, Math.floor(canvas.clientWidth * ratio));
      const height = Math.max(1, Math.floor(canvas.clientHeight * ratio));
      if (canvas.width === width && canvas.height === height) return;
      canvas.width = width;
      canvas.height = height;
    };

    const sizes = () => {
      const q = QUALITY[settingsRef.current.quality];
      const shortSide = Math.min(gl.drawingBufferWidth, gl.drawingBufferHeight);
      return { sim: resolution(q.sim), ink: resolution(Math.max(q.sim, Math.min(q.dye, shortSide))) };
    };

    fit();
    const initial = sizes();
    const dye = createDouble(initial.ink.width, initial.ink.height, rgba, gl.LINEAR);
    const velocity = createDouble(initial.sim.width, initial.sim.height, rg, gl.LINEAR);
    const pressure = createDouble(initial.sim.width, initial.sim.height, r, gl.NEAREST);
    const divergence = createTarget(initial.sim.width, initial.sim.height, r, gl.NEAREST);
    const curl = createTarget(initial.sim.width, initial.sim.height, r, gl.NEAREST);
    let bloom: Target | null = null;
    let bloomChain: Target[] = [];

    const dropBloom = () => {
      destroyTarget(bloom);
      bloomChain.forEach(destroyTarget);
      bloom = null;
      bloomChain = [];
    };

    const ensureBloom = () => {
      if (bloom) return bloom;
      const size = resolution(BLOOM_RESOLUTION);
      const created = createTarget(size.width, size.height, rgba, gl.LINEAR);
      for (let i = 0; i < BLOOM_ITERATIONS; i++) {
        const width = size.width >> (i + 1);
        const height = size.height >> (i + 1);
        if (width < 2 || height < 2) break;
        bloomChain.push(createTarget(width, height, rgba, gl.LINEAR));
      }
      bloom = created;
      return created;
    };

    const resize = () => {
      fit();
      const next = sizes();
      if (dye.width !== next.ink.width || dye.height !== next.ink.height) {
        resizeDouble(dye, next.ink.width, next.ink.height, rgba, gl.LINEAR, true);
      }
      if (velocity.width !== next.sim.width || velocity.height !== next.sim.height) {
        resizeDouble(velocity, next.sim.width, next.sim.height, rg, gl.LINEAR, true);
        resizeDouble(pressure, next.sim.width, next.sim.height, r, gl.NEAREST, false);
        reshape(divergence, next.sim.width, next.sim.height, r);
        reshape(curl, next.sim.width, next.sim.height, r);
      }
      const glowSize = resolution(BLOOM_RESOLUTION);
      if (bloom && (bloom.width !== glowSize.width || bloom.height !== glowSize.height)) dropBloom();
    };

    const radiusFor = (scale: number) => {
      const aspect = canvas.width / canvas.height;
      return ((0.2 * settingsRef.current.size * scale) / 100) * (aspect > 1 ? aspect : 1);
    };

    const splat = (
      ax: number,
      ay: number,
      bx: number,
      by: number,
      vx: number,
      vy: number,
      color: number[],
      radius: number
    ) => {
      const u = use('splat');
      gl.uniform1i(u.uTarget, velocity.read.attach(0));
      gl.uniform1f(u.aspectRatio, canvas.width / canvas.height);
      gl.uniform2f(u.pointA, ax, ay);
      gl.uniform2f(u.pointB, bx, by);
      gl.uniform3f(u.color, vx, vy, 0);
      gl.uniform1f(u.radius, radius);
      blit(velocity.write);
      velocity.swap();
      gl.uniform1i(u.uTarget, dye.read.attach(0));
      gl.uniform3f(u.color, color[0], color[1], color[2]);
      blit(dye.write);
      dye.swap();
    };

    const colorAt = (offset: number, now: number): RGB => {
      const s = settingsRef.current;
      const phase = (((offset + (now / 1000) * s.colorSpeed * 0.6) % 1) + 1) % 1;
      if (s.rainbow) return hsv(phase, 1, 1);
      const palette = s.palette;
      if (palette.length === 1) return palette[0];
      const position = phase * palette.length;
      const from = palette[Math.floor(position) % palette.length];
      const to = palette[(Math.floor(position) + 1) % palette.length];
      const t = position - Math.floor(position);
      const blend = t * t * (3 - 2 * t);
      return [
        from[0] + (to[0] - from[0]) * blend,
        from[1] + (to[1] - from[1]) * blend,
        from[2] + (to[2] - from[2]) * blend
      ];
    };

    const inkFor = (color: RGB, amount: number) =>
      color.map(channel => (settingsRef.current.light ? 1 - channel : channel) * amount);

    const flush = (pointer: Pointer, dt: number, now: number) => {
      const s = settingsRef.current;
      const aspect = canvas.width / canvas.height;
      const length = Math.hypot((pointer.x - pointer.px) * aspect, pointer.y - pointer.py);
      if (length > 0.35) {
        pointer.px = pointer.x;
        pointer.py = pointer.y;
        return;
      }
      let dx = pointer.x - pointer.px;
      let dy = pointer.y - pointer.py;
      if (aspect < 1) dx *= aspect;
      else dy /= aspect;
      const radius = radiusFor(1);
      const spread = 1 + length / (1.77 * Math.sqrt(radius));
      const push = (6000 * s.force) / Math.sqrt(spread);
      const amount = (0.15 * s.intensity * Math.min(dt * 60, 1)) / Math.sqrt(spread);
      const color = inkFor(colorAt(pointer.offset, now), amount);
      splat(pointer.px, pointer.py, pointer.x, pointer.y, dx * push, dy * push, color, radius);
      pointer.px = pointer.x;
      pointer.py = pointer.y;
    };

    const burst = (x: number, y: number, now: number) => {
      const s = settingsRef.current;
      const seed = Math.random() * Math.PI * 2;
      const aspect = canvas.width / canvas.height;
      let u = use('burst');
      gl.uniform1i(u.uTarget, velocity.read.attach(0));
      gl.uniform1f(u.aspectRatio, aspect);
      gl.uniform2f(u.point, x, y);
      gl.uniform1f(u.radius, radiusFor(3));
      gl.uniform1f(u.strength, 1100 * s.force);
      gl.uniform1f(u.seed, seed);
      blit(velocity.write);
      velocity.swap();
      const offset = Math.random();
      const amount = 1.6 * s.intensity;
      const first = inkFor(colorAt(offset, now), amount);
      const second = inkFor(colorAt(offset + 0.3, now), amount);
      u = use('crown');
      gl.uniform1i(u.uTarget, dye.read.attach(0));
      gl.uniform1f(u.aspectRatio, aspect);
      gl.uniform2f(u.point, x, y);
      gl.uniform1f(u.radius, radiusFor(1.6));
      gl.uniform3f(u.colorA, first[0], first[1], first[2]);
      gl.uniform3f(u.colorB, second[0], second[1], second[2]);
      gl.uniform1f(u.seed, seed);
      blit(dye.write);
      dye.swap();
    };

    const step = (dt: number) => {
      const s = settingsRef.current;
      const iterations = QUALITY[s.quality].iterations;
      gl.disable(gl.BLEND);

      let u = use('curl');
      gl.uniform2f(u.texelSize, velocity.texelX, velocity.texelY);
      gl.uniform1i(u.uVelocity, velocity.read.attach(0));
      blit(curl);

      u = use('vorticity');
      gl.uniform2f(u.texelSize, velocity.texelX, velocity.texelY);
      gl.uniform1i(u.uVelocity, velocity.read.attach(0));
      gl.uniform1i(u.uCurl, curl.attach(1));
      gl.uniform1f(u.curl, s.swirl);
      gl.uniform1f(u.dt, dt);
      blit(velocity.write);
      velocity.swap();

      u = use('divergence');
      gl.uniform2f(u.texelSize, velocity.texelX, velocity.texelY);
      gl.uniform1i(u.uVelocity, velocity.read.attach(0));
      blit(divergence);

      u = use('clear');
      gl.uniform1i(u.uTexture, pressure.read.attach(0));
      gl.uniform1f(u.value, 0.1);
      blit(pressure.write);
      pressure.swap();

      u = use('pressure');
      gl.uniform2f(u.texelSize, velocity.texelX, velocity.texelY);
      gl.uniform1i(u.uDivergence, divergence.attach(0));
      for (let i = 0; i < iterations; i++) {
        gl.uniform1i(u.uPressure, pressure.read.attach(1));
        blit(pressure.write);
        pressure.swap();
      }

      u = use('gradient');
      gl.uniform2f(u.texelSize, velocity.texelX, velocity.texelY);
      gl.uniform1i(u.uPressure, pressure.read.attach(0));
      gl.uniform1i(u.uVelocity, velocity.read.attach(1));
      blit(velocity.write);
      velocity.swap();

      u = use('advection');
      gl.uniform2f(u.texelSize, velocity.texelX, velocity.texelY);
      gl.uniform1i(u.uVelocity, velocity.read.attach(0));
      gl.uniform1i(u.uSource, velocity.read.attach(0));
      gl.uniform1f(u.dt, dt);
      gl.uniform1f(u.dissipation, 2 / s.momentum);
      blit(velocity.write);
      velocity.swap();

      gl.uniform1i(u.uVelocity, velocity.read.attach(0));
      gl.uniform1i(u.uSource, dye.read.attach(1));
      gl.uniform1f(u.dissipation, 3.5 / s.trail);
      blit(dye.write);
      dye.swap();
    };

    const applyBloom = (amount: number) => {
      const base = ensureBloom();
      if (!bloomChain.length) return;
      gl.disable(gl.BLEND);
      let u = use('prefilter');
      const knee = BLOOM_THRESHOLD * BLOOM_KNEE + 0.0001;
      gl.uniform3f(u.curve, BLOOM_THRESHOLD - knee, knee * 2, 0.25 / knee);
      gl.uniform1f(u.threshold, BLOOM_THRESHOLD);
      gl.uniform1i(u.uTexture, dye.read.attach(0));
      blit(base);
      u = use('blur');
      gl.uniform1f(u.intensity, 1);
      let last = base;
      bloomChain.forEach(target => {
        gl.uniform2f(u.texelSize, last.texelX, last.texelY);
        gl.uniform1i(u.uTexture, last.attach(0));
        blit(target);
        last = target;
      });
      gl.blendFunc(gl.ONE, gl.ONE);
      gl.enable(gl.BLEND);
      for (let i = bloomChain.length - 2; i >= 0; i--) {
        const target = bloomChain[i];
        gl.uniform2f(u.texelSize, last.texelX, last.texelY);
        gl.uniform1i(u.uTexture, last.attach(0));
        blit(target);
        last = target;
      }
      gl.disable(gl.BLEND);
      gl.uniform1f(u.intensity, amount);
      gl.uniform2f(u.texelSize, last.texelX, last.texelY);
      gl.uniform1i(u.uTexture, last.attach(0));
      blit(base);
    };

    const render = () => {
      const s = settingsRef.current;
      if (s.glow > 0) applyBloom(2 * s.glow);
      gl.disable(gl.BLEND);
      const u = use('display');
      gl.uniform2f(u.texelSize, 1 / gl.drawingBufferWidth, 1 / gl.drawingBufferHeight);
      gl.uniform1i(u.uTexture, dye.read.attach(0));
      gl.uniform1i(u.uBloom, (bloom ?? dye.read).attach(1));
      gl.uniform1f(u.shading, s.shading);
      gl.uniform1f(u.bloom, s.glow > 0 ? 1 : 0);
      gl.uniform1f(u.light, s.light ? 1 : 0);
      blit(null);
    };

    const clearScreen = () => {
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
    };

    const pointers = new Map<string, Pointer>();
    const bursts: { x: number; y: number }[] = [];
    const reduced = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const introPointer: Pointer = { x: 0, y: 0, px: 0, py: 0, ready: false, moved: false, offset: Math.random() };
    let introStart = introRef.current && !reduced ? performance.now() + 150 : -1;
    let raf = 0;
    let last = 0;
    let lastActivity = performance.now();

    const advanceIntro = (now: number) => {
      if (introStart < 0) return;
      const progress = (now - introStart) / 1100;
      if (progress < 0) return;
      const t = Math.min(progress, 1);
      const eased = t * t * (3 - 2 * t);
      const x = 0.2 + 0.6 * eased;
      const y = 0.5 + 0.12 * Math.sin(eased * Math.PI * 2);
      if (!introPointer.ready) {
        introPointer.x = introPointer.px = x;
        introPointer.y = introPointer.py = y;
        introPointer.ready = true;
      } else {
        introPointer.x = x;
        introPointer.y = y;
        introPointer.moved = true;
      }
      if (t >= 1) introStart = -1;
      lastActivity = now;
    };

    const frame = (now: number) => {
      raf = 0;
      if (disposed || lost) return;
      const s = settingsRef.current;
      const dt = clamp((now - last) / 1000, 0, 1 / 60);
      last = now;
      resize();
      advanceIntro(now);
      if (introPointer.moved) {
        introPointer.moved = false;
        flush(introPointer, dt, now);
      }
      pointers.forEach(pointer => {
        if (!pointer.moved) return;
        pointer.moved = false;
        flush(pointer, dt, now);
      });
      bursts.splice(0).forEach(point => burst(point.x, point.y, now));
      step(dt);
      render();
      const quiet = (2.2 * s.trail + 0.4) * 1000;
      if (introStart >= 0 || now - lastActivity < quiet) raf = requestAnimationFrame(frame);
      else clearScreen();
    };

    const wake = () => {
      lastActivity = performance.now();
      if (raf || disposed || lost) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };

    const locate = (clientX: number, clientY: number) => {
      const rect = canvas.getBoundingClientRect();
      if (!rect.width || !rect.height) return null;
      const x = (clientX - rect.left) / rect.width;
      const y = 1 - (clientY - rect.top) / rect.height;
      if (settingsRef.current.contained && (x < 0 || x > 1 || y < 0 || y > 1)) return null;
      return { x, y };
    };

    const track = (id: string, clientX: number, clientY: number) => {
      const point = locate(clientX, clientY);
      let pointer = pointers.get(id);
      if (!point) {
        if (pointer) pointer.ready = false;
        return;
      }
      if (!pointer) {
        pointer = { x: 0, y: 0, px: 0, py: 0, ready: false, moved: false, offset: Math.random() };
        pointers.set(id, pointer);
      }
      if (!pointer.ready) {
        pointer.x = pointer.px = point.x;
        pointer.y = pointer.py = point.y;
        pointer.ready = true;
        return;
      }
      pointer.x = point.x;
      pointer.y = point.y;
      pointer.moved = true;
      wake();
    };

    const press = (clientX: number, clientY: number) => {
      if (!settingsRef.current.clickSplash) return;
      const point = locate(clientX, clientY);
      if (!point) return;
      bursts.push(point);
      wake();
    };

    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerType !== 'touch') track(`p${event.pointerId}`, event.clientX, event.clientY);
    };
    const onPointerDown = (event: PointerEvent) => {
      if (event.pointerType !== 'touch') press(event.clientX, event.clientY);
    };
    const onTouchStart = (event: TouchEvent) => {
      Array.from(event.changedTouches).forEach(touch => {
        pointers.delete(`t${touch.identifier}`);
        track(`t${touch.identifier}`, touch.clientX, touch.clientY);
        press(touch.clientX, touch.clientY);
      });
    };
    const onTouchMove = (event: TouchEvent) => {
      Array.from(event.changedTouches).forEach(touch => track(`t${touch.identifier}`, touch.clientX, touch.clientY));
    };
    const onTouchEnd = (event: TouchEvent) => {
      Array.from(event.changedTouches).forEach(touch => pointers.delete(`t${touch.identifier}`));
    };
    const onLeave = () => {
      pointers.forEach(pointer => {
        pointer.ready = false;
      });
    };
    const onLost = (event: Event) => {
      event.preventDefault();
      lost = true;
      cancelAnimationFrame(raf);
      raf = 0;
    };
    const onRestored = () => setGeneration(value => value + 1);

    window.addEventListener('pointermove', onPointerMove, { passive: true });
    window.addEventListener('pointerdown', onPointerDown, { passive: true });
    window.addEventListener('touchstart', onTouchStart, { passive: true });
    window.addEventListener('touchmove', onTouchMove, { passive: true });
    window.addEventListener('touchend', onTouchEnd, { passive: true });
    window.addEventListener('touchcancel', onTouchEnd, { passive: true });
    document.documentElement.addEventListener('pointerleave', onLeave);
    canvas.addEventListener('webglcontextlost', onLost);
    canvas.addEventListener('webglcontextrestored', onRestored);

    resize();
    if (introStart >= 0) wake();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerdown', onPointerDown);
      window.removeEventListener('touchstart', onTouchStart);
      window.removeEventListener('touchmove', onTouchMove);
      window.removeEventListener('touchend', onTouchEnd);
      window.removeEventListener('touchcancel', onTouchEnd);
      document.documentElement.removeEventListener('pointerleave', onLeave);
      canvas.removeEventListener('webglcontextlost', onLost);
      canvas.removeEventListener('webglcontextrestored', onRestored);
      release();
    };
  }, [generation]);

  return (
    <div
      ref={rootRef}
      className={[ROOT, className].filter(Boolean).join(' ')}
      style={{ zIndex, ...style }}
      data-contained={contained ? '' : undefined}
      aria-hidden="true"
    >
      <canvas ref={canvasRef} className={CANVAS} />
    </div>
  );
}

export default SplashCursor;

'use client';

import React, { useEffect, useRef } from 'react';

export type StarBorderTheme = 'dark' | 'light';

export type StarBorderHover = 'lap' | 'brighten' | 'reveal' | 'none';

type StarBorderOwnProps = {
  children?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  color?: string;
  trailColor?: string;
  duration?: number;
  thickness?: number;
  radius?: number;
  trailLength?: number;
  stars?: number;
  glow?: number;
  sparkle?: boolean;
  direction?: 'clockwise' | 'counterclockwise';
  hover?: StarBorderHover;
  clickPulse?: boolean;
  theme?: StarBorderTheme;
  backgroundColor?: string;
  textColor?: string;
  borderColor?: string;
};

export type StarBorderProps<T extends React.ElementType = 'button'> = StarBorderOwnProps & {
  as?: T;
} & Omit<React.ComponentPropsWithoutRef<T>, keyof StarBorderOwnProps | 'as'>;

type Palette = { surface: string; text: string; track: string; light: string };

type Rgb = [number, number, number];

type Segment = { length: number; x: number; y: number; dx: number; dy: number; angle: number | null };

type Shape = { r: number; segments: Segment[]; total: number };

type Point = { x: number; y: number; nx: number; ny: number };

type Pulse = { origin: number; age: number };

type Mote = { x: number; y: number; vx: number; vy: number; age: number; life: number; size: number; seed: number };

type Settings = {
  light: boolean;
  color: string;
  trailColor: string;
  duration: number;
  thickness: number;
  radius: number;
  trailLength: number;
  stars: number;
  glow: number;
  sparkle: boolean;
  direction: number;
  hover: StarBorderHover;
  clickPulse: boolean;
};

const ROOT =
  "relative isolate m-0 inline-flex items-center justify-center gap-2 rounded-[var(--star-border-radius)] border-0 px-6 py-3.5 font-medium leading-tight no-underline [background:var(--star-border-surface)] text-[color:var(--star-border-text)] [-webkit-tap-highlight-color:transparent] before:pointer-events-none before:absolute before:inset-0 before:-z-1 before:rounded-[inherit] before:shadow-[inset_0_0_0_var(--star-border-thickness)_var(--star-border-track)] before:content-[''] focus-visible:outline-2 focus-visible:outline-offset-3 focus-visible:outline-[color:var(--star-border-track)] disabled:cursor-not-allowed disabled:opacity-50";

const LIGHT = 'pointer-events-none absolute top-[-48px] left-[-48px] -z-1 h-[calc(100%+96px)] w-[calc(100%+96px)]';

const THEMES: Record<StarBorderTheme, Palette> = {
  dark: {
    surface: '#0c0c0f',
    text: '#fafafa',
    track: 'rgba(255, 255, 255, 0.1)',
    light: '#ffffff'
  },
  light: {
    surface: '#ffffff',
    text: '#18181b',
    track: 'rgba(24, 24, 27, 0.12)',
    light: '#18181b'
  }
};

const HOVERS: StarBorderHover[] = ['lap', 'brighten', 'reveal', 'none'];
const BLEED = 48;
const LAP = 0.9;
const TAU = Math.PI * 2;
const WHITE: Rgb = [255, 255, 255];

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const wrap = (value: number, total: number) => ((value % total) + total) % total;
const ease = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - (2 - 2 * t) ** 3 / 2);
const mix = (a: Rgb, b: Rgb, t: number): Rgb => [
  a[0] + (b[0] - a[0]) * t,
  a[1] + (b[1] - a[1]) * t,
  a[2] + (b[2] - a[2]) * t
];
const rgba = (rgb: Rgb, alpha: number) =>
  `rgba(${Math.round(rgb[0])}, ${Math.round(rgb[1])}, ${Math.round(rgb[2])}, ${clamp(alpha, 0, 1).toFixed(3)})`;

let colorContext: CanvasRenderingContext2D | null = null;

const toRgb = (color: string): Rgb => {
  colorContext = colorContext ?? document.createElement('canvas').getContext('2d');
  if (!colorContext) return WHITE;
  colorContext.fillStyle = '#000000';
  colorContext.fillStyle = color;
  const value = String(colorContext.fillStyle);
  if (value.startsWith('#')) {
    const hex = parseInt(value.slice(1, 7), 16);
    return [(hex >> 16) & 255, (hex >> 8) & 255, hex & 255];
  }
  const parts = value.match(/[\d.]+/g)?.map(Number) ?? WHITE;
  return [parts[0], parts[1], parts[2]];
};

const outline = (width: number, height: number, radius: number): Shape => {
  const r = Math.max(0, Math.min(radius, width / 2, height / 2));
  const arc = (Math.PI * r) / 2;
  const across = Math.max(0, width - 2 * r);
  const down = Math.max(0, height - 2 * r);
  const segments: Segment[] = [
    { length: across, x: r, y: 0, dx: 1, dy: 0, angle: null },
    { length: arc, x: width - r, y: r, dx: 0, dy: 0, angle: -Math.PI / 2 },
    { length: down, x: width, y: r, dx: 0, dy: 1, angle: null },
    { length: arc, x: width - r, y: height - r, dx: 0, dy: 0, angle: 0 },
    { length: across, x: width - r, y: height, dx: -1, dy: 0, angle: null },
    { length: arc, x: r, y: height - r, dx: 0, dy: 0, angle: Math.PI / 2 },
    { length: down, x: 0, y: height - r, dx: 0, dy: -1, angle: null },
    { length: arc, x: r, y: r, dx: 0, dy: 0, angle: Math.PI }
  ];
  return {
    r,
    segments,
    total: Math.max(
      1,
      segments.reduce((sum, segment) => sum + segment.length, 0)
    )
  };
};

const pointAt = (shape: Shape, distance: number, point: Point) => {
  let s = wrap(distance, shape.total);
  for (const segment of shape.segments) {
    if (segment.length > 0 && s <= segment.length) {
      if (segment.angle === null) {
        point.x = segment.x + segment.dx * s;
        point.y = segment.y + segment.dy * s;
        point.nx = segment.dy;
        point.ny = -segment.dx;
      } else {
        const angle = segment.angle + s / shape.r;
        point.nx = Math.cos(angle);
        point.ny = Math.sin(angle);
        point.x = segment.x + point.nx * shape.r;
        point.y = segment.y + point.ny * shape.r;
      }
      return point;
    }
    s -= segment.length;
  }
  return point;
};

const project = (shape: Shape, px: number, py: number) => {
  let best = Infinity;
  let found = 0;
  let offset = 0;
  shape.segments.forEach(segment => {
    if (segment.length > 0) {
      let s = 0;
      let x = 0;
      let y = 0;
      if (segment.angle === null) {
        s = clamp((px - segment.x) * segment.dx + (py - segment.y) * segment.dy, 0, segment.length);
        x = segment.x + segment.dx * s;
        y = segment.y + segment.dy * s;
      } else {
        let angle = wrap(Math.atan2(py - segment.y, px - segment.x) - segment.angle, TAU);
        if (angle > Math.PI / 2) angle = angle > Math.PI * 1.25 ? 0 : Math.PI / 2;
        s = angle * shape.r;
        x = segment.x + Math.cos(segment.angle + angle) * shape.r;
        y = segment.y + Math.sin(segment.angle + angle) * shape.r;
      }
      const distance = (px - x) ** 2 + (py - y) ** 2;
      if (distance < best) {
        best = distance;
        found = offset + s;
      }
    }
    offset += segment.length;
  });
  return found;
};

const StarBorder = <T extends React.ElementType = 'button'>({
  as,
  children,
  className = '',
  style,
  color,
  trailColor,
  duration = 4,
  thickness = 1,
  radius = 12,
  trailLength = 0.3,
  stars = 1,
  glow = 0.6,
  sparkle = false,
  direction = 'clockwise',
  hover = 'lap',
  clickPulse = true,
  theme = 'dark',
  backgroundColor,
  textColor,
  borderColor,
  ...rest
}: StarBorderProps<T>) => {
  const tag = as || 'button';
  const Component = tag as unknown as React.FC<Record<string, unknown>>;
  const rootRef = useRef<HTMLElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wakeRef = useRef<(() => void) | null>(null);
  const palette = THEMES[theme] ?? THEMES.dark;
  const light = color ?? palette.light;
  const settings: Settings = {
    light: theme === 'light',
    color: light,
    trailColor: trailColor ?? light,
    duration: Math.max(0.3, duration),
    thickness: Math.max(0.5, thickness),
    radius: Math.max(0, radius),
    trailLength: clamp(trailLength, 0, 1),
    stars: clamp(Math.round(stars), 1, 6),
    glow: clamp(glow, 0, 1),
    sparkle,
    direction: direction === 'counterclockwise' ? -1 : 1,
    hover: HOVERS.includes(hover) ? hover : 'lap',
    clickPulse
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!root || !canvas || !ctx) return undefined;

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const point: Point = { x: 0, y: 0, nx: 0, ny: -1 };
    const state = {
      width: 0,
      height: 0,
      dpr: 1,
      phase: 0,
      velocity: 0,
      motion: 0,
      lap: -1,
      time: 0,
      reveal: 0,
      boost: 0,
      flash: 0,
      emit: 0,
      hovered: false,
      focused: false,
      pointerX: 0,
      pointerY: 0,
      visible: true
    };
    const pulses: Pulse[] = [];
    const dust: Mote[] = [];
    const colors = { key: '', head: WHITE, tail: WHITE };
    let raf = 0;
    let last = performance.now();
    let alive = true;

    const measure = () => {
      state.width = root.offsetWidth;
      state.height = root.offsetHeight;
      state.dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round((state.width + BLEED * 2) * state.dpr));
      canvas.height = Math.max(1, Math.round((state.height + BLEED * 2) * state.dpr));
      wake();
    };

    const local = (event: MouseEvent): [number, number] => {
      const rect = root.getBoundingClientRect();
      const scaleX = rect.width ? state.width / rect.width : 1;
      const scaleY = rect.height ? state.height / rect.height : 1;
      return [(event.clientX - rect.left) * scaleX, (event.clientY - rect.top) * scaleY];
    };

    const shapeFor = (s: Settings) =>
      outline(
        Math.max(1, state.width - s.thickness),
        Math.max(1, state.height - s.thickness),
        s.radius - s.thickness / 2
      );

    const stroke = (x1: number, y1: number, x2: number, y2: number, width: number, style: string | CanvasGradient) => {
      ctx.lineWidth = width;
      ctx.strokeStyle = style;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
    };

    const drawTrail = (
      s: Settings,
      shape: Shape,
      head: number,
      length: number,
      sign: number,
      intensity: number,
      tip = true
    ) => {
      if (length < 0.5 || intensity <= 0) return;
      const steps = clamp(Math.ceil(length / 2), 2, 90);
      pointAt(shape, head, point);
      let px = point.x;
      let py = point.y;
      for (let i = 1; i <= steps; i++) {
        pointAt(shape, head - sign * length * (i / steps), point);
        const u = 1 - (i - 0.5) / steps;
        const fade = u * u * intensity;
        let tone = mix(colors.tail, colors.head, u);
        if (!s.light) tone = mix(tone, WHITE, u ** 6 * 0.65);
        ctx.lineCap = tip && i === 1 ? 'round' : 'butt';
        stroke(px, py, point.x, point.y, 2 + 6 * s.glow, rgba(tone, fade * (s.light ? 0.1 : 0.2) * s.glow));
        stroke(px, py, point.x, point.y, s.thickness, rgba(tone, fade));
        px = point.x;
        py = point.y;
      }
    };

    const drawHead = (s: Settings, x: number, y: number, intensity: number, twinkle: number) => {
      if (intensity <= 0) return;
      const tone = colors.head;
      const reach = (12 + 40 * s.glow) * (s.light ? 0.6 : 1);
      const bloom = ctx.createRadialGradient(x, y, 0, x, y, reach);
      const strength = (s.light ? 0.08 : 0.4) * s.glow * intensity;
      bloom.addColorStop(0, rgba(tone, strength));
      bloom.addColorStop(0.2, rgba(tone, strength * 0.4));
      bloom.addColorStop(0.5, rgba(tone, strength * 0.1));
      bloom.addColorStop(1, rgba(tone, 0));
      ctx.fillStyle = bloom;
      ctx.fillRect(x - reach, y - reach, reach * 2, reach * 2);
      if (!s.sparkle) return;

      const size = (1 + s.thickness * 0.6) * (s.light ? 0.85 : 1);
      const core = ctx.createRadialGradient(x, y, 0, x, y, size * 2.2);
      core.addColorStop(0, rgba(s.light ? tone : WHITE, intensity));
      core.addColorStop(s.light ? 0.3 : 0.4, rgba(s.light ? tone : mix(tone, WHITE, 0.5), intensity * 0.9));
      core.addColorStop(s.light ? 0.55 : 1, rgba(tone, s.light ? intensity * 0.12 : 0));
      core.addColorStop(1, rgba(tone, 0));
      ctx.fillStyle = core;
      ctx.beginPath();
      ctx.arc(x, y, size * 2.2, 0, TAU);
      ctx.fill();

      const spike = (3 + 4 * s.glow + s.thickness * 1.5) * twinkle;
      const center = s.light ? tone : WHITE;
      const horizontal = ctx.createLinearGradient(x - spike, y, x + spike, y);
      horizontal.addColorStop(0, rgba(tone, 0));
      horizontal.addColorStop(0.5, rgba(center, intensity * 0.95));
      horizontal.addColorStop(1, rgba(tone, 0));
      stroke(x - spike, y, x + spike, y, s.light ? 0.75 : 1, horizontal);
      const vertical = ctx.createLinearGradient(x, y - spike, x, y + spike);
      vertical.addColorStop(0, rgba(tone, 0));
      vertical.addColorStop(0.5, rgba(center, intensity * 0.95));
      vertical.addColorStop(1, rgba(tone, 0));
      stroke(x, y - spike, x, y + spike, s.light ? 0.75 : 1, vertical);
    };

    const spawnDust = (x: number, y: number, nx: number, ny: number, speed: number) => {
      if (dust.length > 48) return;
      const push = 3 + Math.random() * 10;
      const drift = (Math.random() - 0.5) * 8;
      dust.push({
        x: x + nx * (Math.random() * 3 - 1),
        y: y + ny * (Math.random() * 3 - 1),
        vx: nx * push - ny * drift - speed * -ny * 0.04,
        vy: ny * push + nx * drift - speed * nx * 0.04,
        age: 0,
        life: 0.35 + Math.random() * 0.5,
        size: 0.45 + Math.random() * 0.7,
        seed: Math.random() * TAU
      });
    };

    const draw = (base: Settings, shape: Shape) => {
      const s = state.boost > 0.001 ? { ...base, glow: Math.min(1.5, base.glow + 0.4 * state.boost) } : base;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      if (state.width < 2 || state.height < 2) return;
      const offset = (BLEED + s.thickness / 2) * state.dpr;
      ctx.setTransform(state.dpr, 0, 0, state.dpr, offset, offset);
      ctx.globalCompositeOperation = s.light ? 'source-over' : 'lighter';
      ctx.lineCap = 'butt';

      const total = shape.total;
      const spacing = total / s.stars;
      const speed = Math.abs(state.motion);
      const sign = state.motion >= 0 ? 1 : -1;
      const span = s.trailLength * s.duration;
      const length = Math.min(speed * span, spacing * 0.92, total * 0.6);
      const intensity = state.reveal * (1 + 0.4 * state.boost + 0.6 * state.flash);

      const ring = state.flash * (s.light ? 0.18 : 0.32) + state.boost * state.reveal * (s.light ? 0.07 : 0.12);
      if (ring > 0.005) {
        ctx.lineWidth = s.thickness + 2 * s.glow;
        ctx.strokeStyle = rgba(colors.head, ring);
        ctx.beginPath();
        ctx.roundRect(
          0,
          0,
          Math.max(1, state.width - s.thickness),
          Math.max(1, state.height - s.thickness),
          Math.max(0, shape.r)
        );
        ctx.stroke();
      }

      const still = clamp(1 - speed / Math.max(1, (total / s.duration) * 0.6), 0, 1) * Math.min(1, intensity);
      const rest = (10 + 14 * s.glow + s.thickness * 2) * still;
      for (let i = 0; i < s.stars; i++) {
        const head = state.phase + i * spacing;
        drawTrail(s, shape, head, length, sign, Math.min(1, intensity));
        if (still > 0.01) {
          drawTrail(s, shape, head, rest, 1, still, false);
          drawTrail(s, shape, head, rest, -1, still, false);
        }
      }

      pulses.forEach(pulse => {
        const progress = pulse.age / 0.65;
        const fade = (1 - progress) ** 2;
        const travel = (total / 2) * (1 - (1 - Math.min(1, pulse.age / 0.5)) ** 2);
        const tail = Math.min(travel, total * 0.16);
        [1, -1].forEach(way => {
          const front = pulse.origin + way * travel;
          drawTrail(s, shape, front, tail, way, fade);
          pointAt(shape, front, point);
          drawHead(s, point.x, point.y, fade * 0.8, 0.8);
        });
      });

      for (let i = 0; i < s.stars; i++) {
        pointAt(shape, state.phase + i * spacing, point);
        const twinkle = 0.82 + 0.18 * Math.sin(state.time * 6.1 + i * 2.3) * Math.sin(state.time * 2.7 + i);
        drawHead(s, point.x, point.y, Math.min(1.3, intensity), twinkle);
      }

      dust.forEach(mote => {
        const left = 1 - mote.age / mote.life;
        const shimmer = 0.45 + 0.55 * Math.sin(state.time * 20 + mote.seed);
        const alpha = left * shimmer * state.reveal * (s.light ? 0.35 : 0.9);
        if (alpha <= 0.01) return;
        ctx.fillStyle = rgba(s.light ? colors.head : mix(colors.tail, WHITE, 0.6), alpha);
        ctx.beginPath();
        ctx.arc(mote.x, mote.y, mote.size * (0.6 + 0.4 * left), 0, TAU);
        ctx.fill();
      });
    };

    const frame = (now: number) => {
      raf = 0;
      if (!alive) return;
      const s = settingsRef.current;
      const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000));
      last = now;
      state.time += dt;

      const key = `${s.color}|${s.trailColor}`;
      if (key !== colors.key) {
        colors.key = key;
        colors.head = toRgb(s.color);
        colors.tail = toRgb(s.trailColor);
      }

      const shape = shapeFor(s);
      const total = shape.total;
      const spacing = total / s.stars;
      const engaged = state.hovered || state.focused;
      const cruise = reduce ? 0 : (s.direction * total) / s.duration;

      const revealTarget = s.hover === 'reveal' && !engaged ? 0 : 1;
      state.reveal += (revealTarget - state.reveal) * (1 - Math.exp(-dt / (revealTarget > state.reveal ? 0.16 : 0.45)));
      const boostTarget = s.hover === 'brighten' && engaged ? 1 : 0;
      state.boost += (boostTarget - state.boost) * (1 - Math.exp(-dt / (boostTarget > state.boost ? 0.18 : 0.5)));
      state.flash *= Math.exp(-dt / 0.22);

      state.velocity += (cruise - state.velocity) * (1 - Math.exp(-dt / 0.45));
      let extra = 0;
      if (state.lap >= 0) {
        const before = ease(Math.min(1, state.lap / LAP));
        state.lap += dt;
        extra = (ease(Math.min(1, state.lap / LAP)) - before) * total * s.direction;
        if (state.lap >= LAP) state.lap = -1;
      }
      state.motion = state.velocity + extra / dt;
      state.phase = wrap(state.phase + state.velocity * dt + extra, total);

      const pace = Math.abs(state.motion) / Math.max(1, Math.abs(total / s.duration));
      if (s.sparkle && !reduce && state.reveal > 0.05) {
        state.emit += dt * (2 + 6 * Math.min(2, pace)) * s.stars;
        while (state.emit > 1) {
          state.emit -= 1;
          pointAt(shape, state.phase + Math.floor(Math.random() * s.stars) * spacing, point);
          spawnDust(point.x, point.y, point.nx, point.ny, state.motion);
        }
      }
      for (let i = dust.length - 1; i >= 0; i--) {
        const mote = dust[i];
        mote.age += dt;
        mote.x += mote.vx * dt;
        mote.y += mote.vy * dt;
        mote.vx *= Math.exp(-dt * 2.2);
        mote.vy *= Math.exp(-dt * 2.2);
        if (mote.age >= mote.life) dust.splice(i, 1);
      }
      for (let i = pulses.length - 1; i >= 0; i--) {
        pulses[i].age += dt;
        if (pulses[i].age >= 0.65) pulses.splice(i, 1);
      }

      draw(s, shape);

      const settling =
        Math.abs(revealTarget - state.reveal) > 0.002 ||
        Math.abs(boostTarget - state.boost) > 0.002 ||
        state.flash > 0.01 ||
        pulses.length > 0 ||
        dust.length > 0;
      const moving = Math.abs(state.motion) > 0.05 || cruise !== 0 || state.lap >= 0;
      const showing = state.reveal > 0.002 || revealTarget > 0;
      if (state.visible && (settling || (moving && showing) || state.hovered)) raf = requestAnimationFrame(frame);
    };

    const wake = () => {
      if (raf || !alive || !state.visible) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };
    wakeRef.current = wake;

    const onEnter = (event: PointerEvent) => {
      const s = settingsRef.current;
      [state.pointerX, state.pointerY] = local(event);
      state.hovered = true;
      if (s.hover === 'reveal' && state.reveal < 0.15) {
        state.phase = project(shapeFor(s), state.pointerX - s.thickness / 2, state.pointerY - s.thickness / 2);
        state.velocity = 0;
      }
      if (s.hover === 'lap' && state.lap < 0 && !reduce) state.lap = 0;
      wake();
    };
    const onLeave = () => {
      state.hovered = false;
      wake();
    };
    const pulse = (origin: number) => {
      if (!settingsRef.current.clickPulse) return;
      pulses.push({ origin, age: 0 });
      if (pulses.length > 4) pulses.shift();
      state.flash = 1;
      wake();
    };
    const onDown = (event: PointerEvent) => {
      if (event.button !== 0 && event.pointerType === 'mouse') return;
      const s = settingsRef.current;
      const [x, y] = local(event);
      pulse(project(shapeFor(s), x - s.thickness / 2, y - s.thickness / 2));
    };
    const onClick = (event: MouseEvent) => {
      if (event.detail === 0) pulse(state.phase);
    };
    const onFocus = () => {
      state.focused = root.matches(':focus-visible');
      if (state.focused && settingsRef.current.hover === 'lap' && state.lap < 0 && !reduce) state.lap = 0;
      wake();
    };
    const onBlur = () => {
      state.focused = false;
      wake();
    };

    const resizeObserver = new ResizeObserver(measure);
    resizeObserver.observe(root);
    const visibility = new IntersectionObserver(entries => {
      state.visible = entries.some(entry => entry.isIntersecting);
      if (state.visible) wake();
    });
    visibility.observe(root);
    root.addEventListener('pointerenter', onEnter);
    root.addEventListener('pointerleave', onLeave);
    root.addEventListener('pointerdown', onDown);
    root.addEventListener('click', onClick);
    root.addEventListener('focus', onFocus);
    root.addEventListener('blur', onBlur);
    measure();

    return () => {
      alive = false;
      wakeRef.current = null;
      cancelAnimationFrame(raf);
      resizeObserver.disconnect();
      visibility.disconnect();
      root.removeEventListener('pointerenter', onEnter);
      root.removeEventListener('pointerleave', onLeave);
      root.removeEventListener('pointerdown', onDown);
      root.removeEventListener('click', onClick);
      root.removeEventListener('focus', onFocus);
      root.removeEventListener('blur', onBlur);
    };
  }, []);

  useEffect(() => {
    wakeRef.current?.();
  });

  return (
    <Component
      ref={rootRef}
      className={`${ROOT}${tag === 'button' || tag === 'a' ? ' cursor-pointer' : ''}${className ? ` ${className}` : ''}`}
      style={
        {
          '--star-border-radius': `${settings.radius}px`,
          '--star-border-thickness': `${settings.thickness}px`,
          '--star-border-surface': backgroundColor ?? palette.surface,
          '--star-border-text': textColor ?? palette.text,
          '--star-border-track': borderColor ?? palette.track,
          ...style
        } as React.CSSProperties
      }
      {...(tag === 'button' && (rest as { type?: string }).type === undefined ? { type: 'button' } : null)}
      {...rest}
    >
      <canvas ref={canvasRef} className={LIGHT} aria-hidden="true" />
      {children}
    </Component>
  );
};

export default StarBorder;

'use client';

import { useEffect, useRef, type CSSProperties, type HTMLAttributes } from 'react';

export type StickerFinish = 'gloss' | 'matte' | 'holo';

export interface StickerPeelProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'style' | 'draggable' | 'onDragStart' | 'onDragEnd'> {
  imageSrc: string;
  width?: number;
  rotate?: number;
  peelDirection?: number;
  peelBackHoverPct?: number;
  peelBackActivePct?: number;
  curlRadius?: number;
  finish?: StickerFinish;
  backColor?: string;
  lightingIntensity?: number;
  shadowIntensity?: number;
  followPointer?: boolean;
  draggable?: boolean;
  swing?: number;
  friction?: number;
  bounce?: number;
  intro?: boolean;
  initialPosition?: 'center' | { x: number; y: number };
  onDragStart?: () => void;
  onDragEnd?: () => void;
  dpr?: number;
  style?: CSSProperties;
}

type Settings = {
  imageSrc: string;
  width: number;
  rotate: number;
  peelDirection: number;
  hoverPeel: number;
  activePeel: number;
  curlRadius: number;
  finish: number;
  backColor: string;
  lighting: number;
  shadow: number;
  followPointer: boolean;
  draggable: boolean;
  swing: number;
  friction: number;
  bounce: number;
  intro: boolean;
  initialPosition: 'center' | { x: number; y: number };
  onDragStart?: () => void;
  onDragEnd?: () => void;
  dpr?: number;
};

type Point = { x: number; y: number };

type SpringState = Record<'swing' | 'swingV' | 'peel' | 'peelV' | 'lift' | 'liftV', number>;

type Press = {
  id: number;
  grab: Point;
  origin: Point;
  pointer: Point;
  pivot: Point;
  moving: boolean;
  samples: { x: number; y: number; t: number }[];
};

type Program = { program: WebGLProgram; uniforms: Record<string, WebGLUniformLocation | null> };

type Target = { texture: WebGLTexture; buffer: WebGLFramebuffer; width: number; height: number };

const GRID = 96;
const PAD = 0.18;
const MAX_TEXTURE = 1024;
const MASK_SIZE = 96;
const LIGHT_HEIGHT = 260;
const FINISHES = { gloss: 0, matte: 1, holo: 2 };
let stack = 1;

const VERTEX = `#version 300 es
in vec2 aGrid;
uniform vec2 uCanvas;
uniform vec2 uMesh;
uniform vec2 uCenter;
uniform vec2 uDir;
uniform float uFold;
uniform float uRadius;
uniform float uAngle;
uniform float uScale;
uniform float uLift;
uniform int uPass;
uniform vec2 uShadowOffset;
uniform vec2 uShadowSlope;
out vec2 vUv;
out float vFold;
out vec3 vNormal;
out vec3 vPos;
out float vHeight;
out float vCurl;
const float PI = 3.14159265;

void main() {
  vec2 local = (aGrid - 0.5) * uMesh;
  float s = dot(local, uDir);
  float d = uFold - s;
  vec3 normal = vec3(0.0, 0.0, 1.0);
  float z = 0.0;
  vec2 p = local;
  if (d > 0.0) {
    float theta = d / uRadius;
    float along = uFold + d - PI * uRadius;
    z = 2.0 * uRadius;
    normal = vec3(0.0, 0.0, -1.0);
    if (theta < PI) {
      along = uFold - uRadius * sin(theta);
      z = uRadius * (1.0 - cos(theta));
      normal = vec3(uDir * sin(theta), cos(theta));
    }
    p += (along - s) * uDir;
  }
  float c = cos(uAngle);
  float sn = sin(uAngle);
  vec2 turned = vec2(c * p.x - sn * p.y, sn * p.x + c * p.y) * uScale;
  vNormal = vec3(c * normal.x - sn * normal.y, sn * normal.x + c * normal.y, normal.z);
  vUv = aGrid;
  vFold = d;
  vCurl = z * uScale;
  float height = z * uScale + uLift;
  vec2 screen = uCenter + turned;
  float depth = 0.0;
  if (uPass == 0 || uPass == 2) {
    vHeight = uPass == 0 ? height : z * uScale;
    screen += uShadowOffset + uShadowSlope * vHeight;
  } else {
    vHeight = height;
    depth = clamp(-height / 1000.0, -1.0, 1.0);
  }
  vPos = vec3(uCenter + turned, height);
  gl_Position = vec4(screen.x / uCanvas.x * 2.0 - 1.0, 1.0 - screen.y / uCanvas.y * 2.0, depth, 1.0);
}`;

const FRAGMENT = `#version 300 es
precision highp float;
precision highp int;
uniform sampler2D uImage;
uniform int uPass;
uniform int uFinish;
uniform vec3 uBack;
uniform vec3 uLight;
uniform float uShine;
uniform float uShadow;
uniform float uTexel;
uniform float uLod;
uniform float uRadius;
uniform vec2 uGlint;
in vec2 vUv;
in float vFold;
in vec3 vNormal;
in vec3 vPos;
in float vHeight;
in float vCurl;
out vec4 outColor;

float hash(vec2 p) {
  vec3 q = fract(vec3(p.xyx) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

vec3 spectrum(float t) {
  t = fract(t) * 6.0;
  vec3 a = vec3(1.0, 0.478, 0.46);
  vec3 b = vec3(1.0, 0.928, 0.38);
  vec3 c = vec3(0.659, 1.0, 0.38);
  vec3 d = vec3(0.52, 1.0, 0.968);
  vec3 e = vec3(0.48, 0.584, 1.0);
  vec3 f = vec3(0.68, 0.52, 1.0);
  if (t < 1.0) return mix(a, b, t);
  if (t < 2.0) return mix(b, c, t - 1.0);
  if (t < 3.0) return mix(c, d, t - 2.0);
  if (t < 4.0) return mix(d, e, t - 3.0);
  if (t < 5.0) return mix(e, f, t - 4.0);
  return mix(f, a, t - 5.0);
}

float bars(float t) {
  t = fract(t) * 12.0;
  if (t < 3.8) return mix(0.08, 0.6, t / 3.8);
  if (t < 4.5) return mix(0.6, 0.72, (t - 3.8) / 0.7);
  if (t < 5.2) return mix(0.72, 0.6, (t - 4.5) / 0.7);
  if (t < 10.0) return mix(0.6, 0.08, (t - 5.2) / 4.8);
  return 0.08;
}

void main() {
  if (uPass == 0) {
    float alpha;
    if (vFold > 0.0) {
      alpha = textureLod(uImage, vUv, log2(max(1.5 * uTexel, 1.0))).a * (1.0 - smoothstep(0.0, uRadius, vCurl));
    } else {
      alpha = textureLod(uImage, vUv, log2(max((1.2 + vHeight * 0.55) * uTexel, 1.0))).a;
    }
    outColor = vec4(0.0, 0.0, 0.0, alpha * uShadow / (1.0 + vHeight * 0.03));
    return;
  }
  if (uPass == 2) {
    if (vFold <= 0.0) discard;
    float alpha = textureLod(uImage, vUv, log2(max(uTexel, 1.0))).a * smoothstep(0.0, uRadius, vCurl);
    outColor = vec4(alpha);
    return;
  }
  if (uPass == 1 && vFold > 0.0) discard;
  if (uPass == 3 && vFold <= 0.0) discard;
  vec4 art = textureLod(uImage, vUv, uLod);
  if (art.a < 0.004) discard;
  bool front = vNormal.z >= 0.0;
  vec3 n = normalize(front ? vNormal : -vNormal);
  vec3 toLight = normalize(uLight - vPos);
  vec3 halfway = normalize(toLight + vec3(0.0, 0.0, 1.0));
  float diffuse = max(dot(n, toLight), 0.0);
  float nh = max(dot(n, halfway), 0.0);
  vec3 key = normalize(vec3(-0.45, -0.6, 0.66));
  float shade = clamp(0.5 + 0.25 * dot(n, key) / key.z + 0.25 * n.z, 0.5, front ? 1.0 : 1.08);
  if (uPass == 1) shade = 1.0;
  vec3 color;
  if (!front) {
    float grain = hash(floor(vUv * 700.0)) * 0.06 - 0.03;
    color = uBack * (0.7 + 0.3 * diffuse + grain) * art.a + vec3(pow(nh, 24.0) * 0.2 * uShine) * art.a;
  } else if (uFinish == 1) {
    color = art.rgb * (0.8 + 0.22 * diffuse) + vec3(pow(nh, 8.0) * 0.08 * uShine) * art.a;
  } else if (uFinish == 2) {
    vec3 albedo = art.rgb / art.a;
    float lum = dot(albedo, vec3(0.299, 0.587, 0.114));
    float foil = smoothstep(0.5, 0.92, lum);
    vec2 q = vUv - uGlint;
    float near = exp(-dot(q, q) * 3.0);
    float tilt = dot(n.xy, vec2(0.6, 0.8)) * 1.6;
    vec3 rainbow = spectrum((vUv.x + vUv.y) * 0.85 - (uGlint.x + uGlint.y) * 1.2 + tilt);
    float streak = bars((vUv.x - vUv.y) * 2.6 + uGlint.x * 1.8 - uGlint.y * 0.6 + tilt * 0.5);
    float band = smoothstep(0.32, 0.7, streak);
    vec3 silver = vec3(0.8, 0.82, 0.86) * (0.88 + 0.16 * diffuse);
    vec3 film = mix(silver, rainbow * 1.08, clamp(band * (0.55 + 0.45 * near) + 0.18 * near, 0.0, 1.0));
    vec3 ink = albedo * (0.86 + 0.14 * diffuse) + rainbow * band * 0.22 * (0.4 + 0.6 * near);
    vec3 base = mix(albedo * (0.86 + 0.14 * diffuse), mix(ink, film, foil), uShine * 0.6 + 0.4);
    vec2 cell = floor(vUv * 180.0);
    vec2 jitter = vec2(hash(cell), hash(cell + 7.3)) * 0.6 + 0.2;
    float dist = length(fract(vUv * 180.0) - jitter);
    vec3 facet = normalize(vec3(vec2(hash(cell + 2.1), hash(cell + 5.7)) * 2.0 - 1.0, 1.6));
    float glint = pow(max(dot(facet, halfway), 0.0), 60.0) * smoothstep(0.32, 0.05, dist) * step(0.55, hash(cell + 3.1)) * (0.15 + 0.85 * foil);
    color = (base + spectrum(hash(cell) + uGlint.x) * glint * 1.6 * uShine + vec3(pow(nh, 140.0) * 0.4 * uShine)) * art.a;
  } else {
    color = art.rgb * (0.86 + 0.16 * diffuse) + vec3(pow(nh, 220.0) * 0.4 + pow(nh, 24.0) * 0.03) * uShine * art.a;
  }
  float bend = uPass == 3 ? smoothstep(0.0, uRadius * 0.6, vCurl) : 0.0;
  float glare = pow(max(dot(n, normalize(key + vec3(0.0, 0.0, 1.0))), 0.0), 28.0) * bend * (0.18 + 0.3 * uShine);
  outColor = vec4(min(color * shade + vec3(glare) * art.a, vec3(art.a)), art.a);
}`;

const POST_VERTEX = `#version 300 es
out vec2 vUv;
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  vUv = p;
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}`;

const POST_FRAGMENT = `#version 300 es
precision highp float;
uniform sampler2D uSource;
uniform vec2 uStep;
uniform float uSigma;
uniform float uStrength;
uniform int uMode;
in vec2 vUv;
out vec4 outColor;

void main() {
  if (uMode == 1) {
    outColor = vec4(0.0, 0.0, 0.0, texture(uSource, vUv).a * uStrength);
    return;
  }
  vec4 sum = vec4(0.0);
  float total = 0.0;
  for (int i = -8; i <= 8; i++) {
    float offset = float(i);
    float weight = exp(-0.5 * offset * offset / (uSigma * uSigma));
    sum += texture(uSource, vUv + uStep * offset) * weight;
    total += weight;
  }
  outColor = sum / total;
}`;

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const wrapAngle = (angle: number) => Math.atan2(Math.sin(angle), Math.cos(angle));
const toRadians = (degrees: number) => (degrees * Math.PI) / 180;

const spring = (
  state: SpringState,
  key: 'swing' | 'peel' | 'lift',
  target: number,
  frequency: number,
  damping: number,
  dt: number
) => {
  const omega = 2 * Math.PI * frequency;
  const velocity = `${key}V` as 'swingV' | 'peelV' | 'liftV';
  state[velocity] += (omega * omega * (target - state[key]) - 2 * damping * omega * state[velocity]) * dt;
  state[key] += state[velocity] * dt;
};

const compile = (gl: WebGL2RenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
};

const link = (gl: WebGL2RenderingContext, vertexSource: string, fragmentSource: string): Program | null => {
  const vertex = compile(gl, gl.VERTEX_SHADER, vertexSource);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, fragmentSource);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.bindAttribLocation(program, 0, 'aGrid');
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  const uniforms: Record<string, WebGLUniformLocation | null> = {};
  const count = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < count; i++) {
    const info = gl.getActiveUniform(program, i);
    if (info) uniforms[info.name] = gl.getUniformLocation(program, info.name);
  }
  return { program, uniforms };
};

const convexHull = (points: [number, number][]) => {
  const sorted = [...points].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  if (sorted.length < 3) return sorted;
  const cross = (o: [number, number], a: [number, number], b: [number, number]) =>
    (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lower: [number, number][] = [];
  sorted.forEach(point => {
    while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], point) <= 0) lower.pop();
    lower.push(point);
  });
  const upper: [number, number][] = [];
  for (let i = sorted.length - 1; i >= 0; i--) {
    const point = sorted[i];
    while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], point) <= 0) upper.pop();
    upper.push(point);
  }
  return lower.slice(0, -1).concat(upper.slice(0, -1));
};

const StickerPeel = ({
  imageSrc,
  width = 200,
  rotate = 0,
  peelDirection = 0,
  peelBackHoverPct = 25,
  peelBackActivePct = 40,
  curlRadius = 12,
  finish = 'gloss',
  backColor = '#d4d4d8',
  lightingIntensity = 0.5,
  shadowIntensity = 0.6,
  followPointer = true,
  draggable = true,
  swing = 1,
  friction = 0.5,
  bounce = 0.35,
  intro = true,
  initialPosition = 'center',
  onDragStart,
  onDragEnd,
  dpr,
  className = '',
  style,
  ...rest
}: StickerPeelProps) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hitRef = useRef<HTMLDivElement>(null);
  const wakeRef = useRef<(() => void) | null>(null);
  const settings: Settings = {
    imageSrc,
    width: Math.max(16, width),
    rotate: toRadians(rotate),
    peelDirection: toRadians(peelDirection),
    hoverPeel: clamp(peelBackHoverPct, 0, 100) / 100,
    activePeel: clamp(peelBackActivePct, 0, 100) / 100,
    curlRadius: Math.max(2, curlRadius),
    finish: FINISHES[finish] ?? 0,
    backColor,
    lighting: clamp(lightingIntensity, 0, 1),
    shadow: clamp(shadowIntensity, 0, 1),
    followPointer,
    draggable,
    swing: clamp(swing, 0, 3),
    friction: clamp(friction, 0, 1),
    bounce: clamp(bounce, 0, 1),
    intro,
    initialPosition,
    onDragStart,
    onDragEnd,
    dpr
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const hit = hitRef.current;
    const parent = root?.parentElement;
    const gl = canvas?.getContext('webgl2', {
      alpha: true,
      premultipliedAlpha: true,
      antialias: true,
      depth: true,
      stencil: false
    });
    if (!root || !canvas || !hit || !parent || !gl) return undefined;

    const program = link(gl, VERTEX, FRAGMENT);
    const post = link(gl, POST_VERTEX, POST_FRAGMENT);
    if (!program || !post) return undefined;
    const u = program.uniforms;
    const pu = post.uniforms;
    const targets: Target[] = [0, 1].map(() => {
      const target = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, target);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      const buffer = gl.createFramebuffer();
      return { texture: target, buffer, width: 0, height: 0 };
    });
    const sizeTargets = () => {
      const width = Math.max(1, Math.round(view.size / 2));
      const height = width;
      targets.forEach(target => {
        if (target.width === width && target.height === height) return;
        target.width = width;
        target.height = height;
        gl.bindTexture(gl.TEXTURE_2D, target.texture);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, width, height, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
        gl.bindFramebuffer(gl.FRAMEBUFFER, target.buffer);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, target.texture, 0);
      });
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    };

    const vertices = new Float32Array((GRID + 1) * (GRID + 1) * 2);
    for (let y = 0; y <= GRID; y++) {
      for (let x = 0; x <= GRID; x++) {
        const i = (y * (GRID + 1) + x) * 2;
        vertices[i] = x / GRID;
        vertices[i + 1] = y / GRID;
      }
    }
    const indices = new Uint16Array(GRID * GRID * 6);
    let cursor = 0;
    for (let y = 0; y < GRID; y++) {
      for (let x = 0; x < GRID; x++) {
        const a = y * (GRID + 1) + x;
        const b = a + 1;
        const c = a + GRID + 1;
        const d = c + 1;
        indices.set([a, b, d, a, d, c], cursor);
        cursor += 6;
      }
    }
    const vao = gl.createVertexArray();
    gl.bindVertexArray(vao);
    const vertexBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, vertices, gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    const indexBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, indices, gl.STATIC_DRAW);

    const texture = gl.createTexture();
    const scratch = document.createElement('canvas');
    const scratchContext = scratch.getContext('2d', { willReadFrequently: true });
    const probe = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
    const colorCache = new Map<string, number[]>();
    const parse = (value: string): number[] => {
      const key = String(value);
      const cached = colorCache.get(key);
      if (cached) return cached;
      let rgb = [0.83, 0.83, 0.85];
      if (probe) {
        probe.clearRect(0, 0, 1, 1);
        probe.fillStyle = '#d4d4d8';
        probe.fillStyle = key;
        probe.fillRect(0, 0, 1, 1);
        const [r, g, b] = probe.getImageData(0, 0, 1, 1).data;
        rgb = [r / 255, g / 255, b / 255];
      }
      colorCache.set(key, rgb);
      return rgb;
    };

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const sticker: {
      ready: boolean;
      aspect: number;
      meshX: number;
      meshY: number;
      texel: number;
      mask: Uint8Array | null;
      maskW: number;
      maskH: number;
      hull: [number, number][];
    } = { ready: false, aspect: 1, meshX: 1, meshY: 1, texel: 1, mask: null, maskW: 1, maskH: 1, hull: [] };
    const view = { ratio: 1, size: 1, density: 0 };
    const bounds = { width: 1, height: 1 };
    const state = {
      x: 0,
      y: 0,
      vx: 0,
      vy: 0,
      placed: false,
      swing: 0,
      swingV: 0,
      peel: 0,
      peelV: 0,
      lift: 0,
      liftV: 0,
      dir: settingsRef.current.peelDirection,
      hover: false,
      local: { x: 0, y: 0 },
      press: null as Press | null,
      pivotV: { x: 0, y: 0 },
      light: { x: 0, y: 0, z: LIGHT_HEIGHT },
      pointer: { x: 0, y: 0, inside: false },
      intro: settingsRef.current.intro && !reduce ? 0 : 1
    };
    if (state.intro < 1) {
      state.lift = 1.5;
      state.peel = 0.3;
      state.swing = 0.1;
      state.dir += 0.6;
    }
    let raf = 0;
    let last = 0;
    let visible = true;
    let loadedSrc: string | null = null;
    let alive = true;

    const height = () => settingsRef.current.width * sticker.aspect;

    const extentAlong = (dx: number, dy: number): [number, number] => {
      const s = settingsRef.current;
      const w = s.width;
      const h = height();
      if (!sticker.hull.length) {
        const half = (Math.abs(dx) * w + Math.abs(dy) * h) / 2;
        return [-half, half];
      }
      let min = Infinity;
      let max = -Infinity;
      sticker.hull.forEach(([px, py]) => {
        const value = px * w * dx + py * h * dy;
        if (value < min) min = value;
        if (value > max) max = value;
      });
      return [min, max];
    };

    const load = (src: string) => {
      loadedSrc = src;
      sticker.ready = false;
      if (!src) return;
      const image = new Image();
      image.crossOrigin = 'anonymous';
      image.decoding = 'async';
      image.onload = () => {
        if (!alive || loadedSrc !== src || !scratchContext) return;
        const iw = image.naturalWidth || 1;
        const ih = image.naturalHeight || 1;
        const fit = Math.min(1, MAX_TEXTURE / (Math.max(iw, ih) * (1 + 2 * PAD)));
        const w = Math.max(1, Math.round(iw * fit));
        const h = Math.max(1, Math.round(ih * fit));
        const padX = Math.round(w * PAD);
        const padY = Math.round(h * PAD);
        scratch.width = w + padX * 2;
        scratch.height = h + padY * 2;
        scratchContext.clearRect(0, 0, scratch.width, scratch.height);
        scratchContext.drawImage(image, padX, padY, w, h);
        gl.bindTexture(gl.TEXTURE_2D, texture);
        gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, scratch);
        gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
        gl.generateMipmap(gl.TEXTURE_2D);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        sticker.aspect = ih / iw;
        sticker.meshX = scratch.width / w;
        sticker.meshY = scratch.height / h;
        sticker.texel = scratch.width;
        const maskW = Math.max(8, Math.round(MASK_SIZE * Math.min(1, iw / ih)));
        const maskH = Math.max(8, Math.round(MASK_SIZE * Math.min(1, ih / iw)));
        scratch.width = maskW;
        scratch.height = maskH;
        scratchContext.clearRect(0, 0, maskW, maskH);
        scratchContext.drawImage(image, 0, 0, maskW, maskH);
        const pixels = scratchContext.getImageData(0, 0, maskW, maskH).data;
        const mask = new Uint8Array(maskW * maskH).fill(255);
        const queue: number[] = [];
        const visit = (x: number, y: number) => {
          const i = y * maskW + x;
          if (mask[i] === 0 || pixels[i * 4 + 3] > 100) return;
          mask[i] = 0;
          queue.push(i);
        };
        for (let x = 0; x < maskW; x++) {
          visit(x, 0);
          visit(x, maskH - 1);
        }
        for (let y = 0; y < maskH; y++) {
          visit(0, y);
          visit(maskW - 1, y);
        }
        while (queue.length) {
          const i = queue.pop() as number;
          const x = i % maskW;
          const y = (i - x) / maskW;
          if (x > 0) visit(x - 1, y);
          if (x < maskW - 1) visit(x + 1, y);
          if (y > 0) visit(x, y - 1);
          if (y < maskH - 1) visit(x, y + 1);
        }
        const points: [number, number][] = [];
        for (let y = 0; y < maskH; y++) {
          for (let x = 0; x < maskW; x++) {
            if (pixels[(y * maskW + x) * 4 + 3] > 127) points.push([(x + 0.5) / maskW - 0.5, (y + 0.5) / maskH - 0.5]);
          }
        }
        sticker.mask = mask;
        sticker.maskW = maskW;
        sticker.maskH = maskH;
        sticker.hull = convexHull(points);
        sticker.ready = true;
        layout();
        wake();
      };
      image.src = src;
    };

    const layout = () => {
      const s = settingsRef.current;
      view.ratio = Math.min(s.dpr || window.devicePixelRatio || 1, 2);
      bounds.width = Math.max(1, parent.clientWidth);
      bounds.height = Math.max(1, parent.clientHeight);
      const h = height();
      const size = Math.ceil(Math.hypot(s.width, h) * 1.16 + 2 * (36 + s.curlRadius));
      if (size !== view.size || view.ratio !== view.density) {
        view.size = size;
        view.density = view.ratio;
        root.style.width = `${size}px`;
        root.style.height = `${size}px`;
        canvas.width = Math.round(size * view.ratio);
        canvas.height = Math.round(size * view.ratio);
      }
      hit.style.width = `${s.width}px`;
      hit.style.height = `${h}px`;
      if (!state.placed) {
        const start = s.initialPosition;
        const offset = start && typeof start === 'object' ? start : { x: 0, y: 0 };
        state.x = bounds.width / 2 + (offset.x || 0);
        state.y = bounds.height / 2 + (offset.y || 0);
        state.light = { x: state.x - s.width * 0.45, y: state.y - h * 0.9, z: LIGHT_HEIGHT * 1.6 };
        state.placed = true;
      }
      confine();
    };

    const reach = () => {
      const s = settingsRef.current;
      const angle = s.rotate + state.swing;
      const grow = 1 + 0.07 * Math.max(0, state.lift);
      const w = (s.width / 2) * grow;
      const h = (height() / 2) * grow;
      const c = Math.abs(Math.cos(angle));
      const sn = Math.abs(Math.sin(angle));
      return { x: w * c + h * sn, y: w * sn + h * c };
    };

    const confine = () => {
      const s = settingsRef.current;
      const half = reach();
      const minX = Math.min(half.x, bounds.width / 2);
      const maxX = Math.max(bounds.width - half.x, bounds.width / 2);
      const minY = Math.min(half.y, bounds.height / 2);
      const maxY = Math.max(bounds.height - half.y, bounds.height / 2);
      if (state.x < minX) {
        state.x = minX;
        if (state.vx < 0) state.vx = -state.vx * s.bounce;
      } else if (state.x > maxX) {
        state.x = maxX;
        if (state.vx > 0) state.vx = -state.vx * s.bounce;
      }
      if (state.y < minY) {
        state.y = minY;
        if (state.vy < 0) state.vy = -state.vy * s.bounce;
      } else if (state.y > maxY) {
        state.y = maxY;
        if (state.vy > 0) state.vy = -state.vy * s.bounce;
      }
    };

    const toParent = (event: PointerEvent): Point => {
      const rect = parent.getBoundingClientRect();
      return { x: event.clientX - rect.left - parent.clientLeft, y: event.clientY - rect.top - parent.clientTop };
    };

    const toLocal = (point: Point): Point => {
      const s = settingsRef.current;
      const angle = -(s.rotate + state.swing);
      const scale = 1 + 0.07 * Math.max(0, state.lift);
      const dx = point.x - state.x;
      const dy = point.y - state.y;
      return {
        x: (Math.cos(angle) * dx - Math.sin(angle) * dy) / scale,
        y: (Math.sin(angle) * dx + Math.cos(angle) * dy) / scale
      };
    };

    const solid = (local: Point) => {
      if (!sticker.mask) return false;
      const s = settingsRef.current;
      const mx = Math.floor((local.x / s.width + 0.5) * sticker.maskW);
      const my = Math.floor((local.y / height() + 0.5) * sticker.maskH);
      if (mx < 0 || my < 0 || mx >= sticker.maskW || my >= sticker.maskH) return false;
      return sticker.mask[my * sticker.maskW + mx] > 100;
    };

    const draw = () => {
      const s = settingsRef.current;
      const size = view.size;
      root.style.transform = `translate3d(${state.x - size / 2}px, ${state.y - size / 2}px, 0)`;
      const angle = s.rotate + state.swing;
      const scale = 1 + 0.07 * Math.max(0, state.lift);
      hit.style.transform = `translate(-50%, -50%) rotate(${angle}rad) scale(${scale})`;
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.clearColor(0, 0, 0, 0);
      gl.clearDepth(1);
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
      if (!sticker.ready) return;
      const w = s.width;
      const h = height();
      const dx = -Math.sin(state.dir);
      const dy = Math.cos(state.dir);
      const [start, end] = extentAlong(dx, dy);
      const peel = clamp(state.peel, 0, 1);
      const fold = start + peel * (end - start);
      const lift = Math.max(0, state.lift);
      const center = size / 2;
      const count = GRID * GRID * 6;
      const peeled = peel > 0.001;
      gl.useProgram(program.program);
      gl.bindVertexArray(vao);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.uniform1i(u.uImage, 0);
      gl.uniform2f(u.uCanvas, size, size);
      gl.uniform2f(u.uMesh, w * sticker.meshX, h * sticker.meshY);
      gl.uniform2f(u.uCenter, center, center);
      gl.uniform2f(u.uDir, dx, dy);
      gl.uniform1f(u.uFold, fold);
      gl.uniform1f(u.uRadius, s.curlRadius);
      gl.uniform1f(u.uAngle, angle);
      gl.uniform1f(u.uScale, scale);
      gl.uniform1f(u.uLift, lift * 26);
      gl.uniform2f(u.uShadowOffset, 1.2, 2.4);
      gl.uniform2f(u.uShadowSlope, 0.28, 0.55);
      gl.uniform1i(u.uFinish, s.finish);
      gl.uniform3fv(u.uBack, parse(s.backColor));
      gl.uniform3f(u.uLight, state.light.x - (state.x - center), state.light.y - (state.y - center), state.light.z);
      gl.uniform1f(u.uShine, s.lighting);
      gl.uniform1f(u.uShadow, s.shadow * 0.55);
      gl.uniform1f(u.uTexel, sticker.texel / (w * sticker.meshX));
      gl.uniform1f(u.uLod, Math.max(0, Math.log2(sticker.texel / (w * sticker.meshX * scale * view.ratio))));
      const glint = toLocal(state.light);
      gl.uniform2f(u.uGlint, glint.x / (w * sticker.meshX) + 0.5, glint.y / (h * sticker.meshY) + 0.5);
      gl.disable(gl.DEPTH_TEST);
      if (peeled) {
        sizeTargets();
        const [first, second] = targets;
        gl.bindFramebuffer(gl.FRAMEBUFFER, first.buffer);
        gl.viewport(0, 0, first.width, first.height);
        gl.clear(gl.COLOR_BUFFER_BIT);
        gl.disable(gl.BLEND);
        gl.uniform1i(u.uPass, 2);
        gl.drawElements(gl.TRIANGLES, count, gl.UNSIGNED_SHORT, 0);
        gl.useProgram(post.program);
        gl.uniform1i(pu.uSource, 1);
        gl.uniform1i(pu.uMode, 0);
        gl.uniform1f(pu.uSigma, Math.min(4, (2.5 + s.curlRadius * 0.15) / 2));
        gl.activeTexture(gl.TEXTURE1);
        gl.bindFramebuffer(gl.FRAMEBUFFER, second.buffer);
        gl.bindTexture(gl.TEXTURE_2D, first.texture);
        gl.uniform2f(pu.uStep, 1 / first.width, 0);
        gl.drawArrays(gl.TRIANGLES, 0, 3);
        gl.bindFramebuffer(gl.FRAMEBUFFER, first.buffer);
        gl.bindTexture(gl.TEXTURE_2D, second.texture);
        gl.uniform2f(pu.uStep, 0, 1 / first.height);
        gl.drawArrays(gl.TRIANGLES, 0, 3);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        gl.viewport(0, 0, canvas.width, canvas.height);
        gl.useProgram(program.program);
        gl.activeTexture(gl.TEXTURE0);
      }
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      gl.uniform1i(u.uPass, 0);
      gl.drawElements(gl.TRIANGLES, count, gl.UNSIGNED_SHORT, 0);
      gl.uniform1i(u.uPass, 1);
      gl.drawElements(gl.TRIANGLES, count, gl.UNSIGNED_SHORT, 0);
      if (peeled) {
        gl.useProgram(post.program);
        gl.activeTexture(gl.TEXTURE1);
        gl.bindTexture(gl.TEXTURE_2D, targets[0].texture);
        gl.uniform1i(pu.uMode, 1);
        gl.uniform1f(pu.uStrength, s.shadow * 0.6);
        gl.drawArrays(gl.TRIANGLES, 0, 3);
        gl.useProgram(program.program);
        gl.activeTexture(gl.TEXTURE0);
        gl.enable(gl.DEPTH_TEST);
        gl.depthFunc(gl.LESS);
        gl.uniform1i(u.uPass, 3);
        gl.drawElements(gl.TRIANGLES, count, gl.UNSIGNED_SHORT, 0);
        gl.disable(gl.DEPTH_TEST);
      }
    };

    const frame = (now: number) => {
      raf = 0;
      if (!visible || document.hidden) return;
      const s = settingsRef.current;
      const dt = last ? clamp((now - last) / 1000, 0.001, 1 / 30) : 1 / 60;
      last = now;
      if (s.imageSrc !== loadedSrc) load(s.imageSrc);
      const h = height();
      if (state.intro < 1 && sticker.ready) state.intro = Math.min(1, state.intro + dt / 1.1);
      const press = state.press;
      const drag = press && press.moving ? press : null;
      if (drag) {
        const target = drag.pointer;
        const prev = drag.pivot;
        const smoothing = 1 - Math.exp(-dt / 0.045);
        const vx = state.pivotV.x + ((target.x - prev.x) / dt - state.pivotV.x) * smoothing;
        const vy = state.pivotV.y + ((target.y - prev.y) / dt - state.pivotV.y) * smoothing;
        const ax = (vx - state.pivotV.x) / dt;
        const ay = (vy - state.pivotV.y) / dt;
        state.pivotV.x = vx;
        state.pivotV.y = vy;
        drag.pivot = { x: target.x, y: target.y };
        const angle = s.rotate + state.swing;
        const rx = -(Math.cos(angle) * drag.grab.x - Math.sin(angle) * drag.grab.y);
        const ry = -(Math.sin(angle) * drag.grab.x + Math.cos(angle) * drag.grab.y);
        const inertia = (s.width * s.width + h * h) / 12 + rx * rx + ry * ry;
        const torque = (rx * -clamp(ay, -24000, 24000) - ry * -clamp(ax, -24000, 24000)) / inertia;
        const omega = 2 * Math.PI * 1.5;
        state.swingV += (torque * 1.1 * s.swing - omega * omega * state.swing - 2 * 0.45 * omega * state.swingV) * dt;
        state.swing = clamp(state.swing + state.swingV * dt, -1.2, 1.2);
        const turned = s.rotate + state.swing;
        const grip = 1 + 0.07 * Math.max(0, state.lift);
        state.x = target.x - (Math.cos(turned) * drag.grab.x - Math.sin(turned) * drag.grab.y) * grip;
        state.y = target.y - (Math.sin(turned) * drag.grab.x + Math.cos(turned) * drag.grab.y) * grip;
        confine();
      } else {
        spring(state, 'swing', 0, 1.4, 0.32, dt);
        const decay = Math.exp(-dt * (1.5 + 9 * s.friction));
        state.vx *= decay;
        state.vy *= decay;
        if (Math.hypot(state.vx, state.vy) < 4) {
          state.vx = 0;
          state.vy = 0;
        }
        state.x += state.vx * dt;
        state.y += state.vy * dt;
        confine();
      }
      const introHold = state.intro < 0.2;
      const peelTarget = introHold ? 0.3 : press ? s.activePeel : state.hover ? s.hoverPeel : 0;
      spring(state, 'peel', peelTarget, press || state.hover ? 3 : 3.6, press || state.hover ? 0.7 : 0.62, dt);
      spring(state, 'lift', drag ? 1 : 0, 3.2, 0.55, dt);
      let dirTarget = s.peelDirection;
      if (press && Math.hypot(press.grab.x, press.grab.y) > Math.min(s.width, h) * 0.12) {
        dirTarget = Math.atan2(press.grab.x, -press.grab.y);
      } else if (
        s.followPointer &&
        state.hover &&
        Math.hypot(state.local.x, state.local.y) > Math.min(s.width, h) * 0.12
      ) {
        dirTarget = Math.atan2(state.local.x, -state.local.y);
      }
      if (!introHold) state.dir += wrapAngle(dirTarget - state.dir) * (1 - Math.exp(-dt / 0.12));
      const lightTarget = state.pointer.inside
        ? { x: state.pointer.x, y: state.pointer.y, z: LIGHT_HEIGHT }
        : { x: state.x - s.width * 0.45, y: state.y - h * 0.9, z: LIGHT_HEIGHT * 1.6 };
      const follow = 1 - Math.exp(-dt / 0.08);
      state.light.x += (lightTarget.x - state.light.x) * follow;
      state.light.y += (lightTarget.y - state.light.y) * follow;
      state.light.z += (lightTarget.z - state.light.z) * follow;
      canvas.style.opacity = String(clamp(state.intro / 0.12, 0, 1));
      draw();
      const moving =
        (state.intro < 1 && sticker.ready) ||
        press ||
        Math.abs(state.peel - peelTarget) > 0.0005 ||
        Math.abs(state.peelV) > 0.0005 ||
        Math.abs(state.lift - (drag ? 1 : 0)) > 0.0005 ||
        Math.abs(state.liftV) > 0.0005 ||
        Math.abs(state.swing) > 0.0005 ||
        Math.abs(state.swingV) > 0.0005 ||
        state.vx !== 0 ||
        state.vy !== 0 ||
        Math.abs(wrapAngle(dirTarget - state.dir)) > 0.002 ||
        Math.hypot(lightTarget.x - state.light.x, lightTarget.y - state.light.y, lightTarget.z - state.light.z) > 0.5;
      if (moving) raf = requestAnimationFrame(frame);
      else last = 0;
    };

    function wake() {
      if (!raf && visible && !document.hidden) raf = requestAnimationFrame(frame);
    }

    const updateHover = (event: PointerEvent) => {
      const point = toParent(event);
      state.local = toLocal(point);
      const over = solid(state.local);
      if (over !== state.hover) state.hover = over;
      hit.style.cursor = over && settingsRef.current.draggable ? (state.press ? 'grabbing' : 'grab') : '';
    };

    const onPointerMove = (event: PointerEvent) => {
      const point = toParent(event);
      state.pointer.x = point.x;
      state.pointer.y = point.y;
      state.pointer.inside = point.x >= 0 && point.y >= 0 && point.x <= bounds.width && point.y <= bounds.height;
      wake();
    };

    const onHitMove = (event: PointerEvent) => {
      const press = state.press;
      if (!press) {
        updateHover(event);
      } else if (press.id === event.pointerId) {
        const point = toParent(event);
        press.pointer = point;
        if (!press.moving && Math.hypot(point.x - press.origin.x, point.y - press.origin.y) > 3) {
          press.moving = settingsRef.current.draggable;
          if (press.moving) settingsRef.current.onDragStart?.();
        }
        press.samples.push({ x: point.x, y: point.y, t: performance.now() });
        if (press.samples.length > 8) press.samples.shift();
      }
      wake();
    };

    const onHitLeave = () => {
      if (state.press) return;
      state.hover = false;
      hit.style.cursor = '';
      wake();
    };

    const onHitDown = (event: PointerEvent) => {
      const s = settingsRef.current;
      if (event.button !== 0 || !sticker.ready) return;
      updateHover(event);
      if (!state.hover) return;
      const point = toParent(event);
      state.press = {
        id: event.pointerId,
        grab: toLocal(point),
        origin: point,
        pointer: point,
        pivot: point,
        moving: false,
        samples: []
      };
      state.pivotV = { x: 0, y: 0 };
      state.vx = 0;
      state.vy = 0;
      hit.setPointerCapture?.(event.pointerId);
      if (s.draggable) {
        hit.style.cursor = 'grabbing';
        stack += 1;
        root.style.zIndex = String(stack);
      }
      event.preventDefault();
      wake();
    };

    const onHitUp = (event: PointerEvent) => {
      const press = state.press;
      if (!press || press.id !== event.pointerId) return;
      state.press = null;
      if (hit.hasPointerCapture?.(event.pointerId)) hit.releasePointerCapture(event.pointerId);
      const now = performance.now();
      const recent = press.samples.filter(sample => now - sample.t < 90);
      if (press.moving && recent.length > 1 && !reduce) {
        const a = recent[0];
        const b = recent[recent.length - 1];
        const span = Math.max(b.t - a.t, 16) / 1000;
        const speed = 2600;
        state.vx = clamp((b.x - a.x) / span, -speed, speed);
        state.vy = clamp((b.y - a.y) / span, -speed, speed);
      }
      updateHover(event);
      if (event.pointerType !== 'mouse') state.hover = false;
      if (press.moving) settingsRef.current.onDragEnd?.();
      wake();
    };

    const onLeaveWindow = () => {
      state.pointer.inside = false;
      wake();
    };

    const onVisibility = () => {
      last = 0;
      wake();
    };

    const resizeObserver = new ResizeObserver(() => {
      layout();
      wake();
    });
    resizeObserver.observe(parent);
    const intersection = new IntersectionObserver(entries => {
      visible = entries.some(entry => entry.isIntersecting);
      if (visible) {
        last = 0;
        wake();
      }
    });
    intersection.observe(parent);
    window.addEventListener('pointermove', onPointerMove, { passive: true });
    document.documentElement.addEventListener('pointerleave', onLeaveWindow);
    document.addEventListener('visibilitychange', onVisibility);
    hit.addEventListener('pointermove', onHitMove);
    hit.addEventListener('pointerleave', onHitLeave);
    hit.addEventListener('pointerdown', onHitDown);
    hit.addEventListener('pointerup', onHitUp);
    hit.addEventListener('pointercancel', onHitUp);
    load(settingsRef.current.imageSrc);
    layout();
    wakeRef.current = () => {
      layout();
      wake();
    };
    wake();

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      wakeRef.current = null;
      resizeObserver.disconnect();
      intersection.disconnect();
      window.removeEventListener('pointermove', onPointerMove);
      document.documentElement.removeEventListener('pointerleave', onLeaveWindow);
      document.removeEventListener('visibilitychange', onVisibility);
      hit.removeEventListener('pointermove', onHitMove);
      hit.removeEventListener('pointerleave', onHitLeave);
      hit.removeEventListener('pointerdown', onHitDown);
      hit.removeEventListener('pointerup', onHitUp);
      hit.removeEventListener('pointercancel', onHitUp);
      gl.deleteTexture(texture);
      targets.forEach(target => {
        gl.deleteTexture(target.texture);
        gl.deleteFramebuffer(target.buffer);
      });
      gl.deleteProgram(post.program);
      gl.deleteBuffer(vertexBuffer);
      gl.deleteBuffer(indexBuffer);
      gl.deleteVertexArray(vao);
      gl.deleteProgram(program.program);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    };
  }, []);

  useEffect(() => {
    wakeRef.current?.();
  });

  return (
    <div
      ref={rootRef}
      className={['pointer-events-none absolute left-0 top-0 will-change-transform', className]
        .filter(Boolean)
        .join(' ')}
      style={style}
      {...rest}
    >
      <canvas ref={canvasRef} className="pointer-events-none block h-full w-full" aria-hidden="true" />
      <div
        ref={hitRef}
        className="pointer-events-auto absolute left-1/2 top-1/2 touch-none select-none [-webkit-tap-highlight-color:transparent] [-webkit-touch-callout:none]"
      />
    </div>
  );
};

