const MAX_COLORS = 8;
const ROLES = 7;

const VERT = `#version 300 es
in vec2 position;
void main() {
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

const FRAG = `#version 300 es
precision highp float;

uniform vec2 uResolution;
uniform vec3 uMotion;
uniform float uLevel;
uniform vec3 uColors[8];
uniform int uCount;
uniform float uAmplitude;
uniform float uWaviness;
uniform float uThickness;
uniform float uGlow;
uniform float uTaper;
uniform float uSpread;
uniform float uHueShift;
uniform float uIntensity;
uniform float uSaturation;
uniform float uScale;
uniform float uGlass;
uniform float uRadius;
uniform float uRefraction;
uniform float uDispersion;
uniform float uRim;
uniform vec2 uLean;
uniform float uIntro;
uniform float uPulse;
uniform float uLight;
uniform float uOpacity;

out vec4 fragColor;

const int NB = 10;
const float PI = 3.14159265;

vec3 hueRotate(vec3 c, float a) {
  const mat3 toYiq = mat3(0.299, 0.596, 0.211, 0.587, -0.274, -0.523, 0.114, -0.322, 0.312);
  const mat3 toRgb = mat3(1.0, 1.0, 1.0, 0.956, -0.272, -1.106, 0.621, -0.647, 1.703);
  vec3 yiq = toYiq * c;
  float ca = cos(a);
  float sa = sin(a);
  yiq.yz = mat2(ca, sa, -sa, ca) * yiq.yz;
  return max(toRgb * yiq, 0.0);
}

vec3 grade(vec3 c) {
  float g = dot(c, vec3(0.2126, 0.7152, 0.0722));
  c = clamp(mix(vec3(g), c, 1.5 * uSaturation), 0.0, 1.0);
  return hueRotate(c, uHueShift * 6.2831853);
}

vec3 lightInk(vec3 L, float halo, vec3 body) {
  vec3 Lg = grade(L);
  float lum = dot(Lg, vec3(0.2126, 0.7152, 0.0722));
  float cov = 1.0 - exp(-lum * 2.6);
  vec3 hue = Lg / max(max(Lg.r, max(Lg.g, Lg.b)), 1e-4);
  float white = pow(clamp(min(hue.r, min(hue.g, hue.b)), 0.0, 1.0), 1.4);
  vec3 ink = pow(hue, vec3(2.2)) * 0.88;
  float coreAmt = white * smoothstep(0.05, 2.2, lum) * 0.92;
  vec3 cream = mix(mix(uColors[3], vec3(1.0), 0.3), vec3(1.0, 0.985, 0.95), smoothstep(1.2, 3.5, lum));
  vec3 c = mix(body, vec3(0.66, 0.69, 0.76), halo * 0.32);
  c = mix(c, ink, cov * (1.0 - white));
  return mix(c, cream, clamp(coreAmt, 0.0, 1.0));
}

float sstep(float a, float b, float x) {
  float t = clamp((x - a) / (b - a), 0.0, 1.0);
  return t * t * (3.0 - 2.0 * t);
}

float erfa(float x) {
  float a = abs(x);
  float t = 1.0 / (1.0 + 0.3275911 * a);
  float y = 1.0 - ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * exp(-a * a);
  return x < 0.0 ? -y : y;
}

vec3 grad4(vec3 c0, vec3 c1, vec3 c2, vec3 c3, float p1, float p2, float f) {
  vec3 c = mix(c0, c1, sstep(0.0, p1, f));
  c = mix(c, c2, sstep(p1, p2, f));
  return mix(c, c3, sstep(p2, 1.0, f));
}

float smaxk(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(a, b, h) + k * h * (1.0 - h);
}

vec2 sheetW(float tt, float H, float sig, float sigB, float ridges) {
  float ew = 0.04 * uThickness;
  float res0;
  float res1;
  for (int pass = 0; pass < 2; pass++) {
    float sg = pass == 0 ? sig : sigB;
    float fill = 0.5 * (erfa(tt / sg) - erfa((tt - H) / sg)) / H;
    float se = sqrt(sg * sg + 0.25 * ew * ew * H * H);
    float de = (tt - H + 0.5 * ew * H) / se;
    float eg = exp(-de * de) / (se * 1.7724539);
    float rgw = sqrt(sg * sg + 0.0025 * H * H);
    float d1 = (tt - 0.45 * H) / rgw;
    float d2 = (tt - 0.241 * H) / rgw;
    float rid = 0.04 * (exp(-d1 * d1) * step(1.5, ridges) + 0.7 * exp(-d2 * d2) * step(2.5, ridges)) / (rgw * 1.7724539);
    float v = 0.6 * fill * (1.0 - 0.55 * uLight) + (1.6 * ew * 0.886 * eg + rid) * (1.0 + 1.3 * uLight);
    if (pass == 0) res0 = v;
    else res1 = v;
  }
  return vec2(res0, res1);
}

float axis(float x) {
  float a = uAmplitude;
  return -0.2318 + uLean.y * 0.06 + (-0.2394 + uLean.x * 0.1) * x + 0.2815 * a * x * x + 0.3368 * a * x * x * x;
}

float softp(float z) {
  return 0.03 * log(1.0 + exp(clamp(z / 0.03, -60.0, 60.0)));
}

vec3 light(vec2 u, float fp, float bend, float level, out float halo) {
  float amp = level < 0.65 ? mix(0.25, 1.0, sstep(0.0, 0.65, level)) : mix(1.0, 1.12, (level - 0.65) / 0.35);
  float grow = clamp((amp - 0.25) / 0.75, 0.0, 1.25);
  float x = u.x / uScale;
  float uy = u.y;
  float ya = axis(x);
  float taper = max(uTaper, 0.05);
  float bx = 0.0437 + uMotion.z + uLean.x * 0.08;
  float bump = exp(-pow((x - bx) / (0.6879 * taper), 2.0));
  float hW = 0.02 + softp(-0.12 + 0.5324 * uAmplitude * grow * uMotion.y * bump - 0.02);
  float k = 1.0 * uWaviness;
  float cphi = cos(0.5 * PI + k * (x + 0.0664) + uMotion.x);
  float envC = (0.0886 + 0.3 * exp(-pow((x - 0.0634) / 0.6873, 2.0))) * uSpread * grow;
  float hC = -envC * tanh(cphi / 0.6);
  float th = 0.051 * uThickness * exp(-pow(cphi / 0.5, 2.0));
  float sig = sqrt(pow(0.005 + 0.05 * bend, 2.0) + fp * fp + th * th);
  float sigB = sqrt(0.0064 * max(uGlow, 0.05) * max(uGlow, 0.05) + fp * fp + th * th);
  float mend = exp(-pow(abs((x + 0.0421) / (0.4235 * taper)), 2.2689));
  vec3 red = uColors[0];
  vec3 orange = uColors[1];
  vec3 amber = uColors[2];
  vec3 warmWhite = uColors[3];
  vec3 cyan = uColors[4];
  vec3 blue = uColors[5];
  vec3 deep = uColors[6];
  vec3 orangeEdge = orange * vec3(1.0, 0.85, 0.77);
  vec3 coolCore = mix(warmWhite, vec3(1.0, 1.0, 0.7), 0.6);
  vec3 mint = clamp(mix(cyan, warmWhite, 0.35) * vec3(0.92, 1.05, 0.95), 0.0, 1.0);
  float ridges = float(uCount);
  float glow = max(uGlow, 0.0);
  vec3 L = vec3(0.0);
  vec3 Lb = vec3(0.0);
  {
    float H = max(abs(hW), 1e-4);
    float tt = uy - ya;
    vec2 w = sheetW(tt, H, sig, sigB, ridges);
    float f = clamp(tt / H, 0.0, 1.0);
    vec3 c = grad4(warmWhite, amber, orange, orangeEdge, 0.2351, 0.5643, f);
    c = mix(c, red, sstep(0.75, 1.0, f) * sstep(0.196, 0.3376, hW));
    vec3 mean = (grad4(warmWhite, amber, orange, orangeEdge, 0.2351, 0.5643, 0.1) + grad4(warmWhite, amber, orange, orangeEdge, 0.2351, 0.5643, 0.35) + grad4(warmWhite, amber, orange, orangeEdge, 0.2351, 0.5643, 0.6) + grad4(warmWhite, amber, orange, orangeEdge, 0.2351, 0.5643, 0.9)) * 0.25;
    L += mix(c, mean, sstep(0.3, 1.2, sig / H)) * (w.x * 0.2101 * mend);
    Lb += mix(c, mean, sstep(0.3, 1.2, sigB / H)) * (w.y * 0.2101 * mend);
  }
  {
    float H = max(abs(hC), 1e-4);
    float tt = (uy - ya) * (hC >= 0.0 ? 1.0 : -1.0);
    vec2 w = sheetW(tt, H, sig, sigB, 1.0);
    float f = clamp(tt / H, 0.0, 1.0);
    vec3 c = grad4(coolCore, cyan, blue, deep, 0.15, 0.7931, f);
    vec3 mean = (grad4(coolCore, cyan, blue, deep, 0.15, 0.7931, 0.1) + grad4(coolCore, cyan, blue, deep, 0.15, 0.7931, 0.35) + grad4(coolCore, cyan, blue, deep, 0.15, 0.7931, 0.6) + grad4(coolCore, cyan, blue, deep, 0.15, 0.7931, 0.9)) * 0.25;
    L += mix(c, mean, sstep(0.3, 1.2, sig / H)) * (w.x * 0.28 * mend);
    Lb += mix(c, mean, sstep(0.3, 1.2, sigB / H)) * (w.y * 0.28 * mend);
  }
  vec3 G = vec3(0.0);
  float wh = sqrt(0.0256 + envC * envC * cphi * cphi);
  float dg = (uy - ya) / wh;
  G += vec3(1.0, 0.97, 0.92) * (exp(-dg * dg) * 0.0315 / wh * mend * glow);
  float nx = -0.0664 - uMotion.x / k + 0.2168;
  float bxx = (x - nx) / 0.1849;
  float byy = (uy - axis(nx) - 0.0333) / (0.0544 * mix(0.7, 1.0, min(amp, 1.0)));
  G += mint * (exp(-bxx * bxx - byy * byy) * 1.4 * glow * sstep(0.0, 0.6, amp));
  float hb = (uy - ya - 0.3 * hW) / (0.07 + 0.45 * hW + 0.3 * envC);
  halo = exp(-hb * hb) * mend * smoothstep(0.0, 0.3, uIntro);
  vec3 total = L + 0.16 * glow * Lb + 1.16 * G;
  return total * 2.4 * uIntensity * smoothstep(0.0, 0.3, uIntro) * sstep(uIntro * 1.6, uIntro * 1.6 - 0.5, abs(x));
}

vec2 remap(vec2 p, float f, out float r, out float bend) {
  r = min(length(p), 0.9995);
  bend = pow(r, 5.17);
  float k = clamp(uRefraction, 0.0, 1.8);
  float sc = (1.0 - 0.278 * k * (1.0 - bend)) * (1.0 - 0.632 * k * bend) / (1.0 - 0.278 * k);
  return p * sc * f;
}

void main() {
  vec2 res = uResolution;
  vec2 p = (gl_FragCoord.xy - 0.5 * res) / min(res.x, res.y);
  float level = clamp(uLevel, 0.0, 1.0);
  float appear = smoothstep(0.0, 0.35, uIntro);

  if (uGlass > 0.5) {
    float R = uRadius * mix(0.94, 1.0, uIntro) * (1.0 + 0.03 * uPulse);
    float px = 1.0 / (min(res.x, res.y) * R);
    vec2 pc = p / R;
    float rho = length(pc);
    if (rho > 1.0 + 2.0 * px) {
      float sh = uLight * 0.07 * exp(-pow((rho - 0.985) / 0.07, 2.0)) * smoothstep(-0.6, 0.4, -pc.y) * appear * uOpacity;
      fragColor = vec4(0.0, 0.0, 0.0, sh);
      return;
    }
    float r;
    float bend;
    vec2 u = remap(pc, 1.0, r, bend);
    float fp = 0.5 * max(length(dFdx(u)), length(dFdy(u)));
    float halo;
    float skip;
    vec3 L = light(u, fp, bend, level, halo);
    float ca = 0.02 * uDispersion * bend;
    if (ca > 0.0015) {
      float r2;
      float b2;
      L.r = light(remap(pc, 1.0 - ca, r2, b2), fp, bend, level, skip).r;
      L.b = light(remap(pc, 1.0 + ca, r2, b2), fp, bend, level, skip).b;
    }
    vec3 col = 1.0 - exp(-L);
    vec2 d = pc / max(rho, 1e-6);
    float key = 0.4 * pow(max(0.0, d.x * 0.94 - d.y * 0.34), 6.0) + 0.2 * pow(max(0.0, -d.x * 0.5 + d.y * 0.87), 6.0);
    float ring = exp(-pow((r - 0.985) / 0.011, 2.0));
    float hzk = 0.25 + 0.7 * pow(max(0.0, -d.x * 0.6 + d.y * 0.8), 2.0) + pow(max(0.0, d.x * 0.8 - d.y * 0.6), 2.0);
    float haze = exp(-pow((1.0 - r) / 0.09, 2.0)) * hzk * 0.13 * uRim;
    vec3 orb;
    if (uLight > 0.5) {
      float lz = dot(d * r, vec2(-0.55, 0.83));
      vec3 body = mix(vec3(0.885, 0.893, 0.915), vec3(0.972, 0.975, 0.983), 0.5 + 0.5 * lz);
      float fres = smoothstep(0.8, 1.0, r);
      body = mix(body, vec3(0.82, 0.83, 0.86), fres * fres * 0.5);
      orb = lightInk(L, halo, body);
      float spec = exp(-pow((r - 0.955) / 0.03, 2.0)) * pow(max(0.0, dot(d, vec2(-0.55, 0.83))), 3.0);
      orb = mix(orb, vec3(1.0), clamp(spec * 0.85 * uRim + haze * 0.6, 0.0, 1.0));
      float edge = exp(-pow((1.0 - r) / (0.01 + 1.2 * px), 2.0));
      orb *= 1.0 - 0.12 * edge;
    } else {
      orb = vec3(0.04) + col * (1.0 + 0.1 * bend * uRim) + ring * key * uRim * (1.0 + 0.4 * level) + haze * vec3(1.0, 1.02, 1.04);
      orb = grade(clamp(orb, 0.0, 1.0));
    }
    float inside = clamp((1.0 - rho) / px + 0.5, 0.0, 1.0) * appear;
    vec3 rgb = orb * inside;
    fragColor = vec4(rgb, max(inside * mix(0.92, 1.0, uLight), max(max(rgb.r, rgb.g), rgb.b))) * uOpacity;
  } else {
    float span = 0.5 * res.x / min(res.x, res.y);
    vec2 u = p * (0.78 / span) + vec2(0.0, -0.15);
    float fp = 0.5 * max(length(dFdx(u)), length(dFdy(u)));
    float halo;
    float fade = sstep(0.82, 0.55, abs(u.x));
    vec3 L = light(u, fp, 0.0, level, halo) * fade;
    vec3 col = grade(1.0 - exp(-L)) * appear;
    if (uLight > 0.5) {
      vec3 c = lightInk(L, halo * fade * 0.6, vec3(1.0));
      float a = clamp(1.0 - min(c.r, min(c.g, c.b)), 0.0, 1.0) * appear;
      fragColor = vec4((c - (1.0 - a)) * appear, a) * uOpacity;
    } else {
      fragColor = vec4(col, max(max(col.r, col.g), col.b)) * uOpacity;
    }
  }
}
`;

const hexToRgb = (hex: string): [number, number, number] => {
  let h = String(hex).replace('#', '').trim();
  if (h.length === 3) h = h.replace(/(.)/g, '$1$1');
  const v = parseInt(h.slice(0, 6), 16);
  if (!isFinite(v)) return [1, 1, 1];
  return [((v >> 16) & 255) / 255, ((v >> 8) & 255) / 255, (v & 255) / 255];
};

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const compile = (gl: WebGL2RenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type) as WebGLShader;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  return shader;
};

const createProgram = (gl: WebGL2RenderingContext) => {
  const program = gl.createProgram() as WebGLProgram;
  gl.attachShader(program, compile(gl, gl.VERTEX_SHADER, VERT));
  gl.attachShader(program, compile(gl, gl.FRAGMENT_SHADER, FRAG));
  gl.bindAttribLocation(program, 0, 'position');
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;
  return program;
};

const smooth = (a: number, b: number, x: number) => {
  const k = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return k * k * (3 - 2 * k);
};

const speech = (t: number) => {
  const phrase = smooth(-0.8, -0.3, 0.6 * Math.sin(t * 2.7) + 0.5 * Math.sin(t * 1.53 + 1.2));
  const syllable = Math.max(0, Math.sin(t * 17 + 1.6 * Math.sin(t * 5.3)));
  const stress = 0.6 + 0.4 * Math.sin(t * 3.7 + 0.7);
  return phrase * (0.35 + 0.65 * syllable) * (0.25 + stress);
};

const DEFAULT_COLORS = ['#d95b56', '#ba5046', '#ffa24c', '#ffe0b3', '#93f1ff', '#3569fa', '#193d9b'];

export default function Strands({
  colors = DEFAULT_COLORS,
  count = 3,
  speed = 1,
  amplitude = 1,
  waviness = 1,
  thickness = 1,
  glow = 1,
  taper = 1,
  spread = 1,
  hueShift = 0,
  intensity = 1,
  saturation = 1,
  opacity = 1,
  scale = 1,
  glass = true,
  refraction = 1,
  dispersion = 1,
  glassSize = 1,
  rim = 1,
  energy = 0.65,
  listening = false,
  level,
  interactive = true,
  clickPulse = true,
  intro = true,
  lightMode = false,
  maxDevicePixelRatio = 2,
  className = '',
  style
}: StrandsProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const propsRef = useRef<StrandsConfig>({} as StrandsConfig);
  propsRef.current = {
    colors,
    count,
    speed,
    amplitude,
    waviness,
    thickness,
    glow,
    taper,
    spread,
    hueShift,
    intensity,
    saturation,
    opacity,
    scale,
    glass,
    refraction,
    dispersion,
    glassSize,
    rim,
    energy,
    listening,
    level,
    interactive,
    clickPulse,
    intro,
    lightMode,
    maxDevicePixelRatio
  };

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const canvas = document.createElement('canvas');
    canvas.style.display = 'block';
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    canvas.setAttribute('aria-hidden', 'true');
    const gl = canvas.getContext('webgl2', { alpha: true, premultipliedAlpha: true, antialias: false });
    if (!gl) return;
    container.appendChild(canvas);

    let program: WebGLProgram | null = null;
    let buffer: WebGLBuffer | null = null;
    let loc: Record<string, WebGLUniformLocation | null> = {};
    const names = [
      'uResolution',
      'uMotion',
      'uLevel',
      'uColors',
      'uCount',
      'uAmplitude',
      'uWaviness',
      'uThickness',
      'uGlow',
      'uTaper',
      'uSpread',
      'uHueShift',
      'uIntensity',
      'uSaturation',
      'uScale',
      'uGlass',
      'uRadius',
      'uRefraction',
      'uDispersion',
      'uRim',
      'uLean',
      'uIntro',
      'uPulse',
      'uLight',
      'uOpacity'
    ];
    const setup = () => {
      const next = createProgram(gl);
      if (!next) return false;
      program = next;
      buffer = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
      gl.enableVertexAttribArray(0);
      gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
      gl.useProgram(next);
      loc = Object.fromEntries(names.map(name => [name, gl.getUniformLocation(next, name)]));
      gl.disable(gl.BLEND);
      gl.clearColor(0, 0, 0, 0);
      return true;
    };
    if (!setup()) {
      canvas.remove();
      return;
    }

    const query =
      typeof window.matchMedia === 'function' ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
    const st = {
      clock: 0,
      pace: 0,
      activity: 0,
      hover: 0,
      hoverTarget: 0,
      burst: 0,
      lean: [0, 0] as number[],
      leanTarget: [0, 0] as number[],
      pulse: 0,
      pulseV: 0,
      introStart: -1,
      intro: propsRef.current.intro ? 0 : 1,
      visible: typeof IntersectionObserver === 'undefined',
      lost: false,
      raf: 0,
      last: 0,
      width: 0,
      height: 0,
      speechT: 0,
      paletteKey: '',
      palette: { flat: new Float32Array(MAX_COLORS * 3), count: 1 }
    };

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, Math.max(0.5, propsRef.current.maxDevicePixelRatio));
      const w = Math.max(1, Math.round(container.clientWidth * dpr));
      const h = Math.max(1, Math.round(container.clientHeight * dpr));
      if (w !== st.width || h !== st.height) {
        st.width = w;
        st.height = h;
        canvas.width = w;
        canvas.height = h;
      }
    };

    const updatePalette = (list: string[]) => {
      const key = list.join(',');
      if (key === st.paletteKey) return;
      st.paletteKey = key;
      const rgb = (list.length ? list : DEFAULT_COLORS).slice(0, MAX_COLORS).map(hexToRgb);
      const flat = new Float32Array(MAX_COLORS * 3);
      for (let i = 0; i < ROLES; i++) {
        const t = rgb.length > 1 ? (i / (ROLES - 1)) * (rgb.length - 1) : 0;
        const a = Math.floor(t);
        const b = Math.min(a + 1, rgb.length - 1);
        const f = t - a;
        flat.set(
          rgb[a].map((c, k) => c + (rgb[b][k] - c) * f),
          i * 3
        );
      }
      st.palette = { flat, count: ROLES };
    };

    const draw = () => {
      if (st.lost || !program) return;
      const p = propsRef.current;
      updatePalette(Array.isArray(p.colors) ? p.colors : []);
      gl.viewport(0, 0, st.width, st.height);
      gl.uniform2f(loc.uResolution, st.width, st.height);
      const c = st.clock;
      const sway = 0.75 + 0.45 * st.pace;
      gl.uniform3f(
        loc.uMotion,
        (0.26 * Math.sin(0.53 * c) + 0.1 * Math.sin(1.19 * c + 1.3)) * sway,
        1 + (0.06 * Math.sin(0.71 * c) + 0.035 * Math.sin(1.37 * c + 0.4)) * sway,
        0.06 * Math.sin(0.41 * c + 2) * sway
      );
      gl.uniform1f(loc.uLevel, clamp(st.activity, 0, 1));
      gl.uniform3fv(loc.uColors, st.palette.flat);
      gl.uniform1i(loc.uCount, clamp(Math.round(p.count), 1, 3));
      gl.uniform1f(loc.uAmplitude, p.amplitude);
      gl.uniform1f(loc.uWaviness, p.waviness);
      gl.uniform1f(loc.uThickness, p.thickness);
      gl.uniform1f(loc.uGlow, p.glow);
      gl.uniform1f(loc.uTaper, Math.max(0.05, p.taper));
      gl.uniform1f(loc.uSpread, p.spread);
      gl.uniform1f(loc.uHueShift, p.hueShift);
      gl.uniform1f(loc.uIntensity, p.intensity);
      gl.uniform1f(loc.uSaturation, p.saturation);
      gl.uniform1f(loc.uScale, Math.max(0.05, p.scale));
      gl.uniform1f(loc.uGlass, p.glass ? 1 : 0);
      gl.uniform1f(loc.uRadius, 0.42 * p.glassSize);
      gl.uniform1f(loc.uRefraction, p.refraction);
      gl.uniform1f(loc.uDispersion, p.dispersion);
      gl.uniform1f(loc.uRim, p.rim);
      gl.uniform2f(loc.uLean, st.lean[0], st.lean[1]);
      gl.uniform1f(loc.uIntro, st.intro);
      gl.uniform1f(loc.uPulse, st.pulse);
      gl.uniform1f(loc.uLight, p.lightMode ? 1 : 0);
      gl.uniform1f(loc.uOpacity, p.opacity);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    };

    const frame = (now: number) => {
      st.raf = 0;
      const p = propsRef.current;
      const dt = st.last ? clamp((now - st.last) / 1000, 0, 0.05) : 0;
      st.last = now;
      const reduced = !!query?.matches;
      if (st.introStart < 0 && st.visible) st.introStart = now;
      if (p.intro && !reduced && st.introStart >= 0) {
        const t = clamp((now - st.introStart) / 1400, 0, 1);
        st.intro = 1 - Math.pow(1 - t, 3);
      } else {
        st.intro = 1;
      }
      st.hover += (st.hoverTarget - st.hover) * (1 - Math.exp(-dt / (st.hoverTarget > st.hover ? 0.25 : 0.6)));
      for (let i = 0; i < 2; i++) st.lean[i] += (st.leanTarget[i] - st.lean[i]) * (1 - Math.exp(-dt / 0.35));
      st.pulseV += (-170 * st.pulse - 14 * st.pulseV) * dt;
      st.pulse += st.pulseV * dt;
      st.burst *= Math.exp(-dt / 0.45);
      if (p.listening && !reduced) st.speechT += dt;
      const voice =
        typeof p.level === 'number' ? clamp(p.level, 0, 1) : p.listening && !reduced ? speech(st.speechT) : 0;
      const target = Math.min(1.2, Math.max(clamp(p.energy, 0, 1), voice) + st.hover * 0.18 + st.burst);
      st.activity += (target - st.activity) * (1 - Math.exp(-dt / (target > st.activity ? 0.12 : 0.4)));
      st.pace += (Math.min(1, st.activity) - st.pace) * (1 - Math.exp(-dt / 0.8));
      if (!reduced) {
        st.clock += dt * p.speed * (0.6 + 1.6 * st.pace);
      }
      draw();
      const settled =
        reduced &&
        Math.abs(st.activity - target) < 1e-3 &&
        Math.abs(st.pulse) < 1e-3 &&
        Math.abs(st.pulseV) < 1e-3 &&
        st.burst < 1e-3 &&
        Math.abs(st.hover - st.hoverTarget) < 1e-3 &&
        Math.abs(st.lean[0] - st.leanTarget[0]) < 1e-3 &&
        Math.abs(st.lean[1] - st.leanTarget[1]) < 1e-3;
      if (st.visible && !document.hidden && !st.lost && !settled) st.raf = requestAnimationFrame(frame);
    };

    const wake = () => {
      if (!st.raf && st.visible && !st.lost) {
        st.last = 0;
        st.raf = requestAnimationFrame(frame);
      }
    };

    const local = (e: PointerEvent): [number, number] => {
      const r = container.getBoundingClientRect();
      const m = Math.min(r.width, r.height) || 1;
      return [(e.clientX - r.left - r.width / 2) / (m / 2), (e.clientY - r.top - r.height / 2) / (m / 2)];
    };

    const onMove = (e: PointerEvent) => {
      if (!propsRef.current.interactive) return;
      const [x, y] = local(e);
      st.hoverTarget = clamp(1.6 - Math.hypot(x, y), 0, 1);
      st.leanTarget = [clamp(x, -1.2, 1.2) * 0.8, clamp(-y, -1.2, 1.2) * 0.8];
      wake();
    };

    const onLeave = () => {
      st.hoverTarget = 0;
      st.leanTarget = [0, 0];
      wake();
    };

    const onDown = () => {
      if (!propsRef.current.clickPulse) return;
      st.pulseV += 5;
      st.burst = Math.min(1.2, st.burst + 0.9);
      wake();
    };

    const onLost = (e: Event) => {
      e.preventDefault();
      st.lost = true;
      if (st.raf) cancelAnimationFrame(st.raf);
      st.raf = 0;
    };

    const onRestored = () => {
      st.lost = false;
      if (setup()) wake();
    };

    canvas.addEventListener('webglcontextlost', onLost);
    canvas.addEventListener('webglcontextrestored', onRestored);
    container.addEventListener('pointermove', onMove);
    container.addEventListener('pointerleave', onLeave);
    container.addEventListener('pointerdown', onDown);

    const resizeObserver = new ResizeObserver(() => {
      resize();
      draw();
    });
    resizeObserver.observe(container);
    resize();

    let intersection: IntersectionObserver | null = null;
    if (typeof IntersectionObserver !== 'undefined') {
      intersection = new IntersectionObserver(entries => {
        st.visible = entries[entries.length - 1].isIntersecting;
        if (st.visible) wake();
      });
      intersection.observe(container);
    }
    const onVisibility = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener('visibilitychange', onVisibility);
    wake();

    return () => {
      if (st.raf) cancelAnimationFrame(st.raf);
      canvas.removeEventListener('webglcontextlost', onLost);
      canvas.removeEventListener('webglcontextrestored', onRestored);
      container.removeEventListener('pointermove', onMove);
      container.removeEventListener('pointerleave', onLeave);
      container.removeEventListener('pointerdown', onDown);
      document.removeEventListener('visibilitychange', onVisibility);
      resizeObserver.disconnect();
      intersection?.disconnect();
      if (program) gl.deleteProgram(program);
      if (buffer) gl.deleteBuffer(buffer);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
      canvas.remove();
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className={`relative h-full w-full bg-transparent [-webkit-tap-highlight-color:transparent] ${className}`.trim()}
      style={style}
    />
  );
}

'use client';

import { useEffect, useRef, type CSSProperties, type HTMLAttributes, type ReactNode } from 'react';

export type SwarmShape = 'dot' | 'streak' | 'square';
export type SwarmIdle = 'roam' | 'gather' | 'hide';
export type SwarmClickEffect = 'burst' | 'pulse' | 'none';

export interface SwarmCursorProps extends Omit<HTMLAttributes<HTMLDivElement>, 'style' | 'color'> {
  count?: number;
  size?: number;
  shape?: SwarmShape;
  color?: string;
  accentColor?: string;
  spread?: number;
  speed?: number;
  swirl?: number;
  tail?: number;
  trail?: number;
  wander?: number;
  depth?: number;
  targets?: string;
  idle?: SwarmIdle;
  clickEffect?: SwarmClickEffect;
  hideCursor?: boolean;
  intro?: boolean;
  enabled?: boolean;
  lightMode?: boolean;
  dpr?: number;
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

type Settings = {
  count: number;
  size: number;
  shape: number;
  color: string;
  accentColor: string;
  spread: number;
  speed: number;
  swirl: number;
  tail: number;
  trail: number;
  wander: number;
  depth: number;
  targets: string;
  idle: SwarmIdle;
  clickEffect: SwarmClickEffect;
  hideCursor: boolean;
  intro: boolean;
  enabled: boolean;
  lightMode: boolean;
  dpr?: number;
};

type Program = { program: WebGLProgram; uniforms: Record<string, WebGLUniformLocation | null> };

const MAX_PARTICLES = 2000;
const INTRO_SECONDS = 1.4;
const HIDDEN = 'swarm-cursor-hidden';
const SHAPES: Record<string, number> = { dot: 0, square: 1, streak: 2 };
const CELL = 16;
const MAX_COLS = 72;
const MAX_ROWS = 48;
const PRESSURE_STEPS = 12;

const VERTEX = `#version 300 es
layout(location = 0) in vec2 aCorner;
layout(location = 1) in vec4 aAgent;
layout(location = 2) in vec4 aLook;
layout(location = 3) in vec2 aExtra;
uniform vec2 uView;
out vec2 vLocal;
out vec2 vHalf;
out float vAlpha;
out float vTint;
out float vSoft;
out float vShape;

void main() {
  vec2 dir = aAgent.zw;
  vec2 side = vec2(-dir.y, dir.x);
  vec2 extent = aLook.xy * 0.5;
  vec2 pad = extent + 1.0 + aExtra.x * 1.5;
  vec2 local = aCorner * pad;
  vec2 center = aAgent.xy - dir * (extent.x - extent.y);
  vec2 pos = center + dir * local.x + side * local.y;
  vLocal = local;
  vHalf = extent;
  vAlpha = aLook.z;
  vTint = aLook.w;
  vSoft = aExtra.x;
  vShape = aExtra.y;
  vec2 clip = pos / uView * 2.0 - 1.0;
  gl_Position = vec4(clip.x, -clip.y, 0.0, 1.0);
}`;

const FRAGMENT = `#version 300 es
precision highp float;
uniform vec3 uColor;
uniform vec3 uAccent;
uniform float uRatio;
in vec2 vLocal;
in vec2 vHalf;
in float vAlpha;
in float vTint;
in float vSoft;
in float vShape;
out vec4 outColor;

void main() {
  float d;
  if (vShape > 0.5 && vShape < 1.5) {
    float corner = vHalf.y * 0.3;
    vec2 q = abs(vLocal) - vHalf + corner;
    d = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - corner;
  } else {
    vec2 q = vLocal;
    q.x = max(abs(q.x) - (vHalf.x - vHalf.y), 0.0);
    d = length(q) - vHalf.y;
  }
  float edge = 0.6 / uRatio + vSoft;
  float cover = 1.0 - smoothstep(-edge, edge, d);
  float stretch = clamp(1.0 - vHalf.y / max(vHalf.x, 0.001), 0.0, 1.0);
  float head = clamp((vLocal.x + vHalf.x) / max(2.0 * vHalf.x, 0.001), 0.0, 1.0);
  cover *= mix(1.0, 0.12 + 0.88 * head * head, stretch);
  float alpha = cover * vAlpha;
  outColor = vec4(mix(uColor, uAccent, vTint) * alpha, alpha);
}`;

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const compile = (gl: WebGL2RenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
};

const link = (gl: WebGL2RenderingContext): Program | null => {
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  const uniforms: Record<string, WebGLUniformLocation | null> = {};
  const count = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < count; i++) {
    const info = gl.getActiveUniform(program, i);
    if (info) uniforms[info.name] = gl.getUniformLocation(program, info.name);
  }
  return { program, uniforms };
};

const random = (seed: number) => {
  let state = seed >>> 0 || 1;
  return () => {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    return (state >>> 0) / 4294967296;
  };
};

const rectField = (x: number, y: number, hx: number, hy: number, r: number, out: number[]) => {
  const sx = x < 0 ? -1 : 1;
  const sy = y < 0 ? -1 : 1;
  const qx = Math.abs(x) - (hx - r);
  const qy = Math.abs(y) - (hy - r);
  if (qx > 0 && qy > 0) {
    const l = Math.hypot(qx, qy) || 1;
    out[0] = l - r;
    out[1] = (qx / l) * sx;
    out[2] = (qy / l) * sy;
  } else if (qx > qy) {
    out[0] = qx - r;
    out[1] = sx;
    out[2] = 0;
  } else {
    out[0] = qy - r;
    out[1] = 0;
    out[2] = sy;
  }
  return out;
};

const SwarmCursor = ({
  count = 800,
  size = 2.6,
  shape = 'dot',
  color,
  accentColor,
  spread = 90,
  speed = 1,
  swirl = 0.6,
  tail = 0.5,
  trail = 0.6,
  wander = 0.5,
  depth = 0.7,
  targets = 'a, button, [data-swarm-target]',
  idle = 'roam',
  clickEffect = 'burst',
  hideCursor = false,
  intro = true,
  enabled = true,
  lightMode = false,
  dpr,
  children,
  className = '',
  style,
  ...rest
}: SwarmCursorProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wakeRef = useRef<(() => void) | null>(null);
  const ink = lightMode ? '#18181b' : '#ffffff';
  const settings: Settings = {
    count: Math.round(clamp(count, 1, MAX_PARTICLES)),
    size: clamp(size, 0.5, 16),
    shape: SHAPES[shape] ?? 0,
    color: color || ink,
    accentColor: accentColor || color || ink,
    spread: clamp(spread, 20, 400),
    speed: clamp(speed, 0, 4),
    swirl: clamp(swirl, 0, 1),
    tail: clamp(tail, 0, 1),
    trail: clamp(trail, 0, 3),
    wander: clamp(wander, 0, 2),
    depth: clamp(depth, 0, 1),
    targets,
    idle,
    clickEffect,
    hideCursor,
    intro,
    enabled,
    lightMode,
    dpr
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    const gl = canvas?.getContext('webgl2', {
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      depth: false,
      stencil: false
    });
    if (!container || !canvas || !gl) return undefined;
    const shader = link(gl);
    if (!shader) return undefined;
    const u = shader.uniforms;

    const slots = MAX_PARTICLES + 1;
    const vao = gl.createVertexArray();
    gl.bindVertexArray(vao);
    const cornerBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, cornerBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    const agentData = new Float32Array(slots * 4);
    const lookData = new Float32Array(slots * 4);
    const extraData = new Float32Array(slots * 2);
    const instanced = (location: number, width: number, data: Float32Array) => {
      const buffer = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
      gl.bufferData(gl.ARRAY_BUFFER, data.byteLength, gl.DYNAMIC_DRAW);
      gl.enableVertexAttribArray(location);
      gl.vertexAttribPointer(location, width, gl.FLOAT, false, 0, 0);
      gl.vertexAttribDivisor(location, 1);
      return buffer;
    };
    const agentBuffer = instanced(1, 4, agentData);
    const lookBuffer = instanced(2, 4, lookData);
    const extraBuffer = instanced(3, 2, extraData);
    gl.bindVertexArray(null);

    const probe = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
    const colorCache = new Map<string, number[]>();
    const parse = (value: string): number[] => {
      const key = String(value);
      const cached = colorCache.get(key);
      if (cached) return cached;
      let rgb = [1, 1, 1];
      if (probe) {
        probe.clearRect(0, 0, 1, 1);
        probe.fillStyle = '#000000';
        probe.fillStyle = key;
        probe.fillRect(0, 0, 1, 1);
        const [r, g, b] = probe.getImageData(0, 0, 1, 1).data;
        rgb = [r / 255, g / 255, b / 255];
      }
      colorCache.set(key, rgb);
      return rgb;
    };

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const view = { width: 1, height: 1, ratio: 1 };
    const px = new Float32Array(MAX_PARTICLES);
    const py = new Float32Array(MAX_PARTICLES);
    const pz = new Float32Array(MAX_PARTICLES);
    const vx = new Float32Array(MAX_PARTICLES);
    const vy = new Float32Array(MAX_PARTICLES);
    const vz = new Float32Array(MAX_PARTICLES);
    const home = new Float32Array(MAX_PARTICLES);
    const heft = new Float32Array(MAX_PARTICLES);
    const bob = new Float32Array(MAX_PARTICLES);
    const bobRate = new Float32Array(MAX_PARTICLES);
    const grain = new Float32Array(MAX_PARTICLES);
    const glint = new Float32Array(MAX_PARTICLES);
    const order = new Int32Array(MAX_PARTICLES);
    const field = [0, 0, 0];
    let cols = 1;
    let rows = 1;
    let cell = CELL;
    let flowX = new Float32Array(1);
    let flowY = new Float32Array(1);
    let lastX = new Float32Array(1);
    let lastY = new Float32Array(1);
    let pressure = new Float32Array(1);
    let divergence = new Float32Array(1);
    let curl = new Float32Array(1);
    const pointer = { x: 0, y: 0, inside: false };
    const anchor = { x: 0, y: 0, lastX: 0, lastY: 0, moveX: 0, moveY: 0 };
    const ring = { active: false, x: 0, y: 0, hx: 0, hy: 0, corner: 0, spin: 1 };
    const burst = { age: 10 };
    const ping = { age: 10, x: 0, y: 0 };
    let hovered: Element | null = null;
    let time = 0;
    let presence = 1;
    let introClock = settingsRef.current.intro && !reduce ? 0 : 1;
    let raf = 0;
    let last = 0;
    let visible = true;
    let seeded = false;
    let hidden = false;
    let sorted = 0;

    const setHidden = (value: boolean) => {
      if (value === hidden) return;
      hidden = value;
      container.classList.toggle(HIDDEN, value);
    };

    const allocate = () => {
      const nextCols = clamp(Math.round(view.width / CELL), 8, MAX_COLS);
      const nextRows = clamp(Math.round(view.height / CELL), 8, MAX_ROWS);
      cell = Math.max(view.width / nextCols, view.height / nextRows);
      if (nextCols === cols && nextRows === rows) return;
      cols = nextCols;
      rows = nextRows;
      const total = cols * rows;
      flowX = new Float32Array(total);
      flowY = new Float32Array(total);
      lastX = new Float32Array(total);
      lastY = new Float32Array(total);
      pressure = new Float32Array(total);
      divergence = new Float32Array(total);
      curl = new Float32Array(total);
    };

    const sample = (values: Float32Array, x: number, y: number) => {
      let gx = x / cell - 0.5;
      let gy = y / cell - 0.5;
      if (gx < 0) gx = 0;
      else if (gx > cols - 1.001) gx = cols - 1.001;
      if (gy < 0) gy = 0;
      else if (gy > rows - 1.001) gy = rows - 1.001;
      const i = gx | 0;
      const j = gy | 0;
      const fx = gx - i;
      const fy = gy - j;
      const k = i + j * cols;
      return (
        (values[k] * (1 - fx) + values[k + 1] * fx) * (1 - fy) +
        (values[k + cols] * (1 - fx) + values[k + cols + 1] * fx) * fy
      );
    };

    const walls = (values: Float32Array, axis: number) => {
      for (let j = 1; j < rows - 1; j++) {
        const left = j * cols;
        const right = left + cols - 1;
        values[left] = axis === 1 ? -values[left + 1] : values[left + 1];
        values[right] = axis === 1 ? -values[right - 1] : values[right - 1];
      }
      for (let i = 1; i < cols - 1; i++) {
        const bottom = i + (rows - 1) * cols;
        values[i] = axis === 2 ? -values[i + cols] : values[i + cols];
        values[bottom] = axis === 2 ? -values[bottom - cols] : values[bottom - cols];
      }
      values[0] = 0.5 * (values[1] + values[cols]);
      values[cols - 1] = 0.5 * (values[cols - 2] + values[2 * cols - 1]);
      values[(rows - 1) * cols] = 0.5 * (values[(rows - 2) * cols] + values[(rows - 1) * cols + 1]);
      values[rows * cols - 1] = 0.5 * (values[rows * cols - 2] + values[(rows - 1) * cols - 1]);
    };

    const stir = (s: Settings, dt: number, ease: number) => {
      const radius = s.spread;
      const reach = radius * 2.2;
      const i0 = Math.max(1, Math.floor((anchor.x - reach) / cell));
      const i1 = Math.min(cols - 2, Math.ceil((anchor.x + reach) / cell));
      const j0 = Math.max(1, Math.floor((anchor.y - reach) / cell));
      const j1 = Math.min(rows - 2, Math.ceil((anchor.y + reach) / cell));
      const inv = 1 / (radius * radius * 0.55);
      const moving = Math.hypot(anchor.moveX, anchor.moveY);
      const grab = (1 - Math.exp(-dt * 20)) * clamp(moving / 240, 0, 1) * presence;
      const whirl = ring.active ? 0 : radius * (0.5 + 4 * (1 - ease)) * (0.35 + 0.65 * s.speed);
      const churn = s.wander * radius * 14 * (0.4 + 0.6 * s.speed);
      const fk = 1.4 / radius;
      const ft = time * 0.75 * (0.4 + 0.6 * s.speed);
      for (let j = j0; j <= j1; j++) {
        for (let i = i0; i <= i1; i++) {
          const k = i + j * cols;
          const x = (i + 0.5) * cell;
          const y = (j + 0.5) * cell;
          const rx = x - anchor.x;
          const ry = y - anchor.y;
          const d2 = rx * rx + ry * ry;
          const w = Math.exp(-d2 * inv);
          if (w < 0.003) continue;
          const d = Math.sqrt(d2) + 0.001;
          flowX[k] += (anchor.moveX - flowX[k]) * w * grab;
          flowY[k] += (anchor.moveY - flowY[k]) * w * grab;
          const reachOut = Math.min(1, d / (radius * 0.45));
          flowX[k] += (-ry / d) * whirl * reachOut * w * dt;
          flowY[k] += (rx / d) * whirl * reachOut * w * dt;
          const a1 = x * fk + ft;
          const b1 = y * fk * 1.1 - ft * 0.8;
          const a2 = y * fk * 1.7 + ft * 1.2 + 1.3;
          const b2 = x * fk * 1.3 - 0.7;
          const curlX = -Math.sin(a1) * Math.sin(b1) * 1.1 + 1.02 * Math.cos(a2) * Math.cos(b2);
          const curlY = -(Math.cos(a1) * Math.cos(b1) - 0.78 * Math.sin(a2) * Math.sin(b2));
          flowX[k] += curlX * churn * w * dt;
          flowY[k] += curlY * churn * w * dt;
        }
      }
      if (!ring.active) return;
      const band = Math.max(4, radius * 0.16);
      const margin = band + 24;
      const circulate = 230 * (0.4 + 0.6 * s.speed) * ring.spin;
      const r0 = Math.max(1, Math.floor((ring.x - ring.hx - margin) / cell));
      const r1 = Math.min(cols - 2, Math.ceil((ring.x + ring.hx + margin) / cell));
      const c0 = Math.max(1, Math.floor((ring.y - ring.hy - margin) / cell));
      const c1 = Math.min(rows - 2, Math.ceil((ring.y + ring.hy + margin) / cell));
      const rate = 1 - Math.exp(-dt * 6);
      for (let j = c0; j <= c1; j++) {
        for (let i = r0; i <= r1; i++) {
          const k = i + j * cols;
          rectField((i + 0.5) * cell - ring.x, (j + 0.5) * cell - ring.y, ring.hx, ring.hy, ring.corner, field);
          const off = field[0] - (5 + band * 0.5);
          const w = Math.exp(-(off * off) / (margin * margin * 0.35));
          if (w < 0.01) continue;
          flowX[k] += (-field[2] * circulate - flowX[k]) * w * rate;
          flowY[k] += (field[1] * circulate - flowY[k]) * w * rate;
        }
      }
    };

    const flow = (s: Settings, dt: number) => {
      const total = cols * rows;
      for (let j = 1; j < rows - 1; j++) {
        for (let i = 1; i < cols - 1; i++) {
          const k = i + j * cols;
          curl[k] = (flowY[k + 1] - flowY[k - 1] - flowX[k + cols] + flowX[k - cols]) * (0.5 / cell);
        }
      }
      const confine = s.swirl * cell * 9;
      for (let j = 2; j < rows - 2; j++) {
        for (let i = 2; i < cols - 2; i++) {
          const k = i + j * cols;
          const gx = Math.abs(curl[k + 1]) - Math.abs(curl[k - 1]);
          const gy = Math.abs(curl[k + cols]) - Math.abs(curl[k - cols]);
          const len = Math.hypot(gx, gy) + 1e-5;
          flowX[k] += (gy / len) * curl[k] * confine * dt;
          flowY[k] -= (gx / len) * curl[k] * confine * dt;
        }
      }
      lastX.set(flowX);
      lastY.set(flowY);
      const back = dt / cell;
      const fade = Math.exp(-dt / (0.35 + 1.5 * s.swirl));
      for (let j = 1; j < rows - 1; j++) {
        for (let i = 1; i < cols - 1; i++) {
          const k = i + j * cols;
          let x = i - back * lastX[k];
          let y = j - back * lastY[k];
          if (x < 0.5) x = 0.5;
          else if (x > cols - 1.5) x = cols - 1.5;
          if (y < 0.5) y = 0.5;
          else if (y > rows - 1.5) y = rows - 1.5;
          const i0 = x | 0;
          const j0 = y | 0;
          const fx = x - i0;
          const fy = y - j0;
          const a = i0 + j0 * cols;
          flowX[k] =
            ((lastX[a] * (1 - fx) + lastX[a + 1] * fx) * (1 - fy) +
              (lastX[a + cols] * (1 - fx) + lastX[a + cols + 1] * fx) * fy) *
            fade;
          flowY[k] =
            ((lastY[a] * (1 - fx) + lastY[a + 1] * fx) * (1 - fy) +
              (lastY[a + cols] * (1 - fx) + lastY[a + cols + 1] * fx) * fy) *
            fade;
        }
      }
      walls(flowX, 1);
      walls(flowY, 2);
      const h2 = cell * cell;
      for (let j = 1; j < rows - 1; j++) {
        for (let i = 1; i < cols - 1; i++) {
          const k = i + j * cols;
          divergence[k] = (flowX[k + 1] - flowX[k - 1] + flowY[k + cols] - flowY[k - cols]) * (0.5 / cell);
        }
      }
      pressure.fill(0, 0, total);
      walls(divergence, 0);
      for (let step = 0; step < PRESSURE_STEPS; step++) {
        for (let j = 1; j < rows - 1; j++) {
          for (let i = 1; i < cols - 1; i++) {
            const k = i + j * cols;
            pressure[k] =
              (pressure[k - 1] + pressure[k + 1] + pressure[k - cols] + pressure[k + cols] - h2 * divergence[k]) * 0.25;
          }
        }
        walls(pressure, 0);
      }
      for (let j = 1; j < rows - 1; j++) {
        for (let i = 1; i < cols - 1; i++) {
          const k = i + j * cols;
          flowX[k] -= (pressure[k + 1] - pressure[k - 1]) * (0.5 / cell);
          flowY[k] -= (pressure[k + cols] - pressure[k - cols]) * (0.5 / cell);
        }
      }
      walls(flowX, 1);
      walls(flowY, 2);
    };

    const crowd = new Int32Array(MAX_PARTICLES);
    let crowdHeads = new Int32Array(1);
    let crowdRows = 1;
    const push = (n: number, h: number) => {
      const gc = Math.max(1, Math.ceil(view.width / h) + 2);
      const gr = Math.max(1, Math.ceil(view.height / h) + 2);
      if (crowdHeads.length < gc * gr) crowdHeads = new Int32Array(gc * gr);
      crowdHeads.fill(-1, 0, gc * gr);
      crowdRows = gr;
      for (let i = 0; i < n; i++) {
        const cx = clamp(Math.floor(px[i] / h) + 1, 0, gc - 1);
        const cy = clamp(Math.floor(py[i] / h) + 1, 0, gr - 1);
        const key = cy * gc + cx;
        crowd[i] = crowdHeads[key];
        crowdHeads[key] = i;
      }
      return gc;
    };

    const move = (s: Settings, dt: number, ease: number) => {
      const n = s.count;
      const radius = s.spread;
      const loose = 1 - 0.6 * s.tail;
      const gather = 12 * loose * (0.2 + 0.8 * ease);
      const pull = 30 * loose * (0.2 + 0.8 * ease);
      const band = Math.max(4, radius * 0.16);
      const w = view.width;
      const h = view.height;
      const gap = radius * Math.sqrt(Math.PI / Math.max(n, 1)) * 1.6;
      const repel = 4000;
      const gc = push(n, gap);
      for (let i = 0; i < n; i++) {
        const x = px[i];
        const y = py[i];
        const k = 10 * (1 - 0.6 * s.tail * heft[i]);
        let ax = (sample(flowX, x, y) - vx[i]) * k;
        let ay = (sample(flowY, x, y) - vy[i]) * k;
        const cx = clamp(Math.floor(x / gap) + 1, 0, gc - 1);
        const cy = clamp(Math.floor(y / gap) + 1, 0, crowdRows - 1);
        for (let oy = -1; oy <= 1; oy++) {
          const row = cy + oy;
          if (row < 0 || row >= crowdRows) continue;
          for (let ox = -1; ox <= 1; ox++) {
            const col = cx + ox;
            if (col < 0 || col >= gc) continue;
            for (let j = crowdHeads[row * gc + col]; j !== -1; j = crowd[j]) {
              if (j === i) continue;
              const dx = x - px[j];
              const dy = y - py[j];
              const d2 = dx * dx + dy * dy;
              if (d2 >= gap * gap || d2 < 1e-6) continue;
              const d = Math.sqrt(d2);
              const q = 1 - d / gap;
              ax += (dx / d) * q * q * repel;
              ay += (dy / d) * q * q * repel;
            }
          }
        }
        if (ring.active) {
          rectField(x - ring.x, y - ring.y, ring.hx, ring.hy, ring.corner, field);
          const e = field[0] - (5 + band * home[i] * home[i]);
          const hold = e > 0 ? 70 : 140;
          ax -= field[1] * e * hold;
          ay -= field[2] * e * hold;
        } else {
          const dx = anchor.x - x;
          const dy = anchor.y - y;
          const d = Math.hypot(dx, dy) + 0.001;
          const over = Math.max(0, d - radius);
          ax += (dx / d) * (d * gather + over * pull);
          ay += (dy / d) * (d * gather + over * pull);
        }
        if (introClock >= 1) {
          if (x < 8) ax += (8 - x) * 30;
          else if (x > w - 8) ax -= (x - w + 8) * 30;
          if (y < 8) ay += (8 - y) * 30;
          else if (y > h - 8) ay -= (y - h + 8) * 30;
        }
        const lift = Math.sin(time * bobRate[i] + bob[i]) * radius * (ring.active ? 0.15 : 0.55);
        const az = (lift - pz[i]) * 36 - vz[i] * 9;
        vx[i] += ax * dt;
        vy[i] += ay * dt;
        vz[i] += az * dt;
        px[i] += vx[i] * dt;
        py[i] += vy[i] * dt;
        pz[i] += vz[i] * dt;
      }
    };

    const seed = () => {
      const rand = random(7);
      for (let i = 0; i < MAX_PARTICLES; i++) {
        home[i] = 0.08 + 0.92 * Math.sqrt(rand());
        heft[i] = rand() * rand();
        bob[i] = rand() * Math.PI * 2;
        bobRate[i] = 0.5 + rand() * 1.1;
        grain[i] = 0.55 + rand() * 0.9;
        glint[i] = rand() * 100;
      }
      seeded = true;
    };

    const place = (gathered: boolean) => {
      const s = settingsRef.current;
      const rand = random(11);
      const reachOut = Math.hypot(view.width, view.height) * 0.5;
      for (let i = 0; i < MAX_PARTICLES; i++) {
        const a = rand() * Math.PI * 2;
        const r = gathered ? home[i] * s.spread : (0.35 + 0.65 * Math.sqrt(rand())) * reachOut;
        px[i] = anchor.x + Math.cos(a) * r;
        py[i] = anchor.y + Math.sin(a) * r;
        pz[i] = Math.sin(bob[i]) * s.spread * 0.55;
        vx[i] = 0;
        vy[i] = 0;
        vz[i] = 0;
      }
    };

    const findTarget = () => {
      const s = settingsRef.current;
      if (!s.targets || !pointer.inside) return null;
      const rect = container.getBoundingClientRect();
      const element = document.elementFromPoint(rect.left + pointer.x, rect.top + pointer.y);
      if (!element || !container.contains(element)) return null;
      let match: Element | null = null;
      try {
        match = element.closest(s.targets);
      } catch {
        match = null;
      }
      return match && container.contains(match) ? match : null;
    };

    const updateAnchor = (s: Settings, dt: number) => {
      const w = view.width;
      const h = view.height;
      if (hovered && hovered.isConnected) {
        const box = hovered.getBoundingClientRect();
        const frame = container.getBoundingClientRect();
        const radius = parseFloat(getComputedStyle(hovered).borderTopLeftRadius) || 0;
        ring.x = box.left - frame.left + box.width / 2;
        ring.y = box.top - frame.top + box.height / 2;
        ring.hx = box.width / 2;
        ring.hy = box.height / 2;
        ring.corner = Math.min(radius, ring.hx, ring.hy);
        if (!ring.active) {
          let turning = 0;
          for (let i = 0; i < s.count; i++) turning += (px[i] - ring.x) * vy[i] - (py[i] - ring.y) * vx[i];
          ring.spin = turning < 0 ? -1 : 1;
        }
        ring.active = true;
      } else {
        ring.active = false;
      }
      let goal = 1;
      if (pointer.inside) {
        anchor.x = pointer.x;
        anchor.y = pointer.y;
      } else if (s.idle === 'gather') {
        anchor.x = w * 0.5;
        anchor.y = h * 0.5;
      } else if (s.idle === 'hide') {
        goal = 0;
      } else {
        anchor.x = w * (0.5 + 0.3 * Math.sin(time * 0.21) + 0.06 * Math.sin(time * 0.53 + 1.7));
        anchor.y = h * (0.5 + 0.24 * Math.sin(time * 0.29 + 0.8) + 0.05 * Math.sin(time * 0.71));
      }
      if (dt > 0) {
        const moveX = clamp((anchor.x - anchor.lastX) / dt, -4000, 4000);
        const moveY = clamp((anchor.y - anchor.lastY) / dt, -4000, 4000);
        const blend = 1 - Math.exp(-dt * 30);
        anchor.moveX += (moveX - anchor.moveX) * blend;
        anchor.moveY += (moveY - anchor.moveY) * blend;
      }
      anchor.lastX = anchor.x;
      anchor.lastY = anchor.y;
      presence += (goal - presence) * (1 - Math.exp(-dt / 0.25));
    };

    const draw = () => {
      const s = settingsRef.current;
      const n = s.count;
      const fade = introClock * introClock * (3 - 2 * introClock) * presence;
      const zr = Math.max(s.spread * 0.55, 10);
      if (sorted !== n) {
        for (let a = 0; a < n; a++) order[a] = a;
        sorted = n;
      }
      for (let a = 1; a < n; a++) {
        const value = order[a];
        const key = pz[value];
        let b = a - 1;
        while (b >= 0 && pz[order[b]] > key) {
          order[b + 1] = order[b];
          b--;
        }
        order[b + 1] = value;
      }
      const flash = burst.age < 1.2 ? Math.exp(-burst.age / 0.3) : 0;
      const front = ping.age * 520;
      let written = 0;
      for (let a = 0; a < n; a++) {
        const i = order[a];
        const near = clamp(pz[i] / zr, -1, 1);
        const scale = 1 + s.depth * 0.6 * near;
        const body = s.size * grain[i] * scale;
        const soft = s.depth * s.size * (s.lightMode ? 0.35 : 1.4) * Math.pow(Math.abs(near), 1.6);
        const flat = Math.hypot(vx[i], vy[i]);
        const dx = flat > 0.001 ? vx[i] / flat : 1;
        const dy = flat > 0.001 ? vy[i] / flat : 0;
        let wave = 0;
        if (ping.age < 1.6) {
          const offset = (Math.hypot(px[i] - ping.x, py[i] - ping.y) - front) / 40;
          wave = Math.exp(-offset * offset) * (1 - ping.age / 1.6);
        }
        const tint = Math.max(clamp((flat - 380) / 900, 0, 1), flash, wave);
        const width = body * (1 + wave * 0.8);
        let length = width + Math.min(flat * s.trail * 0.02, body * 14);
        if (s.shape === 2) length = width * 2.6 + Math.min(flat * s.trail * 0.03, body * 18);
        const twinkle = 0.86 + 0.14 * Math.sin(time * 3.1 + glint[i]);
        const dim = 1 - s.depth * 0.45 * Math.max(0, -near);
        const o = written * 4;
        agentData[o] = px[i];
        agentData[o + 1] = py[i];
        agentData[o + 2] = dx;
        agentData[o + 3] = dy;
        lookData[o] = length;
        lookData[o + 1] = width;
        lookData[o + 2] = clamp(0.95 * dim * (body / (body + soft)) * twinkle * (1 + wave * 0.4), 0, 1) * fade;
        lookData[o + 3] = tint;
        extraData[written * 2] = soft;
        extraData[written * 2 + 1] = s.shape;
        written++;
      }
      if (s.hideCursor && pointer.inside) {
        const o = written * 4;
        agentData[o] = pointer.x;
        agentData[o + 1] = pointer.y;
        agentData[o + 2] = 1;
        agentData[o + 3] = 0;
        lookData[o] = 6;
        lookData[o + 1] = 6;
        lookData[o + 2] = 1;
        lookData[o + 3] = 0;
        extraData[written * 2] = 0;
        extraData[written * 2 + 1] = 0;
        written++;
      }
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      if (!s.enabled || !written) return;
      gl.useProgram(shader.program);
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      gl.bindVertexArray(vao);
      gl.bindBuffer(gl.ARRAY_BUFFER, agentBuffer);
      gl.bufferSubData(gl.ARRAY_BUFFER, 0, agentData, 0, written * 4);
      gl.bindBuffer(gl.ARRAY_BUFFER, lookBuffer);
      gl.bufferSubData(gl.ARRAY_BUFFER, 0, lookData, 0, written * 4);
      gl.bindBuffer(gl.ARRAY_BUFFER, extraBuffer);
      gl.bufferSubData(gl.ARRAY_BUFFER, 0, extraData, 0, written * 2);
      gl.uniform2f(u.uView, view.width, view.height);
      gl.uniform3fv(u.uColor, parse(s.color));
      gl.uniform3fv(u.uAccent, parse(s.accentColor));
      gl.uniform1f(u.uRatio, view.ratio);
      gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, written);
      gl.bindVertexArray(null);
    };

    const resize = () => {
      const s = settingsRef.current;
      view.width = Math.max(1, container.clientWidth);
      view.height = Math.max(1, container.clientHeight);
      view.ratio = Math.min(s.dpr || window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(view.width * view.ratio));
      canvas.height = Math.max(1, Math.round(view.height * view.ratio));
      allocate();
      if (!seeded) {
        seed();
        updateAnchor(s, 0);
        if (reduce) {
          anchor.x = view.width / 2;
          anchor.y = view.height / 2;
        }
        anchor.lastX = anchor.x;
        anchor.lastY = anchor.y;
        place(introClock >= 1);
      }
      draw();
      wake();
    };

    const frame = (now: number) => {
      raf = 0;
      if (!visible || document.hidden) return;
      const s = settingsRef.current;
      const dt = last ? clamp((now - last) / 1000, 0.001, 1 / 30) : 1 / 60;
      last = now;
      if (!s.enabled || reduce) {
        setHidden(false);
        draw();
        return;
      }
      time += dt;
      burst.age += dt;
      ping.age += dt;
      if (introClock < 1) introClock = Math.min(1, introClock + dt / INTRO_SECONDS);
      const ease = introClock * introClock * (3 - 2 * introClock);
      hovered = findTarget();
      updateAnchor(s, dt);
      setHidden(s.hideCursor && pointer.inside);
      stir(s, dt, ease);
      flow(s, dt);
      move(s, dt / 2, ease);
      move(s, dt / 2, ease);
      draw();
      raf = requestAnimationFrame(frame);
    };

    function wake() {
      if (!raf && visible && !document.hidden) raf = requestAnimationFrame(frame);
    }

    const locate = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;
      return { x, y, inside: x >= 0 && y >= 0 && x <= rect.width && y <= rect.height };
    };

    const onPointerMove = (event: PointerEvent) => {
      const { x, y, inside } = locate(event);
      pointer.x = x;
      pointer.y = y;
      pointer.inside = inside;
    };

    const onPointerDown = (event: PointerEvent) => {
      const s = settingsRef.current;
      const { x, y, inside } = locate(event);
      if (!inside || !s.enabled || reduce || s.clickEffect === 'none') return;
      const reachOut = s.spread * 2.2;
      if (s.clickEffect === 'pulse') {
        ping.x = x;
        ping.y = y;
        ping.age = 0;
      } else {
        burst.age = 0;
      }
      const kick = s.clickEffect === 'pulse' ? 160 : 780;
      for (let i = 0; i < s.count; i++) {
        const dx = px[i] - x;
        const dy = py[i] - y;
        const d = Math.hypot(dx, dy) || 1;
        if (d > reachOut) continue;
        const k = (1 - d / reachOut) * kick * (0.6 + 0.4 * grain[i]);
        vx[i] += (dx / d) * k;
        vy[i] += (dy / d) * k;
      }
      if (s.clickEffect === 'pulse') return;
      const twist = 520 * (time % 2 < 1 ? 1 : -1);
      const inv = 1 / (s.spread * s.spread);
      for (let j = 1; j < rows - 1; j++) {
        for (let i = 1; i < cols - 1; i++) {
          const k = i + j * cols;
          const rx = (i + 0.5) * cell - x;
          const ry = (j + 0.5) * cell - y;
          const d2 = rx * rx + ry * ry;
          const w = (Math.sqrt(d2) / s.spread) * Math.exp(-d2 * inv);
          if (w < 0.003) continue;
          const d = Math.sqrt(d2) + 0.001;
          flowX[k] += (-ry / d) * twist * w;
          flowY[k] += (rx / d) * twist * w;
        }
      }
    };

    const onPointerUp = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse') pointer.inside = false;
    };

    const onPointerLeave = () => {
      pointer.inside = false;
    };

    const onVisibility = () => {
      last = 0;
      wake();
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(container);
    const intersection = new IntersectionObserver(entries => {
      visible = entries.some(entry => entry.isIntersecting);
      if (visible) {
        last = 0;
        wake();
      }
    });
    intersection.observe(container);
    window.addEventListener('pointermove', onPointerMove, { passive: true });
    window.addEventListener('pointerdown', onPointerDown, { passive: true });
    window.addEventListener('pointerup', onPointerUp, { passive: true });
    window.addEventListener('pointercancel', onPointerUp, { passive: true });
    document.documentElement.addEventListener('pointerleave', onPointerLeave);
    document.addEventListener('visibilitychange', onVisibility);
    resize();
    wakeRef.current = wake;

    return () => {
      cancelAnimationFrame(raf);
      wakeRef.current = null;
      setHidden(false);
      resizeObserver.disconnect();
      intersection.disconnect();
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerdown', onPointerDown);
      window.removeEventListener('pointerup', onPointerUp);
      window.removeEventListener('pointercancel', onPointerUp);
      document.documentElement.removeEventListener('pointerleave', onPointerLeave);
      document.removeEventListener('visibilitychange', onVisibility);
      gl.deleteBuffer(cornerBuffer);
      gl.deleteBuffer(agentBuffer);
      gl.deleteBuffer(lookBuffer);
      gl.deleteBuffer(extraBuffer);
      gl.deleteVertexArray(vao);
      gl.deleteProgram(shader.program);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    };
  }, []);

  useEffect(() => {
    wakeRef.current?.();
  });

  return (
    <div
      ref={containerRef}
      className={['relative h-full w-full overflow-hidden', className].filter(Boolean).join(' ')}
      style={style}
      {...rest}
    >
      <style>{`.${HIDDEN}, .${HIDDEN} * { cursor: none !important; }`}</style>
      <canvas ref={canvasRef} className="pointer-events-none absolute inset-0 block h-full w-full" aria-hidden="true" />
      {children ? <div className="relative h-full w-full">{children}</div> : null}
    </div>
  );
};

export default SwarmCursor;

'use client';

import { useEffect, useRef, useState, type CSSProperties, type RefObject } from 'react';
import { createPortal } from 'react-dom';

export interface TargetCursorProps {
  targetSelector?: string;
  cursorColor?: string;
  cursorColorOnTarget?: string;
  spinDuration?: number;
  hoverDuration?: number;
  parallaxOn?: boolean;
  hideDefaultCursor?: boolean;
  size?: number;
  cornerSize?: number;
  thickness?: number;
  padding?: number;
  matchRadius?: boolean;
  dotSize?: number;
  blendMode?: CSSProperties['mixBlendMode'];
  showLabel?: boolean;
  clickEffect?: boolean;
  container?: RefObject<HTMLElement | null> | HTMLElement | null;
}

type Spring = { x: number; v: number };

const CORNER_ANGLES = [0, 90, 180, 270];
const QUARTER = Math.PI / 2;

const spring = (state: Spring, goal: number, stiffness: number, damping: number, dt: number) => {
  const steps = 2;
  const h = dt / steps;
  for (let i = 0; i < steps; i++) {
    state.v += (stiffness * (goal - state.x) - damping * state.v) * h;
    state.x += state.v * h;
  }
};

const resolveElement = (value: TargetCursorProps['container']): HTMLElement | null =>
  (value && 'current' in value ? value.current : value) || null;

const TargetCursor = ({
  targetSelector = '.cursor-target',
  cursorColor = '#ffffff',
  cursorColorOnTarget,
  spinDuration = 2,
  hoverDuration = 0.2,
  parallaxOn = true,
  hideDefaultCursor = true,
  size = 36,
  cornerSize = 12,
  thickness = 3,
  padding = 6,
  matchRadius = true,
  dotSize = 4,
  blendMode = 'difference',
  showLabel = true,
  clickEffect = true,
  container
}: TargetCursorProps) => {
  const [host, setHost] = useState<HTMLElement | null>(null);
  const rootRef = useRef<HTMLDivElement>(null);
  const cornerRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const dotRef = useRef<HTMLSpanElement>(null);
  const labelRef = useRef<HTMLSpanElement>(null);
  const wakeRef = useRef<(() => void) | null>(null);
  const settings = {
    targetSelector,
    cursorColor,
    cursorColorOnTarget,
    spinDuration,
    hoverDuration: Math.max(0.05, hoverDuration),
    parallaxOn,
    hideDefaultCursor,
    size: Math.max(4, size),
    cornerSize: Math.max(2, cornerSize),
    thickness: Math.max(0.5, thickness),
    padding,
    matchRadius,
    dotSize: Math.max(0, dotSize),
    showLabel,
    clickEffect,
    container
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    const finePointer = window.matchMedia('(hover: hover) and (pointer: fine)');
    const update = () => setHost(finePointer.matches ? document.body : null);
    update();
    finePointer.addEventListener('change', update);
    return () => finePointer.removeEventListener('change', update);
  }, []);

  useEffect(() => {
    const root = rootRef.current;
    if (!host || !root) return undefined;

    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const style = document.createElement('style');
    document.head.appendChild(style);

    const pointer = { x: 0, y: 0, inside: false, seen: false, pressed: false };
    const centerX = { x: 0, v: 0 };
    const centerY = { x: 0, v: 0 };
    const halfW = { x: 0, v: 0 };
    const halfH = { x: 0, v: 0 };
    const radius = { x: 0, v: 0 };
    const turn = { x: 0, v: 0 };
    const lock = { x: 0, v: 0 };
    const press = { x: 0, v: 0 };
    const presence = { x: 0, v: 0 };
    let target: Element | null = null;
    let targetRadius = 0;
    let quarter = 0;
    let spinSpeed = 0;
    let raf = 0;
    let last = 0;
    let lastLabel = '';
    let lastColor = '';
    let lastScope: HTMLElement | null = null;

    const scopeOf = () => resolveElement(settingsRef.current.container);

    const hideCursor = () => {
      const s = settingsRef.current;
      const scope = scopeOf();
      if (scope !== lastScope) {
        lastScope?.removeAttribute('data-target-cursor-scope');
        scope?.setAttribute('data-target-cursor-scope', '');
        lastScope = scope;
      }
      const selector = scope ? '[data-target-cursor-scope]' : 'html';
      const rule =
        s.hideDefaultCursor && pointer.inside ? `${selector}, ${selector} * { cursor: none !important; }` : '';
      if (style.textContent !== rule) style.textContent = rule;
    };

    const findTarget = (x: number, y: number, element?: Element | null): Element | null => {
      const s = settingsRef.current;
      const node = element || document.elementFromPoint(x, y);
      const found = node?.closest(s.targetSelector) || null;
      const scope = scopeOf();
      if (found && scope && !scope.contains(found)) return null;
      return found;
    };

    const lockOn = (next: Element | null) => {
      if (next === target) return;
      target = next;
      if (target) {
        const angle = turn.x;
        quarter = Math.round(angle / QUARTER);
        const corner = parseFloat(getComputedStyle(target).borderTopLeftRadius) || 0;
        targetRadius = corner;
        spinSpeed = 0;
      }
    };

    const frame = (now: number) => {
      raf = 0;
      const s = settingsRef.current;
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;

      if (target && !target.isConnected) lockOn(null);
      const rect = target ? target.getBoundingClientRect() : null;
      const locked = !!rect && pointer.inside;
      const snapW = 4.6 / s.hoverDuration;
      const snapK = snapW * snapW;
      const snapC = 2 * 0.62 * snapW;

      spring(presence, pointer.inside ? 1 : 0, 260, 32, dt);
      spring(lock, locked ? 1 : 0, snapK, 2 * snapW, dt);
      spring(press, pointer.pressed && s.clickEffect ? 1 : 0, 900, 40, dt);

      let goalX = pointer.x;
      let goalY = pointer.y;
      let goalW = s.size / 2;
      let goalH = s.size / 2;
      let goalR = Math.min(2, s.cornerSize / 4);
      if (locked) {
        const cx = rect.left + rect.width / 2;
        const cy = rect.top + rect.height / 2;
        const lean = s.parallaxOn ? 0.08 : 0;
        goalX = cx + (pointer.x - cx) * lean;
        goalY = cy + (pointer.y - cy) * lean;
        const odd = Math.abs(quarter) % 2 === 1;
        const w = rect.width / 2 + s.padding;
        const h = rect.height / 2 + s.padding;
        goalW = odd ? h : w;
        goalH = odd ? w : h;
        goalR = s.matchRadius ? Math.min(targetRadius + Math.max(0, s.padding), s.cornerSize) : 0;
      }

      if (!pointer.inside && presence.x < 0.01) pointer.seen = false;
      if (!pointer.seen) {
        centerX.x = goalX;
        centerY.x = goalY;
        halfW.x = goalW;
        halfH.x = goalH;
        pointer.seen = pointer.inside;
      }

      const follow = locked ? snapK : 2200;
      const followC = locked ? snapC : 2 * Math.sqrt(2200);
      spring(centerX, goalX, follow, followC, dt);
      spring(centerY, goalY, follow, followC, dt);
      spring(halfW, goalW, snapK, snapC, dt);
      spring(halfH, goalH, snapK, snapC, dt);
      spring(radius, goalR, snapK, 2 * snapW, dt);

      if (locked) {
        spring(turn, quarter * QUARTER, snapK, snapC, dt);
      } else {
        const speed = s.spinDuration > 0 && !reduce ? (Math.PI * 2) / s.spinDuration : 0;
        spinSpeed += (speed - spinSpeed) * (1 - Math.exp(-dt * 3));
        turn.v = spinSpeed;
        turn.x += spinSpeed * dt;
      }

      const squeeze = 1 - press.x * 0.14;
      const cos = Math.cos(turn.x);
      const sin = Math.sin(turn.x);
      const w = Math.max(0, halfW.x) * squeeze;
      const h = Math.max(0, halfH.x) * squeeze;
      const local = [
        [-w, -h],
        [w, -h],
        [w, h],
        [-w, h]
      ];
      const r = Math.max(0, Math.min(radius.x, s.cornerSize));
      const degrees = (turn.x * 180) / Math.PI;
      let left = Infinity;
      let top = Infinity;
      cornerRefs.current.forEach((corner, i) => {
        if (!corner) return;
        const [lx, ly] = local[i];
        const x = centerX.x + lx * cos - ly * sin;
        const y = centerY.x + lx * sin + ly * cos;
        left = Math.min(left, x);
        top = Math.min(top, y);
        corner.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0) rotate(${(CORNER_ANGLES[i] + degrees).toFixed(2)}deg)`;
        corner.style.width = `${s.cornerSize}px`;
        corner.style.height = `${s.cornerSize}px`;
        corner.style.borderWidth = `${s.thickness}px 0 0 ${s.thickness}px`;
        corner.style.borderTopLeftRadius = `${r.toFixed(2)}px`;
      });

      const dot = dotRef.current;
      if (dot) {
        const dotScale = 1 - press.x * 0.35;
        dot.style.transform = `translate3d(${pointer.x}px, ${pointer.y}px, 0) translate(-50%, -50%) scale(${dotScale.toFixed(3)})`;
        dot.style.width = `${s.dotSize}px`;
        dot.style.height = `${s.dotSize}px`;
      }

      const label = labelRef.current;
      if (label) {
        const text = s.showLabel && target ? target.getAttribute('data-cursor-label') || '' : '';
        if (text && text !== lastLabel) label.textContent = text;
        if (text) lastLabel = text;
        const shown = text ? Math.max(0, Math.min(1, lock.x)) : 0;
        label.style.transform = `translate3d(${left.toFixed(2)}px, ${(top - 8).toFixed(2)}px, 0) translateY(-100%) translateY(${((1 - shown) * 4).toFixed(2)}px)`;
        label.style.opacity = shown.toFixed(3);
      }

      const mix = s.cursorColorOnTarget ? Math.round(Math.max(0, Math.min(1, lock.x)) * 100) : 0;
      const color = mix ? `color-mix(in oklab, ${s.cursorColorOnTarget} ${mix}%, ${s.cursorColor})` : s.cursorColor;
      if (color !== lastColor) {
        root.style.setProperty('--target-cursor-color', color);
        lastColor = color;
      }
      root.style.opacity = Math.max(0, Math.min(1, presence.x)).toFixed(3);

      const resting =
        !pointer.inside &&
        presence.x < 0.002 &&
        Math.abs(presence.v) < 0.002 &&
        Math.abs(lock.x) < 0.002 &&
        Math.abs(press.x) < 0.002;
      const spinning = pointer.inside && !locked && spinSpeed > 0.0001;
      const moving =
        Math.abs(centerX.v) + Math.abs(centerY.v) + Math.abs(halfW.v) + Math.abs(halfH.v) + Math.abs(turn.v) > 0.01 ||
        Math.abs(goalX - centerX.x) + Math.abs(goalY - centerY.x) > 0.05 ||
        Math.abs(lock.v) + Math.abs(press.v) + Math.abs(presence.v) > 0.001;
      if (!resting && (spinning || moving || locked)) raf = requestAnimationFrame(frame);
      else last = 0;
    };

    const wake = () => {
      if (!raf) raf = requestAnimationFrame(frame);
    };
    wakeRef.current = () => {
      hideCursor();
      wake();
    };

    const insideScope = (x: number, y: number, element?: Element | null) => {
      const scope = scopeOf();
      if (!scope) return true;
      if (element && scope.contains(element)) return true;
      const box = scope.getBoundingClientRect();
      return x >= box.left && x <= box.right && y >= box.top && y <= box.bottom;
    };

    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerType && event.pointerType !== 'mouse') return;
      pointer.x = event.clientX;
      pointer.y = event.clientY;
      const inside = insideScope(pointer.x, pointer.y, event.target as Element | null);
      if (inside !== pointer.inside) {
        pointer.inside = inside;
        hideCursor();
      }
      lockOn(inside ? findTarget(pointer.x, pointer.y, event.target as Element | null) : null);
      wake();
    };

    const onPointerDown = (event: PointerEvent) => {
      if (event.pointerType && event.pointerType !== 'mouse') return;
      pointer.pressed = true;
      wake();
    };

    const onPointerUp = () => {
      pointer.pressed = false;
      wake();
    };

    const onLeave = () => {
      pointer.inside = false;
      pointer.pressed = false;
      lockOn(null);
      hideCursor();
      wake();
    };

    const onScroll = () => {
      if (!pointer.inside) return;
      lockOn(findTarget(pointer.x, pointer.y));
      wake();
    };

    window.addEventListener('pointermove', onPointerMove, { passive: true });
    window.addEventListener('pointerdown', onPointerDown, { passive: true });
    window.addEventListener('pointerup', onPointerUp, { passive: true });
    window.addEventListener('scroll', onScroll, { passive: true, capture: true });
    document.documentElement.addEventListener('pointerleave', onLeave);
    window.addEventListener('blur', onLeave);

    return () => {
      cancelAnimationFrame(raf);
      wakeRef.current = null;
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerdown', onPointerDown);
      window.removeEventListener('pointerup', onPointerUp);
      window.removeEventListener('scroll', onScroll, { capture: true });
      document.documentElement.removeEventListener('pointerleave', onLeave);
      window.removeEventListener('blur', onLeave);
      lastScope?.removeAttribute('data-target-cursor-scope');
      style.remove();
    };
  }, [host]);

  useEffect(() => {
    wakeRef.current?.();
  });

  if (!host) return null;

  return createPortal(
    <div
      ref={rootRef}
      className="pointer-events-none fixed inset-0 z-[2147483647]"
      style={{ mixBlendMode: blendMode, opacity: 0 }}
      aria-hidden="true"
    >
      {CORNER_ANGLES.map((angle, i) => (
        <span
          key={angle}
          ref={element => {
            cornerRefs.current[i] = element;
          }}
          className="absolute top-0 left-0 box-border origin-top-left border-solid [border-color:var(--target-cursor-color,#ffffff)] will-change-transform"
        />
      ))}
      <span
        ref={dotRef}
        className="absolute top-0 left-0 rounded-full [background:var(--target-cursor-color,#ffffff)] will-change-transform"
      />
      <span
        ref={labelRef}
        className="absolute top-0 left-0 text-[12px] leading-none font-medium whitespace-nowrap opacity-0 [color:var(--target-cursor-color,#ffffff)] will-change-[transform,opacity]"
      />
    </div>,
    host
  );
};

