  detail = 5,
  offset = [0, 0],
  pixelSize = 1.5,
  crt = 0,
  mouseInteraction = true,
  mouseStrength = 1,
  clickSwirl = true,
  intro = true,
  lightMode = false,
  opacity = 1,
  maxDevicePixelRatio = 2,
  className = '',
  style
}: BalatroProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wakeRef = useRef<(() => void) | null>(null);
  const [generation, setGeneration] = useState(0);

  const settings: Settings = {
    color1: parseColor(color1) || [0.871, 0.267, 0.231],
    color2: parseColor(color2) || [0, 0.42, 0.706],
    color3: parseColor(color3) || [0.086, 0.137, 0.145],
    contrast: clamp(contrast, 0.5, 10),
    lighting: clamp(lighting, 0, 1.5),
    swirl: clamp(swirl, 0, 1),
    speed: Math.max(0, speed),
    rotation: clamp(rotationSpeed, -10, 10),
    scale: clamp(scale, 0.2, 5),
    detail: clamp(Math.round(detail), 1, 8),
    offset: Array.isArray(offset) ? [Number(offset[0]) || 0, Number(offset[1]) || 0] : [0, 0],
    pixelSize: clamp(pixelSize, 0, 24),
    crt: clamp(crt, 0, 1),
    mouse: mouseInteraction,
    strength: clamp(mouseStrength, 0, 3),
    clickSwirl,
    intro,
    light: lightMode,
    opacity: clamp(opacity, 0, 1),
    maxRatio: clamp(maxDevicePixelRatio, 0.5, 3)
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    wakeRef.current?.();
  });

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;

    const gl = canvas.getContext('webgl2', {
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      powerPreference: 'high-performance'
    });
    const paintProgram = gl ? link(gl, PAINT) : null;
    const screenProgram = gl ? link(gl, SCREEN) : null;
    if (!gl || !paintProgram || !screenProgram) return;
    const floatTargets = !!(
      gl.getExtension('EXT_color_buffer_float') || gl.getExtension('EXT_color_buffer_half_float')
    );
    const fieldProgram = floatTargets ? link(gl, FIELD) : null;

    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const vao = gl.createVertexArray();
    const view = { cssWidth: 1, cssHeight: 1, block: 1, device: 1, width: 1, height: 1, crt: false };
    const paintTarget = {
      texture: gl.createTexture() as WebGLTexture,
      framebuffer: gl.createFramebuffer() as WebGLFramebuffer,
      width: 0,
      height: 0
    };
    const field: { width: number; height: number; targets: Target[]; energy: number } = {
      width: 0,
      height: 0,
      targets: [],
      energy: 0
    };
    const pointer = { x: 0, y: 0, lastX: 0, lastY: 0, vx: 0, inside: false, ready: false };
    const steer = { value: 0 };
    const twirls: Twirl[] = [];
    const twirlData = new Float32Array(MAX_TWIRLS * 4);
    let flow = 14;
    let spin = 0;
    let opening = settingsRef.current.intro && !reduced && generation === 0 ? 0 : 1;
    let raf = 0;
    let last = 0;
    let visible = true;
    let pageVisible = document.visibilityState !== 'hidden';
    let lost = false;

    const makeTarget = (width: number, height: number): Target => {
      const texture = gl.createTexture() as WebGLTexture;
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RG16F, width, height, 0, gl.RG, gl.HALF_FLOAT, null);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      const framebuffer = gl.createFramebuffer() as WebGLFramebuffer;
      gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      return { texture, framebuffer };
    };

    const dropField = () => {
      field.targets.forEach(target => {
        gl.deleteTexture(target.texture);
        gl.deleteFramebuffer(target.framebuffer);
      });
      field.targets = [];
      field.width = 0;
      field.height = 0;
      field.energy = 0;
    };

    const resize = () => {
      const s = settingsRef.current;
      const rect = container.getBoundingClientRect();
      const cssWidth = Math.max(1, rect.width);
      const cssHeight = Math.max(1, rect.height);
      const dpr = Math.min(window.devicePixelRatio || 1, s.maxRatio);
      const budget = Math.ceil(Math.sqrt((cssWidth * cssHeight * dpr * dpr) / PIXEL_BUDGET) - 0.05);
      const device = Math.max(s.pixelSize > 0 ? Math.round(s.pixelSize * dpr) : 1, budget, 1);
      const width = Math.max(1, Math.ceil((cssWidth * dpr) / device));
      const height = Math.max(1, Math.ceil((cssHeight * dpr) / device));
      const crt = s.crt > 0;
      const canvasWidth = crt ? width * device : width;
      const canvasHeight = crt ? height * device : height;
      if (canvas.width !== canvasWidth || canvas.height !== canvasHeight) {
        canvas.width = canvasWidth;
        canvas.height = canvasHeight;
      }
      canvas.style.width = `${(width * device) / dpr}px`;
      canvas.style.height = `${(height * device) / dpr}px`;
      canvas.style.imageRendering = !crt && s.pixelSize > 0 && device >= 2 ? 'pixelated' : 'auto';
      if (crt && (paintTarget.width !== width || paintTarget.height !== height)) {
        gl.bindTexture(gl.TEXTURE_2D, paintTarget.texture);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, width, height, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        gl.bindFramebuffer(gl.FRAMEBUFFER, paintTarget.framebuffer);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, paintTarget.texture, 0);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        paintTarget.width = width;
        paintTarget.height = height;
      }
      view.cssWidth = cssWidth;
      view.cssHeight = cssHeight;
      view.block = device / dpr;
      view.device = device;
      view.width = width;
      view.height = height;
      view.crt = crt;
      if (!fieldProgram) return;
      const fieldWidth = clamp(Math.ceil(cssWidth / FIELD_SCALE), 8, 320);
      const fieldHeight = clamp(Math.ceil(cssHeight / FIELD_SCALE), 8, 320);
      if (fieldWidth === field.width && fieldHeight === field.height) return;
      dropField();
      field.width = fieldWidth;
      field.height = fieldHeight;
      field.targets = [makeTarget(fieldWidth, fieldHeight), makeTarget(fieldWidth, fieldHeight)];
    };

    const stir = (
      fromX: number,
      fromY: number,
      toX: number,
      toY: number,
      pushX: number,
      pushY: number,
      decay: number
    ) => {
      if (!fieldProgram) return;
      const [read, write] = field.targets;
      gl.bindFramebuffer(gl.FRAMEBUFFER, write.framebuffer);
      gl.viewport(0, 0, field.width, field.height);
      gl.useProgram(fieldProgram.program);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, read.texture);
      const u = fieldProgram.uniforms;
      gl.uniform1i(u.uPrev, 0);
      gl.uniform2f(u.uSize, field.width, field.height);
      gl.uniform2f(u.uCss, view.cssWidth, view.cssHeight);
      gl.uniform2f(u.uFrom, fromX, fromY);
      gl.uniform2f(u.uTo, toX, toY);
      gl.uniform2f(u.uPush, pushX, pushY);
      gl.uniform1f(u.uRadius, STIR_RADIUS);
      gl.uniform1f(u.uDecay, decay);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      field.targets = [write, read];
    };

    const frame = (now: number) => {
      raf = 0;
      if (lost) return;
      const s = settingsRef.current;
      const dt = clamp((now - last) / 1000 || 0, 0, 0.05);
      last = Math.max(last, now);
      const pace = reduced ? 0.2 : 1;
      flow += dt * s.speed * 7 * pace;
      spin += dt * s.rotation * 0.2 * pace;
      if (opening < 1) opening = Math.min(1, opening + dt / 2.2);

      const tracking = s.mouse && pointer.inside;
      const steerTarget = tracking ? (pointer.x / view.cssWidth - 0.5) * 0.35 * s.strength : 0;
      steer.value += (steerTarget - steer.value) * (1 - Math.exp(-dt / 0.8));

      gl.bindVertexArray(vao);
      if (fieldProgram && field.targets.length) {
        const dx = pointer.x - pointer.lastX;
        const dy = pointer.y - pointer.lastY;
        const moved = tracking && pointer.ready && (dx !== 0 || dy !== 0);
        const decay = Math.exp(-dt / 1.6);
        if (moved || field.energy > 0.05) {
          const amount = 0.85 * s.strength * (reduced ? 0.4 : 1);
          const travel = moved ? Math.hypot(dx, dy) * amount : 0;
          const steps = Math.max(1, Math.ceil(travel / (STIR_RADIUS * 0.3)));
          for (let step = 0; step < steps; step++) {
            const a = step / steps;
            const b = (step + 1) / steps;
            stir(
              pointer.lastX + dx * a,
              pointer.lastY + dy * a,
              pointer.lastX + dx * b,
              pointer.lastY + dy * b,
              moved ? dx * (b - a) * amount : 0,
              moved ? dy * (b - a) * amount : 0,
              step === steps - 1 ? decay : 1
            );
          }
          field.energy = field.energy * decay + travel;
          if (field.energy <= 0.05) {
            field.targets.forEach(target => {
              gl.bindFramebuffer(gl.FRAMEBUFFER, target.framebuffer);
              gl.clearColor(0, 0, 0, 0);
              gl.clear(gl.COLOR_BUFFER_BIT);
            });
          }
        }
      }
      pointer.lastX = pointer.x;
      pointer.lastY = pointer.y;

      for (let index = twirls.length - 1; index >= 0; index--) {
        twirls[index].age += dt;
        if (twirls[index].age >= 3.2) twirls.splice(index, 1);
      }
      twirlData.fill(0);
      twirls.forEach((twirl, index) => {
        const t = twirl.age;
        const rise = smoother(t / 0.25);
        const fall = 1 - smoother((t - 0.25) / 2.95);
        twirlData[index * 4] = twirl.x;
        twirlData[index * 4 + 1] = twirl.y;
        twirlData[index * 4 + 2] = twirl.direction * 1.9 * rise * fall;
        twirlData[index * 4 + 3] = 150 * (1 + 0.6 * smoother(t / 3.2));
      });

      const eased = 1 - Math.pow(1 - opening, 3);
      const unwind = 1 - eased;
      gl.bindFramebuffer(gl.FRAMEBUFFER, view.crt ? paintTarget.framebuffer : null);
      gl.viewport(0, 0, view.width, view.height);
      gl.useProgram(paintProgram.program);
      const u = paintProgram.uniforms;
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, field.targets.length ? field.targets[0].texture : null);
      gl.uniform1i(u.uField, 0);
      gl.uniform1f(u.uFieldOn, field.targets.length && field.energy > 0.05 ? 1 : 0);
      gl.uniform2f(u.uCss, view.cssWidth, view.cssHeight);
      gl.uniform2f(u.uCanvas, view.width, view.height);
      gl.uniform1f(u.uBlock, view.block);
      gl.uniform1f(u.uFlow, flow);
      gl.uniform1f(u.uSpin, -0.4 + spin + steer.value + 2.6 * unwind * unwind);
      gl.uniform2f(u.uOffset, s.offset[0], s.offset[1]);
      gl.uniform3f(u.uColor1, s.color1[0], s.color1[1], s.color1[2]);
      gl.uniform3f(u.uColor2, s.color2[0], s.color2[1], s.color2[2]);
      gl.uniform3f(u.uColor3, s.color3[0], s.color3[1], s.color3[2]);
      gl.uniform1f(u.uContrast, s.contrast);
      gl.uniform1f(u.uLighting, s.lighting);
      gl.uniform1f(u.uSwirl, Math.min(1, s.swirl + 0.55 * unwind));
      gl.uniform1f(u.uScale, s.scale);
      gl.uniform1i(u.uDetail, s.detail);
      gl.uniform4fv(u.uTwirls, twirlData);
      gl.uniform1f(u.uReveal, smoother(opening / 0.45));
      gl.uniform1f(u.uLight, s.light ? 1 : 0);
      gl.uniform1f(u.uOpacity, s.opacity);
      gl.drawArrays(gl.TRIANGLES, 0, 3);

      if (view.crt) {
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        gl.viewport(0, 0, canvas.width, canvas.height);
        gl.useProgram(screenProgram.program);
        const v = screenProgram.uniforms;
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, paintTarget.texture);
        gl.uniform1i(v.uPaint, 0);
        gl.uniform2f(v.uCanvas, canvas.width, canvas.height);
        gl.uniform2f(v.uSource, view.width, view.height);
        gl.uniform1f(v.uDevice, view.device);
        gl.uniform1f(v.uCrt, s.crt);
        gl.drawArrays(gl.TRIANGLES, 0, 3);
      }

      const settling = Math.abs(steerTarget - steer.value) > 0.0005 || field.energy > 0.05 || twirls.length > 0;
      const busy = s.speed > 0 || s.rotation !== 0 || opening < 1 || settling;
      if (busy && visible && pageVisible) raf = requestAnimationFrame(frame);
    };

    const wake = () => {
      if (raf || lost || !visible || !pageVisible) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };
    wakeRef.current = () => {
      resize();
      wake();
    };

    const locate = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      return {
        x: event.clientX - rect.left,
        y: event.clientY - rect.top,
        inside:
          event.clientX >= rect.left &&
          event.clientX <= rect.right &&
          event.clientY >= rect.top &&
          event.clientY <= rect.bottom
      };
    };

    const onPointerMove = (event: PointerEvent) => {
      const spot = locate(event);
      if (!pointer.ready || !pointer.inside) {
        pointer.lastX = spot.x;
        pointer.lastY = spot.y;
      }
      pointer.vx = spot.x - pointer.x;
      pointer.x = spot.x;
      pointer.y = spot.y;
      pointer.inside = spot.inside;
      pointer.ready = true;
      wake();
    };
    const onPointerDown = (event: PointerEvent) => {
      const s = settingsRef.current;
      const spot = locate(event);
      if (!spot.inside || !s.clickSwirl || reduced) return;
      twirls.push({ x: spot.x, y: spot.y, age: 0, direction: pointer.vx < 0 ? 1 : -1 });
      if (twirls.length > MAX_TWIRLS) twirls.shift();
      wake();
    };
    const onLeave = () => {
      pointer.inside = false;
      wake();
    };
    const onPointerUp = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse') onLeave();
    };
    window.addEventListener('pointermove', onPointerMove, { passive: true });
    window.addEventListener('pointerdown', onPointerDown, { passive: true });
    window.addEventListener('pointerup', onPointerUp, { passive: true });
    window.addEventListener('pointercancel', onPointerUp, { passive: true });
    document.documentElement.addEventListener('pointerleave', onLeave);

    const onLost = (event: Event) => {
      event.preventDefault();
      lost = true;
      cancelAnimationFrame(raf);
      raf = 0;
    };
    const onRestored = () => setGeneration(value => value + 1);
    canvas.addEventListener('webglcontextlost', onLost);
    canvas.addEventListener('webglcontextrestored', onRestored);

    const resizeObserver = new ResizeObserver(() => {
      resize();
      wake();
    });
    resizeObserver.observe(container);

    const intersection = new IntersectionObserver(entries => {
      visible = entries.some(entry => entry.isIntersecting);
      wake();
    });
    intersection.observe(container);

    const onVisibility = () => {
      pageVisible = document.visibilityState !== 'hidden';
      wake();
    };
    document.addEventListener('visibilitychange', onVisibility);

    resize();
    wake();

    return () => {
      cancelAnimationFrame(raf);
      wakeRef.current = null;
      resizeObserver.disconnect();
      intersection.disconnect();
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerdown', onPointerDown);
      window.removeEventListener('pointerup', onPointerUp);
      window.removeEventListener('pointercancel', onPointerUp);
      document.documentElement.removeEventListener('pointerleave', onLeave);
      document.removeEventListener('visibilitychange', onVisibility);
      canvas.removeEventListener('webglcontextlost', onLost);
      canvas.removeEventListener('webglcontextrestored', onRestored);
      if (!gl.isContextLost()) {
        dropField();
        gl.deleteTexture(paintTarget.texture);
        gl.deleteFramebuffer(paintTarget.framebuffer);
        gl.deleteVertexArray(vao);
        gl.deleteProgram(paintProgram.program);
        gl.deleteProgram(screenProgram.program);
        if (fieldProgram) gl.deleteProgram(fieldProgram.program);
      }
    };
  }, [generation]);

  return (
    <div ref={containerRef} className={`relative h-full w-full overflow-hidden ${className}`.trim()} style={style}>
      <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full" aria-hidden="true" />
    </div>
  );
};

export default Balatro;

'use client';

import { useEffect, useRef, type CSSProperties } from 'react';

const FOV = 50;
const CAMERA_Z = 20;
const MAX_ASPECT = 1.5;
const MAX_SPEED = 16;
const STRIDE = 12;
const SLOP = 0.01;

export type BallpitMaterial = 'satin' | 'matte' | 'gloss' | 'frosted' | 'metal';

export interface BallpitProps {
  count?: number;
  colors?: Array<string | number>;
  material?: BallpitMaterial;
  minSize?: number;
  maxSize?: number;
  gravity?: number;
  friction?: number;
  wallBounce?: number;
  bounce?: number;
  depth?: number;
  drift?: number;
  followCursor?: boolean;
  cursorSize?: number;
  grab?: boolean;
  clickEffect?: 'burst' | 'none';
  lightColor?: string;
  lightIntensity?: number;
  exposure?: number;
  shadows?: number;
  intro?: boolean;
  dpr?: number;
  className?: string;
  style?: CSSProperties;
}

interface Material {
  roughness: number;
  metalness: number;
  coat: number;
  coatRoughness: number;
  scatter: number;
  frost: number;
}

const MATERIALS: Record<string, Material> = {
  satin: { roughness: 0.42, metalness: 0, coat: 0.35, coatRoughness: 0.22, scatter: 1, frost: 0 },
  matte: { roughness: 0.92, metalness: 0, coat: 0, coatRoughness: 0.5, scatter: 0.5, frost: 0 },
  gloss: { roughness: 0.2, metalness: 0, coat: 1, coatRoughness: 0.08, scatter: 1, frost: 0 },
  frosted: { roughness: 0.55, metalness: 0, coat: 0.6, coatRoughness: 0.18, scatter: 1.5, frost: 1 },
  metal: { roughness: 0.3, metalness: 1, coat: 0, coatRoughness: 0.2, scatter: 0, frost: 0 }
};

const VERTEX = `#version 300 es
precision highp float;
layout(location = 0) in vec2 aCorner;
layout(location = 1) in vec4 aSphere;
layout(location = 2) in vec4 aColor;
layout(location = 3) in vec4 aShade;
uniform mat4 uProj;
uniform float uCameraZ;
uniform float uPixel;
out vec3 vPoint;
flat out vec3 vCenter;
flat out float vRadius;
flat out vec4 vColor;
flat out vec4 vShade;
void main() {
  vec3 c = vec3(aSphere.xy, aSphere.z - uCameraZ);
  float r = aSphere.w;
  float d = length(c);
  vec3 toCamera = -c / d;
  vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), toCamera));
  vec3 up = cross(toCamera, right);
  float reach = r * d / sqrt(max(d * d - r * r, 1e-4)) + uPixel * d * 2.0;
  vec3 p = c + (right * aCorner.x + up * aCorner.y) * reach;
  vPoint = p;
  vCenter = c;
  vRadius = r;
  vColor = aColor;
  vShade = aShade;
  gl_Position = uProj * vec4(p, 1.0);
}`;

const FRAGMENT = `#version 300 es
precision highp float;
in vec3 vPoint;
flat in vec3 vCenter;
flat in float vRadius;
flat in vec4 vColor;
flat in vec4 vShade;
uniform mat4 uProj;
uniform vec3 uLightPos;
uniform vec3 uLight;
uniform float uExposure;
uniform float uShadow;
uniform vec4 uSurface;
uniform vec2 uExtra;
out vec4 outColor;

const float PI = 3.14159265;

float lobe(vec3 d, vec3 axis, float sharp) {
  return pow(max(dot(d, axis), 0.0), sharp) * (sharp + 1.0) * 0.16;
}

vec3 studio(vec3 d, float rough) {
  float r = clamp(rough, 0.0, 1.0);
  float sharp = mix(60.0, 1.2, sqrt(r));
  vec3 col = mix(vec3(0.085, 0.085, 0.09), vec3(0.38, 0.38, 0.39), smoothstep(-0.7, 0.9, d.y));
  col += vec3(1.0, 0.99, 0.97) * 2.6 * lobe(d, normalize(vec3(-0.42, 0.78, 0.47)), sharp);
  col += vec3(0.97, 0.98, 1.0) * 1.1 * lobe(d, normalize(vec3(0.78, 0.22, 0.58)), sharp * 0.7);
  col += vec3(1.0) * 1.3 * lobe(d, normalize(vec3(0.15, 0.55, -0.82)), sharp * 0.8);
  return col;
}

vec2 envBRDF(float NoV, float rough) {
  vec4 c0 = vec4(-1.0, -0.0275, -0.572, 0.022);
  vec4 c1 = vec4(1.0, 0.0425, 1.04, -0.04);
  vec4 r = rough * c0 + c1;
  float a = min(r.x * r.x, exp2(-9.28 * NoV)) * r.x + r.y;
  return vec2(-1.04, 1.04) * a + r.zw;
}

float ggx(float NoH, float a) {
  float a2 = a * a;
  float d = NoH * NoH * (a2 - 1.0) + 1.0;
  return a2 / (PI * d * d);
}

float smith(float NoV, float NoL, float a) {
  float k = a * 0.5;
  return 0.25 / max((NoV * (1.0 - k) + k) * (NoL * (1.0 - k) + k), 1e-4);
}

vec3 aces(vec3 x) {
  return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

void main() {
  vec3 rd = normalize(vPoint);
  float b = dot(vCenter, rd);
  float h = length(vCenter - rd * b);
  float r = vRadius;
  float aa = max(fwidth(h), 1e-5);
  float cover = clamp((r - h) / aa + 0.5, 0.0, 1.0);
  if (cover <= 0.002) discard;
  float hc = min(h, r * 0.9995);
  float t = b - sqrt(r * r - hc * hc);
  vec3 pos = rd * t;
  vec3 n = normalize(pos - vCenter);
  vec4 clip = uProj * vec4(pos, 1.0);
  gl_FragDepth = clamp(clip.z / clip.w * 0.5 + 0.5, 0.0, 1.0);

  vec3 v = -rd;
  vec3 albedo = vColor.rgb;
  bool lamp = vColor.a > 0.5;
  vec3 dn = fwidth(n);
  float rough = sqrt(min(uSurface.x * uSurface.x + dot(dn, dn) * 0.6, 1.0));
  float metal = uSurface.y;
  float coat = uSurface.z;
  float coatRough = sqrt(min(uSurface.w * uSurface.w + dot(dn, dn) * 0.6, 1.0));
  float NoV = clamp(dot(n, v), 1e-4, 1.0);
  vec3 R = reflect(-v, n);

  float occlusion = vShade.w * smoothstep(-0.15, 0.9, dot(n, vShade.xyz));
  float ao = 1.0 - uShadow * occlusion;
  float specAo = 1.0 - uShadow * occlusion * 0.7;

  vec3 L = uLightPos - pos;
  float dist2 = dot(L, L);
  L *= inversesqrt(dist2);
  vec3 radiance = lamp ? vec3(0.0) : uLight / (dist2 + 1.0);
  float NoL = clamp(dot(n, L), 0.0, 1.0);
  vec3 H = normalize(L + v);
  float NoH = clamp(dot(n, H), 0.0, 1.0);
  float VoH = clamp(dot(v, H), 0.0, 1.0);

  vec3 F0 = mix(vec3(0.04), albedo, metal);
  vec2 ab = envBRDF(NoV, rough);
  vec3 Fr = max(vec3(1.0 - rough), F0) - F0;
  vec3 kS = F0 + Fr * pow(1.0 - NoV, 5.0);
  vec3 diffuseColor = albedo * (1.0 - metal);
  vec3 irradiance = studio(n, 1.0) * 1.15;
  vec3 envSpec = studio(R, rough) * (F0 * ab.x + ab.y);
  vec3 col = diffuseColor * irradiance * (1.0 - kS) * ao + envSpec * specAo;
  vec3 F = F0 + (1.0 - F0) * pow(1.0 - VoH, 5.0);
  float a = max(rough * rough, 0.06);
  vec3 spec = ggx(NoH, a) * smith(NoV, NoL, a) * F;
  float wrap = clamp((dot(n, L) + 0.3) / 1.3, 0.0, 1.0);
  col += (diffuseColor * (1.0 - F) / PI * wrap + spec * NoL) * radiance;
  vec3 sh = normalize(L + n * 0.1);
  float scatter = pow(clamp(dot(v, -sh), 0.0, 1.0), 2.0) * 10.0 + 0.04;
  col += scatter * albedo * radiance * 0.03 * uExtra.x;
  float alpha = 1.0;
  if (uExtra.y > 0.5) {
    float rim = pow(1.0 - NoV, 2.5);
    col += albedo * (studio(-R, 1.0) * 0.35 + 0.06) * (1.0 - rim);
    col += radiance * albedo * pow(max(dot(-v, L), 0.0), 3.0) * 0.08;
    alpha = mix(0.5, 0.96, rim);
  }
  if (coat > 0.0) {
    float Fc = 0.04 + 0.96 * pow(1.0 - NoV, 5.0);
    float ca = max(coatRough * coatRough, 0.03);
    vec3 coatEnv = studio(R, coatRough) * Fc;
    float coatSpec = ggx(NoH, ca) * smith(NoV, NoL, ca) * (0.04 + 0.96 * pow(1.0 - VoH, 5.0)) * NoL;
    col = col * (1.0 - Fc * coat) + (coatEnv * specAo + radiance * coatSpec) * coat;
    alpha = mix(alpha, 1.0, Fc * coat);
  }
  if (lamp) col += uLight * 0.0025 * (0.4 + 0.6 * albedo);
  col = aces(col * uExposure);
  col = pow(col, vec3(1.0 / 2.2));
  col += (fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453) - 0.5) / 255.0;
  float a2 = alpha * cover;
  outColor = vec4(col * a2, a2);
}`;

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const compile = (gl: WebGL2RenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
};

const link = (gl: WebGL2RenderingContext) => {
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  const uniforms: Record<string, WebGLUniformLocation | null> = {};
  const total = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < total; i++) {
    const info = gl.getActiveUniform(program, i);
    if (info) uniforms[info.name] = gl.getUniformLocation(program, info.name);
  }
  return { program, uniforms };
};

const toLinear = (value: string | number): number[] => {
  let rgb: number[];
  if (typeof value === 'number') {
    rgb = [((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255];
  } else {
    let hex = String(value || '#ffffff')
      .replace('#', '')
      .trim();
    if (hex.length === 3 || hex.length === 4)
      hex = hex
        .slice(0, 3)
        .split('')
        .map(c => c + c)
        .join('');
    const num = parseInt(hex.slice(0, 6), 16);
    rgb = Number.isNaN(num) ? [1, 1, 1] : [((num >> 16) & 255) / 255, ((num >> 8) & 255) / 255, (num & 255) / 255];
  }
  return rgb.map(c => Math.pow(c, 2.2));
};

const Ballpit = ({
  count = 200,
  colors = ['#ffffff'],
  material = 'satin',
  minSize = 0.5,
  maxSize = 1,
  gravity = 0.5,
  friction = 0.9975,
  wallBounce = 0.95,
  bounce = 0.85,
  depth = 2,
  drift = 0,
  followCursor = true,
  cursorSize = 1,
  grab = true,
  clickEffect = 'burst',
  lightColor = '#ffffff',
  lightIntensity = 1,
  exposure = 1,
  shadows = 0.6,
  intro = true,
  dpr,
  className = '',
  style
}: BallpitProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wakeRef = useRef<(() => void) | null>(null);
  const settings = {
    count: Math.round(clamp(count, 1, 4000)),
    colors: Array.isArray(colors) && colors.length ? colors : ['#ffffff'],
    material: MATERIALS[material] ? material : 'satin',
    minSize: Math.max(0.05, Math.min(minSize, maxSize)),
    maxSize: Math.max(0.05, Math.max(minSize, maxSize)),
    gravity,
    friction: clamp(friction, 0.5, 1),
    wallBounce: clamp(wallBounce, 0, 1),
    bounce: clamp(bounce, 0, 1),
    depth: Math.max(0, depth),
    drift: Math.max(0, drift),
    followCursor,
    cursorSize: Math.max(0, cursorSize),
    grab,
    clickEffect,
    lightColor,
    lightIntensity: lightIntensity > 20 ? lightIntensity / 200 : Math.max(0, lightIntensity),
    exposure: Math.max(0, exposure),
    shadows: clamp(shadows, 0, 1),
    intro,
    dpr
  };
  type Settings = typeof settings;
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    const gl = canvas?.getContext('webgl2', {
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      depth: true,
      stencil: false,
      powerPreference: 'high-performance'
    });
    if (!container || !canvas || !gl) return undefined;
    const shader = link(gl);
    if (!shader) return undefined;
    const u = shader.uniforms;

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const view = { width: 1, height: 1, ratio: 1, halfW: 9, halfH: 9, fit: 1, tan: Math.tan((FOV * Math.PI) / 360) };
    const projection = new Float32Array(16);

    const vao = gl.createVertexArray();
    gl.bindVertexArray(vao);
    const quad = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, quad);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    const instances = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, instances);
    for (let k = 0; k < 3; k++) {
      gl.enableVertexAttribArray(1 + k);
      gl.vertexAttribPointer(1 + k, 4, gl.FLOAT, false, STRIDE * 4, k * 16);
      gl.vertexAttribDivisor(1 + k, 1);
    }
    gl.bindVertexArray(null);

    let capacity = 0;
    let n = 0;
    let px = new Float32Array(0);
    let py = new Float32Array(0);
    let pz = new Float32Array(0);
    let vx = new Float32Array(0);
    let vy = new Float32Array(0);
    let vz = new Float32Array(0);
    let rad = new Float32Array(0);
    let inv = new Float32Array(0);
    let size = new Float32Array(0);
    let phase = new Float32Array(0);
    let occ = new Float32Array(0);
    let still = new Float32Array(0);
    let tone = new Uint16Array(0);
    let entered = new Uint8Array(0);
    let cellOf = new Int32Array(0);
    let sorted = new Int32Array(0);
    let order = new Int32Array(1);
    let data = new Float32Array(STRIDE);
    let table = new Int32Array(2);
    let starts = new Int32Array(2);
    let palette: number[][] = [];
    let paletteKey = '';
    let lastSizes = '';

    const allocate = (total: number) => {
      const grow = (old: Float32Array, width = 1) => {
        const next = new Float32Array(total * width);
        next.set(old.subarray(0, Math.min(old.length, next.length)));
        return next;
      };
      const growUint8 = (old: Uint8Array) => {
        const next = new Uint8Array(total);
        next.set(old.subarray(0, Math.min(old.length, next.length)));
        return next;
      };
      px = grow(px);
      py = grow(py);
      pz = grow(pz);
      vx = grow(vx);
      vy = grow(vy);
      vz = grow(vz);
      rad = grow(rad);
      inv = grow(inv);
      size = grow(size);
      phase = grow(phase);
      occ = grow(occ, 4);
      still = grow(still, 3);
      const nextTone = new Uint16Array(total);
      nextTone.set(tone.subarray(0, Math.min(tone.length, total)));
      tone = nextTone;
      entered = growUint8(entered);
      cellOf = new Int32Array(total);
      sorted = new Int32Array(total);
      order = new Int32Array(total + 1);
      data = new Float32Array((total + 1) * STRIDE);
      capacity = total;
      gl.bindBuffer(gl.ARRAY_BUFFER, instances);
      gl.bufferData(gl.ARRAY_BUFFER, data.byteLength, gl.DYNAMIC_DRAW);
    };

    const pointer = { x: 0, y: 0, inside: false, down: false, downX: 0, downY: 0, downAt: 0, moved: false };
    const cursor = { x: 0, y: 0, z: 0, r: 0, tx: 0, ty: 0, vx: 0, vy: 0 };
    const light = { x: 0, y: 5, z: 6, flash: 0 };
    const held = { index: -1, ox: 0, oy: 0, tx: 0, ty: 0, vx: 0, vy: 0 };
    let elapsed = 0;
    let glide = 0;
    let raf = 0;
    let last = 0;
    let visible = true;
    let quiet = 0;

    const spawn = (i: number, s: Settings, fromTop: boolean) => {
      const r = rad[i];
      const zr = Math.max(s.depth - r, 0);
      entered[i] = 1;
      if (fromTop && s.gravity > 0.05) {
        px[i] = (Math.random() * 2 - 1) * Math.max(view.halfW - r, 0.01);
        py[i] = view.halfH + r + Math.random() * view.halfH * 2.2;
        pz[i] = (Math.random() * 2 - 1) * zr;
        vx[i] = (Math.random() - 0.5) * 2;
        vy[i] = -(4 + Math.random() * 5);
        vz[i] = 0;
        entered[i] = 0;
      } else if (fromTop) {
        const tx = (Math.random() * 2 - 1) * Math.max(view.halfW - r, 0.01);
        const ty = (Math.random() * 2 - 1) * Math.max(view.halfH - r, 0.01);
        const tz = (Math.random() * 2 - 1) * zr;
        px[i] = (Math.random() * 2 - 1) * 0.6;
        py[i] = (Math.random() * 2 - 1) * 0.6;
        pz[i] = (Math.random() * 2 - 1) * Math.min(zr, 0.3);
        vx[i] = (tx - px[i]) * 2.2;
        vy[i] = (ty - py[i]) * 2.2;
        vz[i] = (tz - pz[i]) * 2.2;
        glide = 1;
      } else {
        px[i] = (Math.random() * 2 - 1) * Math.max(view.halfW - r, 0.01);
        py[i] = (Math.random() * 2 - 1) * Math.max(view.halfH - r, 0.01);
        pz[i] = (Math.random() * 2 - 1) * zr;
        vx[i] = 0;
        vy[i] = 0;
        vz[i] = 0;
      }
    };

    const applySizes = (s: Settings) => {
      for (let i = 0; i < n; i++) {
        rad[i] = (s.minSize + size[i] * (s.maxSize - s.minSize)) * view.fit;
        inv[i] = 1 / (rad[i] * rad[i] * rad[i]);
      }
    };

    const applyPalette = (s: Settings) => {
      palette = s.colors.map(toLinear);
      paletteKey = s.colors.join('|');
    };

    const sync = (s: Settings, first: boolean) => {
      const key = `${s.minSize}:${s.maxSize}:${view.fit}`;
      if (s.count !== n) {
        if (s.count > capacity) allocate(Math.max(s.count, Math.ceil(capacity * 1.5)));
        const from = n;
        n = s.count;
        for (let i = from; i < n; i++) {
          size[i] = Math.random();
          tone[i] = i;
          phase[i] = Math.random() * Math.PI * 2;
          rad[i] = (s.minSize + size[i] * (s.maxSize - s.minSize)) * view.fit;
          inv[i] = 1 / (rad[i] * rad[i] * rad[i]);
          spawn(i, s, (first ? s.intro : true) && !reduce);
        }
        for (let i = 0; i <= n; i++) order[i] = i;
      }
      if (key !== lastSizes) {
        lastSizes = key;
        applySizes(s);
      }
      if (s.colors.join('|') !== paletteKey) applyPalette(s);
    };

    let contacts = new Float32Array(0);
    let contactCount = 0;

    const grid = { scale: 1, x0: 0, y0: 0, z0: 0, nx: 1, ny: 1, nz: 1 };

    const buildGrid = (cell: number, s: Settings) => {
      grid.scale = 1 / cell;
      grid.x0 = -view.halfW - cell;
      grid.y0 = -view.halfH - cell;
      grid.z0 = -Math.max(s.depth, s.maxSize) - cell;
      grid.nx = Math.max(1, Math.ceil((view.halfW * 2 + cell * 2) * grid.scale) + 1);
      grid.ny = Math.max(1, Math.ceil((view.halfH * 2 + cell * 2) * grid.scale) + 1);
      grid.nz = Math.max(1, Math.ceil((Math.max(s.depth, s.maxSize) * 2 + cell * 2) * grid.scale) + 1);
      const cells = grid.nx * grid.ny * grid.nz;
      if (table.length < cells + 1) {
        table = new Int32Array(cells + 1);
        starts = new Int32Array(cells + 1);
      }
      table.fill(0, 0, cells + 1);
      for (let i = 0; i < n; i++) {
        const cx = clamp(Math.floor((px[i] - grid.x0) * grid.scale), 0, grid.nx - 1);
        const cy = clamp(Math.floor((py[i] - grid.y0) * grid.scale), 0, grid.ny - 1);
        const cz = clamp(Math.floor((pz[i] - grid.z0) * grid.scale), 0, grid.nz - 1);
        const c = (cz * grid.ny + cy) * grid.nx + cx;
        cellOf[i] = c;
        table[c + 1]++;
      }
      for (let c = 1; c <= cells; c++) table[c] += table[c - 1];
      starts.set(table.subarray(0, cells + 1));
      for (let i = 0; i < n; i++) sorted[starts[cellOf[i]]++] = i;
    };

    const wall = (i: number, gap: number, nx: number, ny: number, nz: number, bounce: number, margin: number) => {
      if (gap >= margin || contactCount * 8 >= contacts.length) return;
      const approach = vx[i] * nx + vy[i] * ny + vz[i] * nz;
      const o = contactCount * 8;
      contacts[o] = i;
      contacts[o + 1] = -2;
      contacts[o + 2] = nx;
      contacts[o + 3] = ny;
      contacts[o + 4] = nz;
      contacts[o + 5] = gap;
      contacts[o + 6] = approach < -1.5 ? -bounce * approach : 0;
      contacts[o + 7] = 0;
      contactCount++;
    };

    const findContacts = (s: Settings, dt: number, shade: boolean, margin: number) => {
      const heldIndex = held.index;
      const { nx: gx, ny: gy, nz: gz } = grid;
      contactCount = 0;
      for (let i = 0; i < n; i++) {
        const c = cellOf[i];
        const cx = c % gx;
        const cy = Math.floor(c / gx) % gy;
        const cz = Math.floor(c / (gx * gy));
        for (let dz = cz > 0 ? -1 : 0; dz <= (cz < gz - 1 ? 1 : 0); dz++) {
          for (let dy = cy > 0 ? -1 : 0; dy <= (cy < gy - 1 ? 1 : 0); dy++) {
            const row = ((cz + dz) * gy + cy + dy) * gx;
            for (let dx = cx > 0 ? -1 : 0; dx <= (cx < gx - 1 ? 1 : 0); dx++) {
              const cell = row + cx + dx;
              for (let k = table[cell]; k < table[cell + 1]; k++) {
                const j = sorted[k];
                if (j <= i) continue;
                const ddx = px[j] - px[i];
                const ddy = py[j] - py[i];
                const ddz = pz[j] - pz[i];
                const d2 = ddx * ddx + ddy * ddy + ddz * ddz;
                const sum = rad[i] + rad[j];
                const reach = Math.max(sum + margin, shade ? sum * 1.4 : 0);
                if (d2 >= reach * reach || d2 < 1e-12) continue;
                const d = Math.sqrt(d2);
                const nx = ddx / d;
                const ny = ddy / d;
                const nz = ddz / d;
                if (shade) {
                  const w = clamp(1 - (d - sum) / (sum * 0.4), 0, 1);
                  occ[i * 4] += nx * w;
                  occ[i * 4 + 1] += ny * w;
                  occ[i * 4 + 2] += nz * w;
                  occ[i * 4 + 3] += w;
                  occ[j * 4] -= nx * w;
                  occ[j * 4 + 1] -= ny * w;
                  occ[j * 4 + 2] -= nz * w;
                  occ[j * 4 + 3] += w;
                }
                if (d >= sum + margin || contactCount * 8 >= contacts.length) continue;
                if (i === heldIndex && j === heldIndex) continue;
                const approach = (vx[j] - vx[i]) * nx + (vy[j] - vy[i]) * ny + (vz[j] - vz[i]) * nz;
                const o = contactCount * 8;
                contacts[o] = i;
                contacts[o + 1] = j;
                contacts[o + 2] = nx;
                contacts[o + 3] = ny;
                contacts[o + 4] = nz;
                contacts[o + 5] = d - sum;
                contacts[o + 6] = approach < -1.5 ? -s.bounce * approach : 0;
                contacts[o + 7] = 0;
                contactCount++;
              }
            }
          }
        }
        if (i !== heldIndex) {
          const r = rad[i];
          const zr = Math.max(s.depth - r, 0);
          wall(i, px[i] + view.halfW - r, 1, 0, 0, s.wallBounce, margin);
          wall(i, view.halfW - r - px[i], -1, 0, 0, s.wallBounce, margin);
          wall(i, py[i] + view.halfH - r, 0, 1, 0, s.wallBounce, margin);
          if (entered[i]) wall(i, view.halfH - r - py[i], 0, -1, 0, s.wallBounce, margin);
          wall(i, pz[i] + zr, 0, 0, 1, s.wallBounce, margin);
          wall(i, zr - pz[i], 0, 0, -1, s.wallBounce, margin);
        }
        if (cursor.r > 0.01 && i !== heldIndex && contactCount * 8 < contacts.length) {
          const ddx = px[i] - cursor.x;
          const ddy = py[i] - cursor.y;
          const ddz = pz[i] - cursor.z;
          const sum = rad[i] + cursor.r;
          const d2 = ddx * ddx + ddy * ddy + ddz * ddz;
          if (d2 < (sum + margin) * (sum + margin) && d2 > 1e-12) {
            const d = Math.sqrt(d2);
            const nx = ddx / d;
            const ny = ddy / d;
            const nz = ddz / d;
            const approach = (vx[i] - cursor.vx) * nx + (vy[i] - cursor.vy) * ny + vz[i] * nz;
            const o = contactCount * 8;
            contacts[o] = i;
            contacts[o + 1] = -1;
            contacts[o + 2] = nx;
            contacts[o + 3] = ny;
            contacts[o + 4] = nz;
            contacts[o + 5] = d - sum;
            contacts[o + 6] = approach < -1.5 ? -s.bounce * approach : 0;
            contacts[o + 7] = 0;
            contactCount++;
          }
        }
      }
    };

    const solveVelocities = (dt: number) => {
      const heldIndex = held.index;
      const iterations = n > 800 ? 5 : 8;
      for (let iteration = 0; iteration < iterations; iteration++) {
        for (let c = 0; c < contactCount; c++) {
          const o = c * 8;
          const i = contacts[o];
          const j = contacts[o + 1];
          const nx = contacts[o + 2];
          const ny = contacts[o + 3];
          const nz = contacts[o + 4];
          const gap = contacts[o + 5];
          const target = gap > 0 ? -gap / dt : contacts[o + 6];
          const before = contacts[o + 7];
          if (j < 0) {
            const vn =
              j === -1
                ? (vx[i] - cursor.vx) * nx + (vy[i] - cursor.vy) * ny + vz[i] * nz
                : vx[i] * nx + vy[i] * ny + vz[i] * nz;
            const after = Math.max(before + target - vn, 0);
            const change = after - before;
            contacts[o + 7] = after;
            vx[i] += change * nx;
            vy[i] += change * ny;
            vz[i] += change * nz;
            continue;
          }
          const wi = i === heldIndex ? 0 : inv[i];
          const wj = j === heldIndex ? 0 : inv[j];
          const w = wi + wj;
          if (w <= 0) continue;
          const vn = (vx[j] - vx[i]) * nx + (vy[j] - vy[i]) * ny + (vz[j] - vz[i]) * nz;
          const after = Math.max(before + (target - vn) / w, 0);
          const change = after - before;
          contacts[o + 7] = after;
          vx[i] -= change * wi * nx;
          vy[i] -= change * wi * ny;
          vz[i] -= change * wi * nz;
          vx[j] += change * wj * nx;
          vy[j] += change * wj * ny;
          vz[j] += change * wj * nz;
        }
      }
    };

    const correctPositions = () => {
      const heldIndex = held.index;
      for (let pass = 0; pass < 2; pass++) {
        for (let c = 0; c < contactCount; c++) {
          const o = c * 8;
          const i = contacts[o];
          const j = contacts[o + 1];
          if (j === -2) continue;
          if (j < 0) {
            const ddx = px[i] - cursor.x;
            const ddy = py[i] - cursor.y;
            const ddz = pz[i] - cursor.z;
            const d = Math.sqrt(ddx * ddx + ddy * ddy + ddz * ddz);
            const overlap = rad[i] + cursor.r - d - SLOP;
            if (overlap <= 0 || d < 1e-6) continue;
            const k = (overlap * 0.5) / d;
            px[i] += ddx * k;
            py[i] += ddy * k;
            pz[i] += ddz * k;
            continue;
          }
          const ddx = px[j] - px[i];
          const ddy = py[j] - py[i];
          const ddz = pz[j] - pz[i];
          const d = Math.sqrt(ddx * ddx + ddy * ddy + ddz * ddz);
          const overlap = rad[i] + rad[j] - d - SLOP;
          if (overlap <= 0 || d < 1e-6) continue;
          const wi = i === heldIndex ? 0 : inv[i];
          const wj = j === heldIndex ? 0 : inv[j];
          const w = wi + wj;
          if (w <= 0) continue;
          const k = (overlap * 0.3) / (d * w);
          px[i] -= ddx * k * wi;
          py[i] -= ddy * k * wi;
          pz[i] -= ddz * k * wi;
          px[j] += ddx * k * wj;
          py[j] += ddy * k * wj;
          pz[j] += ddz * k * wj;
        }
      }
    };

    const walls = (s: Settings) => {
      const hw = view.halfW;
      const hh = view.halfH;
      const e = s.wallBounce;
      for (let i = 0; i < n; i++) {
        const r = rad[i];
        if (px[i] < -hw + r) {
          px[i] = -hw + r;
          if (vx[i] < 0) vx[i] = vx[i] < -1.5 ? -vx[i] * e : 0;
        } else if (px[i] > hw - r) {
          px[i] = hw - r;
          if (vx[i] > 0) vx[i] = vx[i] > 1.5 ? -vx[i] * e : 0;
        }
        if (py[i] < -hh + r) {
          py[i] = -hh + r;
          if (vy[i] < 0) vy[i] = vy[i] < -1.5 ? -vy[i] * e : 0;
          vx[i] *= 0.995;
          vz[i] *= 0.995;
        } else if (entered[i] && py[i] > hh - r) {
          py[i] = hh - r;
          if (vy[i] > 0) vy[i] = vy[i] > 1.5 ? -vy[i] * e : 0;
        }
        if (!entered[i] && py[i] < hh - r) entered[i] = 1;
        const zr = Math.max(s.depth - r, 0);
        if (pz[i] < -zr) {
          pz[i] = -zr;
          if (vz[i] < 0) vz[i] = vz[i] < -1.5 ? -vz[i] * e : 0;
        } else if (pz[i] > zr) {
          pz[i] = zr;
          if (vz[i] > 0) vz[i] = vz[i] > 1.5 ? -vz[i] * e : 0;
        }
      }
    };

    const step = (s: Settings, dt: number, shade: boolean) => {
      const g = s.gravity * 45;
      const damp = Math.pow(s.friction, dt * 60) * (glide > 0 ? Math.exp(-2.2 * dt) : 1);
      const wander = reduce ? 0 : s.drift * 2.2;
      const biggest = s.maxSize * view.fit;
      const margin = biggest * 0.3;
      if (contacts.length < n * 96) contacts = new Float32Array(n * 96);
      for (let i = 0; i < n; i++) {
        if (i === held.index) {
          const f = 1 - Math.exp(-dt / 0.02);
          vx[i] = ((held.tx - px[i]) * f) / dt;
          vy[i] = ((held.ty - py[i]) * f) / dt;
          vz[i] = 0;
          continue;
        }
        vy[i] -= g * dt;
        if (wander) {
          const p = phase[i];
          vx[i] += Math.sin(elapsed * 0.63 + p) * wander * dt;
          vy[i] += Math.cos(elapsed * 0.47 + p * 1.7) * wander * dt;
          vz[i] += Math.sin(elapsed * 0.41 + p * 2.3) * wander * dt * 0.5;
        }
        vx[i] *= damp;
        vy[i] *= damp;
        vz[i] *= damp;
        const sp = vx[i] * vx[i] + vy[i] * vy[i] + vz[i] * vz[i];
        if (sp > MAX_SPEED * MAX_SPEED) {
          const f = MAX_SPEED / Math.sqrt(sp);
          vx[i] *= f;
          vy[i] *= f;
          vz[i] *= f;
        }
      }
      buildGrid(biggest * (shade ? 2.8 : 2.3), s);
      if (shade) occ.fill(0, 0, n * 4);
      findContacts(s, dt, shade, margin);
      solveVelocities(dt);
      for (let i = 0; i < n; i++) {
        px[i] += vx[i] * dt;
        py[i] += vy[i] * dt;
        pz[i] += vz[i] * dt;
      }
      correctPositions();
      walls(s);
      if (shade) {
        for (let i = 0; i < n; i++) {
          const gap = py[i] - rad[i] + view.halfH;
          const reach = rad[i] * 0.5;
          if (gap >= reach) continue;
          const w = 1 - Math.max(gap, 0) / reach;
          occ[i * 4 + 1] -= w;
          occ[i * 4 + 3] += w;
        }
      }
      if (held.index >= 0) {
        const i = held.index;
        held.vx += (vx[i] - held.vx) * (1 - Math.exp(-dt / 0.05));
        held.vy += (vy[i] - held.vy) * (1 - Math.exp(-dt / 0.05));
      }
    };

    const rayTo = (clientX: number, clientY: number) => {
      const rect = container.getBoundingClientRect();
      const nx = ((clientX - rect.left) / Math.max(rect.width, 1)) * 2 - 1;
      const ny = 1 - ((clientY - rect.top) / Math.max(rect.height, 1)) * 2;
      return [nx * view.tan * (view.width / view.height), ny * view.tan, -1];
    };

    const onPlane = (ray: number[], z: number) => {
      const t = (z - CAMERA_Z) / ray[2];
      return [ray[0] * t, ray[1] * t];
    };

    const pick = (ray: number[]) => {
      const len = Math.hypot(ray[0], ray[1], ray[2]);
      const dx = ray[0] / len;
      const dy = ray[1] / len;
      const dz = ray[2] / len;
      let best = -1;
      let bestT = Infinity;
      for (let i = 0; i < n; i++) {
        const ox = -px[i];
        const oy = -py[i];
        const oz = CAMERA_Z - pz[i];
        const b = ox * dx + oy * dy + oz * dz;
        const r = rad[i] * 1.15;
        const c = ox * ox + oy * oy + oz * oz - r * r;
        const disc = b * b - c;
        if (disc < 0) continue;
        const t = -b - Math.sqrt(disc);
        if (t > 0 && t < bestT) {
          bestT = t;
          best = i;
        }
      }
      return best;
    };

    const burst = (x: number, y: number) => {
      const s = settingsRef.current;
      const reach = view.halfH * 0.7;
      for (let i = 0; i < n; i++) {
        const dx = px[i] - x;
        const dy = py[i] - y;
        const dz = pz[i];
        const d = Math.hypot(dx, dy, dz);
        if (d >= reach || d < 1e-4) continue;
        const f = Math.pow(1 - d / reach, 2) * 26 * (1 + 0.6 / (rad[i] + 0.4));
        vx[i] += (dx / d) * f;
        vy[i] += (dy / d) * f + f * 0.25;
        vz[i] += (dz / d) * f * 0.5;
      }
      light.x = x;
      light.y = y;
      light.z = Math.max(s.depth, 1) + 1.5;
      light.flash = 1;
    };

    let sizedDpr = settingsRef.current.dpr;

    const resize = () => {
      const s = settingsRef.current;
      sizedDpr = s.dpr;
      view.width = Math.max(1, container.clientWidth);
      view.height = Math.max(1, container.clientHeight);
      view.ratio = Math.min(s.dpr || window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(view.width * view.ratio));
      canvas.height = Math.max(1, Math.round(view.height * view.ratio));
      const aspect = view.width / view.height;
      const base = Math.tan((FOV * Math.PI) / 360);
      view.tan = aspect > MAX_ASPECT ? (base * MAX_ASPECT) / aspect : base;
      view.halfH = view.tan * CAMERA_Z;
      view.halfW = view.halfH * aspect;
      view.fit = clamp(Math.sqrt((view.halfW * view.halfH) / (base * base * CAMERA_Z * CAMERA_Z * MAX_ASPECT)), 0.4, 1);
      const f = 1 / view.tan;
      const near = 1;
      const far = 80;
      projection.fill(0);
      projection[0] = f / aspect;
      projection[5] = f;
      projection[10] = (far + near) / (near - far);
      projection[11] = -1;
      projection[14] = (2 * far * near) / (near - far);
      if (!n) sync(s, true);
      draw();
      wake();
    };

    const draw = () => {
      const s = settingsRef.current;
      const mat = MATERIALS[s.material];
      let count = 0;
      const total = n + 1;
      for (let a = 1; a < total; a++) {
        const item = order[a];
        const z = item === n ? cursor.z : pz[item];
        let b = a - 1;
        while (b >= 0 && (order[b] === n ? cursor.z : pz[order[b]]) > z) {
          order[b + 1] = order[b];
          b--;
        }
        order[b + 1] = item;
      }
      for (let k = 0; k < total; k++) {
        const i = order[k];
        const o = count * STRIDE;
        if (i === n) {
          if (cursor.r < 0.01 || !s.followCursor) continue;
          const c = palette[0] || [1, 1, 1];
          data[o] = cursor.x;
          data[o + 1] = cursor.y;
          data[o + 2] = cursor.z;
          data[o + 3] = cursor.r;
          data[o + 4] = c[0];
          data[o + 5] = c[1];
          data[o + 6] = c[2];
          data[o + 7] = 1;
          data[o + 8] = 0;
          data[o + 9] = 0;
          data[o + 10] = 0;
          data[o + 11] = 0;
        } else {
          const c = palette[tone[i] % palette.length];
          data[o] = px[i];
          data[o + 1] = py[i];
          data[o + 2] = pz[i];
          data[o + 3] = rad[i];
          data[o + 4] = c[0];
          data[o + 5] = c[1];
          data[o + 6] = c[2];
          data[o + 7] = 0;
          const w = occ[i * 4 + 3];
          const len = Math.hypot(occ[i * 4], occ[i * 4 + 1], occ[i * 4 + 2]) || 1;
          data[o + 8] = occ[i * 4] / len;
          data[o + 9] = occ[i * 4 + 1] / len;
          data[o + 10] = occ[i * 4 + 2] / len;
          data[o + 11] = Math.min(w * 0.55, 1);
        }
        count++;
      }
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.clearColor(0, 0, 0, 0);
      gl.clearDepth(1);
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
      if (!count) return;
      gl.enable(gl.DEPTH_TEST);
      gl.depthFunc(gl.LEQUAL);
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      gl.useProgram(shader.program);
      gl.uniformMatrix4fv(u.uProj, false, projection);
      gl.uniform1f(u.uCameraZ, CAMERA_Z);
      gl.uniform1f(u.uPixel, (2 * view.tan) / canvas.height);
      const lc = toLinear(s.lightColor);
      const power = s.lightIntensity * 60 * (1 + light.flash * 3);
      gl.uniform3f(u.uLight, lc[0] * power, lc[1] * power, lc[2] * power);
      gl.uniform3f(u.uLightPos, light.x, light.y, light.z - CAMERA_Z);
      gl.uniform1f(u.uExposure, s.exposure);
      gl.uniform1f(u.uShadow, s.shadows);
      gl.uniform4f(u.uSurface, mat.roughness, mat.metalness, mat.coat, mat.coatRoughness);
      gl.uniform2f(u.uExtra, mat.scatter, mat.frost);
      gl.bindBuffer(gl.ARRAY_BUFFER, instances);
      gl.bufferSubData(gl.ARRAY_BUFFER, 0, data, 0, count * STRIDE);
      gl.bindVertexArray(vao);
      gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, count);
      gl.bindVertexArray(null);
    };

    const frame = (now: number) => {
      raf = 0;
      if (!visible || document.hidden) return;
      const s = settingsRef.current;
      if (s.dpr !== sizedDpr) resize();
      const dt = last ? clamp((now - last) / 1000, 0, 1 / 20) : 1 / 60;
      last = now;
      elapsed += dt;
      glide = Math.max(0, glide - dt);
      sync(s, false);
      const targetR = s.followCursor && pointer.inside && held.index < 0 ? s.cursorSize * view.fit : 0;
      cursor.r += (targetR - cursor.r) * (1 - Math.exp(-dt / 0.12));
      const follow = 1 - Math.exp(-dt / 0.06);
      const fromX = cursor.x;
      const fromY = cursor.y;
      cursor.x += (cursor.tx - cursor.x) * follow;
      cursor.y += (cursor.ty - cursor.y) * follow;
      cursor.vx = clamp((cursor.x - fromX) / Math.max(dt, 1e-3), -MAX_SPEED, MAX_SPEED);
      cursor.vy = clamp((cursor.y - fromY) / Math.max(dt, 1e-3), -MAX_SPEED, MAX_SPEED);
      const restX = 0;
      const restY = view.halfH * 0.75;
      const restZ = s.depth + 4;
      const lightTarget = pointer.inside
        ? [cursor.x, cursor.y, s.followCursor ? cursor.z : 1.5]
        : light.flash > 0.05
          ? [light.x, light.y, light.z]
          : [restX, restY, restZ];
      const lf = 1 - Math.exp(-dt / 0.08);
      light.x += (lightTarget[0] - light.x) * lf;
      light.y += (lightTarget[1] - light.y) * lf;
      light.z += (lightTarget[2] - light.z) * lf;
      light.flash *= Math.exp(-dt / 0.3);
      if (dt > 1e-4) {
        const steps = Math.min(6, Math.max(1, Math.ceil(dt / (1 / 180))));
        const h = dt / steps;
        for (let k = 0; k < steps; k++) step(s, h, k === steps - 1);
      }
      draw();
      let moved = 0;
      for (let i = 0; i < n; i++) {
        const k = i * 3;
        const d = Math.abs(px[i] - still[k]) + Math.abs(py[i] - still[k + 1]) + Math.abs(pz[i] - still[k + 2]);
        if (d > moved) moved = d;
        still[k] = px[i];
        still[k + 1] = py[i];
        still[k + 2] = pz[i];
      }
      const motion = moved / Math.max(dt, 1e-3);
      const busy =
        motion > 0.6 ||
        pointer.inside ||
        held.index >= 0 ||
        light.flash > 0.01 ||
        glide > 0 ||
        cursor.r > 0.01 ||
        (s.drift > 0 && !reduce);
      quiet = busy ? 0 : quiet + dt;
      if (quiet < 0.8) raf = requestAnimationFrame(frame);
    };

    function wake() {
      quiet = 0;
      if (!raf && visible && !document.hidden) {
        last = 0;
        raf = requestAnimationFrame(frame);
      }
    }

    const inside = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;
      return x >= 0 && y >= 0 && x <= rect.width && y <= rect.height;
    };

    const aim = (event: PointerEvent) => {
      const ray = rayTo(event.clientX, event.clientY);
      const [x, y] = onPlane(ray, cursor.z);
      cursor.tx = x;
      cursor.ty = y;
      if (held.index >= 0) {
        const [hx, hy] = onPlane(ray, pz[held.index]);
        held.tx = hx - held.ox;
        held.ty = hy - held.oy;
      }
      return ray;
    };

    const onPointerMove = (event: PointerEvent) => {
      const was = pointer.inside;
      pointer.inside = inside(event) || held.index >= 0;
      if (pointer.inside) {
        aim(event);
        if (!was) {
          cursor.x = cursor.tx;
          cursor.y = cursor.ty;
        }
        if (pointer.down && Math.hypot(event.clientX - pointer.downX, event.clientY - pointer.downY) > 6)
          pointer.moved = true;
      }
      if (pointer.inside || was) wake();
    };

    const interactive = (target: EventTarget | null) =>
      target instanceof Element && target.closest('a, button, input, textarea, select, label, [role="button"]');

    const onPointerDown = (event: PointerEvent) => {
      if (event.button !== 0 || !inside(event) || interactive(event.target)) return;
      const s = settingsRef.current;
      pointer.down = true;
      pointer.moved = false;
      pointer.downX = event.clientX;
      pointer.downY = event.clientY;
      pointer.downAt = performance.now();
      const ray = aim(event);
      if (s.grab) {
        const i = pick(ray);
        if (i >= 0) {
          const [hx, hy] = onPlane(ray, pz[i]);
          held.index = i;
          held.ox = hx - px[i];
          held.oy = hy - py[i];
          held.tx = px[i];
          held.ty = py[i];
          held.vx = 0;
          held.vy = 0;
          if (event.pointerType === 'mouse') event.preventDefault();
        }
      }
      wake();
    };

    const release = (event: PointerEvent | null) => {
      const s = settingsRef.current;
      if (held.index >= 0) {
        const i = held.index;
        const sp = Math.hypot(held.vx, held.vy);
        const k = sp > 22 ? 22 / sp : 1;
        vx[i] = held.vx * k;
        vy[i] = held.vy * k;
        held.index = -1;
        entered[i] = 1;
      } else if (
        event &&
        pointer.down &&
        !pointer.moved &&
        performance.now() - pointer.downAt < 400 &&
        s.clickEffect === 'burst' &&
        !reduce &&
        inside(event)
      ) {
        const [x, y] = onPlane(rayTo(event.clientX, event.clientY), 0);
        burst(x, y);
      }
      pointer.down = false;
      wake();
    };

    const onPointerUp = (event: PointerEvent) => release(event);
    const onPointerCancel = () => release(null);
    const onPointerLeave = () => {
      pointer.inside = held.index >= 0;
      wake();
    };
    const onVisibility = () => wake();

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(container);
    const intersection = new IntersectionObserver(entries => {
      visible = entries.some(entry => entry.isIntersecting);
      if (visible) wake();
    });
    intersection.observe(container);
    window.addEventListener('pointermove', onPointerMove, { passive: true });
    window.addEventListener('pointerdown', onPointerDown);
    window.addEventListener('pointerup', onPointerUp, { passive: true });
    window.addEventListener('pointercancel', onPointerCancel, { passive: true });
    document.documentElement.addEventListener('pointerleave', onPointerLeave);
    document.addEventListener('visibilitychange', onVisibility);
    resize();
    wakeRef.current = wake;

    return () => {
      cancelAnimationFrame(raf);
      wakeRef.current = null;
      resizeObserver.disconnect();
      intersection.disconnect();
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerdown', onPointerDown);
      window.removeEventListener('pointerup', onPointerUp);
      window.removeEventListener('pointercancel', onPointerCancel);
      document.documentElement.removeEventListener('pointerleave', onPointerLeave);
      document.removeEventListener('visibilitychange', onVisibility);
      gl.deleteBuffer(quad);
      gl.deleteBuffer(instances);
      gl.deleteVertexArray(vao);
      gl.deleteProgram(shader.program);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    };
  }, []);

  useEffect(() => {
    wakeRef.current?.();
  });

  return (
    <div
      ref={containerRef}
      className={['relative w-full h-full overflow-hidden', className].filter(Boolean).join(' ')}
      style={style}
    >
      <canvas ref={canvasRef} className="block w-full h-full" aria-hidden="true" />
    </div>
  );
};

export default Ballpit;

'use client';

import { useEffect, useRef, type HTMLAttributes } from 'react';

export interface BeamsProps extends HTMLAttributes<HTMLDivElement> {
  color?: string;
  beamWidth?: number;
  rotation?: number;
  speed?: number;
  waveLength?: number;
  depth?: number;
  sharpness?: number;
  twist?: number;
  fillLight?: number;
  glow?: number;
  brightness?: number;
  variation?: number;
  grain?: number;
  quality?: number;
  mouseInteraction?: boolean;
  mouseStrength?: number;
  intro?: boolean;
  fade?: number;
  opacity?: number;
  lightMode?: boolean;
  backgroundColor?: string;
  paused?: boolean;
  dpr?: number;
  className?: string;
}

type Settings = {
  color: string;
  beamWidth: number;
  rotation: number;
  speed: number;
  waveLength: number;
  depth: number;
  sharpness: number;
  twist: number;
  fillLight: number;
  glow: number;
  brightness: number;
  variation: number;
  grain: number;
  quality: number;
  mouseInteraction: boolean;
  mouseStrength: number;
  intro: boolean;
  fade: number;
  opacity: number;
  lightMode: boolean;
  paused: boolean;
  dpr?: number;
};

type Program = { program: WebGLProgram; uniforms: Record<string, WebGLUniformLocation | null> };

const QUAD_VERTEX = `#version 300 es
in vec2 aPosition;
void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

const FIELD = `#version 300 es
precision highp float;
uniform vec2 uView;
uniform vec2 uScale;
uniform vec2 uTurn;
uniform float uTime;
uniform float uWidth;
uniform float uWave;
uniform float uDepth;
uniform float uRough;
uniform float uSeed;
uniform float uTwist;
uniform vec3 uLight;
uniform float uFill;
uniform float uCamera;
uniform vec4 uPointer;
out vec4 outColor;

const float PI = 3.141592653589793;

vec4 permute(vec4 x) {
  return mod(((x * 34.0) + 1.0) * x, 289.0);
}

vec4 taylorInvSqrt(vec4 r) {
  return 1.79284291400159 - 0.85373472095314 * r;
}

vec3 fade(vec3 t) {
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

float cnoise(vec3 P) {
  vec3 Pi0 = floor(P);
  vec3 Pi1 = Pi0 + vec3(1.0);
  Pi0 = mod(Pi0, 289.0);
  Pi1 = mod(Pi1, 289.0);
  vec3 Pf0 = fract(P);
  vec3 Pf1 = Pf0 - vec3(1.0);
  vec4 ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
  vec4 iy = vec4(Pi0.yy, Pi1.yy);
  vec4 iz0 = Pi0.zzzz;
  vec4 iz1 = Pi1.zzzz;
  vec4 ixy = permute(permute(ix) + iy);
  vec4 ixy0 = permute(ixy + iz0);
  vec4 ixy1 = permute(ixy + iz1);
  vec4 gx0 = ixy0 / 7.0;
  vec4 gy0 = fract(floor(gx0) / 7.0) - 0.5;
  gx0 = fract(gx0);
  vec4 gz0 = vec4(0.5) - abs(gx0) - abs(gy0);
  vec4 sz0 = step(gz0, vec4(0.0));
  gx0 -= sz0 * (step(0.0, gx0) - 0.5);
  gy0 -= sz0 * (step(0.0, gy0) - 0.5);
  vec4 gx1 = ixy1 / 7.0;
  vec4 gy1 = fract(floor(gx1) / 7.0) - 0.5;
  gx1 = fract(gx1);
  vec4 gz1 = vec4(0.5) - abs(gx1) - abs(gy1);
  vec4 sz1 = step(gz1, vec4(0.0));
  gx1 -= sz1 * (step(0.0, gx1) - 0.5);
  gy1 -= sz1 * (step(0.0, gy1) - 0.5);
  vec3 g000 = vec3(gx0.x, gy0.x, gz0.x);
  vec3 g100 = vec3(gx0.y, gy0.y, gz0.y);
  vec3 g010 = vec3(gx0.z, gy0.z, gz0.z);
  vec3 g110 = vec3(gx0.w, gy0.w, gz0.w);
  vec3 g001 = vec3(gx1.x, gy1.x, gz1.x);
  vec3 g101 = vec3(gx1.y, gy1.y, gz1.y);
  vec3 g011 = vec3(gx1.z, gy1.z, gz1.z);
  vec3 g111 = vec3(gx1.w, gy1.w, gz1.w);
  vec4 norm0 = taylorInvSqrt(vec4(dot(g000, g000), dot(g010, g010), dot(g100, g100), dot(g110, g110)));
  g000 *= norm0.x;
  g010 *= norm0.y;
  g100 *= norm0.z;
  g110 *= norm0.w;
  vec4 norm1 = taylorInvSqrt(vec4(dot(g001, g001), dot(g011, g011), dot(g101, g101), dot(g111, g111)));
  g001 *= norm1.x;
  g011 *= norm1.y;
  g101 *= norm1.z;
  g111 *= norm1.w;
  float n000 = dot(g000, Pf0);
  float n100 = dot(g100, vec3(Pf1.x, Pf0.yz));
  float n010 = dot(g010, vec3(Pf0.x, Pf1.y, Pf0.z));
  float n110 = dot(g110, vec3(Pf1.xy, Pf0.z));
  float n001 = dot(g001, vec3(Pf0.xy, Pf1.z));
  float n101 = dot(g101, vec3(Pf1.x, Pf0.y, Pf1.z));
  float n011 = dot(g011, vec3(Pf0.x, Pf1.yz));
  float n111 = dot(g111, Pf1);
  vec3 fade_xyz = fade(Pf0);
  vec4 n_z = mix(vec4(n000, n100, n010, n110), vec4(n001, n101, n011, n111), fade_xyz.z);
  vec2 n_yz = mix(n_z.xy, n_z.zw, fade_xyz.y);
  float n_xyz = mix(n_yz.x, n_yz.y, fade_xyz.x);
  return 2.2 * n_xyz;
}

float laneHash(float lane) {
  return fract(sin(lane * 91.3458 + uSeed * 17.17) * 47453.5453);
}

float lobe(float nh, float nl, float nv, float vh, float roughness) {
  float a = roughness * roughness;
  float a2 = a * a;
  float d = nh * nh * (a2 - 1.0) + 1.0;
  float distribution = a2 / (PI * d * d);
  float gv = nl * sqrt(nv * nv * (1.0 - a2) + a2);
  float gl = nv * sqrt(nl * nl * (1.0 - a2) + a2);
  float visibility = 0.5 / max(gv + gl, 0.0001);
  float fresnel = 0.028 + 0.972 * pow(1.0 - vh, 5.0);
  return distribution * visibility * fresnel * nl;
}

vec2 glint(float lane, vec2 local) {
  float along = local.y / uWave - laneHash(lane) * 60.0;
  float step = 0.01;
  float slope = (cnoise(vec3(0.0, along + step, uTime)) - cnoise(vec3(0.0, along - step, uTime))) / (2.0 * step);
  slope *= 0.2 * uDepth;
  float spin = laneHash(lane + 0.37);
  float tilt = ((spin - 0.5) * 0.5 + sin(uTime * 2.1 + spin * 6.2831) * 0.06) * uTwist;
  vec3 normal = normalize(vec3(tilt, -slope, 1.0));
  vec3 view = normalize(vec3(-local, uCamera));
  float nv = max(dot(normal, view), 0.0001);
  vec3 light = normalize(uLight);
  vec3 halfway = normalize(light + view);
  float core = lobe(max(dot(normal, halfway), 0.0), max(dot(normal, light), 0.0), nv, max(dot(view, halfway), 0.0), uRough);
  vec3 fill = normalize(vec3(0.0, -uLight.y * 1.25, uLight.z));
  vec3 fillHalf = normalize(fill + view);
  core += uFill * lobe(max(dot(normal, fillHalf), 0.0), max(dot(normal, fill), 0.0), nv, max(dot(view, fillHalf), 0.0), uRough);
  return vec2(core, core);
}

void main() {
  vec2 css = gl_FragCoord.xy * uScale;
  vec2 centered = css - uView * 0.5;
  vec2 local = mat2(uTurn.x, -uTurn.y, uTurn.y, uTurn.x) * centered;

  float across = local.x / uWidth + 0.5;
  float lane = floor(across);
  float u = across - lane;
  vec2 value = glint(lane, local);

  float pixel = max(uScale.x, uScale.y);
  float seam = min(u, 1.0 - u) * uWidth;
  if (seam < pixel * 1.5) {
    float other = u < 0.5 ? lane - 1.0 : lane + 1.0;
    float blend = 0.5 * (1.0 - smoothstep(0.0, pixel * 1.5, seam));
    value = mix(value, glint(other, local), blend);
  }

  vec2 toPointer = css - uPointer.xy;
  float near = exp(-dot(toPointer, toPointer) / (2.0 * uPointer.w * uPointer.w)) * uPointer.z;
  value *= 1.0 + near * 0.8;
  float hot = max(value.y - 0.18, 0.0);
  outColor = vec4(value.x, value.y, min(hot, 6.0), 1.0);
}`;

const COMPOSITE = `#version 300 es
precision highp float;
uniform sampler2D uField;
uniform vec2 uResolution;
uniform vec3 uColor;
uniform vec3 uInk;
uniform float uGain;
uniform float uGlow;
uniform float uPresence;
uniform float uGrain;
uniform float uFade;
uniform float uOpacity;
uniform float uLightMode;
out vec4 outColor;

float random(vec2 st) {
  return fract(sin(dot(st, vec2(12.9898, 78.233))) * 43758.5453123);
}

float grainNoise(vec2 st) {
  vec2 i = floor(st);
  vec2 f = fract(st);
  float a = random(i);
  float b = random(i + vec2(1.0, 0.0));
  float c = random(i + vec2(0.0, 1.0));
  float d = random(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

vec3 acesFilmic(vec3 color) {
  const mat3 inputMatrix = mat3(
    vec3(0.59719, 0.07600, 0.02840),
    vec3(0.35458, 0.90834, 0.13383),
    vec3(0.04823, 0.01566, 0.83777)
  );
  const mat3 outputMatrix = mat3(
    vec3(1.60475, -0.10208, -0.00327),
    vec3(-0.53108, 1.10813, -0.07276),
    vec3(-0.07367, -0.00605, 1.07602)
  );
  color = inputMatrix * (color / 0.6);
  vec3 a = color * (color + 0.0245786) - 0.000090537;
  vec3 b = color * (0.983729 * color + 0.4329510) + 0.238081;
  color = outputMatrix * (a / b);
  return clamp(color, 0.0, 1.0);
}

vec3 toSrgb(vec3 color) {
  return mix(color * 12.92, 1.055 * pow(color, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), color));
}

float feather(float x, float edge) {
  float t = clamp(x / max(edge, 0.0001), 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

void main() {
  vec2 uv = gl_FragCoord.xy / uResolution;
  float radiance = textureLod(uField, uv, 0.0).r;
  float bloom = 0.0;
  bloom += textureLod(uField, uv, 2.0).b * 0.3;
  bloom += textureLod(uField, uv, 3.0).b * 0.3;
  bloom += textureLod(uField, uv, 4.0).b * 0.22;
  bloom += textureLod(uField, uv, 5.0).b * 0.18;

  float hot = textureLod(uField, uv, 0.0).g;
  vec3 light = uColor * (radiance + bloom * uGlow) * uGain;
  light += mix(uColor, vec3(1.0), 0.7) * hot * hot * 0.12 * uGain;
  light *= uPresence;
  vec3 color = toSrgb(acesFilmic(light));
  color -= grainNoise(gl_FragCoord.xy) / 15.0 * uGrain;
  color = max(color, 0.0);

  float edge = uFade * 0.5;
  float mask = feather(uv.x, edge) * feather(1.0 - uv.x, edge) * feather(uv.y, edge) * feather(1.0 - uv.y, edge);
  mask *= uOpacity;
  float dither = (random(gl_FragCoord.yx + 31.7) - 0.5) / 255.0;

  float peak = max(color.r, max(color.g, color.b));
  if (uLightMode > 0.5) {
    float alpha = clamp(peak * 0.9 + dither, 0.0, 1.0) * mask;
    outColor = vec4(uInk * alpha, alpha);
  } else {
    color = clamp(color + dither, 0.0, 1.0) * mask;
    outColor = vec4(color, max(color.r, max(color.g, color.b)));
  }
}`;

const INTRO_SECONDS = 1.6;
const MAX_FIELD_PIXELS = 1600000;

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const compile = (gl: WebGL2RenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
};

const link = (gl: WebGL2RenderingContext, fragmentSource: string): Program | null => {
  const vertex = compile(gl, gl.VERTEX_SHADER, QUAD_VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, fragmentSource);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.bindAttribLocation(program, 0, 'aPosition');
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  const uniforms: Record<string, WebGLUniformLocation | null> = {};
  const count = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < count; i++) {
    const info = gl.getActiveUniform(program, i);
    if (info) uniforms[info.name] = gl.getUniformLocation(program, info.name);
  }
  return { program, uniforms };
};

export const Beams = ({
  color = '#ffffff',
  beamWidth = 140,
  rotation = 30,
  speed = 1,
  waveLength = 233,
  depth = 1,
  sharpness = 0.6,
  twist = 0,
  fillLight = 0.3,
  glow = 0.6,
  brightness = 1.6,
  variation = 0,
  grain = 0.35,
  quality = 0.75,
  mouseInteraction = true,
  mouseStrength = 1,
  intro = true,
  fade = 0,
  opacity = 1,
  lightMode = false,
  backgroundColor,
  paused = false,
  dpr,
  className = '',
  style,
  ...rest
}: BeamsProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wakeRef = useRef<(() => void) | null>(null);
  const settings: Settings = {
    color: String(color),
    beamWidth: Math.max(8, beamWidth),
    rotation,
    speed,
    waveLength: Math.max(20, waveLength),
    depth: Math.max(0, depth),
    sharpness: clamp(sharpness, 0, 1),
    twist: clamp(twist, 0, 2),
    fillLight: clamp(fillLight, 0, 1.5),
    glow: Math.max(0, glow),
    brightness: Math.max(0, brightness),
    variation: Number(variation) || 0,
    grain: Math.max(0, grain),
    quality: clamp(quality, 0.25, 1),
    mouseInteraction,
    mouseStrength: Math.max(0, mouseStrength),
    intro,
    fade: clamp(fade, 0, 1),
    opacity: clamp(opacity, 0, 1),
    lightMode,
    paused,
    dpr
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    const gl = canvas?.getContext('webgl2', {
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      powerPreference: 'high-performance'
    });
    if (!container || !canvas || !gl) return undefined;

    const floatTargets = !!gl.getExtension('EXT_color_buffer_float');
    const fieldProgram = link(gl, FIELD);
    const compositeProgram = link(gl, COMPOSITE);
    if (!fieldProgram || !compositeProgram) return undefined;

    const buffer = gl.createBuffer();
    const vao = gl.createVertexArray();
    gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

    let texture: WebGLTexture | null = null;
    const framebuffer = gl.createFramebuffer();
    const target = { width: 0, height: 0 };
    const sizeTarget = (width: number, height: number) => {
      if (target.width === width && target.height === height) return;
      target.width = width;
      target.height = height;
      if (texture) gl.deleteTexture(texture);
      texture = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, texture);
      const levels = Math.floor(Math.log2(Math.max(width, height))) + 1;
      gl.texStorage2D(gl.TEXTURE_2D, levels, floatTargets ? gl.RGBA16F : gl.RGBA8, width, height);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0);
    };

    const probe = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const colorCache = new Map<string, number[]>();
    const toLinear = (value: string): number[] => {
      const cached = colorCache.get(value);
      if (cached) return cached;
      let rgb = [1, 1, 1];
      if (probe) {
        probe.clearRect(0, 0, 1, 1);
        probe.fillStyle = '#ffffff';
        probe.fillStyle = value;
        probe.fillRect(0, 0, 1, 1);
        const [r, g, b] = probe.getImageData(0, 0, 1, 1).data;
        rgb = [r, g, b].map(v => Math.pow(v / 255, 2.2));
      }
      colorCache.set(value, rgb);
      return rgb;
    };

    const view = { width: 1, height: 1, fieldWidth: 1, fieldHeight: 1 };
    const pointer = { x: 0, y: 0, inside: false };
    const state = {
      clock: 0,
      intro: settingsRef.current.intro && !reduce ? 0 : 1,
      reach: 0,
      x: 0,
      y: 0,
      lightY: 0
    };
    let raf = 0;
    let last = 0;
    let visible = true;

    const render = () => {
      const s = settingsRef.current;
      const presence = state.intro * state.intro * state.intro * (state.intro * (state.intro * 6 - 15) + 10);
      gl.bindVertexArray(vao);
      sizeTarget(view.fieldWidth, view.fieldHeight);

      const angle = (s.rotation * Math.PI) / 180;
      const sweep = (1 - presence) * -9;
      const reach = state.reach * s.mouseStrength;
      const f = fieldProgram.uniforms;
      gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
      gl.viewport(0, 0, target.width, target.height);
      gl.useProgram(fieldProgram.program);
      gl.uniform2f(f.uView, view.width, view.height);
      gl.uniform2f(f.uScale, view.width / target.width, view.height / target.height);
      gl.uniform2f(f.uTurn, Math.cos(angle), Math.sin(angle));
      gl.uniform1f(f.uTime, (state.clock * 0.12) % 289);
      gl.uniform1f(f.uWidth, s.beamWidth);
      gl.uniform1f(f.uWave, s.waveLength);
      gl.uniform1f(f.uDepth, s.depth);
      gl.uniform1f(f.uRough, 0.55 - s.sharpness * 0.5);
      gl.uniform1f(f.uSeed, s.variation);
      gl.uniform1f(f.uTwist, s.twist);
      gl.uniform1f(f.uFill, s.fillLight);
      gl.uniform3f(f.uLight, 0, 3 + sweep + state.lightY * reach, 10);
      gl.uniform1f(f.uCamera, view.height * 1.866);
      gl.uniform4f(f.uPointer, state.x, view.height - state.y, reach, Math.max(view.height, view.width) * 0.28);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.generateMipmap(gl.TEXTURE_2D);

      const c = compositeProgram.uniforms;
      const tint = toLinear(s.color);
      const tone = 0.2126 * tint[0] + 0.7152 * tint[1] + 0.0722 * tint[2];
      const shadeDepth = Math.min(1, 0.18 / Math.max(tone, 0.001));
      const ink = tint.map(v => Math.pow(Math.min(1, v * shadeDepth), 1 / 2.2));
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.useProgram(compositeProgram.program);
      gl.uniform2f(c.uResolution, canvas.width, canvas.height);
      gl.uniform3fv(c.uColor, tint);
      gl.uniform3fv(c.uInk, ink);
      gl.uniform1f(c.uGain, s.brightness);
      gl.uniform1f(c.uGlow, s.glow);
      gl.uniform1f(c.uPresence, presence);
      gl.uniform1f(c.uGrain, s.grain * 1.75);
      gl.uniform1f(c.uFade, s.fade);
      gl.uniform1f(c.uOpacity, s.opacity);
      gl.uniform1f(c.uLightMode, s.lightMode ? 1 : 0);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.uniform1i(c.uField, 0);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    };

    const frame = (now: number) => {
      raf = 0;
      if (!visible || document.hidden) return;
      const s = settingsRef.current;
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;
      const moving = !s.paused && !reduce;
      if (moving) state.clock += dt * s.speed;
      if (!s.intro || reduce) state.intro = 1;
      else if (state.intro < 1) state.intro = Math.min(1, state.intro + dt / INTRO_SECONDS);

      const engaged = s.mouseInteraction && pointer.inside && !reduce;
      if (engaged && state.reach < 0.01) {
        state.x = pointer.x;
        state.y = pointer.y;
      }
      const follow = 1 - Math.exp(-dt * 7);
      state.x += (pointer.x - state.x) * follow;
      state.y += (pointer.y - state.y) * follow;
      state.reach += ((engaged ? 1 : 0) - state.reach) * (1 - Math.exp(-dt * (engaged ? 3.2 : 1.8)));
      const turn = (s.rotation * Math.PI) / 180;
      const offsetX = state.x - view.width / 2;
      const offsetY = view.height / 2 - state.y;
      const along = -Math.sin(turn) * offsetX + Math.cos(turn) * offsetY;
      state.lightY = clamp((along / (view.height * 0.5)) * 3, -4, 4);
      render();

      const settling =
        state.intro < 1 ||
        Math.abs((engaged ? 1 : 0) - state.reach) > 0.002 ||
        Math.abs(pointer.x - state.x) + Math.abs(pointer.y - state.y) > 0.3;
      if (moving || settling) raf = requestAnimationFrame(frame);
      else last = 0;
    };

    const wake = () => {
      if (!raf && visible && !document.hidden) raf = requestAnimationFrame(frame);
    };

    const resize = () => {
      const s = settingsRef.current;
      const width = Math.max(1, container.clientWidth);
      const height = Math.max(1, container.clientHeight);
      const ratio = Math.min(s.dpr || window.devicePixelRatio || 1, 2);
      view.width = width;
      view.height = height;
      canvas.width = Math.max(1, Math.round(width * ratio));
      canvas.height = Math.max(1, Math.round(height * ratio));
      let fieldScale = s.quality * ratio;
      if (width * height * fieldScale * fieldScale > MAX_FIELD_PIXELS) {
        fieldScale = Math.sqrt(MAX_FIELD_PIXELS / (width * height));
      }
      view.fieldWidth = Math.max(1, Math.round(width * fieldScale));
      view.fieldHeight = Math.max(1, Math.round(height * fieldScale));
      if (!raf) render();
      wake();
    };

    const onPointerMove = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      pointer.x = event.clientX - rect.left;
      pointer.y = event.clientY - rect.top;
      pointer.inside = pointer.x >= 0 && pointer.y >= 0 && pointer.x <= rect.width && pointer.y <= rect.height;
      wake();
    };

    const onPointerLeave = () => {
      pointer.inside = false;
      wake();
    };

    const onVisibility = () => {
      last = 0;
      wake();
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(container);
    const intersection = new IntersectionObserver(entries => {
      visible = entries.some(entry => entry.isIntersecting);
      if (visible) {
        last = 0;
        wake();
      }
    });
    intersection.observe(container);
    window.addEventListener('pointermove', onPointerMove, { passive: true });
    document.documentElement.addEventListener('pointerleave', onPointerLeave);
    document.addEventListener('visibilitychange', onVisibility);
    resize();

    let lastQuality = settingsRef.current.quality;
    let lastDpr = settingsRef.current.dpr;
    wakeRef.current = () => {
      const s = settingsRef.current;
      if (s.quality !== lastQuality || s.dpr !== lastDpr) {
        lastQuality = s.quality;
        lastDpr = s.dpr;
        resize();
        return;
      }
      if (!raf) render();
      wake();
    };

    return () => {
      cancelAnimationFrame(raf);
      wakeRef.current = null;
      resizeObserver.disconnect();
      intersection.disconnect();
      window.removeEventListener('pointermove', onPointerMove);
      document.documentElement.removeEventListener('pointerleave', onPointerLeave);
      document.removeEventListener('visibilitychange', onVisibility);
      if (texture) gl.deleteTexture(texture);
      gl.deleteFramebuffer(framebuffer);
      gl.deleteProgram(fieldProgram.program);
      gl.deleteProgram(compositeProgram.program);
      gl.deleteBuffer(buffer);
      gl.deleteVertexArray(vao);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    };
  }, []);

  useEffect(() => {
    wakeRef.current?.();
  });

  return (
    <div
      ref={containerRef}
      className={['relative h-full w-full overflow-hidden', className].filter(Boolean).join(' ')}
      style={backgroundColor ? { background: backgroundColor, ...style } : style}
      {...rest}
    >
      <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full" aria-hidden="true" />
    </div>
  );
};

export default Beams;

'use client';

import { useEffect, useMemo, useRef, type CSSProperties } from 'react';

export interface CRTWarpProps {
  color?: string;
  backgroundColor?: string;
  lightMode?: boolean;
  speed?: number;
  variation?: number;
  waveAmplitude?: number;
  waveFrequency?: number;
  levels?: number;
  columns?: number;
  persistence?: number;
  curvature?: number;
  corners?: number;
  scanlineStrength?: number;
  scanlineFrequency?: number;
  mask?: 'aperture' | 'shadow' | 'slot' | 'none';
  maskStrength?: number;
  bloom?: number;
  bloomRadius?: number;
  rgbShift?: number;
  noise?: number;
  flicker?: number;
  interference?: number;
  vignette?: number;
  brightness?: number;
  intro?: boolean;
  mouseReact?: boolean;
  mouseStrength?: number;
  changeOnClick?: boolean;
  dpr?: number;
  fps?: number;
  paused?: boolean;
  className?: string;
  style?: CSSProperties;
}

type RGB = [number, number, number];

interface Program {
  program: WebGLProgram;
  uniforms: Record<string, WebGLUniformLocation | null>;
}

interface Target {
  texture: WebGLTexture;
  framebuffer: WebGLFramebuffer;
  width: number;
  height: number;
}

const ROOT = 'relative h-full w-full overflow-hidden';
const CANVAS = 'absolute inset-0 block h-full w-full';

const MASKS: Record<string, number> = { none: 0, aperture: 1, shadow: 2, slot: 3 };
const CELL_ASPECT = 0.56;
const INTRO_SECONDS = 1.6;
const FLIP_SECONDS = 0.8;
const TAU = Math.PI * 2;

const VERTEX = `#version 300 es
in vec2 aPosition;
void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

const CONTENT = `#version 300 es
precision highp float;
uniform vec2 uGrid;
uniform float uTime;
uniform float uAmplitude;
uniform float uFrequency;
uniform float uLevels;
uniform float uDecay;
uniform float uReveal;
uniform float uRise;
uniform vec4 uSeed;
uniform sampler2D uPrevious;
out vec4 outColor;

float field(vec2 uv, float t) {
  uv = (uv - 0.5) * uFrequency + 0.5;
  float f = 0.0;
  f += 0.7 * sin(0.5 * uv.x + t / 5.0 + uSeed.x);
  f += 3.0 * sin(1.6 * uv.y + t / 5.0 + uSeed.y);
  f += sin(10.0 * (uv.y * sin(t / 2.0 + uSeed.z) + uv.x * cos(t / 5.0)) + t / 2.0);
  float cx = uv.x + 0.5 * sin(t / 2.0 + uSeed.w);
  float cy = uv.y + 0.5 * cos(t / 4.0 + uSeed.x * 0.7);
  f += 0.4 * sin(sqrt(100.0 * cx * cx + 100.0 * cy * cy + 1.0) + t);
  f += 0.9 * sin(sqrt(75.0 * cx * cx + 25.0 * cy * cy + 1.0) + t);
  f -= 1.4 * sin(sqrt(256.0 * cx * cx + 25.0 * cy * cy + 1.0) + t);
  f += 0.3 * sin(0.5 * uv.y + uv.x + sin(t));
  return f;
}

void main() {
  vec2 cell = floor(gl_FragCoord.xy);
  vec2 uv = (cell + 0.5) / uGrid;
  float s = (0.5 + 0.499 * sin(field(uv, uTime) * uAmplitude)) * mix(1.0 / uLevels, 1.0, uReveal);
  float level = floor(s * uLevels) / max(uLevels - 1.0, 1.0);
  float previous = texelFetch(uPrevious, ivec2(cell), 0).r;
  float lifted = min(level, previous + uRise);
  outColor = vec4(max(lifted, previous * uDecay - 0.004), level, 0.0, 1.0);
}`;

const GLOW = `#version 300 es
precision highp float;
uniform sampler2D uContent;
uniform vec2 uSize;
out vec4 outColor;

void main() {
  float v = texture(uContent, gl_FragCoord.xy / uSize).r;
  outColor = vec4(v * v, 0.0, 0.0, 1.0);
}`;

const BLUR = `#version 300 es
precision highp float;
uniform sampler2D uSource;
uniform vec2 uSize;
uniform vec2 uDirection;
uniform float uSigma;
out vec4 outColor;

void main() {
  vec2 uv = gl_FragCoord.xy / uSize;
  float stride = max(uSigma * 0.55, 0.5);
  float total = 0.0;
  float sum = 0.0;
  for (int i = -7; i <= 7; i++) {
    float x = float(i) * stride;
    float w = exp(-0.5 * x * x / (uSigma * uSigma));
    sum += texture(uSource, uv + uDirection * x / uSize).r * w;
    total += w;
  }
  outColor = vec4(sum / total, 0.0, 0.0, 1.0);
}`;

const DISPLAY = `#version 300 es
precision highp float;
uniform sampler2D uContent;
uniform sampler2D uGlow;
uniform vec2 uGrid;
uniform vec2 uResolution;
uniform float uPixel;
uniform float uTime;
uniform vec3 uColor;
uniform vec3 uBackground;
uniform float uOpaque;
uniform float uLight;
uniform float uLines;
uniform float uScanline;
uniform float uCurve;
uniform float uCorners;
uniform int uMaskType;
uniform float uMask;
uniform float uBloom;
uniform float uBrightness;
uniform float uNoise;
uniform float uFlicker;
uniform float uInterference;
uniform float uVignette;
uniform float uShift;
uniform float uWarm;
uniform float uFocus;
uniform float uStatic;
uniform float uRoll;
uniform float uTear;
uniform float uGain;
uniform vec4 uMagnet;
uniform float uPurity;
out vec4 outColor;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

vec2 curve(vec2 uv) {
  if (uCurve <= 0.0) return uv;
  vec2 p = (uv - 0.5) * 2.0;
  float corner = uCurve / sqrt(max(uCurve * uCurve - 2.0, 0.001));
  p = uCurve * p / sqrt(max(uCurve * uCurve - dot(p, p), 0.001));
  p /= corner;
  return p * 0.5 + 0.5;
}

float lineValue(float x, float y) {
  if (x < 0.0 || x > 1.0 || y < 0.0 || y > 1.0) return 0.0;
  float cx = x * uGrid.x - 0.5;
  float c0 = floor(cx);
  int row = int(clamp(floor(y * uGrid.y), 0.0, uGrid.y - 1.0));
  float a = texelFetch(uContent, ivec2(int(clamp(c0, 0.0, uGrid.x - 1.0)), row), 0).r;
  float b = texelFetch(uContent, ivec2(int(clamp(c0 + 1.0, 0.0, uGrid.x - 1.0)), row), 0).r;
  float soft = mix(0.5, 0.14, uFocus);
  return pow(mix(a, b, smoothstep(0.5 - soft, 0.5 + soft, cx - c0)), 1.25);
}

float beam(vec2 uv) {
  float ly = uv.y * uLines - 0.5;
  float r0 = floor(ly);
  float f = ly - r0;
  float a = lineValue(uv.x, (r0 + 0.5) / uLines);
  float b = lineValue(uv.x, (r0 + 1.5) / uLines);
  float nearest = f < 0.5 ? a : b;
  float sa = mix(0.16, 0.34, sqrt(a));
  float sb = mix(0.16, 0.34, sqrt(b));
  float lit = a * exp(-0.5 * f * f / (sa * sa)) + b * exp(-0.5 * (1.0 - f) * (1.0 - f) / (sb * sb));
  return mix(nearest, lit * 1.18, uScanline * mix(0.3, 1.0, uFocus));
}

vec3 maskAt(vec2 px) {
  if (uMaskType == 0 || uMask <= 0.0) return vec3(1.0);
  float size = max(1.0, floor(uPixel + 0.5));
  vec2 q = floor(px / size);
  float low = 1.0 - uMask;
  vec3 m = vec3(low);
  float column = q.x;
  if (uMaskType == 2) column += mod(floor(q.y / 2.0), 2.0) * 1.5;
  int stripe = int(mod(floor(column), 3.0));
  if (stripe == 0) m.r = 1.0;
  else if (stripe == 1) m.g = 1.0;
  else m.b = 1.0;
  if (uMaskType == 2 && mod(q.y, 2.0) > 0.5) m *= mix(1.0, 0.72, uMask);
  if (uMaskType == 3) {
    float slot = mod(q.y + mod(floor(q.x / 3.0), 2.0) * 2.0, 4.0);
    if (slot < 1.0) m *= mix(1.0, 0.45, uMask);
  }
  return m / sqrt((1.0 + 2.0 * low) / 3.0);
}

vec3 phosphor(vec3 cov) {
  float peak = max(max(uColor.r, uColor.g), max(uColor.b, 0.001));
  vec3 weight = 1.0 - uColor / peak;
  return uColor * cov * pow(max(cov, vec3(0.0001)), 0.7 * weight);
}

void main() {
  vec2 frag = gl_FragCoord.xy / uResolution;
  float aspect = uResolution.x / uResolution.y;
  vec2 uv = curve(frag);
  float shape = 1.0;
  if (uCorners > 0.0) {
    float margin = uCorners * 0.035;
    float radius = uCorners * 0.1;
    vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
    vec2 box = (0.5 - margin) * vec2(aspect, 1.0);
    vec2 q = abs(p) - box + radius;
    float sd = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - radius;
    float aa = max(fwidth(sd), 0.0005);
    shape = (1.0 - smoothstep(-aa, aa, sd)) * mix(1.0, smoothstep(0.0, 0.06, -sd), 0.35);
    uv = (uv - 0.5) / (1.0 - 2.0 * margin) + 0.5;
  }
  float rolling = step(0.0001, abs(uRoll));
  uv.y += uRoll;
  float wrapped = fract(uv.y);
  uv.y = mix(uv.y, wrapped, rolling);
  float offset = fract(uRoll);
  float reach = smoothstep(0.0, 0.08, min(offset, 1.0 - offset));
  float blank = mix(1.0, smoothstep(0.0, 0.05, wrapped) * smoothstep(1.0, 0.95, wrapped), rolling * reach);

  float line = floor(uv.y * uLines);
  float tick = floor(uTime * 30.0);
  uv.x += uTear * (sin(uv.y * 21.0 + uTime * 37.0) * 0.6 + hash(vec2(line, tick)) - 0.5) * 0.05;
  uv.x += uInterference * 0.003 * (hash(vec2(line * 0.37, floor(uTime * 24.0))) - 0.5);

  vec2 dp = (frag - uMagnet.xy) * vec2(aspect, 1.0);
  float fall = exp(-dot(dp, dp) / max(uMagnet.w * uMagnet.w, 0.0001));
  vec2 swirl = vec2(-dp.y, dp.x) / vec2(aspect, 1.0) * fall * uMagnet.z * 0.5;
  vec3 spread = mix(vec3(0.85), vec3(1.0, 0.6, 0.2), uPurity);

  vec3 level = vec3(
    beam(uv + swirl * spread.r + vec2(uShift, 0.0)),
    beam(uv + swirl * spread.g),
    beam(uv + swirl * spread.b - vec2(uShift, 0.0))
  );

  float turn = uTime * 0.35;
  vec2 axis = vec2(cos(turn), sin(turn));
  float lobe = dot(dp, axis) / max(uMagnet.w, 0.0001);
  float side = dot(dp, vec2(-axis.y, axis.x)) / max(uMagnet.w, 0.0001);
  vec3 purity = vec3(lobe, -0.35 * lobe + 0.6 * side, -lobe);
  level *= 1.0 + uPurity * fall * uMagnet.z * 0.9 * purity;

  float glow = texture(uGlow, uv).r * uBloom;
  float hum = 1.0 - uInterference * 0.24 * smoothstep(0.2, 1.0, 0.5 + 0.5 * sin((frag.y - uTime * 0.09) * 6.2831853));
  float flick = 1.0 + uFlicker * 0.1 * (hash(vec2(floor(uTime * 60.0), 7.3)) - 0.5);
  float grain = hash(gl_FragCoord.xy + fract(uTime) * 173.0) - 0.5;
  vec2 v = frag - 0.5;
  float vignette = mix(1.0, smoothstep(0.0, 1.0, clamp(1.0 - dot(v, v) * 2.0, 0.0, 1.0)), uVignette);
  float gain = uBrightness * hum * flick * vignette * blank * uGain * uWarm;

  float noise = hash(floor(gl_FragCoord.xy / (uPixel * 1.5)) + fract(uTime * 13.7) * 91.0);
  level = mix(level, vec3(noise * noise * 1.15), uStatic);
  level *= gain * (1.0 + grain * uNoise * 2.0);
  level *= maskAt(gl_FragCoord.xy);
  glow *= gain * shape * (1.0 + 0.6 * (1.0 - uFocus));
  level *= shape;

  vec3 color;
  float alpha;
  if (uLight < 0.5) {
    vec3 cov = clamp(level, 0.0, 1.0);
    vec3 light = phosphor(cov) + uColor * glow * 0.5 * (1.0 - cov);
    vec3 excess = max(level - 1.1, 0.0);
    light += (1.0 - light) * (1.0 - exp(-excess * 0.6));
    light = clamp(light, 0.0, 1.0);
    color = uBackground + light * (1.0 - uBackground);
    alpha = max(max(light.r, light.g), light.b);
    if (uOpaque < 0.5) color = light;
  } else {
    vec3 cov = clamp(level * 0.86, 0.0, 0.88);
    cov += clamp(glow * 0.12, 0.0, 0.2) * (1.0 - cov);
    color = mix(uBackground, uColor, cov);
    alpha = max(max(cov.r, cov.g), cov.b);
    if (uOpaque < 0.5) color = uColor * cov;
  }
  outColor = uOpaque > 0.5 ? vec4(color, 1.0) : vec4(color, alpha);
}`;

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const smooth = (t: number) => t * t * (3 - 2 * t);

const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2);

let probe: CanvasRenderingContext2D | null = null;

const parseColor = (value: string, fallback: RGB | null): RGB | null => {
  if (value === 'transparent') return null;
  if (typeof document === 'undefined') return fallback;
  if (!probe) probe = document.createElement('canvas').getContext('2d');
  if (!probe) return fallback;
  probe.fillStyle = '#000000';
  probe.fillStyle = value;
  const text = probe.fillStyle;
  if (text.startsWith('#')) {
    const hex = parseInt(text.slice(1), 16);
    return [((hex >> 16) & 255) / 255, ((hex >> 8) & 255) / 255, (hex & 255) / 255];
  }
  const match = /rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)(?:,\s*([\d.]+))?/.exec(text);
  if (!match) return fallback;
  if (match[4] !== undefined && Number(match[4]) === 0) return null;
  return [Number(match[1]) / 255, Number(match[2]) / 255, Number(match[3]) / 255];
};

const seedFor = (channel: number) => {
  const a = Math.sin(channel * 12.9898 + 1.7) * 43758.5453;
  const b = Math.sin(channel * 78.233 + 4.1) * 24634.6345;
  const c = Math.sin(channel * 37.719 + 2.9) * 17431.7731;
  const d = Math.sin(channel * 91.113 + 0.3) * 31337.1337;
  const f = (v: number) => (v - Math.floor(v)) * TAU;
  return channel === 0 ? [0, 0, 0, 0] : [f(a), f(b), f(c), f(d)];
};

const introAt = (t: number) => {
  if (t >= INTRO_SECONDS) return [1, 1, 1];
  const reveal = smooth(clamp(t / INTRO_SECONDS, 0, 1));
  const warm = smooth(clamp(t / 0.6, 0, 1));
  const focus = smooth(clamp((t - 0.15) / (INTRO_SECONDS - 0.15), 0, 1));
  return [reveal, warm, focus];
};

const compile = (gl: WebGL2RenderingContext, type: number, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
};

const createProgram = (gl: WebGL2RenderingContext, fragment: string, names: string[]): Program | null => {
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const shader = compile(gl, gl.FRAGMENT_SHADER, fragment);
  if (!vertex || !shader) return null;
  const program = gl.createProgram();
  if (!program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, shader);
  gl.bindAttribLocation(program, 0, 'aPosition');
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(shader);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  const uniforms: Record<string, WebGLUniformLocation | null> = {};
  names.forEach(name => {
    uniforms[name] = gl.getUniformLocation(program, name);
  });
  return { program, uniforms };
};

const createTarget = (gl: WebGL2RenderingContext, width: number, height: number): Target => {
  const texture = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, width, height, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  const framebuffer = gl.createFramebuffer();
  gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0);
  gl.clearColor(0, 0, 0, 1);
  gl.clear(gl.COLOR_BUFFER_BIT);
  return { texture, framebuffer, width, height };
};

const deleteTarget = (gl: WebGL2RenderingContext, target: Target | null) => {
  if (!target) return;
  gl.deleteTexture(target.texture);
  gl.deleteFramebuffer(target.framebuffer);
};

const prefersReduced = () =>
  typeof window !== 'undefined' && (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false);

export default function CRTWarp({
  color = '#c755f7',
  backgroundColor = '#120f17',
  lightMode = false,
  speed = 0.5,
  variation = 0,
  waveAmplitude = 0.3,
  waveFrequency = 2.5,
  levels = 3,
  columns = 80,
  persistence = 0.4,
  curvature = 0.25,
  corners = 0,
  scanlineStrength = 0.6,
  scanlineFrequency = 200,
  mask = 'aperture',
  maskStrength = 0.3,
  bloom = 1.5,
  bloomRadius = 1,
  rgbShift = 0.003,
  noise = 0.1,
  flicker = 0.15,
  interference = 0.2,
  vignette = 0.3,
  brightness = 1,
  intro = true,
  mouseReact = true,
  mouseStrength = 0.5,
  changeOnClick = true,
  dpr = 2,
  fps = 60,
  paused = false,
  className = '',
  style
}: CRTWarpProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const ink = useMemo((): RGB => parseColor(color, [0.78, 0.33, 0.97]) ?? [0.78, 0.33, 0.97], [color]);
  const paper = useMemo(() => parseColor(backgroundColor, [0.07, 0.06, 0.09]), [backgroundColor]);

  const settings = {
    ink,
    paper,
    lightMode,
    speed,
    variation,
    amplitude: Math.max(0, waveAmplitude) / 0.28,
    frequency: Math.max(0.01, waveFrequency) / 2.2,
    levels: clamp(Math.round(levels), 2, 12),
    columns: clamp(Math.round(columns), 8, 400),
    persistence: clamp(persistence, 0, 0.98),
    curve: curvature > 0.001 ? 1.1 + 0.42 / curvature : 0,
    corners: clamp(corners, 0, 1),
    scanline: clamp(scanlineStrength, 0, 1),
    lines: clamp(scanlineFrequency, 20, 1200),
    mask: MASKS[mask] ?? 0,
    maskStrength: clamp(maskStrength, 0, 1),
    bloom: Math.max(0, bloom),
    bloomRadius: Math.max(0.05, bloomRadius),
    rgbShift,
    noise: Math.max(0, noise),
    flicker: Math.max(0, flicker),
    interference: Math.max(0, interference),
    vignette: clamp(vignette, 0, 1),
    brightness: Math.max(0, brightness),
    intro,
    mouseReact,
    mouseStrength: Math.max(0, mouseStrength),
    changeOnClick,
    dpr: Math.max(0.5, dpr),
    fps: Math.max(1, fps),
    paused
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return undefined;
    const canvas = document.createElement('canvas');
    canvas.className = CANVAS;
    container.appendChild(canvas);
    const gl = canvas.getContext('webgl2', {
      alpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      premultipliedAlpha: true,
      powerPreference: 'high-performance'
    });
    if (!gl) {
      canvas.remove();
      return undefined;
    }

    const content = createProgram(gl, CONTENT, [
      'uGrid',
      'uTime',
      'uAmplitude',
      'uFrequency',
      'uLevels',
      'uDecay',
      'uReveal',
      'uRise',
      'uSeed',
      'uPrevious'
    ]);
    const glowSource = createProgram(gl, GLOW, ['uContent', 'uSize']);
    const blur = createProgram(gl, BLUR, ['uSource', 'uSize', 'uDirection', 'uSigma']);
    const display = createProgram(gl, DISPLAY, [
      'uContent',
      'uGlow',
      'uGrid',
      'uResolution',
      'uPixel',
      'uTime',
      'uColor',
      'uBackground',
      'uOpaque',
      'uLight',
      'uLines',
      'uScanline',
      'uCurve',
      'uCorners',
      'uMaskType',
      'uMask',
      'uBloom',
      'uBrightness',
      'uNoise',
      'uFlicker',
      'uInterference',
      'uVignette',
      'uShift',
      'uWarm',
      'uFocus',
      'uStatic',
      'uRoll',
      'uTear',
      'uGain',
      'uMagnet',
      'uPurity'
    ]);
    if (!content || !glowSource || !blur || !display) {
      canvas.remove();
      return undefined;
    }

    const vao = gl.createVertexArray();
    gl.bindVertexArray(vao);
    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

    const state = {
      width: 1,
      height: 1,
      pixel: 1,
      grid: [0, 0],
      cells: [null, null] as (Target | null)[],
      glows: [null, null] as (Target | null)[],
      flip: 0,
      time: 0,
      clock: 0,
      last: 0,
      frame: 0,
      raf: 0,
      visible: false,
      introAt: -1,
      flipAt: -1,
      flipped: true,
      channel: 0,
      pointer: [0.5, 0.5],
      magnet: [0.5, 0.5, 0, 0, 0],
      magnetGoal: 0,
      lost: false,
      quiet: 0,
      seen: null as typeof settings | null
    };

    const ensureTargets = () => {
      const s = settingsRef.current;
      const cols = s.columns;
      const rows = clamp(Math.round((cols * CELL_ASPECT * state.height) / Math.max(state.width, 1)), 4, 300);
      if (cols !== state.grid[0] || rows !== state.grid[1]) {
        state.cells.forEach(target => deleteTarget(gl, target));
        state.cells = [createTarget(gl, cols, rows), createTarget(gl, cols, rows)];
        state.grid = [cols, rows];
      }
      const gw = Math.max(1, Math.round(state.width / 4));
      const gh = Math.max(1, Math.round(state.height / 4));
      const glow = state.glows[0];
      if (!glow || glow.width !== gw || glow.height !== gh) {
        state.glows.forEach(target => deleteTarget(gl, target));
        state.glows = [createTarget(gl, gw, gh), createTarget(gl, gw, gh)];
      }
    };

    const resize = () => {
      const s = settingsRef.current;
      const ratio = Math.min(window.devicePixelRatio || 1, s.dpr);
      const width = Math.max(1, Math.round(container.clientWidth * ratio));
      const height = Math.max(1, Math.round(container.clientHeight * ratio));
      state.pixel = ratio;
      if (width === state.width && height === state.height) return;
      state.quiet = 0;
      state.width = width;
      state.height = height;
      canvas.width = width;
      canvas.height = height;
    };

    const draw = (target: Target | null, width: number, height: number) => {
      gl.bindFramebuffer(gl.FRAMEBUFFER, target ? target.framebuffer : null);
      gl.viewport(0, 0, width, height);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    };

    const bindTexture = (unit: number, texture: WebGLTexture, location: WebGLUniformLocation | null) => {
      gl.activeTexture(gl.TEXTURE0 + unit);
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.uniform1i(location, unit);
    };

    const render = (dt: number, reduced: boolean) => {
      const s = settingsRef.current;
      ensureTargets();
      const [cols, rows] = state.grid;
      const seed = seedFor(s.variation + state.channel);
      const introClock = state.introAt < 0 ? 0 : state.clock - state.introAt;
      const [reveal, warm, focus] = s.intro && !reduced ? introAt(introClock) : [1, 1, 1];

      const previous = state.cells[state.flip];
      const next = state.cells[1 - state.flip];
      const [glowA, glowB] = state.glows;
      if (!previous || !next || !glowA || !glowB) return;
      gl.useProgram(content.program);
      gl.uniform2f(content.uniforms.uGrid, cols, rows);
      gl.uniform1f(content.uniforms.uTime, state.time);
      gl.uniform1f(content.uniforms.uAmplitude, s.amplitude);
      gl.uniform1f(content.uniforms.uFrequency, s.frequency);
      gl.uniform1f(content.uniforms.uLevels, s.levels);
      gl.uniform1f(content.uniforms.uDecay, reduced ? 0 : s.persistence ** (dt * 60));
      gl.uniform1f(content.uniforms.uReveal, reveal);
      gl.uniform1f(content.uniforms.uRise, reveal < 1 ? dt / 0.22 : 1);
      gl.uniform4f(content.uniforms.uSeed, seed[0], seed[1], seed[2], seed[3]);
      bindTexture(0, previous.texture, content.uniforms.uPrevious);
      draw(next, cols, rows);
      state.flip = 1 - state.flip;

      gl.useProgram(glowSource.program);
      gl.uniform2f(glowSource.uniforms.uSize, glowA.width, glowA.height);
      bindTexture(0, next.texture, glowSource.uniforms.uContent);
      draw(glowA, glowA.width, glowA.height);
      const sigma = Math.max(0.6, (glowA.height / 48) * s.bloomRadius);
      gl.useProgram(blur.program);
      gl.uniform2f(blur.uniforms.uSize, glowA.width, glowA.height);
      gl.uniform1f(blur.uniforms.uSigma, sigma);
      gl.uniform2f(blur.uniforms.uDirection, 1, 0);
      bindTexture(0, glowA.texture, blur.uniforms.uSource);
      draw(glowB, glowB.width, glowB.height);
      gl.uniform2f(blur.uniforms.uDirection, 0, 1);
      bindTexture(0, glowB.texture, blur.uniforms.uSource);
      draw(glowA, glowA.width, glowA.height);

      let roll = 0;
      let tear = 0;
      let staticNoise = 0;
      let gain = 1;
      if (state.flipAt >= 0) {
        const t = state.clock - state.flipAt;
        if (!state.flipped && t >= 0.22) {
          state.flipped = true;
          state.channel += 1;
        }
        if (t >= FLIP_SECONDS) {
          state.flipAt = -1;
        } else {
          const p = t / FLIP_SECONDS;
          roll = easeInOut(p);
          tear = Math.sin(Math.PI * clamp(t / 0.5, 0, 1)) * 0.6;
          staticNoise = Math.sin(Math.PI * clamp(t / 0.55, 0, 1)) * 0.75;
          gain = 1 - 0.3 * Math.sin(Math.PI * p);
        }
      }

      gl.useProgram(display.program);
      const u = display.uniforms;
      bindTexture(0, next.texture, u.uContent);
      bindTexture(1, glowA.texture, u.uGlow);
      gl.uniform2f(u.uGrid, cols, rows);
      gl.uniform2f(u.uResolution, state.width, state.height);
      gl.uniform1f(u.uPixel, state.pixel);
      gl.uniform1f(u.uTime, reduced ? 0 : state.clock);
      gl.uniform3f(u.uColor, s.ink[0], s.ink[1], s.ink[2]);
      const paperColor = s.paper ?? [0, 0, 0];
      gl.uniform3f(u.uBackground, paperColor[0], paperColor[1], paperColor[2]);
      gl.uniform1f(u.uOpaque, s.paper ? 1 : 0);
      gl.uniform1f(u.uLight, s.lightMode ? 1 : 0);
      gl.uniform1f(u.uLines, s.lines);
      gl.uniform1f(u.uScanline, s.scanline);
      gl.uniform1f(u.uCurve, s.curve);
      gl.uniform1f(u.uCorners, s.corners);
      gl.uniform1i(u.uMaskType, s.mask);
      gl.uniform1f(u.uMask, s.maskStrength);
      gl.uniform1f(u.uBloom, s.bloom);
      gl.uniform1f(u.uBrightness, s.brightness);
      gl.uniform1f(u.uNoise, s.noise);
      gl.uniform1f(u.uFlicker, reduced ? 0 : s.flicker);
      gl.uniform1f(u.uInterference, s.interference);
      gl.uniform1f(u.uVignette, s.vignette);
      gl.uniform1f(u.uShift, s.rgbShift);
      gl.uniform1f(u.uWarm, warm);
      gl.uniform1f(u.uFocus, focus);
      gl.uniform1f(u.uStatic, staticNoise);
      gl.uniform1f(u.uRoll, roll);
      gl.uniform1f(u.uTear, tear);
      gl.uniform1f(u.uGain, gain);
      gl.uniform4f(u.uMagnet, state.magnet[0], 1 - state.magnet[1], state.magnet[4] * s.mouseStrength * 2, 0.24);
      gl.uniform1f(u.uPurity, s.mask > 0 ? 1 : 0);
      draw(null, state.width, state.height);
    };

    const tick = (now: number) => {
      state.raf = requestAnimationFrame(tick);
      if (!state.visible || document.hidden || state.lost) {
        state.last = now;
        return;
      }
      const s = settingsRef.current;
      const interval = 1000 / s.fps;
      if (state.last && now - state.last < interval - 1) return;
      const dt = state.last ? Math.min((now - state.last) / 1000, 0.1) : 1 / 60;
      state.last = now;
      const reduced = prefersReduced();
      state.clock += dt;
      if (state.introAt < 0) state.introAt = state.clock;
      if (!s.paused && !reduced) state.time += dt * s.speed;

      const m = state.magnet;
      const omega = TAU / 0.3;
      for (let i = 0; i < 2; i++) {
        const accel = -omega * omega * (m[i] - state.pointer[i]) - 2 * omega * m[2 + i];
        m[2 + i] += accel * dt;
        m[i] += m[2 + i] * dt;
      }
      const goal = s.mouseReact && !reduced ? state.magnetGoal : 0;
      m[4] += (goal - m[4]) * (1 - Math.exp(-dt / 0.18));

      const still = s.paused || reduced;
      const settling =
        Math.abs(m[4] - goal) > 0.002 ||
        (m[4] > 0.002 && (Math.abs(m[2]) + Math.abs(m[3]) > 0.0005 || Math.abs(m[0] - state.pointer[0]) > 0.0005));
      const transient =
        state.flipAt >= 0 || (s.intro && !reduced && state.clock - state.introAt < INTRO_SECONDS) || settling;
      if (state.seen !== s || transient || !still) state.quiet = 0;
      else state.quiet += 1;
      state.seen = s;
      if (state.quiet > 90) return;

      resize();
      render(dt, reduced);
    };

    const local = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      return {
        x: (event.clientX - rect.left) / Math.max(rect.width, 1),
        y: (event.clientY - rect.top) / Math.max(rect.height, 1),
        inside:
          event.clientX >= rect.left &&
          event.clientX <= rect.right &&
          event.clientY >= rect.top &&
          event.clientY <= rect.bottom
      };
    };

    const onMove = (event: PointerEvent) => {
      const point = local(event);
      if (point.inside) {
        if (state.magnetGoal === 0 && state.magnet[4] < 0.02) {
          state.magnet[0] = point.x;
          state.magnet[1] = point.y;
          state.magnet[2] = 0;
          state.magnet[3] = 0;
        }
        state.pointer = [point.x, point.y];
      }
      state.magnetGoal = point.inside ? 1 : 0;
    };

    const onLeave = () => {
      state.magnetGoal = 0;
    };

    const onDown = (event: PointerEvent) => {
      const s = settingsRef.current;
      if (!s.changeOnClick || event.button !== 0) return;
      if (
        event.target instanceof Element &&
        event.target.closest('a, button, input, textarea, select, label, [role="button"]')
      )
        return;
      const point = local(event);
      if (!point.inside) return;
      if (prefersReduced()) {
        state.channel += 1;
        return;
      }
      if (state.flipAt >= 0) return;
      state.flipAt = state.clock;
      state.flipped = false;
    };

    const onLost = (event: Event) => {
      event.preventDefault();
      state.lost = true;
    };

    const visibility = new IntersectionObserver(entries => {
      state.visible = entries.some(entry => entry.isIntersecting);
    });
    visibility.observe(container);
    const sizes = new ResizeObserver(resize);
    sizes.observe(container);
    resize();
    window.addEventListener('pointermove', onMove, { passive: true });
    window.addEventListener('pointerdown', onDown);
    document.documentElement.addEventListener('pointerleave', onLeave);
    canvas.addEventListener('webglcontextlost', onLost);
    state.raf = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(state.raf);
      visibility.disconnect();
      sizes.disconnect();
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerdown', onDown);
      document.documentElement.removeEventListener('pointerleave', onLeave);
      canvas.removeEventListener('webglcontextlost', onLost);
      state.cells.forEach(target => deleteTarget(gl, target));
      state.glows.forEach(target => deleteTarget(gl, target));
      [content, glowSource, blur, display].forEach(item => gl.deleteProgram(item.program));
      gl.deleteBuffer(buffer);
      gl.deleteVertexArray(vao);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
      canvas.remove();
    };
  }, []);

  return <div ref={containerRef} className={[ROOT, className].filter(Boolean).join(' ')} style={style} />;
}

'use client';

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

type ColorBendsProps = {
  className?: string;
  style?: React.CSSProperties;
  rotation?: number;
  speed?: number;
  colors?: string[];
  transparent?: boolean;
  autoRotate?: number;
  scale?: number;
  frequency?: number;
  warpStrength?: number;
  mouseInfluence?: number;
  parallax?: number;
  noise?: number;
  iterations?: number;
  intensity?: number;
  bandWidth?: number;
};

const MAX_COLORS = 8 as const;

const frag = `
#define MAX_COLORS ${MAX_COLORS}
uniform vec2 uCanvas;
uniform float uTime;
uniform float uSpeed;
uniform vec2 uRot;
uniform int uColorCount;
uniform vec3 uColors[MAX_COLORS];
uniform int uTransparent;
uniform float uScale;
uniform float uFrequency;
uniform float uWarpStrength;
uniform vec2 uPointer; // in NDC [-1,1]
uniform float uMouseInfluence;
uniform float uParallax;
uniform float uNoise;
uniform int uIterations;
uniform float uIntensity;
uniform float uBandWidth;
varying vec2 vUv;

void main() {
  float t = uTime * uSpeed;
  vec2 p = vUv * 2.0 - 1.0;
  p += uPointer * uParallax * 0.1;
  vec2 rp = vec2(p.x * uRot.x - p.y * uRot.y, p.x * uRot.y + p.y * uRot.x);
  vec2 q = vec2(rp.x * (uCanvas.x / uCanvas.y), rp.y);
  q /= max(uScale, 0.0001);
  q /= 0.5 + 0.2 * dot(q, q);
  q += 0.2 * cos(t) - 7.56;
  vec2 toward = (uPointer - rp);
  q += toward * uMouseInfluence * 0.2;

    for (int j = 0; j < 5; j++) {
      if (j >= uIterations - 1) break;
      vec2 rr = sin(1.5 * (q.yx * uFrequency) + 2.0 * cos(q * uFrequency));
      q += (rr - q) * 0.15;
    }

    vec3 col = vec3(0.0);
    float a = 1.0;

    if (uColorCount > 0) {
      vec2 s = q;
      vec3 sumCol = vec3(0.0);
      float cover = 0.0;
      for (int i = 0; i < MAX_COLORS; ++i) {
            if (i >= uColorCount) break;
            s -= 0.01;
            vec2 r = sin(1.5 * (s.yx * uFrequency) + 2.0 * cos(s * uFrequency));
            float m0 = length(r + sin(5.0 * r.y * uFrequency - 3.0 * t + float(i)) / 4.0);
            float kBelow = clamp(uWarpStrength, 0.0, 1.0);
            float kMix = pow(kBelow, 0.3); // strong response across 0..1
            float gain = 1.0 + max(uWarpStrength - 1.0, 0.0); // allow >1 to amplify displacement
            vec2 disp = (r - s) * kBelow;
            vec2 warped = s + disp * gain;
            float m1 = length(warped + sin(5.0 * warped.y * uFrequency - 3.0 * t + float(i)) / 4.0);
            float m = mix(m0, m1, kMix);
            float w = 1.0 - exp(-uBandWidth / exp(uBandWidth * m));
            sumCol += uColors[i] * w;
            cover = max(cover, w);
      }
      col = clamp(sumCol, 0.0, 1.0);
      a = uTransparent > 0 ? cover : 1.0;
    } else {
        vec2 s = q;
        for (int k = 0; k < 3; ++k) {
            s -= 0.01;
            vec2 r = sin(1.5 * (s.yx * uFrequency) + 2.0 * cos(s * uFrequency));
            float m0 = length(r + sin(5.0 * r.y * uFrequency - 3.0 * t + float(k)) / 4.0);
            float kBelow = clamp(uWarpStrength, 0.0, 1.0);
            float kMix = pow(kBelow, 0.3);
            float gain = 1.0 + max(uWarpStrength - 1.0, 0.0);
            vec2 disp = (r - s) * kBelow;
            vec2 warped = s + disp * gain;
            float m1 = length(warped + sin(5.0 * warped.y * uFrequency - 3.0 * t + float(k)) / 4.0);
            float m = mix(m0, m1, kMix);
            col[k] = 1.0 - exp(-uBandWidth / exp(uBandWidth * m));
        }
        a = uTransparent > 0 ? max(max(col.r, col.g), col.b) : 1.0;
    }

    col *= uIntensity;

    if (uNoise > 0.0001) {
      float n = fract(sin(dot(gl_FragCoord.xy + vec2(uTime), vec2(12.9898, 78.233))) * 43758.5453123);
      col += (n - 0.5) * uNoise;
      col = clamp(col, 0.0, 1.0);
    }

    vec3 rgb = (uTransparent > 0) ? col * a : col;
    gl_FragColor = vec4(rgb, a);
}
`;

const vert = `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position, 1.0);
}
`;

export default function ColorBends({
  className,
  style,
  rotation = 90,
  speed = 0.2,
  colors = [],
  transparent = true,
  autoRotate = 0,
  scale = 1,
  frequency = 1,
  warpStrength = 1,
  mouseInfluence = 1,
  parallax = 0.5,
  noise = 0.15,
  iterations = 1,
  intensity = 1.5,
  bandWidth = 6
}: ColorBendsProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const rafRef = useRef<number | null>(null);
  const materialRef = useRef<THREE.ShaderMaterial | null>(null);
  const resizeObserverRef = useRef<ResizeObserver | null>(null);
  const rotationRef = useRef<number>(rotation);
  const autoRotateRef = useRef<number>(autoRotate);
  const pointerTargetRef = useRef<THREE.Vector2>(new THREE.Vector2(0, 0));
  const pointerCurrentRef = useRef<THREE.Vector2>(new THREE.Vector2(0, 0));
  const pointerSmoothRef = useRef<number>(8);

  useEffect(() => {
    const container = containerRef.current!;
    const scene = new THREE.Scene();
    const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);

    const geometry = new THREE.PlaneGeometry(2, 2);
    const uColorsArray = Array.from({ length: MAX_COLORS }, () => new THREE.Vector3(0, 0, 0));
    const material = new THREE.ShaderMaterial({
      vertexShader: vert,
      fragmentShader: frag,
      uniforms: {
        uCanvas: { value: new THREE.Vector2(1, 1) },
        uTime: { value: 0 },
        uSpeed: { value: speed },
        uRot: { value: new THREE.Vector2(1, 0) },
        uColorCount: { value: 0 },
        uColors: { value: uColorsArray },
        uTransparent: { value: transparent ? 1 : 0 },
        uScale: { value: scale },
        uFrequency: { value: frequency },
        uWarpStrength: { value: warpStrength },
        uPointer: { value: new THREE.Vector2(0, 0) },
        uMouseInfluence: { value: mouseInfluence },
        uParallax: { value: parallax },
        uNoise: { value: noise },
        uIterations: { value: iterations },
        uIntensity: { value: intensity },
        uBandWidth: { value: bandWidth }
      },
      premultipliedAlpha: true,
      transparent: true
    });
    materialRef.current = material;

    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    const renderer = new THREE.WebGLRenderer({
      antialias: false,
      powerPreference: 'high-performance',
      alpha: true
    });
    rendererRef.current = renderer;
    (renderer as any).outputColorSpace = (THREE as any).SRGBColorSpace;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setClearColor(0x000000, transparent ? 0 : 1);
    renderer.domElement.style.width = '100%';
    renderer.domElement.style.height = '100%';
    renderer.domElement.style.display = 'block';
    container.appendChild(renderer.domElement);

    const clock = new THREE.Clock();

    const handleResize = () => {
      const w = container.clientWidth || 1;
      const h = container.clientHeight || 1;
      renderer.setSize(w, h, false);
      (material.uniforms.uCanvas.value as THREE.Vector2).set(w, h);
    };

    handleResize();

    if ('ResizeObserver' in window) {
      const ro = new ResizeObserver(handleResize);
      ro.observe(container);
      resizeObserverRef.current = ro;
    } else {
      (window as Window).addEventListener('resize', handleResize);
    }

    const loop = () => {
      const dt = clock.getDelta();
      const elapsed = clock.elapsedTime;
      material.uniforms.uTime.value = elapsed;

      const deg = (rotationRef.current % 360) + autoRotateRef.current * elapsed;
      const rad = (deg * Math.PI) / 180;
      const c = Math.cos(rad);
      const s = Math.sin(rad);
      (material.uniforms.uRot.value as THREE.Vector2).set(c, s);

      const cur = pointerCurrentRef.current;
      const tgt = pointerTargetRef.current;
      const amt = Math.min(1, dt * pointerSmoothRef.current);
      cur.lerp(tgt, amt);
      (material.uniforms.uPointer.value as THREE.Vector2).copy(cur);
      renderer.render(scene, camera);
      rafRef.current = requestAnimationFrame(loop);
    };
    rafRef.current = requestAnimationFrame(loop);

    return () => {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
      if (resizeObserverRef.current) resizeObserverRef.current.disconnect();
      else (window as Window).removeEventListener('resize', handleResize);
      geometry.dispose();
      material.dispose();
      renderer.dispose();
      renderer.forceContextLoss();
      if (renderer.domElement && renderer.domElement.parentElement === container) {
        container.removeChild(renderer.domElement);
      }
    };
  }, []);

  useEffect(() => {
    const material = materialRef.current;
    const renderer = rendererRef.current;
    if (!material) return;

    rotationRef.current = rotation;
    autoRotateRef.current = autoRotate;
    material.uniforms.uSpeed.value = speed;
    material.uniforms.uScale.value = scale;
    material.uniforms.uFrequency.value = frequency;
    material.uniforms.uWarpStrength.value = warpStrength;
    material.uniforms.uMouseInfluence.value = mouseInfluence;
    material.uniforms.uParallax.value = parallax;
    material.uniforms.uNoise.value = noise;
    material.uniforms.uIterations.value = iterations;
    material.uniforms.uIntensity.value = intensity;
    material.uniforms.uBandWidth.value = bandWidth;

    const toVec3 = (hex: string) => {
      const h = hex.replace('#', '').trim();
      const v =
        h.length === 3
          ? [parseInt(h[0] + h[0], 16), parseInt(h[1] + h[1], 16), parseInt(h[2] + h[2], 16)]
          : [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
      return new THREE.Vector3(v[0] / 255, v[1] / 255, v[2] / 255);
    };

    const arr = (colors || []).filter(Boolean).slice(0, MAX_COLORS).map(toVec3);
    for (let i = 0; i < MAX_COLORS; i++) {
      const vec = (material.uniforms.uColors.value as THREE.Vector3[])[i];
      if (i < arr.length) vec.copy(arr[i]);
      else vec.set(0, 0, 0);
    }
    material.uniforms.uColorCount.value = arr.length;

    material.uniforms.uTransparent.value = transparent ? 1 : 0;
    if (renderer) renderer.setClearColor(0x000000, transparent ? 0 : 1);
  }, [
    rotation,
    autoRotate,
    speed,
    scale,
    frequency,
    warpStrength,
    mouseInfluence,
    parallax,
    noise,
    iterations,
    intensity,
    bandWidth,
    colors,
    transparent
  ]);

  useEffect(() => {
    const material = materialRef.current;
    const container = containerRef.current;
    if (!material || !container) return;

    const handlePointerMove = (e: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / (rect.width || 1)) * 2 - 1;
      const y = -(((e.clientY - rect.top) / (rect.height || 1)) * 2 - 1);
      pointerTargetRef.current.set(x, y);
    };

    container.addEventListener('pointermove', handlePointerMove);
    return () => {
      container.removeEventListener('pointermove', handlePointerMove);
    };
  }, []);

  return <div ref={containerRef} className={`w-full h-full relative overflow-hidden ${className}`} style={style} />;
}

