import { useEffect, useRef, type HTMLAttributes } from 'react';

export interface DarkVeilProps extends HTMLAttributes<HTMLDivElement> {
  color?: string;
  speed?: number;
  scale?: number;
  rotation?: number;
  flow?: number;
  warp?: number;
  variation?: number;
  brightness?: number;
  sheen?: number;
  glow?: number;
  grain?: number;
  quality?: number;
  mouseInteraction?: boolean;
  mouseStrength?: number;
